INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インテリア", "is_correct": true, "explanation": "部屋の飾りの写真を見てソファを探すという意味が合う。"}, {"text": "動物", "is_correct": false, "explanation": "形は合うが、動物の写真でソファを探すのは意味が合わない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、電車の写真でソファを探すのは意味が合わない。"}, {"text": "野球", "is_correct": false, "explanation": "形は合うが、野球の写真でソファを探すのは意味が合わない。"}], "explanations": {"インテリア": "部屋の飾りの写真を見てソファを探すという意味が合う。", "動物": "形は合うが、動物の写真でソファを探すのは意味が合わない。", "電車": "形は合うが、電車の写真でソファを探すのは意味が合わない。", "野球": "形は合うが、野球の写真でソファを探すのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "インテリア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インテリアが空を飛んでいる。", "explanation": "インテリアは鳥ではなく、部屋の飾りつけを指すので飛ばない。"}, {"text": "私のインテリアは三歳で、よく鳴く。", "explanation": "インテリアは動物ではなく、鳴かない。"}, {"text": "インテリアに乗って海を渡った。", "explanation": "インテリアは船などの乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達の家のインテリアが、おいしくておしゃれだ。", "corrected_sentence": "友達の家のインテリアが、明るくておしゃれだ。", "error_description": "インテリアは味わうものではないので「おいしくて」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "インテリアを笑うために、毎月花を飾っている。", "corrected_sentence": "インテリアを楽しむために、毎月花を飾っている。", "error_description": "インテリアは笑う対象ではなく、楽しむものなので「笑う」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に興味がある」の形で、興味の対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「インテリアを興味がある」とは言えない。"}, {"text": "と", "is_correct": false, "explanation": "「インテリアと興味がある」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "へは方向を表すので、興味の対象には使えない。"}], "correct_answer": "に", "explanations": {"に": "「〜に興味がある」の形で、興味の対象を表す。", "を": "「インテリアを興味がある」とは言えない。", "と": "「インテリアと興味がある」は文として成り立たない。", "へ": "へは方向を表すので、興味の対象には使えない。"}, "error_tags": {"を": "object", "と": "comitative", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "エクステリア", "is_correct": true, "explanation": "建物の外まわりのことで、室内のインテリアの反対。"}, {"text": "家具", "is_correct": false, "explanation": "インテリアの一部で、反対の関係ではない。"}, {"text": "照明", "is_correct": false, "explanation": "インテリアの要素で、反対の関係ではない。"}, {"text": "壁紙", "is_correct": false, "explanation": "室内の装飾の一部で、反対の関係ではない。"}], "correct_answer": "エクステリア", "explanations": {"エクステリア": "建物の外まわりのことで、室内のインテリアの反対。", "家具": "インテリアの一部で、反対の関係ではない。", "照明": "インテリアの要素で、反対の関係ではない。", "壁紙": "室内の装飾の一部で、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人気を集めている」の主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "後ろに「人気を」があるので、目的語が重なって文にならない。"}, {"text": "に", "is_correct": false, "explanation": "主語が足りなくなり、「人気を集めている」につながらない。"}, {"text": "と", "is_correct": false, "explanation": "「インテリアと人気を集めている」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「人気を集めている」の主語を表す。", "を": "後ろに「人気を」があるので、目的語が重なって文にならない。", "に": "主語が足りなくなり、「人気を集めている」につながらない。", "と": "「インテリアと人気を集めている」は文として成り立たない。"}, "error_tags": {"を": "object", "に": "target", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外観", "is_correct": true, "explanation": "建物の外から見た様子で、内側のインテリアの反対。"}, {"text": "内装", "is_correct": false, "explanation": "インテリアと近い意味で、反対ではない。"}, {"text": "天井", "is_correct": false, "explanation": "室内の一部で、反対の関係ではない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の部品で、反対の関係ではない。"}], "correct_answer": "外観", "explanations": {"外観": "建物の外から見た様子で、内側のインテリアの反対。", "内装": "インテリアと近い意味で、反対ではない。", "天井": "室内の一部で、反対の関係ではない。", "窓": "建物の部品で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "室内の装飾やデザインのこと。特に、家具や照明、色使いなどで空間を整えること。", "primary_collocate": null, "pronunciation": "いんてりあ", "ipa": "interia", "syllable_count": 5, "sentences": [{"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "インテリア", "complexity_tier": "T6", "furigana": "都会[とかい]の限[かぎ]られたスペースを持[も]つアパートメントでは、モダンなインテリアデザインが空間[くうかん]の印象[いんしょう]を大[おお]きく左右[さゆう]します。", "sentence_source": "mined"}, {"text": "インテリアに興味があります。", "target_word": "インテリア", "complexity_tier": "T2", "furigana": "インテリアに興味[きょうみ]があります。", "sentence_source": "generated"}, {"text": "友達はインテリアの仕事をしている。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "友達[ともだち]はインテリアの仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "白と木の色でインテリアをそろえた。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "白[しろ]と木[き]の色[いろ]でインテリアをそろえた。", "sentence_source": "generated"}, {"text": "好きな雑誌でインテリアの勉強をしている。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "好[す]きな雑誌[ざっし]でインテリアの勉強[べんきょう]をしている。", "sentence_source": "generated"}, {"text": "このインテリアは、照明の使い方がうまい。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "このインテリアは、照明[しょうめい]の使[つか]い方[かた]がうまい。", "sentence_source": "generated"}, {"text": "インテリアを変えるだけで、部屋の雰囲気が明るくなる。", "target_word": "インテリア", "complexity_tier": "T4", "furigana": "インテリアを変[か]えるだけで、部屋[へや]の雰囲気[ふんいき]が明[あか]るくなる。", "sentence_source": "generated"}, {"text": "北欧風のインテリアが人気を集めている。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "北欧風[ほくおうふう]のインテリアが人気[にんき]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "引っ越しを機にインテリアを見直すことにした。", "target_word": "インテリア", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しを機[き]にインテリアを見直[みなお]すことにした。", "sentence_source": "generated"}, {"text": "インテリアにこだわる人ほど、家で過ごす時間が長い。", "target_word": "インテリア", "complexity_tier": "T4", "furigana": "インテリアにこだわる人[ひと]ほど、家[いえ]で過[す]ごす時間[じかん]が長[なが]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インテリアデザイン", "label": "派生"}, {"form": "インテリアショップ", "label": "派生"}, {"form": "インテリアコーディネーター", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 家具や照明で室内を整える装飾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インテリア", "is_correct": true, "explanation": "室内の装飾のデザインで、空間の印象を左右する意味が合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、空間の印象を左右するデザインとして意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、デザインの種類として意味が合わない。"}, {"text": "電話", "is_correct": false, "explanation": "形は合うが、空間の印象を決めるデザインとして意味が合わない。"}], "explanations": {"インテリア": "室内の装飾のデザインで、空間の印象を左右する意味が合う。", "野菜": "形は合うが、空間の印象を左右するデザインとして意味が合わない。", "天気": "形は合うが、デザインの種類として意味が合わない。", "電話": "形は合うが、空間の印象を決めるデザインとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "インテリア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "インテリアに乗って、会社まで通っている。", "explanation": "インテリアは室内の装飾で、乗り物ではない。"}, {"text": "私はインテリアを食べるのが好きだ。", "explanation": "インテリアは食べ物ではなく、室内の装飾を指す。"}, {"text": "インテリアの雨が降って、傘を差した。", "explanation": "インテリアは室内の装飾で、天気とは関係がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インテリア", "is_correct": true, "explanation": "室内の装飾を変えれば部屋の雰囲気が変わるという意味が合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、変えても部屋の雰囲気は明るくならず意味が合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "形は合うが、部屋の雰囲気を変えるものとして意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、人が変えるものではなく意味が合わない。"}], "explanations": {"インテリア": "室内の装飾を変えれば部屋の雰囲気が変わるという意味が合う。", "野菜": "形は合うが、変えても部屋の雰囲気は明るくならず意味が合わない。", "年齢": "形は合うが、部屋の雰囲気を変えるものとして意味が合わない。", "天気": "形は合うが、人が変えるものではなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "インテリア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝インテリアを飲んでから出かける。", "explanation": "インテリアは飲み物ではなく、室内の装飾である。"}, {"text": "インテリアは電話で、遠くの友達と話せる。", "explanation": "インテリアは機械ではなく、室内の装飾を指す。"}, {"text": "この辺りはインテリアが多くて空気がきれいだ。", "explanation": "インテリアは自然ではなく、室内の装飾なので空気とは関係がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休みの日にインテリアを建てて、部屋を明るくした。", "corrected_sentence": "休みの日にインテリアを変えて、部屋を明るくした。", "error_description": "インテリアは建てるものではなく、変える、整えるものなので「建てて」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51676, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいインテリアを食べて、部屋が明るくなった。", "corrected_sentence": "新しいインテリアをそろえて、部屋が明るくなった。", "error_description": "インテリアは食べるものではなく、そろえるものなので「食べて」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51677, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ミニマリストは」と主題を示し、物が少ないと述べる。"}, {"text": "を", "is_correct": false, "explanation": "「ミニマリストを物が少ない」は形容詞の文に目的語がなく成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ミニマリストへ」は方向を示し、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「ミニマリストから物が少ない」は起点の意味になり、文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「ミニマリストは」と主題を示し、物が少ないと述べる。", "を": "「ミニマリストを物が少ない」は形容詞の文に目的語がなく成り立たない。", "へ": "「ミニマリストへ」は方向を示し、文として成り立たない。", "から": "「ミニマリストから物が少ない」は起点の意味になり、文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source_marker"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
