INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51677, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「ミニマリスト」は、いらないものをなくして、本当に必要なものだけでくらす人のことです。", "primary_collocate": null, "pronunciation": "みにまりすと", "ipa": "minimaɾisɯto", "syllable_count": 6, "sentences": [{"text": "友達はミニマリストだ。", "target_word": "ミニマリスト", "complexity_tier": "T1", "furigana": "友達[ともだち]はミニマリストだ。", "sentence_source": "generated"}, {"text": "ミニマリストは物が少ない。", "target_word": "ミニマリスト", "complexity_tier": "T2", "furigana": "ミニマリストは物[もの]が少[すく]ない。", "sentence_source": "generated"}, {"text": "あの人はミニマリストなので、服が五着しかない。", "target_word": "ミニマリスト", "complexity_tier": "T4", "furigana": "あの人[ひと]はミニマリストなので、服[ふく]が五着[ごちゃく]しかない。", "sentence_source": "generated"}, {"text": "ミニマリストの家はとても広く見える。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストの家[いえ]はとても広[ひろ]く見[み]える。", "sentence_source": "generated"}, {"text": "私もミニマリストになりたいです。", "target_word": "ミニマリスト", "complexity_tier": "T2", "furigana": "私[わたし]もミニマリストになりたいです。", "sentence_source": "generated"}, {"text": "ミニマリストが書いた本を読んでいる。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストが書[か]いた本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "ミニマリストに憧れて、いらない物を売った。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストに憧[あこが]れて、いらない物[もの]を売[う]った。", "sentence_source": "generated"}, {"text": "彼はミニマリストではないが、物は少ない。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "彼[かれ]はミニマリストではないが、物[もの]は少[すく]ない。", "sentence_source": "generated"}, {"text": "ミニマリストの友達に、花をもらった。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストの友達[ともだち]に、花[はな]をもらった。", "sentence_source": "generated"}, {"text": "ミニマリストと一緒に住むと、片付けが楽になる。", "target_word": "ミニマリスト", "complexity_tier": "T4", "furigana": "ミニマリストと一緒[いっしょ]に住[す]むと、片付[かたづ]けが楽[らく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミニマリズム", "label": "派生"}, {"form": "ミニマル", "label": "派生"}, {"form": "ミニマリストたち", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 必要な物だけで暮らす人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51677, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミニマリスト", "is_correct": true, "explanation": "友達が必要な物だけで暮らす人だという意味で合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、友達が天気だという意味が合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "形は合うが、友達が教科書だという意味が合わない。"}, {"text": "駅", "is_correct": false, "explanation": "形は合うが、友達が駅だという意味が合わない。"}], "explanations": {"ミニマリスト": "友達が必要な物だけで暮らす人だという意味で合う。", "天気": "形は合うが、友達が天気だという意味が合わない。", "教科書": "形は合うが、友達が教科書だという意味が合わない。", "駅": "形は合うが、友達が駅だという意味が合わない。"}, "sentence_index": 0, "correct_answer": "ミニマリスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ミニマリストは新しい服や道具を毎月たくさん買う人だ。", "explanation": "ミニマリストは物を増やさない人なので、たくさん買う人という説明は意味が逆。"}, {"text": "ミニマリストは魚をとって市場で売る人のことだ。", "explanation": "ミニマリストを漁師のような職業の意味で使っており、語義が違う。"}, {"text": "ミニマリストの家は物でいっぱいで、とても狭く見える。", "explanation": "ミニマリストの家は物が少ないので、物でいっぱいという描写は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51677, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミニマリスト", "is_correct": true, "explanation": "「憧れて、いらない物を売った」という行動とつながる。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、宿題に憧れて物を売るという意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気に憧れて物を売るという意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震に憧れるという意味が合わない。"}], "explanations": {"ミニマリスト": "「憧れて、いらない物を売った」という行動とつながる。", "宿題": "形は合うが、宿題に憧れて物を売るという意味が合わない。", "天気": "形は合うが、天気に憧れて物を売るという意味が合わない。", "地震": "形は合うが、地震に憧れるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "ミニマリスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ミニマリストと一緒に住むと、荷物が増えて片付けが大変になる。", "explanation": "ミニマリストは物が少ない人なので、荷物が増えるという結果は合わない。"}, {"text": "ミニマリストと一緒に住むと、家中が使わない物であふれる。", "explanation": "ミニマリストはいらない物を持たない人なので、家が使わない物であふれるのは意味に反する。"}, {"text": "ミニマリストと一緒に住むと、いつもいろいろな服を貸してもらえる。", "explanation": "服をたくさん持つ人というのはミニマリストの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51677, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の母はミニマリストなので、部屋が物でいっぱいだ。", "corrected_sentence": "私の母はミニマリストなので、部屋がすっきりしている。", "error_description": "ミニマリストの部屋が物でいっぱいという内容が意味に反する。「すっきりしている」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
