INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51678, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「ミニマリスト」とは、物質的な所有を最小限に抑え、必要最低限のものだけで生活することを理想とする人や、そのような考え方を持つ人のことです。", "primary_collocate": null, "pronunciation": "みにまりすと", "ipa": "minimaɾisɯto", "syllable_count": 6, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "ミニマリスト", "complexity_tier": "T6", "furigana": "ミニマリストの思想[しそう]に基[もと]づき、必要[ひつよう]な要素[ようそ]だけを残[のこ]すことで、居住者[きょじゅうしゃ]はより穏[おだ]やかな日常[にちじょう]を送[おく]ることができます。", "sentence_source": "mined"}, {"text": "私の兄はミニマリストです。", "target_word": "ミニマリスト", "complexity_tier": "T2", "furigana": "私[わたし]の兄[あに]はミニマリストです。", "sentence_source": "generated"}, {"text": "ミニマリストは物をあまり持たない。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストは物[もの]をあまり持[も]たない。", "sentence_source": "generated"}, {"text": "彼女はミニマリストになってから、部屋が広くなった。", "target_word": "ミニマリスト", "complexity_tier": "T4", "furigana": "彼女[かのじょ]はミニマリストになってから、部屋[へや]が広[ひろ]くなった。", "sentence_source": "generated"}, {"text": "ミニマリストの部屋には、家具がほとんどない。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストの部屋[へや]には、家具[かぐ]がほとんどない。", "sentence_source": "generated"}, {"text": "ミニマリストと呼ばれる人が増えている。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストと呼[よ]ばれる人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "ミニマリストを目指して、服を半分に減らした。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストを目指[めざ]して、服[ふく]を半分[はんぶん]に減[へ]らした。", "sentence_source": "generated"}, {"text": "彼はミニマリストらしく、小さなかばん一つで旅をする。", "target_word": "ミニマリスト", "complexity_tier": "T4", "furigana": "彼[かれ]はミニマリストらしく、小[ちい]さなかばん一[ひと]つで旅[たび]をする。", "sentence_source": "generated"}, {"text": "ミニマリストでも、本だけは捨てられないそうだ。", "target_word": "ミニマリスト", "complexity_tier": "T4", "furigana": "ミニマリストでも、本[ほん]だけは捨[す]てられないそうだ。", "sentence_source": "generated"}, {"text": "ミニマリストの生き方に学ぶことは多い。", "target_word": "ミニマリスト", "complexity_tier": "T3", "furigana": "ミニマリストの生[い]き方[かた]に学[まな]ぶことは多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミニマリズム", "label": "派生"}, {"form": "ミニマル", "label": "派生"}, {"form": "ミニマリストたち", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 持ち物を最小限にして暮らす人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミニマリスト", "is_correct": true, "explanation": "物を最小限にして暮らす人で、「思想に基づき必要な要素だけを残す」に合う。"}, {"text": "消防士", "is_correct": false, "explanation": "形は合うが、消防士の思想に基づいて必要な要素だけを残すという意味が合わない。"}, {"text": "観光客", "is_correct": false, "explanation": "形は合うが、観光客の思想で居住者の日常が穏やかになるという意味が合わない。"}, {"text": "配達員", "is_correct": false, "explanation": "形は合うが、配達員の思想に基づく暮らし方という意味が合わない。"}], "explanations": {"ミニマリスト": "物を最小限にして暮らす人で、「思想に基づき必要な要素だけを残す」に合う。", "消防士": "形は合うが、消防士の思想に基づいて必要な要素だけを残すという意味が合わない。", "観光客": "形は合うが、観光客の思想で居住者の日常が穏やかになるという意味が合わない。", "配達員": "形は合うが、配達員の思想に基づく暮らし方という意味が合わない。"}, "sentence_index": 0, "correct_answer": "ミニマリスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ミニマリストは家具や服をたくさん集めるのが大好きだ。", "explanation": "ミニマリストは物を最小限にする人なので、たくさん集めるという使い方は意味が逆。"}, {"text": "このレストランのミニマリストが、注文を取って料理を運んでくれた。", "explanation": "ミニマリストは店員の職業名ではなく、暮らし方の人を指す。"}, {"text": "ミニマリストは物を買うたびに、部屋にもっと家具を増やしていく。", "explanation": "物を増やし続ける人はミニマリストの意味に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミニマリスト", "is_correct": true, "explanation": "服を半分に減らす行動とつながり、目指す対象として自然。"}, {"text": "医者", "is_correct": false, "explanation": "形は合うが、医者を目指して服を減らすという意味のつながりが合わない。"}, {"text": "野球選手", "is_correct": false, "explanation": "形は合うが、野球選手を目指して服を減らすという意味が合わない。"}, {"text": "弁護士", "is_correct": false, "explanation": "形は合うが、弁護士を目指して服を半分にする理由が合わない。"}], "explanations": {"ミニマリスト": "服を半分に減らす行動とつながり、目指す対象として自然。", "医者": "形は合うが、医者を目指して服を減らすという意味のつながりが合わない。", "野球選手": "形は合うが、野球選手を目指して服を減らすという意味が合わない。", "弁護士": "形は合うが、弁護士を目指して服を半分にする理由が合わない。"}, "sentence_index": 6, "correct_answer": "ミニマリスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ミニマリストは大きな家にたくさんの宝物を飾って暮らしている。", "explanation": "ミニマリストは持ち物を少なくする人なので、宝物を多く飾るのは意味に反する。"}, {"text": "ミニマリストになるには、国の試験に受かって医者の資格を取る必要がある。", "explanation": "ミニマリストは資格のいる職業ではなく、暮らし方を表す。"}, {"text": "ミニマリストは毎週デパートで高い家具をたくさん買う。", "explanation": "ミニマリストは持ち物を最小限にする人なので、毎週家具をたくさん買うのは意味に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はミニマリストを憧れて、服を減らした。", "corrected_sentence": "彼はミニマリストに憧れて、服を減らした。", "error_description": "「憧れる」の対象は「を」ではなく「に」で示す。「ミニマリストを」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ミニマリストは物をたくさん持ちたがる人だ。", "corrected_sentence": "ミニマリストは物をあまり持ちたがらない人だ。", "error_description": "ミニマリストは物を最小限にする人なので、「たくさん持ちたがる」が意味上の誤り。「あまり持ちたがらない」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51679, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「あの人の印象」と、印象の持ち主を示す。"}, {"text": "を", "is_correct": false, "explanation": "「あの人を印象は」は名詞の修飾にならず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「あの人へ印象は」は方向を示し、成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「あの人から印象は」は起点を示し、成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「あの人の印象」と、印象の持ち主を示す。", "を": "「あの人を印象は」は名詞の修飾にならず成り立たない。", "へ": "「あの人へ印象は」は方向を示し、成り立たない。", "から": "「あの人から印象は」は起点を示し、成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source_marker"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51679, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「印象が悪い」と、印象を主語にして状態を述べる。"}, {"text": "を", "is_correct": false, "explanation": "「印象を悪いと」は形容詞の文に目的語がなく成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「印象に悪いと」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「印象へ悪いと」は方向を示し、成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「印象が悪い」と、印象を主語にして状態を述べる。", "を": "「印象を悪いと」は形容詞の文に目的語がなく成り立たない。", "に": "「印象に悪いと」は文として成り立たない。", "へ": "「印象へ悪いと」は方向を示し、成り立たない。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51679, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "見たり聞いたりしたときに、心にうかぶ感じ。", "primary_collocate": null, "pronunciation": "いんしょう", "ipa": "iɴɕoː", "syllable_count": 4, "sentences": [{"text": "強い印象を受けた。", "target_word": "印象", "complexity_tier": "T1", "furigana": "強[つよ]い印象[いんしょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "あの人の印象は明るい。", "target_word": "印象", "complexity_tier": "T1", "furigana": "あの人[ひと]の印象[いんしょう]は明[あか]るい。", "sentence_source": "generated"}, {"text": "日本の印象はどうでしたか。", "target_word": "印象", "complexity_tier": "T2", "furigana": "日本[にほん]の印象[いんしょう]はどうでしたか。", "sentence_source": "generated"}, {"text": "彼の話はあまり印象に残らなかった。", "target_word": "印象", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]はあまり印象[いんしょう]に残[のこ]らなかった。", "sentence_source": "generated"}, {"text": "駅前の景色が強い印象を残した。", "target_word": "印象", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の景色[けしき]が強[つよ]い印象[いんしょう]を残[のこ]した。", "sentence_source": "generated"}, {"text": "写真で見た印象と、実際の町は少し違った。", "target_word": "印象", "complexity_tier": "T3", "furigana": "写真[しゃしん]で見[み]た印象[いんしょう]と、実際[じっさい]の町[まち]は少[すこ]し違[ちが]った。", "sentence_source": "generated"}, {"text": "会議では、落ち着いた印象を与えたい。", "target_word": "印象", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、落[お]ち着[つ]いた印象[いんしょう]を与[あた]えたい。", "sentence_source": "generated"}, {"text": "印象が悪いと、話を聞いてもらえない。", "target_word": "印象", "complexity_tier": "T4", "furigana": "印象[いんしょう]が悪[わる]いと、話[はなし]を聞[き]いてもらえない。", "sentence_source": "generated"}, {"text": "旅行の印象は、日記に書いておいた。", "target_word": "印象", "complexity_tier": "T3", "furigana": "旅行[りょこう]の印象[いんしょう]は、日記[にっき]に書[か]いておいた。", "sentence_source": "generated"}, {"text": "初めて聞いた曲なのに、不思議な印象があった。", "target_word": "印象", "complexity_tier": "T4", "furigana": "初[はじ]めて聞[き]いた曲[きょく]なのに、不思議[ふしぎ]な印象[いんしょう]があった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "印象的", "label": "派生"}, {"form": "第一印象", "label": "派生"}, {"form": "印象派", "label": "派生"}, {"form": "印象深い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 見聞きして心に浮かぶ感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51679, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "いんしょう。これが正解の語。"}, {"text": "因習", "is_correct": false, "explanation": "いんしゅう。「しょ」が「しゅ」に変わる一拍違い。"}, {"text": "引用", "is_correct": false, "explanation": "いんよう。「しょ」が「よ」に変わる一拍違い。"}, {"text": "飲料", "is_correct": false, "explanation": "いんりょう。「しょ」が「りょ」に変わる一拍違い。"}, {"text": "飲食", "is_correct": false, "explanation": "いんしょく。最後の「う」が「く」に変わる一拍違い。"}], "explanations": {"印象": "いんしょう。これが正解の語。", "因習": "いんしゅう。「しょ」が「しゅ」に変わる一拍違い。", "引用": "いんよう。「しょ」が「よ」に変わる一拍違い。", "飲料": "いんりょう。「しょ」が「りょ」に変わる一拍違い。", "飲食": "いんしょく。最後の「う」が「く」に変わる一拍違い。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "「強い印象を受けた」は心に感じを受けたという意味で合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、強い机を受けたという意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、強い野菜を受けたという意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、強い地図を受けたという意味が合わない。"}], "explanations": {"印象": "「強い印象を受けた」は心に感じを受けたという意味で合う。", "机": "形は合うが、強い机を受けたという意味が合わない。", "野菜": "形は合うが、強い野菜を受けたという意味が合わない。", "地図": "形は合うが、強い地図を受けたという意味が合わない。"}, "sentence_index": 0, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の印象は、午前九時に駅で乗る電車だ。", "explanation": "印象は心に浮かぶ感じで、乗り物の意味では使えない。"}, {"text": "彼の話はあまり印象を食べなかった。", "explanation": "印象は食べる対象ではなく、「食べる」とは結びつかない。"}, {"text": "印象は駅の近くにある大きな会社で、千人が働いている。", "explanation": "印象を会社の名前のように使っており、心に浮かぶ感じという語義と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51679, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "いんしょう。これが正解の語。"}, {"text": "金賞", "is_correct": false, "explanation": "きんしょう。最初の「い」が「き」に変わる一拍違い。"}, {"text": "陰謀", "is_correct": false, "explanation": "いんぼう。「しょ」が「ぼ」に変わる一拍違い。"}, {"text": "咽喉", "is_correct": false, "explanation": "いんこう。「しょ」が「こ」に変わる一拍違い。"}], "explanations": {"印象": "いんしょう。これが正解の語。", "金賞": "きんしょう。最初の「い」が「き」に変わる一拍違い。", "陰謀": "いんぼう。「しょ」が「ぼ」に変わる一拍違い。", "咽喉": "いんこう。「しょ」が「こ」に変わる一拍違い。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "会議で落ち着いた感じを相手に与えたいという意味で合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、落ち着いた鉛筆を与えるという意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、落ち着いた地図を与えるという意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、落ち着いた季節を与えるという意味が合わない。"}], "explanations": {"印象": "会議で落ち着いた感じを相手に与えたいという意味で合う。", "鉛筆": "形は合うが、落ち着いた鉛筆を与えるという意味が合わない。", "地図": "形は合うが、落ち着いた地図を与えるという意味が合わない。", "季節": "形は合うが、落ち着いた季節を与えるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "初めて聞いた曲なのに、不思議な印象を歌った。", "explanation": "印象は心に浮かぶ感じで、歌う対象ではなく「歌う」とは結びつかない。"}, {"text": "初めて聞いた曲なのに、不思議な印象に乗って家へ帰った。", "explanation": "印象を乗り物のように使っており、意味が合わない。"}, {"text": "初めて聞いた曲なのに、不思議な印象を二本買った。", "explanation": "印象は買って数えられる物ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warning