INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51680, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事から受ける感じやイメージ。また、そのような心に残るイメージ。", "primary_collocate": null, "pronunciation": "いんしょう", "ipa": "iɴɕoː", "syllable_count": 4, "sentences": [{"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "印象", "complexity_tier": "T6", "furigana": "都会[とかい]の限[かぎ]られたスペースを持[も]つアパートメントでは、モダンなインテリアデザインが空間[くうかん]の印象[いんしょう]を大[おお]きく左右[さゆう]します。", "sentence_source": "mined"}, {"text": "最初の印象は大切です。", "target_word": "印象", "complexity_tier": "T2", "furigana": "最初[さいしょ]の印象[いんしょう]は大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "その人にはいい印象を持った。", "target_word": "印象", "complexity_tier": "T3", "furigana": "その人[ひと]にはいい印象[いんしょう]を持[も]った。", "sentence_source": "generated"}, {"text": "京都の印象はどうでしたか。", "target_word": "印象", "complexity_tier": "T2", "furigana": "京都[きょうと]の印象[いんしょう]はどうでしたか。", "sentence_source": "generated"}, {"text": "初めて会ったとき、彼は優しい印象だった。", "target_word": "印象", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]ったとき、彼[かれ]は優[やさ]しい印象[いんしょう]だった。", "sentence_source": "generated"}, {"text": "髪型を変えると、印象が大きく変わる。", "target_word": "印象", "complexity_tier": "T3", "furigana": "髪型[かみがた]を変[か]えると、印象[いんしょう]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "この映画は印象に残るシーンが多い。", "target_word": "印象", "complexity_tier": "T3", "furigana": "この映画[えいが]は印象[いんしょう]に残[のこ]るシーンが多[おお]い。", "sentence_source": "generated"}, {"text": "服の色で人に与える印象は違ってくる。", "target_word": "印象", "complexity_tier": "T4", "furigana": "服[ふく]の色[いろ]で人[ひと]に与[あた]える印象[いんしょう]は違[ちが]ってくる。", "sentence_source": "generated"}, {"text": "先生に悪い印象を持たれたくなかった。", "target_word": "印象", "complexity_tier": "T4", "furigana": "先生[せんせい]に悪[わる]い印象[いんしょう]を持[も]たれたくなかった。", "sentence_source": "generated"}, {"text": "印象を聞かれて、「静かな町です」と答えた。", "target_word": "印象", "complexity_tier": "T4", "furigana": "印象[いんしょう]を聞[き]かれて、「静[しず]かな町[まち]です」と答[こた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "印象的", "label": "派生"}, {"form": "第一印象", "label": "派生"}, {"form": "印象派", "label": "派生"}, {"form": "印象深い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事から受ける感じやイメージ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アパートメント (Zipf 2.37)']::text[], '13d1ddaa-b229-4220-8e32-2b70806d81c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
