_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51680, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "いんしょう。これが正解の語。"}, {"text": "金賞", "is_correct": false, "explanation": "きんしょう。最初の「い」が「き」に変わる一拍違い。"}, {"text": "陰謀", "is_correct": false, "explanation": "いんぼう。「しょ」が「ぼ」に変わる一拍違い。"}, {"text": "咽喉", "is_correct": false, "explanation": "いんこう。「しょ」が「こ」に変わる一拍違い。"}], "explanations": {"印象": "いんしょう。これが正解の語。", "金賞": "きんしょう。最初の「い」が「き」に変わる一拍違い。", "陰謀": "いんぼう。「しょ」が「ぼ」に変わる一拍違い。", "咽喉": "いんこう。「しょ」が「こ」に変わる一拍違い。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "「印象に残る」は心に残るという意味で自然に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、映画のシーンが机に残るという意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、シーンが値段に残るという意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、シーンが天気に残るという意味が合わない。"}], "explanations": {"印象": "「印象に残る」は心に残るという意味で自然に合う。", "机": "形は合うが、映画のシーンが机に残るという意味が合わない。", "値段": "形は合うが、シーンが値段に残るという意味が合わない。", "天気": "形は合うが、シーンが天気に残るという意味が合わない。"}, "sentence_index": 6, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の印象を聞かれて、「千円です」と答えた。", "explanation": "印象は感じを問うもので、値段で答えるのは意味が合わない。"}, {"text": "町の印象を聞かれて、はさみで印象を切って渡した。", "explanation": "印象は形のない感じで、切って渡せる物ではない。"}, {"text": "印象は、毎朝六時に起きてご飯を食べる人のことだ。", "explanation": "印象を人を指す語として使っており、語義が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51680, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "初めて会った人に、いい印象を落とした。", "corrected_sentence": "初めて会った人に、いい印象を与えた。", "error_description": "「印象」と結びつく動詞は「与える」。「落とした」は印象との組み合わせとして不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51680, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は私によい印象に持っているようだ。", "corrected_sentence": "先生は私によい印象を持っているようだ。", "error_description": "「印象を持つ」と、持つ対象は「を」で示す。「印象に」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '002d9ab9-970b-479f-b5af-144b07d1a2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "険悪", "is_correct": true, "explanation": "二人の間の空気が穏やかなのと反対に、仲が悪く危うい様子を表す。"}, {"text": "和やか", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}, {"text": "平和", "is_correct": false, "explanation": "争いのない状態を表し、「穏やか」の反対ではない。"}, {"text": "静か", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}], "correct_answer": "険悪", "explanations": {"険悪": "二人の間の空気が穏やかなのと反対に、仲が悪く危うい様子を表す。", "和やか": "「穏やか」に近い意味で、反対ではない。", "平和": "争いのない状態を表し、「穏やか」の反対ではない。", "静か": "「穏やか」に近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短気", "is_correct": true, "explanation": "怒りやすい性格を表し、穏やかな性格と反対になる。"}, {"text": "優しい", "is_correct": false, "explanation": "「穏やか」に近い性格を表し、反対ではない。"}, {"text": "素直", "is_correct": false, "explanation": "性格を表すが、「穏やか」の反対ではない。"}, {"text": "温厚", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}], "correct_answer": "短気", "explanations": {"短気": "怒りやすい性格を表し、穏やかな性格と反対になる。", "優しい": "「穏やか」に近い性格を表し、反対ではない。", "素直": "性格を表すが、「穏やか」の反対ではない。", "温厚": "「穏やか」に近い意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "けんかや怒りがなくて、心が落ち着いていること。", "primary_collocate": null, "pronunciation": "おだやか", "ipa": "odajaka", "syllable_count": 4, "sentences": [{"text": "兄弟は穏やかに話し合った。", "target_word": "穏やかに", "complexity_tier": "T2", "furigana": "兄弟(きょうだい)は穏(おだ)やかに話(はな)し合(あ)った。", "sentence_source": "generated"}, {"text": "穏やかな人と話すと、心が休まる。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "穏(おだ)やかな人(ひと)と話(はな)すと、心(こころ)が休(やす)まる。", "sentence_source": "generated"}, {"text": "先生は怒らずに穏やかに注意した。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "先生(せんせい)は怒(おこ)らずに穏(おだ)やかに注意(ちゅうい)した。", "sentence_source": "generated"}, {"text": "二人の間には穏やかな空気が戻った。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "二人(ふたり)の間(あいだ)には穏(おだ)やかな空気(くうき)が戻(もど)った。", "sentence_source": "generated"}, {"text": "長い話し合いのあと、彼の顔は穏やかだった。", "target_word": "穏やかだった", "complexity_tier": "T3", "furigana": "長(なが)い話(はな)し合(あ)いのあと、彼(かれ)の顔(かお)は穏(おだ)やかだった。", "sentence_source": "generated"}, {"text": "穏やかで優しい父は、めったに怒らない。", "target_word": "穏やかで", "complexity_tier": "T3", "furigana": "穏(おだ)やかで優(やさ)しい父(ちち)は、めったに怒(おこ)らない。", "sentence_source": "generated"}, {"text": "けんかをやめて、穏やかに暮らしたい。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "けんかをやめて、穏(おだ)やかに暮(く)らしたい。", "sentence_source": "generated"}, {"text": "彼はどんなときも穏やかな口調で話す。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "彼(かれ)はどんなときも穏(おだ)やかな口調(くちょう)で話(はな)す。", "sentence_source": "generated"}, {"text": "怒っていた母も、しだいに穏やかになった。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "怒(おこ)っていた母(はは)も、しだいに穏(おだ)やかになった。", "sentence_source": "generated"}, {"text": "穏やかな性格の彼女は、友達が多い。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "穏(おだ)やかな性格(せいかく)の彼女(かのじょ)は、友達(ともだち)が多(おお)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穏やかな", "label": "活用"}, {"form": "穏やかに", "label": "活用"}, {"form": "穏やかだ", "label": "活用"}, {"form": "穏やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 怒りやけんかがなく心が静かなさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穏やかに", "is_correct": true, "explanation": "けんかにならず落ち着いて話し合う様子を表し、文脈に合う。"}, {"text": "鮮やかに", "is_correct": false, "explanation": "形は合うが、話し合いの様子としては意味が合わない。"}, {"text": "華やかに", "is_correct": false, "explanation": "形は合うが、話し合いの様子としては意味が合わない。"}, {"text": "新鮮に", "is_correct": false, "explanation": "形は合うが、話し合うという動作の様子として意味が合わない。"}], "explanations": {"穏やかに": "けんかにならず落ち着いて話し合う様子を表し、文脈に合う。", "鮮やかに": "形は合うが、話し合いの様子としては意味が合わない。", "華やかに": "形は合うが、話し合いの様子としては意味が合わない。", "新鮮に": "形は合うが、話し合うという動作の様子として意味が合わない。"}, "sentence_index": 0, "correct_answer": "穏やかに"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人はけんかして、穏やかな声で怒鳴り合った。", "explanation": "怒鳴り合う声は穏やかではなく、「穏やか」と矛盾するので誤り。"}, {"text": "このナイフはとても穏やかで、指を切ってしまった。", "explanation": "「穏やか」は道具の切れ味を表す語ではないので誤り。"}, {"text": "この問題は穏やかで、誰にも解けなかった。", "explanation": "「穏やか」は問題の難しさを表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穏やかに", "is_correct": true, "explanation": "けんかをやめて争いのない落ち着いた暮らしを望む文脈に合う。"}, {"text": "鮮やかに", "is_correct": false, "explanation": "形は合うが、暮らし方として意味が合わない。"}, {"text": "滑らかに", "is_correct": false, "explanation": "形は合うが、暮らし方として意味が合わない。"}, {"text": "明らかに", "is_correct": false, "explanation": "形は合うが、「暮らす」様子としては意味が合わない。"}], "explanations": {"穏やかに": "けんかをやめて争いのない落ち着いた暮らしを望む文脈に合う。", "鮮やかに": "形は合うが、暮らし方として意味が合わない。", "滑らかに": "形は合うが、暮らし方として意味が合わない。", "明らかに": "形は合うが、「暮らす」様子としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "穏やかに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "穏やかな性格の彼女は、毎日誰かと言い争っている。", "explanation": "毎日言い争う人は穏やかではなく、「穏やか」と矛盾するので誤り。"}, {"text": "彼女の部屋は穏やかで、足の踏み場もない。", "explanation": "「穏やか」は部屋の散らかり具合を表す語ではないので誤り。"}, {"text": "穏やかな計算機は、答えを出すのが速い。", "explanation": "「穏やか」は機械の性能を表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "けんかのあと、二人は穏やかに殴り合った。", "corrected_sentence": "けんかのあと、二人は激しく殴り合った。", "error_description": "殴り合うのは穏やかな行動ではないので、「穏やかに」は不適切。「激しく」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「人」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、名詞「人」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形なので、名詞「人」の前では使えない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形なので、「人」の前に置くと意味が通らない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 1, "explanations": {"穏やかな": "「人」を修飾する連体形で、空所に合う。", "穏やかに": "連用形なので、名詞「人」を直接修飾できない。", "穏やかだ": "終止形なので、名詞「人」の前では使えない。", "穏やかさ": "名詞形なので、「人」の前に置くと意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51681, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "穏やかな性格の彼は、毎日誰かと殴り合っている。", "corrected_sentence": "乱暴な性格の彼は、毎日誰かと殴り合っている。", "error_description": "毎日殴り合う人の性格が「穏やか」というのは矛盾する。「乱暴な」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「口調」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、名詞「口調」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形なので、名詞「口調」の前では使えない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形なので、「口調」の前に置くと意味が通らない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 7, "explanations": {"穏やかな": "「口調」を修飾する連体形で、空所に合う。", "穏やかに": "連用形なので、名詞「口調」を直接修飾できない。", "穏やかだ": "終止形なので、名詞「口調」の前では使えない。", "穏やかさ": "名詞形なので、「口調」の前に置くと意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "荒々しい", "is_correct": true, "explanation": "様子が静かで落ち着いた「穏やか」と反対で、乱れて荒い様子を表す。"}, {"text": "静か", "is_correct": false, "explanation": "「穏やか」と近い意味で、反対ではない。"}, {"text": "優しい", "is_correct": false, "explanation": "「穏やか」と近い印象で、反対ではない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "手触りや印象を表す語で、「穏やか」の反対ではない。"}], "correct_answer": "荒々しい", "explanations": {"荒々しい": "様子が静かで落ち着いた「穏やか」と反対で、乱れて荒い様子を表す。", "静か": "「穏やか」と近い意味で、反対ではない。", "優しい": "「穏やか」と近い印象で、反対ではない。", "柔らかい": "手触りや印象を表す語で、「穏やか」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厳しい", "is_correct": true, "explanation": "気候が穏やかであるのと反対に、過酷で厳しい気候を表す。"}, {"text": "暖かい", "is_correct": false, "explanation": "気温を表す語で、「穏やか」の反対ではない。"}, {"text": "静か", "is_correct": false, "explanation": "「穏やか」と近い意味で、反対ではない。"}, {"text": "優しい", "is_correct": false, "explanation": "「穏やか」に近い印象の語で、反対ではない。"}], "correct_answer": "厳しい", "explanations": {"厳しい": "気候が穏やかであるのと反対に、過酷で厳しい気候を表す。", "暖かい": "気温を表す語で、「穏やか」の反対ではない。", "静か": "「穏やか」と近い意味で、反対ではない。", "優しい": "「穏やか」に近い印象の語で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気持ちや様子が落ち着いていて、静かなさま。", "primary_collocate": null, "pronunciation": "おだやか", "ipa": "odajaka", "syllable_count": 4, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "穏やかな", "complexity_tier": "T6", "furigana": "ミニマリストの思想(しそう)に基(もと)づき、必要(ひつよう)な要素(ようそ)だけを残(のこ)すことで、居住者(きょじゅうしゃ)はより穏(おだ)やかな日常(にちじょう)を送(おく)ることができます。", "sentence_source": "mined"}, {"text": "今日の海は穏やかです。", "target_word": "穏やかです", "complexity_tier": "T2", "furigana": "今日(きょう)の海(うみ)は穏(おだ)やかです。", "sentence_source": "generated"}, {"text": "穏やかな朝でした。", "target_word": "穏やかな", "complexity_tier": "T2", "furigana": "穏(おだ)やかな朝(あさ)でした。", "sentence_source": "generated"}, {"text": "祖父は穏やかに笑っていました。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "祖父(そふ)は穏(おだ)やかに笑(わら)っていました。", "sentence_source": "generated"}, {"text": "風がやみ、湖は穏やかになった。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "風(かぜ)がやみ、湖(みずうみ)は穏(おだ)やかになった。", "sentence_source": "generated"}, {"text": "彼女の声はいつも穏やかで、聞くと安心する。", "target_word": "穏やかで", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の声(こえ)はいつも穏(おだ)やかで、聞(き)くと安心(あんしん)する。", "sentence_source": "generated"}, {"text": "穏やかな気持ちで本を読んだ。", "target_word": "穏やかな", "complexity_tier": "T2", "furigana": "穏(おだ)やかな気持(きも)ちで本(ほん)を読(よ)んだ。", "sentence_source": "generated"}, {"text": "田舎では穏やかな時間が流れている。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "田舎(いなか)では穏(おだ)やかな時間(じかん)が流(なが)れている。", "sentence_source": "generated"}, {"text": "母は穏やかな表情で話を聞いてくれた。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "母(はは)は穏(おだ)やかな表情(ひょうじょう)で話(はなし)を聞(き)いてくれた。", "sentence_source": "generated"}, {"text": "この町は冬でも気候が穏やかだ。", "target_word": "穏やかだ", "complexity_tier": "T3", "furigana": "この町(まち)は冬(ふゆ)でも気候(きこう)が穏(おだ)やかだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穏やかな", "label": "活用"}, {"form": "穏やかに", "label": "活用"}, {"form": "穏やかだ", "label": "活用"}, {"form": "穏やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 気持ちや様子が静かで落ち着いたさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「より穏やかな日常」は、余分なものを減らした静かな暮らしを表し、文脈に合う。"}, {"text": "複雑な", "is_correct": false, "explanation": "形は合うが、要素を減らすという文脈と意味が合わない。"}, {"text": "派手な", "is_correct": false, "explanation": "形は合うが、必要なものだけを残す暮らしとは意味が合わない。"}, {"text": "乱暴な", "is_correct": false, "explanation": "形は合うが、日常の様子を表す語として意味が合わない。"}], "explanations": {"穏やかな": "「より穏やかな日常」は、余分なものを減らした静かな暮らしを表し、文脈に合う。", "複雑な": "形は合うが、要素を減らすという文脈と意味が合わない。", "派手な": "形は合うが、必要なものだけを残す暮らしとは意味が合わない。", "乱暴な": "形は合うが、日常の様子を表す語として意味が合わない。"}, "sentence_index": 0, "correct_answer": "穏やかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは穏やかに辛くて、汗が止まらない。", "explanation": "汗が止まらないほどの辛さは穏やかとは言えず、「穏やか」と矛盾するので誤り。"}, {"text": "試験の結果は穏やかで、不合格だった。", "explanation": "「穏やか」は結果の良し悪しを表さず、「不合格」とも意味がつながらないので誤り。"}, {"text": "穏やかな大雨で川があふれた。", "explanation": "川があふれるほどの大雨は静かな様子ではなく、「穏やか」と矛盾するので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「穏やかな気持ち」で、落ち着いた気持ちを表し、本を読む場面に合う。"}, {"text": "乱暴な", "is_correct": false, "explanation": "形は合うが、気持ちを表す語として本を読む場面と意味が合わない。"}, {"text": "派手な", "is_correct": false, "explanation": "形は合うが、気持ちを修飾すると意味が合わない。"}, {"text": "豪華な", "is_correct": false, "explanation": "形は合うが、気持ちの様子を表す語として意味が合わない。"}], "explanations": {"穏やかな": "「穏やかな気持ち」で、落ち着いた気持ちを表し、本を読む場面に合う。", "乱暴な": "形は合うが、気持ちを表す語として本を読む場面と意味が合わない。", "派手な": "形は合うが、気持ちを修飾すると意味が合わない。", "豪華な": "形は合うが、気持ちの様子を表す語として意味が合わない。"}, "sentence_index": 6, "correct_answer": "穏やかな"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店のカレーはとても穏やかで、一口で泣いた。", "explanation": "一口で泣くほど強い味は穏やかとは言えず、「穏やか」と矛盾するので誤り。"}, {"text": "穏やかな重さの荷物を一人では持てない。", "explanation": "「穏やか」は物の重さを表す語ではないので誤り。"}, {"text": "穏やかな試合で観客は熱狂して怒鳴った。", "explanation": "観客が熱狂する試合は静かな様子ではなく、「穏やか」と矛盾するので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "穏やかな嵐が町の屋根を吹き飛ばした。", "corrected_sentence": "激しい嵐が町の屋根を吹き飛ばした。", "error_description": "屋根を吹き飛ばす嵐は静かではないので、「穏やかな」は不適切。「激しい」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "穏やかです", "is_correct": true, "explanation": "文末で「海は穏やかです」と述べる丁寧な述語の形で、空所に合う。"}, {"text": "穏やかな", "is_correct": false, "explanation": "連体形なので、文末の述語としては使えない。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、「海は」の述語として文が終わらない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形なので、「海は〜さ。」では状態を述べる文にならない。"}], "correct_form": "穏やかです", "base_form": "穏やか", "form_label": "終止形（丁寧）", "sentence_index": 1, "explanations": {"穏やかです": "文末で「海は穏やかです」と述べる丁寧な述語の形で、空所に合う。", "穏やかな": "連体形なので、文末の述語としては使えない。", "穏やかに": "連用形なので、「海は」の述語として文が終わらない。", "穏やかさ": "名詞形なので、「海は〜さ。」では状態を述べる文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51682, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の山は穏やかで、吹雪で歩けなかった。", "corrected_sentence": "冬の山は厳しくて、吹雪で歩けなかった。", "error_description": "吹雪で歩けない山は穏やかではないので、「穏やか」は不適切。「厳しい」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「時間」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、名詞「時間」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形なので、名詞「時間」の前では使えない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形なので、「時間」の前に置くと意味が通らない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 7, "explanations": {"穏やかな": "「時間」を修飾する連体形で、空所に合う。", "穏やかに": "連用形なので、名詞「時間」を直接修飾できない。", "穏やかだ": "終止形なので、名詞「時間」の前では使えない。", "穏やかさ": "名詞形なので、「時間」の前に置くと意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51683, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在する物を示す「家具が」。"}, {"text": "を", "is_correct": false, "explanation": "「あります」の前に目的語を示す「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「あります」にはつながらない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「あります」にはつながらない。"}], "correct_answer": "が", "explanations": {"が": "存在する物を示す「家具が」。", "を": "「あります」の前に目的語を示す「を」は使えない。", "へ": "方向を示す助詞で、「あります」にはつながらない。", "から": "起点を示す助詞で、「あります」にはつながらない。"}, "error_tags": {"を": "object", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51683, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「置く」の対象を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "「置いた」の対象は「を」で示すため、ここでは不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞で、「置いた」にはつながらない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示す助詞で、ここでは文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「置く」の対象を示す助詞。", "が": "「置いた」の対象は「を」で示すため、ここでは不自然。", "の": "名詞をつなぐ助詞で、「置いた」にはつながらない。", "と": "並列や共同を示す助詞で、ここでは文法的に成り立たない。"}, "error_tags": {"が": "subject", "の": "possessive", "と": "conjunction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51683, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の中で使うもの。机や椅子、たんすなど。", "primary_collocate": null, "pronunciation": "かぐ", "ipa": "kaɡɯ", "syllable_count": 2, "sentences": [{"text": "家具を買います。", "target_word": "家具", "complexity_tier": "T2", "furigana": "家具(かぐ)を買(か)います。", "sentence_source": "generated"}, {"text": "部屋に家具があります。", "target_word": "家具", "complexity_tier": "T2", "furigana": "部屋(へや)に家具(かぐ)があります。", "sentence_source": "generated"}, {"text": "この家具は古いです。", "target_word": "家具", "complexity_tier": "T2", "furigana": "この家具(かぐ)は古(ふる)いです。", "sentence_source": "generated"}, {"text": "机も椅子も家具です。", "target_word": "家具", "complexity_tier": "T2", "furigana": "机(つくえ)も椅子(いす)も家具(かぐ)です。", "sentence_source": "generated"}, {"text": "新しい家具が届きました。", "target_word": "家具", "complexity_tier": "T2", "furigana": "新(あたら)しい家具(かぐ)が届(とど)きました。", "sentence_source": "generated"}, {"text": "家具を動かして、掃除した。", "target_word": "家具", "complexity_tier": "T3", "furigana": "家具(かぐ)を動(うご)かして、掃除(そうじ)した。", "sentence_source": "generated"}, {"text": "姉は家具の店で働いています。", "target_word": "家具", "complexity_tier": "T3", "furigana": "姉(あね)は家具(かぐ)の店(みせ)で働(はたら)いています。", "sentence_source": "generated"}, {"text": "小さな部屋に家具を置いた。", "target_word": "家具", "complexity_tier": "T2", "furigana": "小(ちい)さな部屋(へや)に家具(かぐ)を置(お)いた。", "sentence_source": "generated"}, {"text": "家具がたくさんある家に住みたい。", "target_word": "家具", "complexity_tier": "T3", "furigana": "家具(かぐ)がたくさんある家(いえ)に住(す)みたい。", "sentence_source": "generated"}, {"text": "家具は木でできています。", "target_word": "家具", "complexity_tier": "T3", "furigana": "家具(かぐ)は木(き)でできています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家具屋", "label": "派生"}, {"form": "家具店", "label": "派生"}, {"form": "家具類", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 家の中で使う机や椅子などの物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51683, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家具", "is_correct": true, "explanation": "見出し語「かぐ」そのもの。"}, {"text": "籠", "is_correct": false, "explanation": "「かご」で、2拍目が「ぐ」と「ご」で異なる。"}, {"text": "鍵", "is_correct": false, "explanation": "「かぎ」で、2拍目が「ぐ」と「ぎ」で異なる。"}, {"text": "数", "is_correct": false, "explanation": "「かず」で、2拍目が「ぐ」と「ず」で異なる。"}, {"text": "株", "is_correct": false, "explanation": "「かぶ」で、2拍目が「ぐ」と「ぶ」で異なる。"}], "explanations": {"家具": "見出し語「かぐ」そのもの。", "籠": "「かご」で、2拍目が「ぐ」と「ご」で異なる。", "鍵": "「かぎ」で、2拍目が「ぐ」と「ぎ」で異なる。", "数": "「かず」で、2拍目が「ぐ」と「ず」で異なる。", "株": "「かぶ」で、2拍目が「ぐ」と「ぶ」で異なる。"}, "sentence_index": null, "correct_answer": "家具"}, "level_3": {"options": [{"text": "家具", "is_correct": true, "explanation": "買う物として自然な、家の中で使う物。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は買う物ではなく意味が合わない。"}, {"text": "気分", "is_correct": false, "explanation": "形は合うが、気分は買う物ではなく意味が合わない。"}, {"text": "失敗", "is_correct": false, "explanation": "形は合うが、失敗は買う物ではなく意味が合わない。"}], "explanations": {"家具": "買う物として自然な、家の中で使う物。", "天気": "形は合うが、天気は買う物ではなく意味が合わない。", "気分": "形は合うが、気分は買う物ではなく意味が合わない。", "失敗": "形は合うが、失敗は買う物ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "家具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、家具を飲んでから学校に行きます。", "explanation": "家具は飲み物ではなく、用法が誤り。"}, {"text": "家具は空を飛んで町へ行きました。", "explanation": "家具は自分で飛ぶものではなく、用法が誤り。"}, {"text": "家具を読んで物語を楽しみました。", "explanation": "家具は読む対象ではなく、用法が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_war