INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51684, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の中で生活に使う道具や設備の総称。机、椅子、ベッド、棚など。", "primary_collocate": null, "pronunciation": "かぐ", "ipa": "kaɡɯ", "syllable_count": 2, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "家具", "complexity_tier": "T6", "furigana": "具体的(ぐたいてき)には、無垢材(むくざい)の家具(かぐ)と白壁(しらかべ)の組(く)み合(あ)わせ、あるいは間接照明(かんせつしょうめい)による陰影(いんえい)の演出(えんしゅつ)などが効果的(こうかてき)です。", "sentence_source": "mined"}, {"text": "新しい家具を買いました。", "target_word": "家具", "complexity_tier": "T2", "furigana": "新(あたら)しい家具(かぐ)を買(か)いました。", "sentence_source": "generated"}, {"text": "この部屋は家具が少ない。", "target_word": "家具", "complexity_tier": "T2", "furigana": "この部屋(へや)は家具(かぐ)が少(すく)ない。", "sentence_source": "generated"}, {"text": "引っ越しのとき、古い家具を捨てた。", "target_word": "家具", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しのとき、古(ふる)い家具(かぐ)を捨(す)てた。", "sentence_source": "generated"}, {"text": "家具の配置を変えて、部屋を広く使っている。", "target_word": "家具", "complexity_tier": "T3", "furigana": "家具(かぐ)の配置(はいち)を変(か)えて、部屋(へや)を広(ひろ)く使(つか)っている。", "sentence_source": "generated"}, {"text": "祖父が作った家具は、今も大切に使われている。", "target_word": "家具", "complexity_tier": "T4", "furigana": "祖父(そふ)が作(つく)った家具(かぐ)は、今(いま)も大切(たいせつ)に使(つか)われている。", "sentence_source": "generated"}, {"text": "木の家具が好きで、休日に店を見て回る。", "target_word": "家具", "complexity_tier": "T3", "furigana": "木(き)の家具(かぐ)が好(す)きで、休日(きゅうじつ)に店(みせ)を見(み)て回(まわ)る。", "sentence_source": "generated"}, {"text": "地震に備えて、家具を壁に固定しておこう。", "target_word": "家具", "complexity_tier": "T3", "furigana": "地震(じしん)に備(そな)えて、家具(かぐ)を壁(かべ)に固定(こてい)しておこう。", "sentence_source": "generated"}, {"text": "家具や家電をまとめて運んでもらった。", "target_word": "家具", "complexity_tier": "T3", "furigana": "家具(かぐ)や家電(かでん)をまとめて運(はこ)んでもらった。", "sentence_source": "generated"}, {"text": "安い家具でも、手入れすれば長持ちする。", "target_word": "家具", "complexity_tier": "T4", "furigana": "安(やす)い家具(かぐ)でも、手入(てい)れすれば長持(なが)もちする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家具屋", "label": "派生"}, {"form": "家具店", "label": "派生"}, {"form": "家具類", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 家の中で使う道具や設備の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51684, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家具", "is_correct": true, "explanation": "見出し語「かぐ」そのもの。"}, {"text": "籠", "is_correct": false, "explanation": "「かご」で、2拍目が「ぐ」と「ご」で異なる。"}, {"text": "鍵", "is_correct": false, "explanation": "「かぎ」で、2拍目が「ぐ」と「ぎ」で異なる。"}, {"text": "数", "is_correct": false, "explanation": "「かず」で、2拍目が「ぐ」と「ず」で異なる。"}, {"text": "株", "is_correct": false, "explanation": "「かぶ」で、2拍目が「ぐ」と「ぶ」で異なる。"}], "explanations": {"家具": "見出し語「かぐ」そのもの。", "籠": "「かご」で、2拍目が「ぐ」と「ご」で異なる。", "鍵": "「かぎ」で、2拍目が「ぐ」と「ぎ」で異なる。", "数": "「かず」で、2拍目が「ぐ」と「ず」で異なる。", "株": "「かぶ」で、2拍目が「ぐ」と「ぶ」で異なる。"}, "sentence_index": null, "correct_answer": "家具"}, "level_3": {"options": [{"text": "家具", "is_correct": true, "explanation": "無垢材で作る室内の道具で、白壁との組み合わせの文脈に合う。"}, {"text": "洗剤", "is_correct": false, "explanation": "形は合うが、無垢材でできる物ではなく意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、無垢材と白壁の演出に意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、無垢材の物ではなく意味が合わない。"}], "explanations": {"家具": "無垢材で作る室内の道具で、白壁との組み合わせの文脈に合う。", "洗剤": "形は合うが、無垢材でできる物ではなく意味が合わない。", "野菜": "形は合うが、無垢材と白壁の演出に意味が合わない。", "天気": "形は合うが、無垢材の物ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "家具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜は家具を食べて、おなかがいっぱいになった。", "explanation": "家具は食べ物ではなく、意味の使い方が誤り。"}, {"text": "家具に電話をかけて、遅れると伝えた。", "explanation": "家具は電話をかける相手になれず、用法が誤り。"}, {"text": "家具を読んで、物語を楽しんだ。", "explanation": "家具は読む対象ではなく、用法が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51684, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "家具", "is_correct": true, "explanation": "見出し語「かぐ」そのもの。"}, {"text": "影", "is_correct": false, "explanation": "「かげ」で、2拍目が「ぐ」と「げ」で異なる。"}, {"text": "風", "is_correct": false, "explanation": "「かぜ」で、2拍目が「ぐ」と「ぜ」で異なる。"}, {"text": "傘", "is_correct": false, "explanation": "「かさ」で、2拍目が「ぐ」と「さ」で異なる。"}, {"text": "釜", "is_correct": false, "explanation": "「かま」で、2拍目が「ぐ」と「ま」で異なる。"}], "explanations": {"家具": "見出し語「かぐ」そのもの。", "影": "「かげ」で、2拍目が「ぐ」と「げ」で異なる。", "風": "「かぜ」で、2拍目が「ぐ」と「ぜ」で異なる。", "傘": "「かさ」で、2拍目が「ぐ」と「さ」で異なる。", "釜": "「かま」で、2拍目が「ぐ」と「ま」で異なる。"}, "sentence_index": null, "correct_answer": "家具"}, "level_3": {"options": [{"text": "家具", "is_correct": true, "explanation": "木でできた家具が好きで店を見て回るという意味に合う。"}, {"text": "気分", "is_correct": false, "explanation": "形は合うが、木の物ではなく店で見る対象にならず意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、店で見て回る物ではなく意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、店で見て回る物ではなく意味が合わない。"}], "explanations": {"家具": "木でできた家具が好きで店を見て回るという意味に合う。", "気分": "形は合うが、木の物ではなく店で見る対象にならず意味が合わない。", "天気": "形は合うが、店で見て回る物ではなく意味が合わない。", "季節": "形は合うが、店で見て回る物ではなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "家具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎朝家具を飲んでから出かける。", "explanation": "家具は飲み物ではなく、用法が誤り。"}, {"text": "家具が雨になって、傘を持って出た。", "explanation": "家具は天気のように変化せず、用法が誤り。"}, {"text": "家具を着て、学校へ行った。", "explanation": "家具は身に着ける服ではなく、用法が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51684, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引っ越しで、古い家具に捨てた。", "corrected_sentence": "引っ越しで、古い家具を捨てた。", "error_description": "「捨てる」の対象を示す助詞は「を」で、「家具に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51684, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちの部屋には、大きな家具へある。", "corrected_sentence": "友だちの部屋には、大きな家具がある。", "error_description": "存在する物を示す助詞は「が」で、「家具へ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「白壁にする」で、変化の結果を表す「に」。"}, {"text": "が", "is_correct": false, "explanation": "「白壁がしました」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「白壁のしました」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「白壁へしました」は結果を表せず誤り。"}], "correct_answer": "に", "explanations": {"に": "「白壁にする」で、変化の結果を表す「に」。", "が": "「白壁がしました」では文が成り立たない。", "の": "「白壁のしました」では文が成り立たない。", "へ": "「白壁へしました」は結果を表せず誤り。"}, "error_tags": {"が": "subject_misuse", "の": "possessive_misuse", "へ": "direction_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「白壁の家」で、名詞を修飾する「の」。"}, {"text": "を", "is_correct": false, "explanation": "「白壁を家が」では家を修飾できず誤り。"}, {"text": "で", "is_correct": false, "explanation": "「白壁で家が多い」は意味が通らず誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「白壁へ家が」は方向を表せず誤り。"}], "correct_answer": "の", "explanations": {"の": "「白壁の家」で、名詞を修飾する「の」。", "を": "「白壁を家が」では家を修飾できず誤り。", "で": "「白壁で家が多い」は意味が通らず誤り。", "へ": "「白壁へ家が」は方向を表せず誤り。"}, "error_tags": {"を": "object_misuse", "で": "location_misuse", "へ": "direction_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "白く塗って仕上げた壁。", "primary_collocate": null, "pronunciation": "しらかべ", "ipa": "ɕiɾakabe", "syllable_count": 4, "sentences": [{"text": "白壁の家に住んでいます。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "白壁(しらかべ)の家(いえ)に住(す)んでいます。", "sentence_source": "generated"}, {"text": "古い壁を白壁にしました。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "古(ふる)い壁(かべ)を白壁(しらかべ)にしました。", "sentence_source": "generated"}, {"text": "この白壁はきれいです。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "この白壁(しらかべ)はきれいです。", "sentence_source": "generated"}, {"text": "白壁に絵をかけた。", "target_word": "白壁", "complexity_tier": "T1", "furigana": "白壁(しらかべ)に絵(え)をかけた。", "sentence_source": "generated"}, {"text": "白壁の前で写真を撮った。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "白壁(しらかべ)の前(まえ)で写真(しゃしん)を撮(と)った。", "sentence_source": "generated"}, {"text": "白壁は明るいです。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "白壁(しらかべ)は明(あか)るいです。", "sentence_source": "generated"}, {"text": "弟が白壁にいたずらをした。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "弟(おとうと)が白壁(しらかべ)にいたずらをした。", "sentence_source": "generated"}, {"text": "町に白壁の家が多い。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "町(まち)に白壁(しらかべ)の家(いえ)が多(おお)い。", "sentence_source": "generated"}, {"text": "白壁と青い空が好きだ。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "白壁(しらかべ)と青(あお)い空(そら)が好(す)きだ。", "sentence_source": "generated"}, {"text": "白壁を塗るのは大変だった。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "白壁(しらかべ)を塗(ぬ)るのは大変(たいへん)だった。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 白色に塗って仕上げた壁のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白壁", "is_correct": true, "explanation": "住んでいる家の特徴として、白く塗った壁の家は自然。"}, {"text": "計算", "is_correct": false, "explanation": "形は合うが、計算の家という意味は合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "形は合うが、挨拶の家という意味は合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、宿題の家という意味は合わない。"}], "explanations": {"白壁": "住んでいる家の特徴として、白く塗った壁の家は自然。", "計算": "形は合うが、計算の家という意味は合わない。", "挨拶": "形は合うが、挨拶の家という意味は合わない。", "宿題": "形は合うが、宿題の家という意味は合わない。"}, "sentence_index": 0, "correct_answer": "白壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "白壁を泳いで家に帰った。", "explanation": "白壁は壁なので、泳ぐ場所としては使えない。"}, {"text": "白壁を飲んだら、のどが痛くなった。", "explanation": "白壁は飲むものではないので、「飲む」との組み合わせは誤り。"}, {"text": "白壁は走るのが速い。", "explanation": "白壁は動かない壁なので、走る主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白壁", "is_correct": true, "explanation": "弟がいたずらをする対象として、白い壁は自然。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気にいたずらをするという意味は合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節にいたずらをするという意味は合わない。"}, {"text": "意見", "is_correct": false, "explanation": "形は合うが、意見にいたずらをするという意味は合わない。"}], "explanations": {"白壁": "弟がいたずらをする対象として、白い壁は自然。", "天気": "形は合うが、天気にいたずらをするという意味は合わない。", "季節": "形は合うが、季節にいたずらをするという意味は合わない。", "意見": "形は合うが、意見にいたずらをするという意味は合わない。"}, "sentence_index": 6, "correct_answer": "白壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "白壁を食べるのは大変だった。", "explanation": "白壁は食べるものではないので、「食べる」との組み合わせは誤り。"}, {"text": "白壁を着るのは大変だった。", "explanation": "白壁は服ではないので、「着る」対象にならず誤り。"}, {"text": "白壁を話すのは大変だった。", "explanation": "白壁は話す対象にならないので、「話す」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい白壁を絵をかけた。", "corrected_sentence": "新しい白壁に絵をかけた。", "error_description": "絵をかける場所を示す助詞は「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51685, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は毎年、白壁が塗り直す。", "corrected_sentence": "兄は毎年、白壁を塗り直す。", "error_description": "「塗り直す」の対象を示す助詞は「が」ではなく「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51686, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「家が見えます」で、見える対象を表す主格の「が」。"}, {"text": "で", "is_correct": false, "explanation": "「家で見えます」では「見えます」と結びつかず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「家の見えます」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「家へ見えます」は方向を表せず誤り。"}], "correct_answer": "が", "explanations": {"が": "「家が見えます」で、見える対象を表す主格の「が」。", "で": "「家で見えます」では「見えます」と結びつかず不自然。", "の": "「家の見えます」では文が成り立たない。", "へ": "「家へ見えます」は方向を表せず誤り。"}, "error_tags": {"で": "location_misuse", "の": "possessive_misuse", "へ": "direction_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51686, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「道を歩く」で、移動する場所を表す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「道に歩いた」では「歩く」と結びつかず誤り。"}, {"text": "と", "is_correct": false, "explanation": "「道と歩いた」では意味が通らず誤り。"}, {"text": "の", "is_correct": false, "explanation": "「道の歩いた」では文が終われず誤り。"}], "correct_answer": "を", "explanations": {"を": "「道を歩く」で、移動する場所を表す「を」。", "に": "「道に歩いた」では「歩く」と結びつかず誤り。", "と": "「道と歩いた」では意味が通らず誤り。", "の": "「道の歩いた」では文が終われず誤り。"}, "error_tags": {"に": "target_misuse", "と": "accompaniment_misuse", "の": "possessive_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "白色に塗られた壁。特に、内装や外壁で白く仕上げた壁を指す。", "primary_collocate": null, "pronunciation": "しらかべ", "ipa": "ɕiɾakabe", "syllable_count": 4, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "白壁", "complexity_tier": "T6", "furigana": "具体的(ぐたいてき)には、無垢材(むくざい)の家具(かぐ)と白壁(しらかべ)の組(く)み合(あ)わせ、あるいは間接照明(かんせつしょうめい)による陰影(いんえい)の演出(えんしゅつ)などが効果的(こうかてき)です。", "sentence_source": "mined"}, {"text": "白壁の家が見えます。", "target_word": "白壁", "complexity_tier": "T2", "furigana": "白壁(しらかべ)の家(いえ)が見(み)えます。", "sentence_source": "generated"}, {"text": "古い町には白壁の蔵が並んでいる。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "古(ふる)い町(まち)には白壁(しらかべ)の蔵(くら)が並(なら)んでいる。", "sentence_source": "generated"}, {"text": "白壁に木の影が映っている。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "白壁(しらかべ)に木(き)の影(かげ)が映(うつ)っている。", "sentence_source": "generated"}, {"text": "部屋を白壁にして、明るくした。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "部屋(へや)を白壁(しらかべ)にして、明(あか)るくした。", "sentence_source": "generated"}, {"text": "白壁は汚れが目立ちやすい。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "白壁(しらかべ)は汚(よご)れが目立(めだ)ちやすい。", "sentence_source": "generated"}, {"text": "夕日を受けて、白壁が赤く染まった。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "夕日(ゆうひ)を受(う)けて、白壁(しらかべ)が赤(あか)く染(そ)まった。", "sentence_source": "generated"}, {"text": "京都で白壁が続く道を歩いた。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "京都(きょうと)で白壁(しらかべ)が続(つづ)く道(みち)を歩(ある)いた。", "sentence_source": "generated"}, {"text": "白壁と黒い屋根の組み合わせが美しい。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "白壁(しらかべ)と黒(くろ)い屋根(やね)の組(く)み合(あ)わせが美(うつく)しい。", "sentence_source": "generated"}, {"text": "古い家の白壁を、職人が塗り直した。", "target_word": "白壁", "complexity_tier": "T3", "furigana": "古(ふる)い家(いえ)の白壁(しらかべ)を、職人(しょくにん)が塗(ぬ)り直(なお)した。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 白く塗られた壁、特に内装や外壁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51686, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白壁", "is_correct": true, "explanation": "家具との組み合わせで陰影が映える、白く塗った壁を指すので文意に合う。"}, {"text": "騒音", "is_correct": false, "explanation": "形は合うが、騒音と家具の組み合わせが効果的という意味は合わない。"}, {"text": "税金", "is_correct": false, "explanation": "形は合うが、税金と家具の組み合わせが演出になるという意味は合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、台風と家具の組み合わせが演出になるという意味は合わない。"}], "explanations": {"白壁": "家具との組み合わせで陰影が映える、白く塗った壁を指すので文意に合う。", "騒音": "形は合うが、騒音と家具の組み合わせが効果的という意味は合わない。", "税金": "形は合うが、税金と家具の組み合わせが演出になるという意味は合わない。", "台風": "形は合うが、台風と家具の組み合わせが演出になるという意味は合わない。"}, "sentence_index": 0, "correct_answer": "白壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、白壁を食べてから出かける。", "explanation": "白壁は塗られた壁なので、食べるものとして使うのは誤り。"}, {"text": "白壁は空を飛んで海を渡った。", "explanation": "白壁は動かない壁なので、飛んで海を渡る主語にはならない。"}, {"text": "彼は白壁を読んで感動した。", "explanation": "白壁は読む対象ではないので、「読む」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51686, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白壁", "is_correct": true, "explanation": "夕日を受けて赤く染まる白い壁として自然に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、約束が夕日で赤く染まるという意味は合わない。"}, {"text": "試験", "is_correct": false, "explanation": "形は合うが、試験が夕日で赤く染まるという意味は合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段が夕日で赤く染まるという意味は合わない。"}], "explanations": {"白壁": "夕日を受けて赤く染まる白い壁として自然に合う。", "約束": "形は合うが、約束が夕日で赤く染まるという意味は合わない。", "試験": "形は合うが、試験が夕日で赤く染まるという意味は合わない。", "値段": "形は合うが、値段が夕日で赤く染まるという意味は合わない。"}, "sentence_index": 6, "correct_answer": "白壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "白壁を歌いながら、駅まで歩いた。", "explanation": "白壁は歌う対象ではないので、「歌う」との組み合わせは誤り。"}, {"text": "母は白壁を洗濯機に入れて洗った。", "explanation": "白壁は建物の壁なので、洗濯機で洗うものとしては使えない。"}, {"text": "白壁が笑って、私に話しかけた。", "explanation": "白壁は壁なので、笑って話しかける主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51686, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の白壁を木の影が映っている。", "corrected_sentence": "庭の白壁に木の影が映っている。", "error_description": "影が映る場所を示す助詞は「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
