INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51687, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まじりけがないこと。きれいなこと。", "primary_collocate": null, "pronunciation": "むく", "ipa": "mɯkɯ", "syllable_count": 2, "sentences": [{"text": "赤ちゃんの無垢な笑顔を見ると、心がなごむ。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの無垢[むく]な笑顔[えがお]を見[み]ると、心[こころ]がなごむ。", "sentence_source": "generated"}, {"text": "子どものころは、だれもが無垢な心を持っている。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "子[こ]どものころは、だれもが無垢[むく]な心[こころ]を持[も]っている。", "sentence_source": "generated"}, {"text": "彼女は無垢な目で、空を見上げていた。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は無垢[むく]な目[め]で、空[そら]を見上[みあ]げていた。", "sentence_source": "generated"}, {"text": "この机は、無垢の木で作られていて、とても丈夫だ。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "この机[つくえ]は、無垢[むく]の木[き]で作[つく]られていて、とても丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "雪が降って、町は無垢な白さに包まれた。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]って、町[まち]は無垢[むく]な白[しろ]さに包[つつ]まれた。", "sentence_source": "generated"}, {"text": "彼女の無垢な寝顔を、母はじっと見つめていた。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "彼女の無垢[むく]な寝顔[ねがお]を、母はじっと見つめていた。", "sentence_source": "generated"}, {"text": "無垢な気持ちで絵を描くのが、いちばん楽しい。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "無垢[むく]な気持[きも]ちで絵[え]を描[か]くのが、いちばん楽[たの]しい。", "sentence_source": "generated"}, {"text": "生まれたばかりの子馬は、無垢な顔で母を見ていた。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "生[う]まれたばかりの子馬[こうま]は、無垢[むく]な顔[かお]で母[はは]を見[み]ていた。", "sentence_source": "generated"}, {"text": "無垢の金でできた指輪は、重みがある。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "無垢[むく]の金[きん]でできた指輪[ゆびわ]は、重[おも]みがある。", "sentence_source": "generated"}, {"text": "悪いことを知らない無垢な子どもを、だましてはいけない。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "悪[わる]いことを知[し]らない無垢[むく]な子[こ]どもを、だましてはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無垢な", "label": "連体形"}, {"form": "無垢の", "label": "の形"}, {"form": "無垢だ", "label": "終止形"}, {"form": "無垢で", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "他のものがまじらず、よごれのないこと。心や素材が純粋できれいなさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51687, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無垢", "is_correct": true, "explanation": "まじりけのない純粋な様子を表し、「赤ちゃんの無垢な笑顔」と文意が通る"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくい様子を表し、笑顔の描写には使えない"}, {"text": "煩雑", "is_correct": false, "explanation": "手続きなどが込み入っている様子で、「煩雑な笑顔」は意味が通らない"}, {"text": "多忙", "is_correct": false, "explanation": "忙しい様子を表し、笑顔の性質として「多忙な笑顔」は成り立たない"}], "explanations": {"無垢": "まじりけのない純粋な様子を表し、「赤ちゃんの無垢な笑顔」と文意が通る", "頑丈": "丈夫で壊れにくい様子を表し、笑顔の描写には使えない", "煩雑": "手続きなどが込み入っている様子で、「煩雑な笑顔」は意味が通らない", "多忙": "忙しい様子を表し、笑顔の性質として「多忙な笑顔」は成り立たない"}, "sentence_index": 0, "correct_answer": "無垢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は無垢な性格で、ほしいものは何でも手に入れようとする。", "explanation": "ここは〈無欲〉（欲がないこと）の意味。無垢は純粋さを表すので、欲の少なさを表すことはできない"}, {"text": "期限が過ぎたので、この券は無垢になった。", "explanation": "ここは〈無効〉（効力がなくなること）の意味。無垢は純粋さを表すので、券の効力には使えない"}, {"text": "無垢な星が、夜空に数えきれないほど輝いていた。", "explanation": "ここは〈無数〉（数えきれないほど多いこと）の意味。無垢は純粋さを表すので、数の多さを表すことはできない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51687, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無垢", "is_correct": true, "explanation": "素直でまじりけのない気持ちを表し、「無垢な気持ちで絵を描く」と合う"}, {"text": "手狭", "is_correct": false, "explanation": "場所が狭いことを表し、気持ちには使えない"}, {"text": "肥沃", "is_correct": false, "explanation": "土地が豊かな様子を表し、「肥沃な気持ち」は意味が通らない"}, {"text": "莫大", "is_correct": false, "explanation": "量や規模が大きいことを表し、気持ちの描写には合わない"}], "explanations": {"無垢": "素直でまじりけのない気持ちを表し、「無垢な気持ちで絵を描く」と合う", "手狭": "場所が狭いことを表し、気持ちには使えない", "肥沃": "土地が豊かな様子を表し、「肥沃な気持ち」は意味が通らない", "莫大": "量や規模が大きいことを表し、気持ちの描写には合わない"}, "sentence_index": 6, "correct_answer": "無垢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "材料を無垢にしないように、少しずつ使った。", "explanation": "ここは〈無駄〉（使いどころを誤ること）の意味。無垢は純粋さを表し、浪費の意味では使えない"}, {"text": "無垢なスケジュールで、体を壊してしまった。", "explanation": "ここは〈無理〉（道理に合わないほど厳しいこと）の意味。無垢は予定の厳しさを表せない"}, {"text": "この店では、お茶は無垢で飲み放題だ。", "explanation": "ここは〈無料〉（お金がかからないこと）の意味。無垢は純粋さを表すので、代金がかからないことは表せない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51687, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の無垢に笑顔に、みんなが癒やされた。", "corrected_sentence": "彼女の無垢な笑顔に、みんなが癒やされた。", "error_description": "名詞「笑顔」を修飾するには連体形「無垢な」が必要。「無垢に」は連用形で名詞を直接修飾できないため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無垢な", "is_correct": true, "explanation": "連体形。「無垢な心」と連体形で名詞を修飾しており、この形が答え"}, {"text": "無垢だ", "is_correct": false, "explanation": "終止形。「心」を直接修飾できず、「無垢だ心」は文として成り立たない"}, {"text": "無垢で", "is_correct": false, "explanation": "連用形。名詞を修飾する形ではないため、「無垢で心を持っている」は不自然"}, {"text": "無垢に", "is_correct": false, "explanation": "連用形（副詞的）。「無垢に持っている」となり、「心」を修飾できない"}], "correct_form": "無垢な", "base_form": "無垢だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"無垢な": "連体形。「無垢な心」と連体形で名詞を修飾しており、この形が答え", "無垢だ": "終止形。「心」を直接修飾できず、「無垢だ心」は文として成り立たない", "無垢で": "連用形。名詞を修飾する形ではないため、「無垢で心を持っている」は不自然", "無垢に": "連用形（副詞的）。「無垢に持っている」となり、「心」を修飾できない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51687, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの無垢さを、大人は心を打たれる。", "corrected_sentence": "子どもの無垢さに、大人は心を打たれる。", "error_description": "「心を打たれる」の原因は「に」で示す。「無垢さを」と目的語の「を」を使うと、文の構造が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無垢な", "is_correct": true, "explanation": "連体形。「無垢な顔」と連体形で名詞「顔」を修飾している"}, {"text": "無垢だった", "is_correct": false, "explanation": "過去形。「無垢だった顔で」は修飾にならず、文の流れに合わない"}, {"text": "無垢ならば", "is_correct": false, "explanation": "仮定形。「無垢ならば顔で」は条件節になり、文が成り立たない"}, {"text": "無垢だろう", "is_correct": false, "explanation": "推量形。名詞「顔」を修飾できず、文脈と合わない"}], "correct_form": "無垢な", "base_form": "無垢だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"無垢な": "連体形。「無垢な顔」と連体形で名詞「顔」を修飾している", "無垢だった": "過去形。「無垢だった顔で」は修飾にならず、文の流れに合わない", "無垢ならば": "仮定形。「無垢ならば顔で」は条件節になり、文が成り立たない", "無垢だろう": "推量形。名詞「顔」を修飾できず、文脈と合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「陰影がきれいです」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "形容詞「きれいです」の前に目的語の「を」は置けない。"}, {"text": "に", "is_correct": false, "explanation": "「陰影にきれいです」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「陰影へきれいです」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「陰影がきれいです」の主語を示す。", "を": "形容詞「きれいです」の前に目的語の「を」は置けない。", "に": "「陰影にきれいです」は文として成り立たない。", "へ": "「へ」は方向を表し、「陰影へきれいです」は成り立たない。"}, "error_tags": {"を": "object_marker_with_adjective", "に": "wrong_case_for_subject", "へ": "direction_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「陰影をつける」で目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「陰影がつけて」は主語と動詞の関係が合わず非文になる。"}, {"text": "で", "is_correct": false, "explanation": "「陰影でつけて」は「つける」の目的語がなくなり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「陰影とつけて」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「陰影をつける」で目的語を示す。", "が": "「陰影がつけて」は主語と動詞の関係が合わず非文になる。", "で": "「陰影でつけて」は「つける」の目的語がなくなり不自然。", "と": "「陰影とつけて」は文として成り立たない。"}, "error_tags": {"が": "subject_for_object", "で": "wrong_case_for_object", "と": "wrong_case_for_object"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "光が当たらないためにできる、暗い部分や形。光と影のコントラストによって生まれる模様や効果。", "primary_collocate": null, "pronunciation": "いんえい", "ipa": "iŋeː", "syllable_count": 4, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "陰影", "complexity_tier": "T6", "furigana": "具体的[ぐたいてき]には、無垢材[むくざい]の家具[かぐ]と白壁[しろかべ]の組[く]み合[あ]わせ、あるいは間接照明[かんせつしょうめい]による陰影[いんえい]の演出[えんしゅつ]などが効果的[こうかてき]です。", "sentence_source": "mined"}, {"text": "この写真は陰影がきれいです。", "target_word": "陰影", "complexity_tier": "T2", "furigana": "この写真[しゃしん]は陰影[いんえい]がきれいです。", "sentence_source": "generated"}, {"text": "壁に陰影ができている。", "target_word": "陰影", "complexity_tier": "T3", "furigana": "壁[かべ]に陰影[いんえい]ができている。", "sentence_source": "generated"}, {"text": "彫刻の陰影を楽しみます。", "target_word": "陰影", "complexity_tier": "T2", "furigana": "彫刻[ちょうこく]の陰影[いんえい]を楽[たの]しみます。", "sentence_source": "generated"}, {"text": "夕方になると、陰影が濃くなります。", "target_word": "陰影", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になると、陰影[いんえい]が濃[こ]くなります。", "sentence_source": "generated"}, {"text": "陰影のある絵が好きです。", "target_word": "陰影", "complexity_tier": "T2", "furigana": "陰影[いんえい]のある絵[え]が好[す]きです。", "sentence_source": "generated"}, {"text": "光の当て方で陰影は変わる。", "target_word": "陰影", "complexity_tier": "T3", "furigana": "光[ひかり]の当[あ]て方[かた]で陰影[いんえい]は変[か]わる。", "sentence_source": "generated"}, {"text": "画家は陰影をつけて立体感を出した。", "target_word": "陰影", "complexity_tier": "T3", "furigana": "画家[がか]は陰影[いんえい]をつけて立体感[りったいかん]を出[だ]した。", "sentence_source": "generated"}, {"text": "この部屋は陰影に富んでいる。", "target_word": "陰影", "complexity_tier": "T3", "furigana": "この部屋[へや]は陰影[いんえい]に富[と]んでいる。", "sentence_source": "generated"}, {"text": "陰影の深い写真を撮りたい。", "target_word": "陰影", "complexity_tier": "T3", "furigana": "陰影[いんえい]の深[ふか]い写真[しゃしん]を撮[と]りたい。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 光と影が作る明暗の模様や効果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陰影", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "陣営", "is_correct": false, "explanation": "「じんえい」で、最初の一音だけが違う実在語です。"}, {"text": "新鋭", "is_correct": false, "explanation": "「しんえい」で、最初の一音だけが違う実在語です。"}, {"text": "近影", "is_correct": false, "explanation": "「きんえい」で、最初の一音だけが違う実在語です。"}, {"text": "引退", "is_correct": false, "explanation": "「いんたい」で、三音目だけが違う実在語です。"}], "explanations": {"陰影": "見出し語そのものです。", "陣営": "「じんえい」で、最初の一音だけが違う実在語です。", "新鋭": "「しんえい」で、最初の一音だけが違う実在語です。", "近影": "「きんえい」で、最初の一音だけが違う実在語です。", "引退": "「いんたい」で、三音目だけが違う実在語です。"}, "sentence_index": null, "correct_answer": "陰影"}, "level_3": {"options": [{"text": "陰影", "is_correct": true, "explanation": "間接照明が作る明暗の効果を表し、文脈に合います。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが、照明による演出の内容として意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、照明で演出するものとして意味が合わない。"}, {"text": "出費", "is_correct": false, "explanation": "形は合うが、家具や白壁の演出という文脈に意味が合わない。"}], "explanations": {"陰影": "間接照明が作る明暗の効果を表し、文脈に合います。", "渋滞": "形は合うが、照明による演出の内容として意味が合わない。", "湿度": "形は合うが、照明で演出するものとして意味が合わない。", "出費": "形は合うが、家具や白壁の演出という文脈に意味が合わない。"}, "sentence_index": 0, "correct_answer": "陰影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の試験の陰影は八十点でした。", "explanation": "「陰影」は明暗の模様や効果で、点数や成績を表す語ではない。"}, {"text": "陰影を食べると体が温まります。", "explanation": "「陰影」は光と影の効果で、食べ物ではないので「食べる」の目的語にならない。"}, {"text": "このスープは陰影が辛くておいしい。", "explanation": "「陰影」に味の性質はなく、味を表す「辛い」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "陰影", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "陰性", "is_correct": false, "explanation": "「いんせい」で、三音目だけが違う実在語です。"}, {"text": "院外", "is_correct": false, "explanation": "「いんがい」で、三音目だけが違う実在語です。"}, {"text": "院内", "is_correct": false, "explanation": "「いんない」で、三音目だけが違う実在語です。"}], "explanations": {"陰影": "見出し語そのものです。", "陰性": "「いんせい」で、三音目だけが違う実在語です。", "院外": "「いんがい」で、三音目だけが違う実在語です。", "院内": "「いんない」で、三音目だけが違う実在語です。"}, "sentence_index": null, "correct_answer": "陰影"}, "level_3": {"options": [{"text": "陰影", "is_correct": true, "explanation": "光の当て方で変わるものとして意味が合う。"}, {"text": "国籍", "is_correct": false, "explanation": "形は合うが、光の当て方で変わるものではなく意味が合わない。"}, {"text": "住所", "is_correct": false, "explanation": "形は合うが、光の当て方と関係がなく意味が合わない。"}, {"text": "名前", "is_correct": false, "explanation": "形は合うが、名前は光の当て方で変わるものではなく意味が合わない。"}], "explanations": {"陰影": "光の当て方で変わるものとして意味が合う。", "国籍": "形は合うが、光の当て方で変わるものではなく意味が合わない。", "住所": "形は合うが、光の当て方と関係がなく意味が合わない。", "名前": "形は合うが、名前は光の当て方で変わるものではなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "陰影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達と陰影を約束して駅で会った。", "explanation": "「陰影」は約束する対象ではなく、「約束する」とは結びつかない。"}, {"text": "母は陰影を炒めて夕食に出した。", "explanation": "「陰影」は光と影の効果で食材ではないので「炒める」の目的語にならない。"}, {"text": "この電車は陰影が速いので、早く着く。", "explanation": "「陰影」は速さを持つものではなく、「速い」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDE