INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この絵は陰影を深くて美しい。", "corrected_sentence": "この絵は陰影が深くて美しい。", "error_description": "「陰影」は形容詞「深い」の主語なので「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51690, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は絵に陰影がつけて立体感を出した。", "corrected_sentence": "先生は絵に陰影をつけて立体感を出した。", "error_description": "「陰影をつける」で、「陰影」は目的語なので「を」が必要。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「つける」の目的語を示すので「照明を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「照明がつけてください」は依頼文として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「や」は名詞を並べる助詞で、後に名詞が続かない「照明やつけてください」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「照明のつけてください」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「つける」の目的語を示すので「照明を」が正しい。", "が": "「照明がつけてください」は依頼文として成り立たない。", "や": "「や」は名詞を並べる助詞で、後に名詞が続かない「照明やつけてください」は文として成り立たない。", "の": "「照明のつけてください」は文として成り立たない。"}, "error_tags": {"が": "subject_marker", "や": "listing", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「照明があれば」と、存在するものを示す。"}, {"text": "を", "is_correct": false, "explanation": "「あれば」は目的語を取らないので、「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「照明へあれば」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「照明のあれば」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「照明があれば」と、存在するものを示す。", "を": "「あれば」は目的語を取らないので、「を」は使えない。", "へ": "「照明へあれば」は文として成り立たない。", "の": "「照明のあれば」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "明かりをつけて、部屋を明るくするもの。", "primary_collocate": null, "pronunciation": "しょうめい", "ipa": "ɕoːmeː", "syllable_count": 4, "sentences": [{"text": "照明が切れた。", "target_word": "照明", "complexity_tier": "T1", "furigana": "照明[しょうめい]が切[き]れた。", "sentence_source": "generated"}, {"text": "照明をつけてください。", "target_word": "照明", "complexity_tier": "T2", "furigana": "照明[しょうめい]をつけてください。", "sentence_source": "generated"}, {"text": "この部屋は照明が明るい。", "target_word": "照明", "complexity_tier": "T2", "furigana": "この部屋[へや]は照明[しょうめい]が明[あか]るい。", "sentence_source": "generated"}, {"text": "照明を消すと、真っ暗になる。", "target_word": "照明", "complexity_tier": "T4", "furigana": "照明[しょうめい]を消[け]すと、真[ま]っ暗[くら]になる。", "sentence_source": "generated"}, {"text": "玄関に新しい照明を付けた。", "target_word": "照明", "complexity_tier": "T3", "furigana": "玄関[げんかん]に新[あたら]しい照明[しょうめい]を付[つ]けた。", "sentence_source": "generated"}, {"text": "トイレの照明は人が来るとつく。", "target_word": "照明", "complexity_tier": "T4", "furigana": "トイレの照明[しょうめい]は人[ひと]が来[く]るとつく。", "sentence_source": "generated"}, {"text": "照明のスイッチはどこですか。", "target_word": "照明", "complexity_tier": "T2", "furigana": "照明[しょうめい]のスイッチはどこですか。", "sentence_source": "generated"}, {"text": "夜でも照明があれば安心だ。", "target_word": "照明", "complexity_tier": "T4", "furigana": "夜[よる]でも照明[しょうめい]があれば安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "照明が暗くて、字が読めません。", "target_word": "照明", "complexity_tier": "T3", "furigana": "照明[しょうめい]が暗[くら]くて、字[じ]が読[よ]めません。", "sentence_source": "generated"}, {"text": "店の照明を明るくした。", "target_word": "照明", "complexity_tier": "T2", "furigana": "店[みせ]の照明[しょうめい]を明[あか]るくした。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 部屋を明るくする光の装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "照明", "is_correct": true, "explanation": "しょうめい。これが聞こえた単語です。"}, {"text": "紹介", "is_correct": false, "explanation": "しょうかい。「め」が「か」に変わるだけの別の語です。"}, {"text": "障害", "is_correct": false, "explanation": "しょうがい。「め」が「が」に変わるだけの別の語です。"}, {"text": "正面", "is_correct": false, "explanation": "しょうめん。最後の「い」が「ん」に変わるだけの別の語です。"}, {"text": "消滅", "is_correct": false, "explanation": "しょうめつ。最後の「い」が「つ」に変わるだけの別の語です。"}], "explanations": {"照明": "しょうめい。これが聞こえた単語です。", "紹介": "しょうかい。「め」が「か」に変わるだけの別の語です。", "障害": "しょうがい。「め」が「が」に変わるだけの別の語です。", "正面": "しょうめん。最後の「い」が「ん」に変わるだけの別の語です。", "消滅": "しょうめつ。最後の「い」が「つ」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "照明"}, "level_3": {"options": [{"text": "照明", "is_correct": true, "explanation": "照明が切れる、つまり明かりが消えて使えなくなる意味で自然です。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机が切れるという意味は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "形は合うが、窓が切れるという意味は成り立たない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書が切れるという意味は成り立たない。"}], "explanations": {"照明": "照明が切れる、つまり明かりが消えて使えなくなる意味で自然です。", "机": "形は合うが、机が切れるという意味は成り立たない。", "窓": "形は合うが、窓が切れるという意味は成り立たない。", "辞書": "形は合うが、辞書が切れるという意味は成り立たない。"}, "sentence_index": 0, "correct_answer": "照明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、照明を飲んでから会社に行く。", "explanation": "照明は光の装置で飲み物ではないので、「飲む」とは使えない。"}, {"text": "照明を書いて、友達に送った。", "explanation": "照明は文章や手紙のように「書く」ものではない。"}, {"text": "雨の日は照明をさして出かける。", "explanation": "「さす」のは傘などで、照明は持ち歩いてさすものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "照明", "is_correct": true, "explanation": "しょうめい。これが聞こえた単語です。"}, {"text": "症例", "is_correct": false, "explanation": "しょうれい。「め」が「れ」に変わるだけの別の語です。"}, {"text": "町名", "is_correct": false, "explanation": "ちょうめい。最初の「しょ」が「ちょ」に変わるだけの別の語です。"}, {"text": "小計", "is_correct": false, "explanation": "しょうけい。「め」が「け」に変わるだけの別の語です。"}], "explanations": {"照明": "しょうめい。これが聞こえた単語です。", "症例": "しょうれい。「め」が「れ」に変わるだけの別の語です。", "町名": "ちょうめい。最初の「しょ」が「ちょ」に変わるだけの別の語です。", "小計": "しょうけい。「め」が「け」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "照明"}, "level_3": {"options": [{"text": "照明", "is_correct": true, "explanation": "スイッチがあって部屋を明るくする装置なので、文意に合います。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書にはスイッチがなく意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、普通の机にはスイッチがなく意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、靴のスイッチを探す場面は不自然で意味が合わない。"}], "explanations": {"照明": "スイッチがあって部屋を明るくする装置なので、文意に合います。", "辞書": "形は合うが、辞書にはスイッチがなく意味が合わない。", "机": "形は合うが、普通の机にはスイッチがなく意味が合わない。", "靴": "形は合うが、靴のスイッチを探す場面は不自然で意味が合わない。"}, "sentence_index": 6, "correct_answer": "照明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "照明に入って、ゆっくり温まった。", "explanation": "照明は風呂などの場所ではなく、人が入るものではない。"}, {"text": "照明を着て、出かけた。", "explanation": "照明は光の装置で衣服ではないので、「着る」とは使えない。"}, {"text": "急いでいたので、照明に乗って駅へ行った。", "explanation": "照明は乗り物ではないので、「乗る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暗いので、照明をついてください。", "corrected_sentence": "暗いので、照明をつけてください。", "error_description": "「照明を」に続くのは他動詞の「つける」で、自動詞の「つく」では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51691, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "廊下の照明が消すと、真っ暗になる。", "corrected_sentence": "廊下の照明を消すと、真っ暗になる。", "error_description": "「消す」の目的語になる照明には「を」が必要で、「が」では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51692, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「照明が暗い」と、暗い状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「暗いです」は目的語を取らないので、「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「照明に暗いです」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「照明と暗いです」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「照明が暗い」と、暗い状態の主語を示す。", "を": "「暗いです」は目的語を取らないので、「を」は使えない。", "に": "「照明に暗いです」は文として成り立たない。", "と": "「照明と暗いです」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "に": "location_or_target", "と": "quotation_or_companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51692, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜による」は原因・手段を表す定型表現で、「照明に」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「照明をよる」とは言えず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「照明でよる」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「照明とよる」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「〜による」は原因・手段を表す定型表現で、「照明に」が必要。", "を": "「照明をよる」とは言えず、文として成り立たない。", "で": "「照明でよる」は文として成り立たない。", "と": "「照明とよる」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "で": "means_marker", "と": "companion"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "部屋や場所を明るくするための光の出る装置。", "primary_collocate": null, "pronunciation": "しょうめい", "ipa": "ɕoːmeː", "syllable_count": 4, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "照明", "complexity_tier": "T6", "furigana": "具体的[ぐたいてき]には、無垢材[むくざい]の家具[かぐ]と白壁[しろかべ]の組[く]み合[あ]わせ、あるいは間接照明[かんせつしょうめい]による陰影[いんえい]の演出[えんしゅつ]などが効果的[こうかてき]です。", "sentence_source": "mined"}, {"text": "この店は照明が暗いです。", "target_word": "照明", "complexity_tier": "T2", "furigana": "この店[みせ]は照明[しょうめい]が暗[くら]いです。", "sentence_source": "generated"}, {"text": "部屋の照明を変えたい。", "target_word": "照明", "complexity_tier": "T3", "furigana": "部屋[へや]の照明[しょうめい]を変[か]えたい。", "sentence_source": "generated"}, {"text": "舞台の照明が一度に消えた。", "target_word": "照明", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の照明[しょうめい]が一度[いちど]に消[き]えた。", "sentence_source": "generated"}, {"text": "照明のおかげで本が読みやすい。", "target_word": "照明", "complexity_tier": "T3", "furigana": "照明[しょうめい]のおかげで本[ほん]が読[よ]みやすい。", "sentence_source": "generated"}, {"text": "夜は照明をつけて勉強します。", "target_word": "照明", "complexity_tier": "T2", "furigana": "夜[よる]は照明[しょうめい]をつけて勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "美術館では、照明に気をつけている。", "target_word": "照明", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]では、照明[しょうめい]に気[き]をつけている。", "sentence_source": "generated"}, {"text": "やわらかい照明で、落ち着く部屋になった。", "target_word": "照明", "complexity_tier": "T3", "furigana": "やわらかい照明[しょうめい]で、落[お]ち着[つ]く部屋[へや]になった。", "sentence_source": "generated"}, {"text": "照明を消して、寝ました。", "target_word": "照明", "complexity_tier": "T2", "furigana": "照明[しょうめい]を消[け]して、寝[ね]ました。", "sentence_source": "generated"}, {"text": "照明の色を選べるランプです。", "target_word": "照明", "complexity_tier": "T3", "furigana": "照明[しょうめい]の色[いろ]を選[えら]べるランプです。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 空間に光を与えて見せ方を作る設備", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51692, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "照明", "is_correct": true, "explanation": "しょうめい。これが聞こえた単語です。"}, {"text": "紹介", "is_correct": false, "explanation": "しょうかい。「め」が「か」に変わるだけの別の語です。"}, {"text": "障害", "is_correct": false, "explanation": "しょうがい。「め」が「が」に変わるだけの別の語です。"}, {"text": "正面", "is_correct": false, "explanation": "しょうめん。最後の「い」が「ん」に変わるだけの別の語です。"}, {"text": "消滅", "is_correct": false, "explanation": "しょうめつ。最後の「い」が「つ」に変わるだけの別の語です。"}], "explanations": {"照明": "しょうめい。これが聞こえた単語です。", "紹介": "しょうかい。「め」が「か」に変わるだけの別の語です。", "障害": "しょうがい。「め」が「が」に変わるだけの別の語です。", "正面": "しょうめん。最後の「い」が「ん」に変わるだけの別の語です。", "消滅": "しょうめつ。最後の「い」が「つ」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "照明"}, "level_3": {"options": [{"text": "照明", "is_correct": true, "explanation": "間接照明は陰影を作る光の設備なので、文意に合います。"}, {"text": "暖房", "is_correct": false, "explanation": "形は合うが、暖房では陰影の演出という意味に合わない。"}, {"text": "防音", "is_correct": false, "explanation": "形は合うが、防音では陰影を作れず意味が合わない。"}, {"text": "換気", "is_correct": false, "explanation": "形は合うが、換気では陰影の演出という意味が合わない。"}], "explanations": {"照明": "間接照明は陰影を作る光の設備なので、文意に合います。", "暖房": "形は合うが、暖房では陰影の演出という意味に合わない。", "防音": "形は合うが、防音では陰影を作れず意味が合わない。", "換気": "形は合うが、換気では陰影の演出という意味が合わない。"}, "sentence_index": 0, "correct_answer": "照明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "照明を冷蔵庫に入れて、冷やしておいた。", "explanation": "照明は光を出す装置なので、食べ物のように冷やす対象にはならない。"}, {"text": "昨日のテストの照明は九十点でした。", "explanation": "照明は点数を表す語ではない。証明などと混同した誤用です。"}, {"text": "朝ごはんに照明を食べて出かけた。", "explanation": "照明は光の装置で、食べ物ではないので「食べる」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51692, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "照明", "is_correct": true, "explanation": "しょうめい。これが聞こえた単語です。"}, {"text": "症例", "is_correct": false, "explanation": "しょうれい。「め」が「れ」に変わるだけの別の語です。"}, {"text": "町名", "is_correct": false, "explanation": "ちょうめい。最初の「しょ」が「ちょ」に変わるだけの別の語です。"}, {"text": "小計", "is_correct": false, "explanation": "しょうけい。「め」が「け」に変わるだけの別の語です。"}], "explanations": {"照明": "しょうめい。これが聞こえた単語です。", "症例": "しょうれい。「め」が「れ」に変わるだけの別の語です。", "町名": "ちょうめい。最初の「しょ」が「ちょ」に変わるだけの別の語です。", "小計": "しょうけい。「め」が「け」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "照明"}, "level_3": {"options": [{"text": "照明", "is_correct": true, "explanation": "美術館で作品の見え方のために気をつけるものとして自然です。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、美術館で気をつける対象として意味が合わない。"}, {"text": "給料", "is_correct": false, "explanation": "形は合うが、美術館の展示の配慮として意味が合わない。"}, {"text": "信号", "is_correct": false, "explanation": "形は合うが、美術館の中で気をつけるものとして意味が合わない。"}], "explanations": {"照明": "美術館で作品の見え方のために気をつけるものとして自然です。", "野菜": "形は合うが、美術館で気をつける対象として意味が合わない。", "給料": "形は合うが、美術館の展示の配慮として意味が合わない。", "信号": "形は合うが、美術館の中で気をつけるものとして意味が合わない。"}, "sentence_index": 6, "correct_answer": "照明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "のどがかわいたので、照明を飲んだ。", "explanation": "照明は光の装置で飲み物ではないので、「飲む」とは使えない。"}, {"text": "机の上で照明を焼いて、夕食を作った。", "explanation": "照明は料理の材料ではないので、「焼く」の対象にならない。"}, {"text": "駅まで照明を歩くと十分かかる。", "explanation": "照明は道や場所を表さず、「歩く」の経路にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51692, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "リビングの照明を明るすぎて、目が疲れた。", "corrected_sentence": "リビングの照明が明るすぎて、目が疲れた。", "error_description": "「明るすぎる」は形容詞で目的語を取らないので、照明には「を」ではなく「が」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
