INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51693, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「演出した」の目的語「登場の場面」を示す。"}, {"text": "に", "is_correct": false, "explanation": "「場面に演出した」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「場面と演出した」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「場面へ演出した」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「演出した」の目的語「登場の場面」を示す。", "に": "「場面に演出した」は文として成り立たない。", "と": "「場面と演出した」は文として成り立たない。", "へ": "「場面へ演出した」は文として成り立たない。"}, "error_tags": {"に": "target_marker", "と": "companion", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
