INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51693, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを見せるときに、どうやって見せるかを考えること。", "primary_collocate": null, "pronunciation": "えんしゅつ", "ipa": "eɲɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "パーティーの演出を考えます。", "target_word": "演出", "complexity_tier": "T2", "furigana": "パーティーの演出[えんしゅつ]を考[かんが]えます。", "sentence_source": "generated"}, {"text": "登場の場面を演出した。", "target_word": "演出した", "complexity_tier": "T2", "furigana": "登場[とうじょう]の場面[ばめん]を演出[えんしゅつ]した。", "sentence_source": "generated"}, {"text": "彼女は上手に自分を演出する。", "target_word": "演出する", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は上手[じょうず]に自分[じぶん]を演出[えんしゅつ]する。", "sentence_source": "generated"}, {"text": "いい演出で、客が喜んだ。", "target_word": "演出", "complexity_tier": "T2", "furigana": "いい演出[えんしゅつ]で、客[きゃく]が喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "この演出はおもしろい。", "target_word": "演出", "complexity_tier": "T1", "furigana": "この演出[えんしゅつ]はおもしろい。", "sentence_source": "generated"}, {"text": "授業の演出に工夫が必要だ。", "target_word": "演出", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の演出[えんしゅつ]に工夫[くふう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "ライトで海の雰囲気を演出します。", "target_word": "演出します", "complexity_tier": "T2", "furigana": "ライトで海[うみ]の雰囲気[ふんいき]を演出[えんしゅつ]します。", "sentence_source": "generated"}, {"text": "演出を変えて、もう一度見せた。", "target_word": "演出", "complexity_tier": "T3", "furigana": "演出[えんしゅつ]を変[か]えて、もう一度[いちど]見[み]せた。", "sentence_source": "generated"}, {"text": "サプライズの演出に友達が泣いた。", "target_word": "演出", "complexity_tier": "T3", "furigana": "サプライズの演出[えんしゅつ]に友達[ともだち]が泣[な]いた。", "sentence_source": "generated"}, {"text": "店は静かな音楽で落ち着きを演出している。", "target_word": "演出している", "complexity_tier": "T3", "furigana": "店[みせ]は静[しず]かな音楽[おんがく]で落[お]ち着[つ]きを演出[えんしゅつ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "演出する", "label": "活用"}, {"form": "演出した", "label": "活用"}, {"form": "演出している", "label": "活用"}, {"form": "演出家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 見せ方を考えて工夫すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51693, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演出", "is_correct": true, "explanation": "えんしゅつ。これが聞こえた単語です。"}, {"text": "検出", "is_correct": false, "explanation": "けんしゅつ。最初の「え」が「け」に変わるだけの別の語です。"}, {"text": "転出", "is_correct": false, "explanation": "てんしゅつ。最初の「え」が「て」に変わるだけの別の語です。"}, {"text": "演習", "is_correct": false, "explanation": "えんしゅう。最後の「つ」が「う」に変わるだけの別の語です。"}], "explanations": {"演出": "えんしゅつ。これが聞こえた単語です。", "検出": "けんしゅつ。最初の「え」が「け」に変わるだけの別の語です。", "転出": "てんしゅつ。最初の「え」が「て」に変わるだけの別の語です。", "演習": "えんしゅう。最後の「つ」が「う」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "演出"}, "level_3": {"options": [{"text": "演出", "is_correct": true, "explanation": "パーティーの見せ方を考えるという意味で自然です。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、パーティーの洗濯では意味が合わない。"}, {"text": "納税", "is_correct": false, "explanation": "形は合うが、パーティーの納税では意味が合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、パーティーの病気を考えるでは意味が合わない。"}], "explanations": {"演出": "パーティーの見せ方を考えるという意味で自然です。", "洗濯": "形は合うが、パーティーの洗濯では意味が合わない。", "納税": "形は合うが、パーティーの納税では意味が合わない。", "病気": "形は合うが、パーティーの病気を考えるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "演出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の演出を開けて、空気を入れた。", "explanation": "演出は物ではなく、開けられる対象ではない。"}, {"text": "演出を食べすぎて、お腹が痛い。", "explanation": "演出は食べ物ではないので、「食べる」とは使えない。"}, {"text": "駅の演出で友達と待ち合わせた。", "explanation": "演出は場所を表さないので、待ち合わせの場所にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51693, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "演出", "is_correct": true, "explanation": "えんしゅつ。これが聞こえた単語です。"}, {"text": "産出", "is_correct": false, "explanation": "さんしゅつ。最初の「え」が「さ」に変わるだけの別の語です。"}, {"text": "搬出", "is_correct": false, "explanation": "はんしゅつ。最初の「え」が「は」に変わるだけの別の語です。"}, {"text": "前出", "is_correct": false, "explanation": "ぜんしゅつ。最初の「え」が「ぜ」に変わるだけの別の語です。"}], "explanations": {"演出": "えんしゅつ。これが聞こえた単語です。", "産出": "さんしゅつ。最初の「え」が「さ」に変わるだけの別の語です。", "搬出": "はんしゅつ。最初の「え」が「は」に変わるだけの別の語です。", "前出": "ぜんしゅつ。最初の「え」が「ぜ」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "演出"}, "level_3": {"options": [{"text": "演出します", "is_correct": true, "explanation": "ライトで海の雰囲気を作るので、「演出します」が合います。"}, {"text": "洗濯します", "is_correct": false, "explanation": "形は合うが、雰囲気を洗濯するでは意味が合わない。"}, {"text": "輸送します", "is_correct": false, "explanation": "形は合うが、雰囲気を輸送するでは意味が合わない。"}, {"text": "掃除します", "is_correct": false, "explanation": "形は合うが、雰囲気を掃除するでは意味が合わない。"}], "explanations": {"演出します": "ライトで海の雰囲気を作るので、「演出します」が合います。", "洗濯します": "形は合うが、雰囲気を洗濯するでは意味が合わない。", "輸送します": "形は合うが、雰囲気を輸送するでは意味が合わない。", "掃除します": "形は合うが、雰囲気を掃除するでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "演出します"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、牛乳といっしょに演出を飲む。", "explanation": "演出は飲み物ではないので、「飲む」とは使えない。"}, {"text": "彼は演出を着て、会社に行った。", "explanation": "演出は衣服ではないので、「着る」とは使えない。"}, {"text": "演出が破れたので、新しいのを買った。", "explanation": "演出は形のない行為で、破れたり買ったりできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
