INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51694, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "劇や映画などで、役者の動きや照明、音などを工夫して、作品の表現をまとめること。また、場面の雰囲気を作り出すこと。", "primary_collocate": null, "pronunciation": "えんしゅつ", "ipa": "eɲɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "演出", "complexity_tier": "T6", "furigana": "具体的[ぐたいてき]には、無垢材[むくざい]の家具[かぐ]と白壁[しろかべ]の組[く]み合[あ]わせ、あるいは間接照明[かんせつしょうめい]による陰影[いんえい]の演出[えんしゅつ]などが効果的[こうかてき]です。", "sentence_source": "mined"}, {"text": "この映画は演出がすばらしい。", "target_word": "演出", "complexity_tier": "T3", "furigana": "この映画[えいが]は演出[えんしゅつ]がすばらしい。", "sentence_source": "generated"}, {"text": "彼は舞台の演出を担当している。", "target_word": "演出", "complexity_tier": "T3", "furigana": "彼[かれ]は舞台[ぶたい]の演出[えんしゅつ]を担当[たんとう]している。", "sentence_source": "generated"}, {"text": "夜景を使った演出に感動した。", "target_word": "演出", "complexity_tier": "T3", "furigana": "夜景[やけい]を使[つか]った演出[えんしゅつ]に感動[かんどう]した。", "sentence_source": "generated"}, {"text": "結婚式で、音楽で雰囲気を演出する。", "target_word": "演出する", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]で、音楽[おんがく]で雰囲気[ふんいき]を演出[えんしゅつ]する。", "sentence_source": "generated"}, {"text": "花火で特別な夜を演出した。", "target_word": "演出した", "complexity_tier": "T3", "furigana": "花火[はなび]で特別[とくべつ]な夜[よる]を演出[えんしゅつ]した。", "sentence_source": "generated"}, {"text": "監督は光と音を使って場面を演出する。", "target_word": "演出する", "complexity_tier": "T3", "furigana": "監督[かんとく]は光[ひかり]と音[おと]を使[つか]って場面[ばめん]を演出[えんしゅつ]する。", "sentence_source": "generated"}, {"text": "演出の意図がよくわからない。", "target_word": "演出", "complexity_tier": "T3", "furigana": "演出[えんしゅつ]の意図[いと]がよくわからない。", "sentence_source": "generated"}, {"text": "驚かせる演出が多い劇です。", "target_word": "演出", "complexity_tier": "T3", "furigana": "驚[おどろ]かせる演出[えんしゅつ]が多[おお]い劇[げき]です。", "sentence_source": "generated"}, {"text": "照明で温かさが演出された部屋だ。", "target_word": "演出された", "complexity_tier": "T4", "furigana": "照明[しょうめい]で温[あたた]かさが演出[えんしゅつ]された部屋[へや]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "演出する", "label": "活用"}, {"form": "演出した", "label": "活用"}, {"form": "演出される", "label": "活用"}, {"form": "演出家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 見せ方を工夫して雰囲気を作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51694, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演出", "is_correct": true, "explanation": "えんしゅつ。これが聞こえた単語です。"}, {"text": "検出", "is_correct": false, "explanation": "けんしゅつ。最初の「え」が「け」に変わるだけの別の語です。"}, {"text": "転出", "is_correct": false, "explanation": "てんしゅつ。最初の「え」が「て」に変わるだけの別の語です。"}, {"text": "演習", "is_correct": false, "explanation": "えんしゅう。最後の「つ」が「う」に変わるだけの別の語です。"}], "explanations": {"演出": "えんしゅつ。これが聞こえた単語です。", "検出": "けんしゅつ。最初の「え」が「け」に変わるだけの別の語です。", "転出": "てんしゅつ。最初の「え」が「て」に変わるだけの別の語です。", "演習": "えんしゅう。最後の「つ」が「う」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "演出"}, "level_3": {"options": [{"text": "演出", "is_correct": true, "explanation": "陰影で見せ方を作ることは演出で、効果的という文意に合います。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、陰影の洗濯では意味が合わない。"}, {"text": "輸送", "is_correct": false, "explanation": "形は合うが、陰影の輸送では意味が合わない。"}, {"text": "納税", "is_correct": false, "explanation": "形は合うが、陰影の納税では意味が合わない。"}], "explanations": {"演出": "陰影で見せ方を作ることは演出で、効果的という文意に合います。", "洗濯": "形は合うが、陰影の洗濯では意味が合わない。", "輸送": "形は合うが、陰影の輸送では意味が合わない。", "納税": "形は合うが、陰影の納税では意味が合わない。"}, "sentence_index": 0, "correct_answer": "演出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、スーパーで演出を三個買って帰った。", "explanation": "演出は見せ方を工夫することで、買える物ではない。"}, {"text": "このカレーは演出がとても辛い。", "explanation": "演出に味はなく、「辛い」とは使えない。"}, {"text": "雨で演出が濡れたので、乾かした。", "explanation": "演出は形のない行為で、濡れたり乾かしたりできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51694, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "演出", "is_correct": true, "explanation": "えんしゅつ。これが聞こえた単語です。"}, {"text": "産出", "is_correct": false, "explanation": "さんしゅつ。最初の「え」が「さ」に変わるだけの別の語です。"}, {"text": "搬出", "is_correct": false, "explanation": "はんしゅつ。最初の「え」が「は」に変わるだけの別の語です。"}, {"text": "前出", "is_correct": false, "explanation": "ぜんしゅつ。最初の「え」が「ぜ」に変わるだけの別の語です。"}], "explanations": {"演出": "えんしゅつ。これが聞こえた単語です。", "産出": "さんしゅつ。最初の「え」が「さ」に変わるだけの別の語です。", "搬出": "はんしゅつ。最初の「え」が「は」に変わるだけの別の語です。", "前出": "ぜんしゅつ。最初の「え」が「ぜ」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "演出"}, "level_3": {"options": [{"text": "演出する", "is_correct": true, "explanation": "光と音で場面の見せ方を作るので、「演出する」が合います。"}, {"text": "輸送する", "is_correct": false, "explanation": "形は合うが、場面を輸送するでは意味が合わない。"}, {"text": "洗濯する", "is_correct": false, "explanation": "形は合うが、場面を洗濯するでは意味が合わない。"}, {"text": "購入する", "is_correct": false, "explanation": "形は合うが、場面を購入するでは意味が合わない。"}], "explanations": {"演出する": "光と音で場面の見せ方を作るので、「演出する」が合います。", "輸送する": "形は合うが、場面を輸送するでは意味が合わない。", "洗濯する": "形は合うが、場面を洗濯するでは意味が合わない。", "購入する": "形は合うが、場面を購入するでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "演出する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ごはんに演出を食べて、学校へ行った。", "explanation": "演出は食べ物ではないので、「食べる」とは使えない。"}, {"text": "駅の前で演出を待っていたが、来なかった。", "explanation": "演出は人や乗り物ではなく、待ち合わせる相手にならない。"}, {"text": "この机は演出でできていて、とても丈夫だ。", "explanation": "演出は材料ではないので、「でできている」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
