INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51695, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いやな音のこと。", "primary_collocate": null, "pronunciation": "ざつおん", "ipa": "dzatsɯoɴ", "syllable_count": 4, "sentences": [{"text": "外から雑音が聞こえる。", "target_word": "雑音", "complexity_tier": "T2", "furigana": "外[そと]から雑音[ざつおん]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "雑音がうるさいです。", "target_word": "雑音", "complexity_tier": "T2", "furigana": "雑音[ざつおん]がうるさいです。", "sentence_source": "generated"}, {"text": "雑音が多くて眠れない。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]が多[おお]くて眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "このマイクは雑音が入る。", "target_word": "雑音", "complexity_tier": "T2", "furigana": "このマイクは雑音[ざつおん]が入[はい]る。", "sentence_source": "generated"}, {"text": "工事の雑音が一日中続いた。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "工事[こうじ]の雑音[ざつおん]が一日中[いちにちじゅう]続[つづ]いた。", "sentence_source": "generated"}, {"text": "雑音を聞きたくない。", "target_word": "雑音", "complexity_tier": "T2", "furigana": "雑音[ざつおん]を聞[き]きたくない。", "sentence_source": "generated"}, {"text": "雑音の中でも、母の声はわかった。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]の中[なか]でも、母[はは]の声[こえ]はわかった。", "sentence_source": "generated"}, {"text": "テレビの雑音が急に大きくなった。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "テレビの雑音[ざつおん]が急[きゅう]に大[おお]きくなった。", "sentence_source": "generated"}, {"text": "雑音は嫌いなので、静かな所へ行く。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]は嫌[きら]いなので、静[しず]かな所[ところ]へ行[い]く。", "sentence_source": "generated"}, {"text": "雑音がなくなって、ほっとした。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]がなくなって、ほっとした。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 聞いていやな感じがする音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51695, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑音", "is_correct": true, "explanation": "外から聞こえるいやな音を指し、文意に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「机が聞こえる」は意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「帽子が聞こえる」は意味が合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、「砂糖が聞こえる」は意味が合わない。"}], "explanations": {"雑音": "外から聞こえるいやな音を指し、文意に合う。", "机": "形は合うが、「机が聞こえる」は意味が合わない。", "帽子": "形は合うが、「帽子が聞こえる」は意味が合わない。", "砂糖": "形は合うが、「砂糖が聞こえる」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "雑音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この雑音は甘くておいしい。", "explanation": "雑音は味で表すものではない。性質の述べ方が誤り。"}, {"text": "雑音を着て寒さを防いだ。", "explanation": "雑音は着る物ではなく、音のこと。「着る」との組み合わせが誤り。"}, {"text": "雑音を机の上に三冊置いた。", "explanation": "雑音は本のように置いて数えるものではない。使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51695, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑音", "is_correct": true, "explanation": "いやな音の中でも母の声が聞き分けられたという意味で、文意に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "形は合うが、「冷蔵庫の中でも母の声はわかった」は意味が合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "形は合うが、母の声がわかる状況として意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、「財布の中でも母の声はわかった」は意味が合わない。"}], "explanations": {"雑音": "いやな音の中でも母の声が聞き分けられたという意味で、文意に合う。", "冷蔵庫": "形は合うが、「冷蔵庫の中でも母の声はわかった」は意味が合わない。", "教科書": "形は合うが、母の声がわかる状況として意味が合わない。", "財布": "形は合うが、「財布の中でも母の声はわかった」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "雑音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雑音を洗ってから干した。", "explanation": "雑音は洗って干す物ではない。「洗う」との組み合わせが誤り。"}, {"text": "雑音は去年の夏に生まれた。", "explanation": "雑音は生まれるものではなく、音のこと。述語が誤り。"}, {"text": "昨日、雑音を三人で食べた。", "explanation": "雑音は食べるものではない。「食べる」との組み合わせが誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
