INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51696, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "周囲の音の中で、目的の音を聞き取りにくくする不要な音。また、転じて、情報や視覚などにおいて、目的のものを妨げるもの。", "primary_collocate": null, "pronunciation": "ざつおん", "ipa": "dzatsɯoɴ", "syllable_count": 4, "sentences": [{"text": "これらは視覚的な雑音を減らし、心の豊かさを追求する手段となっています。", "target_word": "雑音", "complexity_tier": "T6", "furigana": "これらは視覚的[しかくてき]な雑音[ざつおん]を減[へ]らし、心[こころ]の豊[ゆた]かさを追求[ついきゅう]する手段[しゅだん]となっています。", "sentence_source": "mined"}, {"text": "電話に雑音が入って、よく聞こえない。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "電話[でんわ]に雑音[ざつおん]が入[はい]って、よく聞[き]こえない。", "sentence_source": "generated"}, {"text": "雑音の少ない部屋で勉強したい。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]の少[すく]ない部屋[へや]で勉強[べんきょう]したい。", "sentence_source": "generated"}, {"text": "ラジオから雑音が聞こえる。", "target_word": "雑音", "complexity_tier": "T2", "furigana": "ラジオから雑音[ざつおん]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "周りの雑音を消すイヤホンを買った。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "周[まわ]りの雑音[ざつおん]を消[け]すイヤホンを買[か]った。", "sentence_source": "generated"}, {"text": "ネットには雑音が多い。", "target_word": "雑音", "complexity_tier": "T2", "furigana": "ネットには雑音[ざつおん]が多[おお]い。", "sentence_source": "generated"}, {"text": "雑音に気を取られて、集中できなかった。", "target_word": "雑音", "complexity_tier": "T4", "furigana": "雑音[ざつおん]に気[き]を取[と]られて、集中[しゅうちゅう]できなかった。", "sentence_source": "generated"}, {"text": "雑音を気にせずに話し続けた。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]を気[き]にせずに話[はな]し続[つづ]けた。", "sentence_source": "generated"}, {"text": "机の上の物は仕事の雑音になる。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の物[もの]は仕事[しごと]の雑音[ざつおん]になる。", "sentence_source": "generated"}, {"text": "雑音のせいで、先生の声が聞こえません。", "target_word": "雑音", "complexity_tier": "T3", "furigana": "雑音[ざつおん]のせいで、先生[せんせい]の声[こえ]が聞[き]こえません。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 目的の音や情報を妨げる不要なもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51696, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑音", "is_correct": true, "explanation": "視覚的な不要なもの、つまり目的を妨げるものを指し、文意に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「視覚的な約束を減らす」は意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「視覚的な季節を減らす」は意味が合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、「視覚的な病気を減らす」は意味が合わない。"}], "explanations": {"雑音": "視覚的な不要なもの、つまり目的を妨げるものを指し、文意に合う。", "約束": "形は合うが、「視覚的な約束を減らす」は意味が合わない。", "季節": "形は合うが、「視覚的な季節を減らす」は意味が合わない。", "病気": "形は合うが、「視覚的な病気を減らす」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "雑音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、雑音を飲んで体を温める。", "explanation": "雑音は音であり、飲むものではない。「飲む」との組み合わせが誤り。"}, {"text": "雑音は赤くて、とても甘い。", "explanation": "雑音は味や色で表すものではない。性質の述べ方が誤り。"}, {"text": "雑音を履いて外に出た。", "explanation": "雑音は履く物ではなく、音のこと。「履く」との組み合わせが誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51696, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑音", "is_correct": true, "explanation": "不要な音に気を取られて集中できないという意味で、文意に合う。"}, {"text": "日曜日", "is_correct": false, "explanation": "形は合うが、「日曜日に気を取られる」は意味が合わない。"}, {"text": "去年", "is_correct": false, "explanation": "「去年に気を取られる」とは言わず、集中できなかった理由として意味が合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、「砂糖に気を取られて集中できない」は意味が合わない。"}], "explanations": {"雑音": "不要な音に気を取られて集中できないという意味で、文意に合う。", "日曜日": "形は合うが、「日曜日に気を取られる」は意味が合わない。", "去年": "「去年に気を取られる」とは言わず、集中できなかった理由として意味が合わない。", "砂糖": "形は合うが、「砂糖に気を取られて集中できない」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "雑音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雑音を塗って壁をきれいにした。", "explanation": "雑音は塗る物ではない。「塗る」との組み合わせが誤り。"}, {"text": "雑音は三階建てで、庭が広い。", "explanation": "雑音は建物ではなく、音のこと。意味が誤り。"}, {"text": "雑音を泳いで川を渡った。", "explanation": "雑音は泳いで渡る場所ではない。「泳ぐ」との組み合わせが誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
