INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51697, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "右と左のこと。二つの反対の方角。", "primary_collocate": null, "pronunciation": "さゆう", "ipa": "sajɯː", "syllable_count": 3, "sentences": [{"text": "左右をよく見てください。", "target_word": "左右", "complexity_tier": "T2", "furigana": "左右[さゆう]をよく見[み]てください。", "sentence_source": "generated"}, {"text": "道を渡る前に左右を確認する。", "target_word": "左右", "complexity_tier": "T3", "furigana": "道[みち]を渡[わた]る前[まえ]に左右[さゆう]を確認[かくにん]する。", "sentence_source": "generated"}, {"text": "左右の手で箱を持った。", "target_word": "左右", "complexity_tier": "T2", "furigana": "左右[さゆう]の手[て]で箱[はこ]を持[も]った。", "sentence_source": "generated"}, {"text": "左右どちらでも書ける。", "target_word": "左右", "complexity_tier": "T2", "furigana": "左右[さゆう]どちらでも書[か]ける。", "sentence_source": "generated"}, {"text": "靴の左右が違っている。", "target_word": "左右", "complexity_tier": "T3", "furigana": "靴[くつ]の左右[さゆう]が違[ちが]っている。", "sentence_source": "generated"}, {"text": "首を左右に振った。", "target_word": "左右", "complexity_tier": "T2", "furigana": "首[くび]を左右[さゆう]に振[ふ]った。", "sentence_source": "generated"}, {"text": "車は左右に揺れた。", "target_word": "左右", "complexity_tier": "T2", "furigana": "車[くるま]は左右[さゆう]に揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "左右の目の色が違う猫だ。", "target_word": "左右", "complexity_tier": "T3", "furigana": "左右[さゆう]の目[め]の色[いろ]が違[ちが]う猫[ねこ]だ。", "sentence_source": "generated"}, {"text": "道の左右に木が並んでいる。", "target_word": "左右", "complexity_tier": "T3", "furigana": "道[みち]の左右[さゆう]に木[き]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "左右が反対になった写真だ。", "target_word": "左右", "complexity_tier": "T3", "furigana": "左右[さゆう]が反対[はんたい]になった写真[しゃしん]だ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 右と左の二つの方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51697, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "左右", "is_correct": true, "explanation": "さゆう。見本の語そのもの。"}, {"text": "自由", "is_correct": false, "explanation": "じゆう。「さ」が「じ」に変わる別の語。"}, {"text": "理由", "is_correct": false, "explanation": "りゆう。「さ」が「り」に変わる別の語。"}, {"text": "作用", "is_correct": false, "explanation": "さよう。「ゆ」が「よ」に変わる別の語。"}, {"text": "座右", "is_correct": false, "explanation": "ざゆう。「さ」が濁音の「ざ」に変わる別の語。"}], "explanations": {"左右": "さゆう。見本の語そのもの。", "自由": "じゆう。「さ」が「じ」に変わる別の語。", "理由": "りゆう。「さ」が「り」に変わる別の語。", "作用": "さよう。「ゆ」が「よ」に変わる別の語。", "座右": "ざゆう。「さ」が濁音の「ざ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "左右"}, "level_3": {"options": [{"text": "左右", "is_correct": true, "explanation": "安全のために右と左をよく見るという意味で、文意に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「約束をよく見る」は意味が合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、「昨日をよく見る」は意味が合わない。"}, {"text": "午後", "is_correct": false, "explanation": "形は合うが、「午後をよく見る」は意味が合わない。"}], "explanations": {"左右": "安全のために右と左をよく見るという意味で、文意に合う。", "約束": "形は合うが、「約束をよく見る」は意味が合わない。", "昨日": "形は合うが、「昨日をよく見る」は意味が合わない。", "午後": "形は合うが、「午後をよく見る」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "左右"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で左右を買って電車に乗った。", "explanation": "左右は方向のことで、買う物ではない。「買う」との組み合わせが誤り。"}, {"text": "左右は甘くて、冷たい食べ物だ。", "explanation": "左右は食べ物ではなく、方向のこと。意味が誤り。"}, {"text": "彼は左右に火をつけて部屋を温めた。", "explanation": "左右は火をつける対象ではない。「火をつける」との組み合わせが誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51697, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "左右", "is_correct": true, "explanation": "さゆう。見本の語そのもの。"}, {"text": "杞憂", "is_correct": false, "explanation": "きゆう。「さ」が「き」に変わる別の語。"}, {"text": "義勇", "is_correct": false, "explanation": "ぎゆう。「さ」が「ぎ」に変わる別の語。"}, {"text": "雌雄", "is_correct": false, "explanation": "しゆう。「さ」が「し」に変わる別の語。"}, {"text": "所有", "is_correct": false, "explanation": "しょゆう。「さ」が「しょ」に変わる別の語。"}], "explanations": {"左右": "さゆう。見本の語そのもの。", "杞憂": "きゆう。「さ」が「き」に変わる別の語。", "義勇": "ぎゆう。「さ」が「ぎ」に変わる別の語。", "雌雄": "しゆう。「さ」が「し」に変わる別の語。", "所有": "しょゆう。「さ」が「しょ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "左右"}, "level_3": {"options": [{"text": "左右", "is_correct": true, "explanation": "車が右や左に揺れたという意味で、文意に合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、「野菜に揺れた」は意味が合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、「昨日に揺れた」は意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「約束に揺れた」は意味が合わない。"}], "explanations": {"左右": "車が右や左に揺れたという意味で、文意に合う。", "野菜": "形は合うが、「野菜に揺れた」は意味が合わない。", "昨日": "形は合うが、「昨日に揺れた」は意味が合わない。", "約束": "形は合うが、「約束に揺れた」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "左右"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、左右を焼いてパンに塗る。", "explanation": "左右は焼いてパンに塗る物ではない。「焼く」との組み合わせが誤り。"}, {"text": "左右は大きな声で歌を歌った。", "explanation": "左右は方向のことで、歌う主体ではない。意味が誤り。"}, {"text": "左右が泣きながら走ってきた。", "explanation": "左右は人や動物ではなく、方向のこと。主語として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.valid