INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51699, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ゴシックの建物」で名詞を修飾する連体修飾の「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ゴシックを建物には」となり、名詞を修飾できず意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では「ゴシックが建物には」となり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「ゴシックへ建物には」となり、名詞につながらない。"}], "correct_answer": "の", "explanations": {"の": "「ゴシックの建物」で名詞を修飾する連体修飾の「の」が正しい。", "を": "「ゴシックを建物には」となり、名詞を修飾できず意味が通らない。", "が": "主格の「が」では「ゴシックが建物には」となり、文が成り立たない。", "へ": "方向の「へ」では「ゴシックへ建物には」となり、名詞につながらない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
