INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51699, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゴシックは、とがった屋根や大きな窓をもつ建物の形のことです。", "primary_collocate": null, "pronunciation": "ごしっく", "ipa": "ɡoɕikkɯ", "syllable_count": 4, "sentences": [{"text": "あの教会はゴシックなので、屋根がとても高くてとがっている。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "あの教会[きょうかい]はゴシックなので、屋根[やね]がとても高[たか]くてとがっている。", "sentence_source": "generated"}, {"text": "ゴシックの建物には、大きな窓がたくさんあります。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ゴシックの建物[たてもの]には、大[おお]きな窓[まど]がたくさんあります。", "sentence_source": "generated"}, {"text": "町でいちばん古い建物はゴシックだそうです。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "町[まち]でいちばん古[ふる]い建物[たてもの]はゴシックだそうです。", "sentence_source": "generated"}, {"text": "ゴシックの教会の窓は、色のついたガラスでできている。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ゴシックの教会[きょうかい]の窓[まど]は、色[いろ]のついたガラスでできている。", "sentence_source": "generated"}, {"text": "私はゴシックの形の建物をスケッチした。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "私[わたし]はゴシックの形[かたち]の建物[たてもの]をスケッチした。", "sentence_source": "generated"}, {"text": "絵の授業で、ゴシックの塔を描きました。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "絵[え]の授業[じゅぎょう]で、ゴシックの塔[とう]を描[えが]きました。", "sentence_source": "generated"}, {"text": "ゴシックは、屋根が空に向かってのびているのが特徴だ。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ゴシックは、屋根[やね]が空[そら]に向[む]かってのびているのが特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "この写真の建物はゴシックですか。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "この写真[しゃしん]の建物[たてもの]はゴシックですか。", "sentence_source": "generated"}, {"text": "日本にも、ゴシックの形をした教会がある。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "日本[にほん]にも、ゴシックの形[かたち]をした教会[きょうかい]がある。", "sentence_source": "generated"}, {"text": "ゴシックの建物は、遠くからでもすぐわかる。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ゴシックの建物[たてもの]は、遠[とお]くからでもすぐわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゴシック", "label": "dictionary form (noun)"}, {"form": "ゴシックの", "label": "attributive (no-adjective use)"}], "register": "neutral", "sense_fingerprint": "とがった屋根や大きな窓をもつ、目に見える建物の形・外観としてのゴシック", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51699, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゴシック", "is_correct": true, "explanation": "「あの教会はゴシックなので」で、建物の形式として屋根の特徴と合う。"}, {"text": "回廊", "is_correct": false, "explanation": "建物の周囲をつなぐ通路を指す名詞で、教会の形式を示さず、屋根のとがった特徴ともつながらない。"}, {"text": "鐘楼", "is_correct": false, "explanation": "鐘を吊るす塔を指す名詞で、教会の形式を示さない。"}, {"text": "天窓", "is_correct": false, "explanation": "屋根に設けた窓を指す名詞で、「あの教会は〜なので」の述語にならない。"}], "explanations": {"ゴシック": "「あの教会はゴシックなので」で、建物の形式として屋根の特徴と合う。", "回廊": "建物の周囲をつなぐ通路を指す名詞で、教会の形式を示さず、屋根のとがった特徴ともつながらない。", "鐘楼": "鐘を吊るす塔を指す名詞で、教会の形式を示さない。", "天窓": "屋根に設けた窓を指す名詞で、「あの教会は〜なので」の述語にならない。"}, "sentence_index": 0, "correct_answer": "ゴシック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この教会では、毎朝ゴシックを鳴らして、朝を知らせる。", "explanation": "ここは〈鐘楼〉（鐘をつるす塔）の意味。ゴシックは建物の形の名前で、鳴らす物ではないので合わない。"}, {"text": "屋根にゴシックをかけて、上った。", "explanation": "ここは〈梯子〉（上り下りに使う道具）の意味。ゴシックは建物の形の名前で、かける道具にはならないので合わない。"}, {"text": "古いゴシックを広げて、道を探した。", "explanation": "ここは〈地図〉（場所や道を示す紙）の意味。ゴシックは建物の形の名前で、広げて使う物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51699, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゴシック", "is_correct": true, "explanation": "「ゴシックは、屋根が空に向かってのびているのが特徴だ」で、建物の形式として文に合う。"}, {"text": "回廊", "is_correct": false, "explanation": "建物の周囲をつなぐ通路を指す名詞で、屋根の形の特徴を示す語ではない。"}, {"text": "柱廊", "is_correct": false, "explanation": "柱が並ぶ通路を指す名詞で、屋根の特徴の主語にはならない。"}, {"text": "穹窿", "is_correct": false, "explanation": "ドーム状の天井を指す名詞で、ここでは建物の形式を表す語として入らない。"}], "explanations": {"ゴシック": "「ゴシックは、屋根が空に向かってのびているのが特徴だ」で、建物の形式として文に合う。", "回廊": "建物の周囲をつなぐ通路を指す名詞で、屋根の形の特徴を示す語ではない。", "柱廊": "柱が並ぶ通路を指す名詞で、屋根の特徴の主語にはならない。", "穹窿": "ドーム状の天井を指す名詞で、ここでは建物の形式を表す語として入らない。"}, "sentence_index": 6, "correct_answer": "ゴシック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "温泉で、ゴシックにつかって疲れを取った。", "explanation": "ここは〈温泉〉（湯につかる場所）の意味。ゴシックは建物の形の名前で、つかる場所にはならないので合わない。"}, {"text": "この見出しはゴシックで、線の太さがほぼ一定だ。", "explanation": "ここは〈ゴシック体〉（活字の書体）の意味。建物の形の義項とは別で、建物の話ではない。"}, {"text": "このポスターの文字はゴシックで、読みやすい。", "explanation": "ここは〈ゴシック体〉（活字の書体）の意味。建物の形の義項とは別で、建物の話ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51699, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゴシックに建物を描いた。", "corrected_sentence": "ゴシックの建物を描いた。", "error_description": "「ゴシックの建物」の「の」が「に」になっている。「に」では建物の形式を示せず、不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51699, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町のゴシックを建物は、遠くからでも目立つ。", "corrected_sentence": "町のゴシックの建物は、遠くからでも目立つ。", "error_description": "「ゴシックの建物」の「の」が「を」になっている。「を」は目的語を示すので、建物を修飾できず不自然になる。正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ゴシックの教会」で名詞を修飾する連体修飾の「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ゴシックを教会は」となり、名詞を修飾できず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す「に」では「ゴシックに教会は」となり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では「ゴシックへ教会は」となり、名詞につながらない。"}], "correct_answer": "の", "explanations": {"の": "「ゴシックの教会」で名詞を修飾する連体修飾の「の」が正しい。", "を": "「ゴシックを教会は」となり、名詞を修飾できず文が成り立たない。", "に": "位置を示す「に」では「ゴシックに教会は」となり、意味が通らない。", "へ": "方向を示す「へ」では「ゴシックへ教会は」となり、名詞につながらない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ゴシックがどの時代に広まった」の主語を示す主格の「が」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「ゴシックへどの時代に」となり、主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」になり、「ゴシックでどの時代に広まった」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」になり、「ゴシックとどの時代に広まった」では主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「ゴシックがどの時代に広まった」の主語を示す主格の「が」が正しい。", "へ": "方向の「へ」では「ゴシックへどの時代に」となり、主語にならない。", "で": "手段の「で」になり、「ゴシックでどの時代に広まった」は意味が通らない。", "と": "並列の「と」になり、「ゴシックとどの時代に広まった」では主語を示せない。"}, "error_tags": {"へ": "方向", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "中世ヨーロッパで発達した建築様式。尖塔アーチやリブ・ヴォールト、フライング・バットレスが特徴。", "primary_collocate": null, "pronunciation": "ごしっく", "ipa": "ɡoɕikkɯ", "syllable_count": 4, "sentences": [{"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]ヨーロッパで発展[はってん]したゴシック様式[ようしき]の大聖堂[だいせいどう]は、その圧倒的[あっとうてき]な高[たか]さと美[うつく]しさで人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "mined"}, {"text": "ゴシックの教会は、高い塔ととがった屋根が特徴だ。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ゴシックの教会[きょうかい]は、高[たか]い塔[とう]ととがった屋根[やね]が特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "この街には、ゴシック様式で建てられた古い駅舎が残っている。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "この街[まち]には、ゴシック様式[ようしき]で建[た]てられた古[ふる]い駅舎[えきしゃ]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "ロマネスクに比べて、ゴシックは窓が大きく、中が明るい。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ロマネスクに比[くら]べて、ゴシックは窓[まど]が大[おお]きく、中[なか]が明[あか]るい。", "sentence_source": "generated"}, {"text": "尖ったアーチを使うのが、ゴシックの大きな特徴です。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "尖[とが]ったアーチを使[つか]うのが、ゴシックの大[おお]きな特徴[とくちょう]です。", "sentence_source": "generated"}, {"text": "ゴシックの建物は、空へ向かって高くのびている。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "ゴシックの建物[たてもの]は、空[そら]へ向[む]かって高[たか]くのびている。", "sentence_source": "generated"}, {"text": "大学の礼拝堂はゴシックの設計で、ステンドグラスが美しい。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "大学[だいがく]の礼拝堂[れいはいどう]はゴシックの設計[せっけい]で、ステンドグラスが美[うつく]しい。", "sentence_source": "generated"}, {"text": "先生は、ゴシックがどの時代に広まったかを説明した。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ゴシックがどの時代[じだい]に広[ひろ]まったかを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "旅行先で、ゴシックの塔を見上げて写真を撮った。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]で、ゴシックの塔[とう]を見上[みあ]げて写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "彼は中世の建築の中で、特にゴシックが好きだ。", "target_word": "ゴシック", "complexity_tier": "T3", "furigana": "彼[かれ]は中世[ちゅうせい]の建築[けんちく]の中[なか]で、特[とく]にゴシックが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゴシック", "label": "dictionary form (noun)"}, {"form": "ゴシックの", "label": "attributive (no-adjective use)"}], "register": "neutral", "sense_fingerprint": "中世ヨーロッパの建築様式としてのゴシック(尖塔アーチ・リブ・ヴォールト・飛び梁)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゴシック", "is_correct": true, "explanation": "中世ヨーロッパで発展した建築様式の名前として、文の意味に合う。"}, {"text": "尖塔", "is_correct": false, "explanation": "建物の先端がとがった塔を指す名詞で、様式の名前としては入らない。"}, {"text": "天井", "is_correct": false, "explanation": "室内の上面を指す名詞で、「発展した〜様式」の語としては成り立たない。"}, {"text": "回廊", "is_correct": false, "explanation": "建物の周囲をつなぐ通路を指す名詞で、様式の名前にはならない。"}], "explanations": {"ゴシック": "中世ヨーロッパで発展した建築様式の名前として、文の意味に合う。", "尖塔": "建物の先端がとがった塔を指す名詞で、様式の名前としては入らない。", "天井": "室内の上面を指す名詞で、「発展した〜様式」の語としては成り立たない。", "回廊": "建物の周囲をつなぐ通路を指す名詞で、様式の名前にはならない。"}, "sentence_index": 0, "correct_answer": "ゴシック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の教会では、毎朝ゴシックが鳴って、朝を告げる。", "explanation": "ここは〈鐘楼〉（鐘をつるす塔）の意味。ゴシックは建築様式の名前なので、鐘を鳴らす物にはならず合わない。"}, {"text": "神殿の入り口に、ゴシックが並んでいる。", "explanation": "ここは〈円柱〉（丸い柱）の意味。ゴシックは様式の名前で、柱のように並ぶ物ではないので合わない。"}, {"text": "この見出しはゴシックで書かれている。", "explanation": "ここは〈ゴシック体〉（活字の書体）の意味。建築様式の義項とは別で、建物の話ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゴシック", "is_correct": true, "explanation": "礼拝堂の設計様式の名前として、文の意味に合う。"}, {"text": "鐘楼", "is_correct": false, "explanation": "鐘を吊るす塔を指す名詞で、設計の様式を表す語ではない。"}, {"text": "柱廊", "is_correct": false, "explanation": "柱が並ぶ通路を指す名詞で、設計の様式を表す語としては入らない。"}, {"text": "穹窿", "is_correct": false, "explanation": "ドーム状の天井を指す名詞で、設計の様式名としては成り立たない。"}], "explanations": {"ゴシック": "礼拝堂の設計様式の名前として、文の意味に合う。", "鐘楼": "鐘を吊るす塔を指す名詞で、設計の様式を表す語ではない。", "柱廊": "柱が並ぶ通路を指す名詞で、設計の様式を表す語としては入らない。", "穹窿": "ドーム状の天井を指す名詞で、設計の様式名としては成り立たない。"}, "sentence_index": 6, "correct_answer": "ゴシック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このゴシックは、分厚い石の壁で敵の攻撃を防いだ。", "explanation": "ここは〈城〉（防御のための建物）の意味。ゴシックは様式の名前で、敵の攻撃を防ぐ建物ではないので合わない。"}, {"text": "抹茶をゴシックに入れて、客に出した。", "explanation": "ここは〈茶碗〉（抹茶を入れる器）の意味。ゴシックは建築様式の名前で、器としては使わないので合わない。"}, {"text": "彼は、このポスターの文字をゴシックにした。", "explanation": "ここは〈ゴシック体〉（活字の書体）の意味。建築様式の義項とは別で、建物の話ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゴシックを大聖堂は、天に向かってそびえる。", "corrected_sentence": "ゴシックの大聖堂は、天に向かってそびえる。", "error_description": "〈ゴシック〉と名詞「大聖堂」をつなぐ「の」が「を」になっている。「を」は目的語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51700, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、ゴシックに建築を研究している。", "corrected_sentence": "彼は、ゴシックの建築を研究している。", "error_description": "「ゴシックの建築」の「の」が「に」になっている。「に」では研究の対象を示せず、不自然な文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「聖堂の中」の「の」で、聖堂に属する内部を示すので、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、名詞同士の所属関係を示す位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所を示すが、「聖堂で中」では所属関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置を示すが、「中に」と重なり「聖堂に中に入る」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「聖堂の中」の「の」で、聖堂に属する内部を示すので、ここに入る。", "が": "「が」は主語を示すが、名詞同士の所属関係を示す位置には入らない。", "で": "「で」は場所を示すが、「聖堂で中」では所属関係が成り立たない。", "に": "「に」は位置を示すが、「中に」と重なり「聖堂に中に入る」は不自然。"}, "error_tags": {"が": "主語", "で": "場所", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「聖堂で」の「で」で、話す場所を示すので、ここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「聖堂へ大きな声で話す」では場所の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を示すが、「聖堂と話す」では場所を示せず意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「聖堂より大きな声で話す」では意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「聖堂で」の「で」で、話す場所を示すので、ここに入る。", "へ": "「へ」は方向を示すが、「聖堂へ大きな声で話す」では場所の意味にならない。", "と": "「と」は相手を示すが、「聖堂と話す」では場所を示せず意味が通らない。", "より": "「より」は比較を示すが、「聖堂より大きな声で話す」では意味が通らない。"}, "error_tags": {"へ": "方向", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大きい建物で、神さまをおがむための特別な場所です。", "primary_collocate": null, "pronunciation": "せいどう", "ipa": "seːdoː", "syllable_count": 4, "sentences": [{"text": "聖堂は神さまにお祈りをするための建物です。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]は神[かみ]さまにお祈[いの]りをするための建物[たてもの]です。", "sentence_source": "generated"}, {"text": "聖堂の中に入ると、みんな静かになる。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]の中[なか]に入[はい]ると、みんな静[しず]かになる。", "sentence_source": "generated"}, {"text": "私は祖母と日曜日に聖堂へ行きました。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "私[わたし]は祖母[そぼ]と日曜日[にちようび]に聖堂[せいどう]へ行[い]きました。", "sentence_source": "generated"}, {"text": "聖堂はとても大きくて、天井が高い。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]はとても大[おお]きくて、天井[てんじょう]が高[たか]い。", "sentence_source": "generated"}, {"text": "聖堂の窓から、きれいな光が入ってくる。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]の窓[まど]から、きれいな光[ひかり]が入[はい]ってくる。", "sentence_source": "generated"}, {"text": "町の真ん中に古い聖堂が立っている。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "町[まち]の真[ま]ん中[なか]に古[ふる]い聖堂[せいどう]が立[た]っている。", "sentence_source": "generated"}, {"text": "聖堂の前で、結婚式の写真を撮った。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]の前[まえ]で、結婚式[けっこんしき]の写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "聖堂では大きな声で話してはいけません。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]では大[おお]きな声[こえ]で話[はな]してはいけません。", "sentence_source": "generated"}, {"text": "聖堂から歌の声が聞こえてきた。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]から歌[うた]の声[こえ]が聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "修学旅行で、有名な聖堂を見学した。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "修学旅行[しゅうがくりょこう]で、有名[ゆうめい]な聖堂[せいどう]を見学[けんがく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聖堂", "label": "dictionary form (noun)"}, {"form": "大聖堂", "label": "compound (cathedral)"}], "register": "neutral", "sense_fingerprint": "神さまに祈るための大きな特別な建物(やさしい説明の意味)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聖堂", "is_correct": true, "explanation": "神さまにお祈りをする大きな建物の名前で、この文の説明に合う。"}, {"text": "祭壇", "is_correct": false, "explanation": "祭壇は祈りの台で建物ではないので、「建物です」の説明には合わない。"}, {"text": "讃美歌", "is_correct": false, "explanation": "讃美歌は歌で、建物ではないので、この文は成り立たない。"}, {"text": "十字架", "is_correct": false, "explanation": "十字架は信仰のしるしで、建物ではないので、この文には入らない。"}], "explanations": {"聖堂": "神さまにお祈りをする大きな建物の名前で、この文の説明に合う。", "祭壇": "祭壇は祈りの台で建物ではないので、「建物です」の説明には合わない。", "讃美歌": "讃美歌は歌で、建物ではないので、この文は成り立たない。", "十字架": "十字架は信仰のしるしで、建物ではないので、この文には入らない。"}, "sentence_index": 0, "correct_answer": "聖堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "聖堂で、お坊さんがお経をあげていた。", "explanation": "ここは〈寺院〉の場面。お坊さんやお経は仏教のもので、聖堂とは合わない。"}, {"text": "聖堂で、子どもたちがサッカーの練習をした。", "explanation": "ここは〈運動場〉の場面。練習をする場所は運動場や体育館で、聖堂は神さまをおがむ場所という定義に合わないので使えない。"}, {"text": "聖堂で、先生が黒板に字を書いていた。", "explanation": "ここは〈教室〉の場面。黒板と授業は教室のもので、聖堂では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聖堂", "is_correct": true, "explanation": "写真を撮る場所になる大きな建物で、「聖堂の前で」として文に合う。"}, {"text": "鐘", "is_correct": false, "explanation": "鐘は建物ではなく、写真を撮る場所として「鐘の前で」は不自然。"}, {"text": "聖水", "is_correct": false, "explanation": "聖水は液体で、写真を撮る場所にはならないので、この文に入らない。"}, {"text": "聖歌", "is_correct": false, "explanation": "聖歌は歌で、場所を表さないので、「の前で」には合わない。"}], "explanations": {"聖堂": "写真を撮る場所になる大きな建物で、「聖堂の前で」として文に合う。", "鐘": "鐘は建物ではなく、写真を撮る場所として「鐘の前で」は不自然。", "聖水": "聖水は液体で、写真を撮る場所にはならないので、この文に入らない。", "聖歌": "聖歌は歌で、場所を表さないので、「の前で」には合わない。"}, "sentence_index": 6, "correct_answer": "聖堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "聖堂で、切符を買って電車に乗った。", "explanation": "ここは〈駅〉の場面。切符を買って電車に乗るのは駅の仕事で、聖堂は神さまをおがむ場所という定義に合わないので使えない。"}, {"text": "聖堂で、野菜を選んで代金を払った。", "explanation": "ここは〈店〉の場面。商品を選んで代金を払うのは店の仕事で、聖堂は神さまをおがむ場所という定義に合わないので使えない。"}, {"text": "聖堂で、患者が診察の順番を待った。", "explanation": "ここは〈病院〉の場面。診察や順番待ちは病院で行うもので、聖堂は神さまをおがむ場所という定義に合わないので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は祖母と日曜日に聖堂で歩いて行きました。", "corrected_sentence": "私は祖母と日曜日に聖堂へ歩いて行きました。", "error_description": "助詞の誤り。「行く」は移動先に「へ」を使う。「で」は場所での動作を示すので、移動の方向にはならない。正しくは「聖堂へ歩いて行きました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人たちは、聖堂を前で、友達と写真を撮った。", "corrected_sentence": "町の人たちは、聖堂の前で、友達と写真を撮った。", "error_description": "助詞の誤り。「前」は名詞なので「の」で結ぶ。「を」は目的語を示すので「聖堂を前で」は成り立たない。正しくは「聖堂の前で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「聖堂の中」の「の」で、聖堂に属する内部を示すので、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「聖堂を中」では名詞同士が結びつかず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、名詞同士の所属関係を示す位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「聖堂へ中」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「聖堂の中」の「の」で、聖堂に属する内部を示すので、ここに入る。", "を": "「を」は動作の対象を示すが、「聖堂を中」では名詞同士が結びつかず成り立たない。", "で": "「で」は場所や手段を示すが、名詞同士の所属関係を示す位置には入らない。", "へ": "「へ」は方向を示すが、「聖堂へ中」では意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「聖堂の高い天井」の「の」で、聖堂に属する天井を示すので、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「聖堂が高い天井を見上げて」では聖堂が見上げる主体になり、文の意味が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語だが、「聖堂を高い天井を」と目的語が二つ重なり不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、聖堂と天井の関係の比較にはならず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「聖堂の高い天井」の「の」で、聖堂に属する天井を示すので、ここに入る。", "が": "「が」は主語を示すが、「聖堂が高い天井を見上げて」では聖堂が見上げる主体になり、文の意味が崩れる。", "を": "「を」は目的語だが、「聖堂を高い天井を」と目的語が二つ重なり不自然。", "より": "「より」は比較を示すが、聖堂と天井の関係の比較にはならず、意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "キリスト教の礼拝のために建てられた、大きくて立派な建物。特に、司教という立場の人がいる教会のこと。", "primary_collocate": null, "pronunciation": "せいどう", "ipa": "seːdoː", "syllable_count": 4, "sentences": [{"text": "ゴシック様式の聖堂は、天に届くような高い天井で人々を魅了しました。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "ゴシック様式[ようしき]の聖堂[せいどう]は、天[てん]に届[とど]くような高[たか]い天井[てんじょう]で人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "generated"}, {"text": "聖堂の中は静かで、ステンドグラスの光が床に映っていた。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]の中[なか]は静[しず]かで、ステンドグラスの光[ひかり]が床[ゆか]に映[うつ]っていた。", "sentence_source": "generated"}, {"text": "日曜日の朝、人々は聖堂に集まって祈りをささげる。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]、人々[ひとびと]は聖堂[せいどう]に集[あつ]まって祈[いの]りをささげる。", "sentence_source": "generated"}, {"text": "司教は聖堂の祭壇の前で、ミサを行った。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "司教[しきょう]は聖堂[せいどう]の祭壇[さいだん]の前[まえ]で、ミサを行[おこな]った。", "sentence_source": "generated"}, {"text": "聖堂の鐘が鳴り、町じゅうに響きわたった。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]の鐘[かね]が鳴[な]り、町[まち]じゅうに響[ひび]きわたった。", "sentence_source": "generated"}, {"text": "修復中の聖堂は、一般の見学者を受け入れていない。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "修復中[しゅうふくちゅう]の聖堂[せいどう]は、一般[いっぱん]の見学者[けんがくしゃ]を受[う]け入[い]れていない。", "sentence_source": "generated"}, {"text": "この聖堂は三百年かけて完成したと言われる。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "この聖堂[せいどう]は三百年[さんびゃくねん]かけて完成[かんせい]したと言[い]われる。", "sentence_source": "generated"}, {"text": "観光客は聖堂の高い天井を見上げて、思わず声を上げた。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]は聖堂[せいどう]の高[たか]い天井[てんじょう]を見上[みあ]げて、思[おも]わず声[こえ]を上[あ]げた。", "sentence_source": "generated"}, {"text": "戦争で壊れた聖堂は、住民の寄付で建て直された。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "戦争[せんそう]で壊[こわ]れた聖堂[せいどう]は、住民[じゅうみん]の寄付[きふ]で建[た]て直[なお]された。", "sentence_source": "generated"}, {"text": "聖堂でパイプオルガンの演奏会が開かれる。", "target_word": "聖堂", "complexity_tier": "T3", "furigana": "聖堂[せいどう]でパイプオルガンの演奏会[えんそうかい]が開[ひら]かれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聖堂", "label": "dictionary form (noun)"}, {"form": "大聖堂", "label": "compound (cathedral)"}], "register": "formal", "sense_fingerprint": "キリスト教の礼拝のための大きく立派な建物。特に司教座のある教会(大聖堂)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 響きわたっ (Zipf 1.37)','sentence 8 above tier T3: contains vocabulary far above tier T3: 建て直さ (Zipf 1.69)']::text[], 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聖堂", "is_correct": true, "explanation": "教会建築としての聖堂を指し、この文の主語として合う。"}, {"text": "祭壇", "is_correct": false, "explanation": "祭壇は礼拝で使う台で建物ではないので、天井の高い建物の説明には合わない。"}, {"text": "礼拝", "is_correct": false, "explanation": "礼拝は行為を表す語で建物を指せないので、「大きな建物」の意味に合わない。"}, {"text": "祈り", "is_correct": false, "explanation": "祈りは行為を表す語で、建物として主語になれないので、この文には入らない。"}], "explanations": {"聖堂": "教会建築としての聖堂を指し、この文の主語として合う。", "祭壇": "祭壇は礼拝で使う台で建物ではないので、天井の高い建物の説明には合わない。", "礼拝": "礼拝は行為を表す語で建物を指せないので、「大きな建物」の意味に合わない。", "祈り": "祈りは行為を表す語で、建物として主語になれないので、この文には入らない。"}, "sentence_index": 0, "correct_answer": "聖堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "京都の聖堂で、住職が静かにお経を読んでいた。", "explanation": "ここは〈寺院〉の場面。住職やお経は仏教のもので、キリスト教の聖堂とは合わない。"}, {"text": "初詣で、聖堂の鳥居の前で手を合わせた。", "explanation": "ここは〈神社〉の場面。鳥居は神道の神社の門なので、聖堂とは結びつかない。"}, {"text": "天守閣のある聖堂に、城主が家臣を集めた。", "explanation": "ここは〈城〉の場面。天守閣は城の建物なので、聖堂には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聖堂", "is_correct": true, "explanation": "教会建築を指し、「三百年かけて完成した」建物として文に合う。"}, {"text": "聖歌", "is_correct": false, "explanation": "聖歌は歌で、三百年かけて完成する建物ではないので、この文に合わない。"}, {"text": "聖水", "is_correct": false, "explanation": "聖水は液体で、完成するものではないので、この文には入らない。"}, {"text": "十字架", "is_correct": false, "explanation": "十字架は象徴のしるしで、建物として三百年かけて完成したとは言えない。"}], "explanations": {"聖堂": "教会建築を指し、「三百年かけて完成した」建物として文に合う。", "聖歌": "聖歌は歌で、三百年かけて完成する建物ではないので、この文に合わない。", "聖水": "聖水は液体で、完成するものではないので、この文には入らない。", "十字架": "十字架は象徴のしるしで、建物として三百年かけて完成したとは言えない。"}, "sentence_index": 6, "correct_answer": "聖堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先祖の聖堂の前で、家族が線香をあげた。", "explanation": "ここは〈墓〉の場面。線香は仏式の供養で、キリスト教の聖堂は墓の代わりにはならない。"}, {"text": "家の聖堂に、毎朝お米を供えた。", "explanation": "ここは〈神棚〉の場面。神棚は家庭の神道の祭壇で、聖堂は教会建築なので家に置かない。"}, {"text": "聖堂で新鮮な魚を買った。", "explanation": "ここは〈市場〉の場面。魚を買う場所は市場で、聖堂は買い物の場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "信者たちは、日曜日の朝に聖堂を集まって、静かに祈る。", "corrected_sentence": "信者たちは、日曜日の朝に聖堂に集まって、静かに祈る。", "error_description": "助詞の誤り。「集まる」は集まる場所に「に」をとるので、「聖堂を」は不自然。正しくは「聖堂に集まって」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の町の人々は、聖堂が建てた。", "corrected_sentence": "昔の町の人々は、聖堂を建てた。", "error_description": "助詞の誤り。「建てる」は作るものを「を」で示す。「聖堂が」では聖堂が主語になり不自然。正しくは「聖堂を建てた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「子どもたちを」の「を」で、魅了の対象を示す目的語として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「子どもたちが魅了しました」では子どもが引きつける側になり、文の意味が逆になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「子どもたちで魅了」では対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、魅了の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「子どもたちを」の「を」で、魅了の対象を示す目的語として正しい。", "が": "「が」は主語を示すが、「子どもたちが魅了しました」では子どもが引きつける側になり、文の意味が逆になる。", "で": "「で」は場所や手段を示すが、「子どもたちで魅了」では対象を示せない。", "へ": "「へ」は方向を示すが、魅了の対象には合わない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「写真に魅了され」の「に」で、受身の魅了される原因を示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、受身の「魅了される」では写真に付けると不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、ここでは原因を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「写真より魅了され」では比較の相手が合わない。"}], "correct_answer": "に", "explanations": {"に": "「写真に魅了され」の「に」で、受身の魅了される原因を示すので正しい。", "を": "「を」は目的語を示すが、受身の「魅了される」では写真に付けると不自然。", "と": "「と」は並列や相手を示すが、ここでは原因を示せない。", "より": "「より」は比較を示すが、「写真より魅了され」では比較の相手が合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人の心をひきつけて、夢中にさせること。", "primary_collocate": null, "pronunciation": "みりょう", "ipa": "miɾʲoː", "syllable_count": 3, "sentences": [{"text": "彼のダンスは見る人を魅了する。", "target_word": "魅了", "complexity_tier": "T2", "furigana": "彼[かれ]のダンスは見[み]る人[ひと]を魅了[みりょう]する。", "sentence_source": "generated"}, {"text": "サーカスの空中ブランコは、子どもたちを魅了しました。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "サーカスの空中[くうちゅう]ブランコは、子[こ]どもたちを魅了[みりょう]しました。", "sentence_source": "generated"}, {"text": "夜空に広がる満天の星に魅了され、時間を忘れて見上げていた。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "夜空[よぞら]に広[ひろ]がる満天[まんてん]の星[ほし]に魅了[みりょう]され、時間[じかん]を忘[わす]れて見上[みあ]げていた。", "sentence_source": "generated"}, {"text": "あの店員の笑顔は客を魅了するので、売り上げも伸びている。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "あの店員[てんいん]の笑顔[えがお]は客[きゃく]を魅了[みりょう]するので、売[う]り上[あ]げも伸[の]びている。", "sentence_source": "generated"}, {"text": "森の静けさに魅了された旅行者が、毎年この村を訪れます。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "森[もり]の静[しず]けさに魅了[みりょう]された旅行者[りょこうしゃ]が、毎年[まいとし]この村[むら]を訪[おとず]れます。", "sentence_source": "generated"}, {"text": "彼女は朗読の声で教室全体を魅了した。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は朗読[ろうどく]の声[こえ]で教室[きょうしつ]全体[ぜんたい]を魅了[みりょう]した。", "sentence_source": "generated"}, {"text": "新しい香水の甘い香りが、多くの女性を魅了しています。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "新[あたら]しい香水[こうすい]の甘[あま]い香[かお]りが、多[おお]くの女性[じょせい]を魅了[みりょう]しています。", "sentence_source": "generated"}, {"text": "少年は初めて見た宇宙の写真に魅了され、天文学者を目指した。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "少年[しょうねん]は初[はじ]めて見[み]た宇宙[うちゅう]の写真[しゃしん]に魅了[みりょう]され、天文学者[てんもんがくしゃ]を目指[めざ]した。", "sentence_source": "generated"}, {"text": "この小説の謎めいた展開は、読者を魅了してやまない。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "この小説[しょうせつ]の謎[なぞ]めいた展開[てんかい]は、読者[どくしゃ]を魅了[みりょう]してやまない。", "sentence_source": "generated"}, {"text": "舞台に立つ彼の存在感は、観客を一瞬で魅了した。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "舞台[ぶたい]に立[た]つ彼[かれ]の存在感[そんざいかん]は、観客[かんきゃく]を一瞬[いっしゅん]で魅了[みりょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "魅了する", "label": "終止形"}, {"form": "魅了した", "label": "過去形"}, {"form": "魅了される", "label": "受身形"}, {"form": "魅了して", "label": "て形"}, {"form": "魅了しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "人の心をとらえて夢中にさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魅了", "is_correct": true, "explanation": "「見る人を魅了する」で、人の心を引きつける意味に合う。"}, {"text": "疲弊", "is_correct": false, "explanation": "疲弊は心身が弱る意味の自動詞的な語で、「見る人を疲弊する」は成り立たない。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光が明暗を繰り返す意味で、人を対象にとれない。"}, {"text": "沈黙", "is_correct": false, "explanation": "沈黙は黙る意味の語で、「見る人を沈黙する」は成り立たない。"}], "explanations": {"魅了": "「見る人を魅了する」で、人の心を引きつける意味に合う。", "疲弊": "疲弊は心身が弱る意味の自動詞的な語で、「見る人を疲弊する」は成り立たない。", "点滅": "点滅は光が明暗を繰り返す意味で、人を対象にとれない。", "沈黙": "沈黙は黙る意味の語で、「見る人を沈黙する」は成り立たない。"}, "sentence_index": 0, "correct_answer": "魅了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は映画館で、強い魅了を支払った。", "explanation": "ここは〈会計〉の場面。支払うのはお金で、魅了は人を引きつける働きなので合わない。"}, {"text": "長時間の作業で、体に魅了がたまった。", "explanation": "ここは〈疲れ〉の場面。「たまる」は疲れなど蓄積するものに使い、魅了は蓄積しない。"}, {"text": "隣人の騒音で、魅了をこうむった。", "explanation": "ここは〈迷惑〉の場面。「こうむる」は迷惑や損害に使い、魅了はこうむるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魅了", "is_correct": true, "explanation": "「女性を魅了しています」で、香りが人の心を引きつける意味に合う。"}, {"text": "沈殿", "is_correct": false, "explanation": "沈殿は沈んで溜まる意味で、女性を対象にとれない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつける意味で、「女性を点火」は成り立たない。"}, {"text": "脱臭", "is_correct": false, "explanation": "脱臭は臭いを取る意味で、人を対象にとらないので合わない。"}], "explanations": {"魅了": "「女性を魅了しています」で、香りが人の心を引きつける意味に合う。", "沈殿": "沈殿は沈んで溜まる意味で、女性を対象にとれない。", "点火": "点火は火をつける意味で、「女性を点火」は成り立たない。", "脱臭": "脱臭は臭いを取る意味で、人を対象にとらないので合わない。"}, "sentence_index": 6, "correct_answer": "魅了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜、雪道でトラックが魅了を起こした。", "explanation": "ここは〈事故〉の場面。事故は起こすものだが、魅了は人の心をとらえる働きで、事故の原因にはならないので合わない。"}, {"text": "停電で、街は大きな魅了に陥った。", "explanation": "ここは〈混乱〉の場面。陥るのは混乱などの状態で、魅了は陥る状態ではない。"}, {"text": "友人の別れの言葉に、魅了が込み上げた。", "explanation": "ここは〈悲しみ〉の場面。込み上げるのは感情で、魅了は人を引きつける働きであり感情ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その演奏は、聴衆を魅了される。", "corrected_sentence": "その演奏は、聴衆を魅了する。", "error_description": "受身の誤り。「聴衆を」は目的語なので、受身の「される」は主語がずれて不自然。能動の「魅了する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51703, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の演説は、聴く人の心を魅了たした。", "corrected_sentence": "彼の演説は、聴く人の心を魅了した。", "error_description": "活用の誤り。「魅了する」の過去形は「魅了した」で、「魅了た」は活用が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「すぐに」の「に」で、副詞を作る形として自然に入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「すぐが魅了した」では副詞が主語にならず成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「すぐを魅了した」では副詞に付かず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「すぐで魅了した」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「すぐに」の「に」で、副詞を作る形として自然に入る。", "が": "「が」は主語を示すが、「すぐが魅了した」では副詞が主語にならず成り立たない。", "を": "「を」は目的語を示すが、「すぐを魅了した」では副詞に付かず不自然。", "で": "「で」は手段を示すが、「すぐで魅了した」では意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「若者を」の「を」で、魅了の対象を示す目的語として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、魅了の対象には使わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは対象を示せず意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、魅了の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「若者を」の「を」で、魅了の対象を示す目的語として正しい。", "と": "「と」は並列や相手を示すが、魅了の対象には使わない。", "より": "「より」は比較を示すが、ここでは対象を示せず意味が通らない。", "へ": "「へ」は方向を示すが、魅了の対象には合わない。"}, "error_tags": {"と": "並列", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人の注意や興味を強く引きつけて、その心をとらえること。", "primary_collocate": null, "pronunciation": "みりょう", "ipa": "miɾʲoː", "syllable_count": 3, "sentences": [{"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]ヨーロッパで発展[はってん]したゴシック様式[ようしき]の大聖堂[だいせいどう]は、その圧倒的[あっとうてき]な高[たか]さと美[うつく]しさで人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "mined"}, {"text": "彼女の歌声は、聞いた人をすぐに魅了した。", "target_word": "魅了", "complexity_tier": "T2", "furigana": "彼女[かのじょ]の歌声[うたごえ]は、聞[き]いた人[ひと]をすぐに魅了[みりょう]した。", "sentence_source": "generated"}, {"text": "この映画は、美しい映像で世界中の観客を魅了しています。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "この映画[えいが]は、美[うつく]しい映像[えいぞう]で世界中[せかいじゅう]の観客[かんきゃく]を魅了[みりょう]しています。", "sentence_source": "generated"}, {"text": "若い画家の絵は、多くの来場者を魅了しました。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "若[わか]い画家[がか]の絵[え]は、多[おお]くの来場者[らいじょうしゃ]を魅了[みりょう]しました。", "sentence_source": "generated"}, {"text": "彼の話し方には人を魅了する力があるので、講演はいつも満員だ。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]には人[ひと]を魅了[みりょう]する力[ちから]があるので、講演[こうえん]はいつも満員[まんいん]だ。", "sentence_source": "generated"}, {"text": "観客はピアニストの繊細な演奏に魅了されて、最後まで席を立てなかった。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "観客[かんきゃく]はピアニストの繊細[せんさい]な演奏[えんそう]に魅了[みりょう]されて、最後[さいご]まで席[せき]を立[た]てなかった。", "sentence_source": "generated"}, {"text": "京都の古い町並みに魅了され、私は何度もこの町を訪れています。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "京都[きょうと]の古[ふる]い町並[まちな]みに魅了[みりょう]され、私[わたし]は何度[なんど]もこの町[まち]を訪[おとず]れています。", "sentence_source": "generated"}, {"text": "新しいゲームは、独特の世界観で若者を魅了している。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "新[あたら]しいゲームは、独特[どくとく]の世界観[せかいかん]で若者[わかもの]を魅了[みりょう]している。", "sentence_source": "generated"}, {"text": "市場の活気にすっかり魅了されて、予定より長く滞在しました。", "target_word": "魅了", "complexity_tier": "T3", "furigana": "市場[いちば]の活気[かっき]にすっかり魅了[みりょう]されて、予定[よてい]より長[なが]く滞在[たいざい]しました。", "sentence_source": "generated"}, {"text": "その作家の物語は、子どもから大人まで幅広い読者を魅了し続けている。", "target_word": "魅了", "complexity_tier": "T4", "furigana": "その作家[さっか]の物語[ものがたり]は、子[こ]どもから大人[おとな]まで幅広[はばひろ]い読者[どくしゃ]を魅了[みりょう]し続[つづ]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "魅了する", "label": "終止形"}, {"form": "魅了した", "label": "過去形"}, {"form": "魅了される", "label": "受身形"}, {"form": "魅了して", "label": "て形"}, {"form": "魅了しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "美しさや魅力で人の注意と心を強く引きつける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魅了", "is_correct": true, "explanation": "「人々を魅了しました」の形で、美しさが人の心を引きつける意味に合う。"}, {"text": "疲弊", "is_correct": false, "explanation": "疲弊は心身が弱ることで、「美しさで人々を疲弊」は意味が通らない。"}, {"text": "中断", "is_correct": false, "explanation": "中断は途切れさせる意味で、「美しさで人々を中断」は合わない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集団を散らす意味で、「美しさで人々を解散」は合わない。"}], "explanations": {"魅了": "「人々を魅了しました」の形で、美しさが人の心を引きつける意味に合う。", "疲弊": "疲弊は心身が弱ることで、「美しさで人々を疲弊」は意味が通らない。", "中断": "中断は途切れさせる意味で、「美しさで人々を中断」は合わない。", "解散": "解散は集団を散らす意味で、「美しさで人々を解散」は合わない。"}, "sentence_index": 0, "correct_answer": "魅了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は店員に、独特の魅了を注文した。", "explanation": "ここは〈注文〉の場面。注文するのは料理などの品物で、魅了は人を引きつける働きなので合わない。"}, {"text": "助けてくれた友人に、私は心から魅了の言葉を述べた。", "explanation": "ここは〈感謝〉の場面。感謝の言葉を述べると言う。魅了は人の心を引きつけて夢中にさせる働きを指すので、感謝の気持ちを表す言葉には使えない。"}, {"text": "その美しい景色に、私は思わず魅了の声を上げた。", "explanation": "ここは〈感嘆〉の場面。感嘆の声を上げると言う。魅了は人の心を引きつけて夢中にさせる働きを指すので、声を上げる表現には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魅了", "is_correct": true, "explanation": "「魅了され」の語幹で、町並みに心を引きつけられた意味に合う。"}, {"text": "混乱", "is_correct": false, "explanation": "混乱は乱れる意味で、「町並みに混乱され」は合わない。"}, {"text": "追放", "is_correct": false, "explanation": "追放は排除する意味で、町並みには使えない。"}, {"text": "暴落", "is_correct": false, "explanation": "暴落は価格が急に下がる意味で、町並みには合わない。"}], "explanations": {"魅了": "「魅了され」の語幹で、町並みに心を引きつけられた意味に合う。", "混乱": "混乱は乱れる意味で、「町並みに混乱され」は合わない。", "追放": "追放は排除する意味で、町並みには使えない。", "暴落": "暴落は価格が急に下がる意味で、町並みには合わない。"}, "sentence_index": 6, "correct_answer": "魅了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、月間の魅了を更新した。", "explanation": "ここは〈売上記録〉の場面。記録は更新するものだが、魅了は人の心をとらえる働きで、数字の記録にはならないので合わない。"}, {"text": "彼は毎月の支払いを、魅了で返済した。", "explanation": "ここは〈借金〉の場面。借金は返済するものだが、魅了は人の心をとらえる働きで、お金の返済には使えないので合わない。"}, {"text": "長い旅の魅了を癒すため、温泉に入った。", "explanation": "ここは〈疲れ〉の場面。癒すのは疲れなど体や心の状態で、魅了は癒すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の歌声は、聞いた人を魅了された。", "corrected_sentence": "彼女の歌声は、聞いた人を魅了した。", "error_description": "受身の誤り。歌声が人を引きつける能動の動作なので、「魅了された」の受身は不適切。正しくは能動の「魅了した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51704, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その音楽は、多くのファンを魅了されている。", "corrected_sentence": "その音楽は、多くのファンを魅了している。", "error_description": "受身の誤り。「ファンを」は目的語なのに受身の「されている」を付けたため主語がずれている。能動の「魅了している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「当時から」は『その時からずっと』の意味になり、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「当時が」は主語として『書いている』と続かず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「当時を」は目的語になり、後ろの『日記を』と重なって不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「当時と」は並列の相手にならず、この文では意味が通らない。"}], "correct_answer": "から", "explanations": {"から": "「当時から」は『その時からずっと』の意味になり、文に合う。", "が": "「当時が」は主語として『書いている』と続かず、文が成り立たない。", "を": "「当時を」は目的語になり、後ろの『日記を』と重なって不自然になる。", "と": "「当時と」は並列の相手にならず、この文では意味が通らない。"}, "error_tags": {"が": "主格", "を": "目的格", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「当時は緊張していた」の「は」で、『入社した当時』を主題として示す。"}, {"text": "へ", "is_correct": false, "explanation": "「当時へ緊張していた」は方向の意味になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「当時で緊張していた」は手段や場所の意味になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「当時の緊張していた」では述語が続かず、名詞修飾としても不自然になる。"}], "correct_answer": "は", "explanations": {"は": "「当時は緊張していた」の「は」で、『入社した当時』を主題として示す。", "へ": "「当時へ緊張していた」は方向の意味になり、文が成り立たない。", "で": "「当時で緊張していた」は手段や場所の意味になり、文が成り立たない。", "の": "「当時の緊張していた」では述語が続かず、名詞修飾としても不自然になる。"}, "error_tags": {"へ": "方向", "で": "手段・場所", "の": "名詞修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "むかしのあるときのこと。", "primary_collocate": null, "pronunciation": "とうじ", "ipa": "toːdʑi", "syllable_count": 3, "sentences": [{"text": "当時のことを思い出すと、今でも胸が熱くなる。", "target_word": "当時", "complexity_tier": "T3", "furigana": "当時[とうじ]のことを思[おも]い出[だ]すと、今[いま]でも胸[むね]が熱[あつ]くなる。", "sentence_source": "generated"}, {"text": "彼女は小学生だった当時から、毎日日記を書いている。", "target_word": "当時", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は小学生[しょうがくせい]だった当時[とうじ]から、毎日[まいにち]日記[にっき]を書[か]いている。", "sentence_source": "generated"}, {"text": "事故が起きた当時、私は海外に住んでいました。", "target_word": "当時", "complexity_tier": "T3", "furigana": "事故[じこ]が起[お]きた当時[とうじ]、私[わたし]は海外[かいがい]に住[す]んでいました。", "sentence_source": "generated"}, {"text": "当時は貧しかったが、家族みんなで楽しく暮らしていた。", "target_word": "当時", "complexity_tier": "T3", "furigana": "当時[とうじ]は貧[まず]しかったが、家族[かぞく]みんなで楽[たの]しく暮[く]らしていた。", "sentence_source": "generated"}, {"text": "祖母は結婚した当時の思い出を、アルバムを開きながら語ってくれた。", "target_word": "当時", "complexity_tier": "T4", "furigana": "祖母[そぼ]は結婚[けっこん]した当時[とうじ]の思[おも]い出[で]を、アルバムを開[ひら]きながら語[かた]ってくれた。", "sentence_source": "generated"}, {"text": "この店は開店当時、客が一人も来なかったそうです。", "target_word": "当時", "complexity_tier": "T3", "furigana": "この店[みせ]は開店[かいてん]当時[とうじ]、客[きゃく]が一人[ひとり]も来[こ]なかったそうです。", "sentence_source": "generated"}, {"text": "手紙には、二人が出会った当時の様子が細かく書かれていた。", "target_word": "当時", "complexity_tier": "T4", "furigana": "手紙[てがみ]には、二人[ふたり]が出会[であ]った当時[とうじ]の様子[ようす]が細[こま]かく書[か]かれていた。", "sentence_source": "generated"}, {"text": "入社した当時は緊張していたが、今は仕事にも慣れた。", "target_word": "当時", "complexity_tier": "T3", "furigana": "入社[にゅうしゃ]した当時[とうじ]は緊張[きんちょう]していたが、今[いま]は仕事[しごと]にも慣[な]れた。", "sentence_source": "generated"}, {"text": "当時の私はまだ若く、将来のことなど考えていなかった。", "target_word": "当時", "complexity_tier": "T3", "furigana": "当時[とうじ]の私[わたし]はまだ若[わか]く、将来[しょうらい]のことなど考[かんが]えていなかった。", "sentence_source": "generated"}, {"text": "卒業して二十年たつが、当時の担任の先生の言葉は忘れられない。", "target_word": "当時", "complexity_tier": "T4", "furigana": "卒業[そつぎょう]して二十年[にじゅうねん]たつが、当時[とうじ]の担任[たんにん]の先生[せんせい]の言葉[ことば]は忘[わす]れられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当時", "label": "基本形"}, {"form": "当時の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "過去のある出来事があった、そのころ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 貧しかっ (Zipf 2.46)']::text[], 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": false, "explanation": "「未来のこと」は今後の話で、過去を思い出す文脈に合わない。"}, {"text": "明日", "is_correct": false, "explanation": "「明日のこと」はまだ来ていない時期で、思い出す対象にならない。"}, {"text": "当時", "is_correct": true, "explanation": "「当時のこと」はむかしのある時期の出来事を指し、思い出す文脈に合う。"}, {"text": "来週", "is_correct": false, "explanation": "「来週のこと」はこれから来る時期で、思い出すことはできない。"}], "explanations": {"未来": "「未来のこと」は今後の話で、過去を思い出す文脈に合わない。", "明日": "「明日のこと」はまだ来ていない時期で、思い出す対象にならない。", "当時": "「当時のこと」はむかしのある時期の出来事を指し、思い出す文脈に合う。", "来週": "「来週のこと」はこれから来る時期で、思い出すことはできない。"}, "sentence_index": 0, "correct_answer": "当時"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三角形の内角の和は当時百八十度だ。", "explanation": "当時は特定のむかしの時期を指すので、いつでも成り立つ法則には使えない。"}, {"text": "家事と育児を当時にこなすのは大変だ。", "explanation": "当時は時期を指す語で、二つの作業を同じ時に行う意味には使えない（同時が正しい）。"}, {"text": "次回の会議は、当時、本社で開かれる。", "explanation": "当時は過ぎた時期を指すので、これから開かれる会議には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来世", "is_correct": false, "explanation": "「出会った来世の様子」は時間の関係が成り立たず、文に合わない。"}, {"text": "次回", "is_correct": false, "explanation": "「出会った次回の様子」は過去の出会いとつながらない。"}, {"text": "当時", "is_correct": true, "explanation": "「出会った当時の様子」は、その出会いの時期の様子を指し、文に合う。"}, {"text": "来春", "is_correct": false, "explanation": "「出会った来春の様子」は未来の時期で、出会いの時期と合わない。"}], "explanations": {"来世": "「出会った来世の様子」は時間の関係が成り立たず、文に合わない。", "次回": "「出会った次回の様子」は過去の出会いとつながらない。", "当時": "「出会った当時の様子」は、その出会いの時期の様子を指し、文に合う。", "来春": "「出会った来春の様子」は未来の時期で、出会いの時期と合わない。"}, "sentence_index": 6, "correct_answer": "当時"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当時は気をつけて運転します。", "explanation": "当時は過ぎた時期を指すので、今後の決意には使えない。"}, {"text": "当時、毎朝ジョギングをしている。", "explanation": "当時は過去の一時期を指すので、今の毎日の習慣には使えない。"}, {"text": "当時、電車が来ます。", "explanation": "当時は過去の時期を指すので、これから来る電車には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当時で電話もなく、手紙で連絡を取り合っていた。", "corrected_sentence": "当時は電話もなく、手紙で連絡を取り合っていた。", "error_description": "「当時」は主題を示すので「は」が正しい。「で」は手段や場所を表し、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51705, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "入社した当時を不安だったが、今は仕事にも慣れた。", "corrected_sentence": "入社した当時は不安だったが、今は仕事にも慣れた。", "error_description": "「不安だった」は目的語をとらないので「を」は誤り。主題を示す「は」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
