INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51706, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「当時の首相」の「の」で、名詞「当時」が後ろの名詞を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「当時が首相は」では「当時」が主語として文を組み立てられず、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「当時を首相」は目的語にならず、名詞を修飾する形も作れない。"}, {"text": "で", "is_correct": false, "explanation": "「当時で首相」は手段や場所の意味にならず、名詞に続かない。"}], "correct_answer": "の", "explanations": {"の": "「当時の首相」の「の」で、名詞「当時」が後ろの名詞を修飾する。", "が": "「当時が首相は」では「当時」が主語として文を組み立てられず、意味が通らない。", "を": "「当時を首相」は目的語にならず、名詞を修飾する形も作れない。", "で": "「当時で首相」は手段や場所の意味にならず、名詞に続かない。"}, "error_tags": {"が": "主格", "を": "目的格", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51706, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その時、その時代。", "primary_collocate": null, "pronunciation": "とうじ", "ipa": "toːdʑi", "syllable_count": 3, "sentences": [{"text": "この建設には、当時の建築工学の知恵が結集されています。", "target_word": "当時", "complexity_tier": "T4", "furigana": "この建設[けんせつ]には、当時[とうじ]の建築[けんちく]工学[こうがく]の知恵[ちえ]が結集[けっしゅう]されています。", "sentence_source": "mined"}, {"text": "当時、この町にはまだ電車が通っていなかった。", "target_word": "当時", "complexity_tier": "T2", "furigana": "当時[とうじ]、この町[まち]にはまだ電車[でんしゃ]が通[かよ]っていなかった。", "sentence_source": "generated"}, {"text": "祖父は戦後の混乱期を生き抜き、当時の苦労をよく話してくれた。", "target_word": "当時", "complexity_tier": "T4", "furigana": "祖父[そふ]は戦後[せんご]の混乱期[こんらんき]を生[い]き抜[ぬ]き、当時[とうじ]の苦労[くろう]をよく話[はな]してくれた。", "sentence_source": "generated"}, {"text": "当時の写真を見ると、街の様子が今とまったく違います。", "target_word": "当時", "complexity_tier": "T3", "furigana": "当時[とうじ]の写真[しゃしん]を見[み]ると、街[まち]の様子[ようす]が今[いま]とまったく違[ちが]います。", "sentence_source": "generated"}, {"text": "その本は昭和初期に書かれたので、当時の言葉遣いが多く残っている。", "target_word": "当時", "complexity_tier": "T4", "furigana": "その本[ほん]は昭和[しょうわ]初期[しょき]に書[か]かれたので、当時[とうじ]の言葉遣[ことばづか]いが多[おお]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "彼は十年前に大学を卒業したが、当時の友人とは今も連絡を取っている。", "target_word": "当時", "complexity_tier": "T4", "furigana": "彼[かれ]は十年前[じゅうねんまえ]に大学[だいがく]を卒業[そつぎょう]したが、当時[とうじ]の友人[ゆうじん]とは今[いま]も連絡[れんらく]を取[と]っている。", "sentence_source": "generated"}, {"text": "江戸時代の人々は、当時としては珍しい旅行ブームを楽しんでいました。", "target_word": "当時", "complexity_tier": "T4", "furigana": "江戸[えど]時代[じだい]の人々[ひとびと]は、当時[とうじ]としては珍[めずら]しい旅行[りょこう]ブームを楽[たの]しんでいました。", "sentence_source": "generated"}, {"text": "当時の首相は、経済政策の見直しを国会で発表した。", "target_word": "当時", "complexity_tier": "T3", "furigana": "当時[とうじ]の首相[しゅしょう]は、経済[けいざい]政策[せいさく]の見直[みなお]しを国会[こっかい]で発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "新幹線が開通した当時、東京から大阪まで約四時間かかりました。", "target_word": "当時", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]が開通[かいつう]した当時[とうじ]、東京[とうきょう]から大阪[おおさか]まで約[やく]四時間[よじかん]かかりました。", "sentence_source": "generated"}, {"text": "当時はスマートフォンがなかったので、地図を紙で確認した。", "target_word": "当時", "complexity_tier": "T3", "furigana": "当時[とうじ]はスマートフォンがなかったので、地図[ちず]を紙[かみ]で確認[かくにん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当時", "label": "基本形"}, {"form": "当時の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "話題にしている過去のその時期や時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 生き抜き (Zipf 2.16)']::text[], 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": false, "explanation": "「未来の建築工学」では、既に建てられた建物の知恵の説明にならず、過去の建設と合わない。"}, {"text": "当時", "is_correct": true, "explanation": "「当時の建築工学」は過去のその時代の技術を指し、昔の建設の文脈に合う。"}, {"text": "翌日", "is_correct": false, "explanation": "「翌日の建築工学」は翌日を指し、昔の建設の知恵の説明にならず、文に合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "「昨日の建築工学」は、長く受け継がれた技術の由来として不自然で、文に合わない。"}], "explanations": {"未来": "「未来の建築工学」では、既に建てられた建物の知恵の説明にならず、過去の建設と合わない。", "当時": "「当時の建築工学」は過去のその時代の技術を指し、昔の建設の文脈に合う。", "翌日": "「翌日の建築工学」は翌日を指し、昔の建設の知恵の説明にならず、文に合わない。", "昨日": "「昨日の建築工学」は、長く受け継がれた技術の由来として不自然で、文に合わない。"}, "sentence_index": 0, "correct_answer": "当時"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの作業を当時に行い、時間を節約した。", "explanation": "当時は時期を指す語で、二つの作業を同じ時に行う意味には使えない。"}, {"text": "当時は貯金を崩して生活するしかない。", "explanation": "当時は過ぎた時期を指すので、さしあたりの生活の話には使えない。"}, {"text": "来年の当時には、工事がすっかり終わっているだろう。", "explanation": "当時はすでに過ぎた時期を指すので、来年の場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明日", "is_correct": false, "explanation": "「明日としては珍しい」は文脈上成り立たず、江戸時代の話に合わない。"}, {"text": "翌年", "is_correct": false, "explanation": "「翌年としては珍しい」は江戸の人々の時代を指せず、文に合わない。"}, {"text": "当時", "is_correct": true, "explanation": "「当時としては」は『その時代の水準では』の意味になり、文に合う。"}, {"text": "昨年", "is_correct": false, "explanation": "「昨年としては珍しい」は江戸時代の話と時間が合わない。"}], "explanations": {"明日": "「明日としては珍しい」は文脈上成り立たず、江戸時代の話に合わない。", "翌年": "「翌年としては珍しい」は江戸の人々の時代を指せず、文に合わない。", "当時": "「当時としては」は『その時代の水準では』の意味になり、文に合う。", "昨年": "「昨年としては珍しい」は江戸時代の話と時間が合わない。"}, "sentence_index": 6, "correct_answer": "当時"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当時は雨が続くでしょう。", "explanation": "当時は過ぎた時期を指すので、これからの予測には使えない。"}, {"text": "水は当時百度で沸騰する。", "explanation": "当時は特定の過去の時期を指すので、いつでも成り立つ事実には使えない。"}, {"text": "私は当時、この道を通って学校へ行く。", "explanation": "当時は過去の一時期を指すので、今の毎日の習慣には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その城は当時に大名によって建てられた。", "corrected_sentence": "その城は当時の大名によって建てられた。", "error_description": "「当時」は名詞を修飾するので「の」が正しい形。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当時な町並みを、今も残している地区がある。", "corrected_sentence": "当時の町並みを、今も残している地区がある。", "error_description": "「当時」は名詞なので、名詞を修飾するには「の」を使う。「な」は形容動詞用で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51707, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜には〜かかる」の「に」。事柄（建築）が要した対象を示し、「建築には一年かかった」で自然"}, {"text": "を", "is_correct": false, "explanation": "「かかる」の主語は建築なので、目的語の「を」では文が崩れる"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を示す「と」。「建築と一年かかった」では意味がつながらない"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示す「より」。「建築より一年かかった」では比較対象が示されず不自然"}], "correct_answer": "に", "explanations": {"に": "「〜には〜かかる」の「に」。事柄（建築）が要した対象を示し、「建築には一年かかった」で自然", "を": "「かかる」の主語は建築なので、目的語の「を」では文が崩れる", "と": "共同の相手を示す「と」。「建築と一年かかった」では意味がつながらない", "より": "比較や起点を示す「より」。「建築より一年かかった」では比較対象が示されず不自然"}, "error_tags": {"を": "object_marker", "と": "companion", "より": "comparison"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解体", "is_correct": true, "explanation": "建物をたてることの反対で、建てた建物を取り壊すことを指し、建築の対義語になる"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取り除く行為で、建物をたてることの対義語ではない"}, {"text": "購入", "is_correct": false, "explanation": "買い入れることで、建物をたてることとは対になっていない"}, {"text": "点検", "is_correct": false, "explanation": "調べて確認することで、建物をたてることの反対の行為ではない"}], "correct_answer": "解体", "explanations": {"解体": "建物をたてることの反対で、建てた建物を取り壊すことを指し、建築の対義語になる", "掃除": "汚れを取り除く行為で、建物をたてることの対義語ではない", "購入": "買い入れることで、建物をたてることとは対になっていない", "点検": "調べて確認することで、建物をたてることの反対の行為ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
