INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51707, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "建物をたてること。", "primary_collocate": null, "pronunciation": "けんちく", "ipa": "keɲtɕikɯ", "syllable_count": 4, "sentences": [{"text": "駅の前に、新しい図書館の建築が始まった。", "target_word": "建築", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に、新[あたら]しい図書館[としょかん]の建築[けんちく]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "この家の建築には、一年かかった。", "target_word": "建築", "complexity_tier": "T3", "furigana": "この家[いえ]の建築[けんちく]には、一年[いちねん]かかった。", "sentence_source": "generated"}, {"text": "この古い寺は、百年前に建築された。", "target_word": "建築", "complexity_tier": "T3", "furigana": "この古い寺[てら]は、百年前[ひゃくねんまえ]に建築[けんちく]された。", "sentence_source": "generated"}, {"text": "建築中のビルから、大きな音が聞こえる。", "target_word": "建築", "complexity_tier": "T3", "furigana": "建築中[けんちくちゅう]のビルから、大[おお]きな音[おと]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "地震に強い建築の方法が研究されている。", "target_word": "建築", "complexity_tier": "T3", "furigana": "地震[じしん]に強[つよ]い建築[けんちく]の方法[ほうほう]が研究[けんきゅう]されている。", "sentence_source": "generated"}, {"text": "祖父は、建築の仕事を四十年続けた。", "target_word": "建築", "complexity_tier": "T3", "furigana": "祖父[そふ]は、建築[けんちく]の仕事[しごと]を四十年[よんじゅうねん]続[つづ]けた。", "sentence_source": "generated"}, {"text": "山の上に家を建築するのは、費用がかかる。", "target_word": "建築", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に家[いえ]を建築[けんちく]するのは、費用[ひよう]がかかる。", "sentence_source": "generated"}, {"text": "建築が始まる前に、近所の人に説明があった。", "target_word": "建築", "complexity_tier": "T3", "furigana": "建築[けんちく]が始[はじ]まる前[まえ]に、近所[きんじょ]の人[ひと]に説明[せつめい]があった。", "sentence_source": "generated"}, {"text": "父は木造の建築にこだわり、家を建てた。", "target_word": "建築", "complexity_tier": "T3", "furigana": "父は木造[もくぞう]の建築[けんちく]にこだわり、家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "学校の建築のために、町の人がお金を出した。", "target_word": "建築", "complexity_tier": "T3", "furigana": "学校[がっこう]の建築[けんちく]のために、町[まち]の人[ひと]がお金[かね]を出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建築する", "label": "辞書形"}, {"form": "建築した", "label": "過去形"}, {"form": "建築して", "label": "て形"}, {"form": "建築される", "label": "受身形"}, {"form": "建築中", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "家やビルなどの建物を造り上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51707, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建築", "is_correct": true, "explanation": "建物をたてることを指し、「新しい図書館の建築が始まった」と文意が通る"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしに歩くことで、図書館の散歩が始まったとは言えない"}, {"text": "花粉", "is_correct": false, "explanation": "植物の粉で、図書館について「花粉が始まった」は意味が通らない"}, {"text": "手術", "is_correct": false, "explanation": "医療行為で、図書館に対して「手術が始まった」は成り立たない"}], "explanations": {"建築": "建物をたてることを指し、「新しい図書館の建築が始まった」と文意が通る", "散歩": "気晴らしに歩くことで、図書館の散歩が始まったとは言えない", "花粉": "植物の粉で、図書館について「花粉が始まった」は意味が通らない", "手術": "医療行為で、図書館に対して「手術が始まった」は成り立たない"}, "sentence_index": 0, "correct_answer": "建築"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この時計は三年かけて建築された。", "explanation": "ここは〈細工〉（精密な物を手で作ること）の意味。建築は建物をたてることを指すので、時計には使わない。"}, {"text": "この映画は二年かけて建築された。", "explanation": "ここは〈製作〉（映画や作品をつくること）の意味。建築は建物に限るので、映画には使わない"}, {"text": "父は、家具の部品を一時間かけて建築した。", "explanation": "ここは〈組み立て〉（部品を組み合わせて作ること）の意味。建築は建物をたてることを指すので、家具の組み立てには使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51707, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建築", "is_correct": true, "explanation": "建物をたてることを指し、「山の上に家を建築するのは費用がかかる」と文意が通る"}, {"text": "散策", "is_correct": false, "explanation": "気ままに歩くことで、家を対象にして「散策する」とは言えない"}, {"text": "読書", "is_correct": false, "explanation": "本を読むことで、家を対象にはできず文が成り立たない"}, {"text": "入浴", "is_correct": false, "explanation": "体を洗い温まることで、家を対象にする「入浴する」は意味が通らない"}], "explanations": {"建築": "建物をたてることを指し、「山の上に家を建築するのは費用がかかる」と文意が通る", "散策": "気ままに歩くことで、家を対象にして「散策する」とは言えない", "読書": "本を読むことで、家を対象にはできず文が成り立たない", "入浴": "体を洗い温まることで、家を対象にする「入浴する」は意味が通らない"}, "sentence_index": 6, "correct_answer": "建築"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は木を一本ずつ建築して、小さな仏像を作った。", "explanation": "ここは〈彫刻〉（木や石を彫って形を作ること）の意味。建築は建物をたてることなので、仏像を彫る作業には合わない"}, {"text": "この曲は一晩で建築された。", "explanation": "ここは〈作曲〉（曲を作ること）の意味。建築は建物に限るので、曲には使わない"}, {"text": "この絵は一年かけて建築された。", "explanation": "ここは〈描く〉（絵をかくこと）の意味。建築は建物をたてることを指すので、絵には使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51707, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この校舎は、大正時代に建築する。", "corrected_sentence": "この校舎は、大正時代に建築された。", "error_description": "主語の「校舎」は建てられる側なので、受身形「建築された」が必要。能動形「建築する」では校舎が建てる主体になり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51707, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、新しい体育館の建築が来年始める予定だ。", "corrected_sentence": "町は、新しい体育館の建築を来年始める予定だ。", "error_description": "「始める」は他動詞で、対象を「を」で示す。「建築が」と主格にすると「始める」の目的語が示せず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
