INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物の重さのことです。", "primary_collocate": null, "pronunciation": "じゅうりょう", "ipa": "dʑuːɾʲoː", "syllable_count": 4, "sentences": [{"text": "この荷物の重量は五キロです。", "target_word": "重量", "complexity_tier": "T2", "furigana": "この荷物[にもつ]の重量[じゅうりょう]は五[ご]キロです。", "sentence_source": "generated"}, {"text": "魚の重量を量って、値段を決めた。", "target_word": "重量", "complexity_tier": "T2", "furigana": "魚[さかな]の重量[じゅうりょう]を量[はか]って、値段[ねだん]を決[き]めた。", "sentence_source": "generated"}, {"text": "この車は重量が軽いので、燃料が少なくて済む。", "target_word": "重量", "complexity_tier": "T3", "furigana": "この車[くるま]は重量[じゅうりょう]が軽[かる]いので、燃料[ねんりょう]が少[すく]なくて済[す]む。", "sentence_source": "generated"}, {"text": "決められた重量を超えた荷物には、追加料金がかかります。", "target_word": "重量", "complexity_tier": "T3", "furigana": "決[き]められた重量[じゅうりょう]を超[こ]えた荷物[にもつ]には、追加[ついか]料金[りょうきん]がかかります。", "sentence_source": "generated"}, {"text": "大きな机の重量を支えるために、脚を太くした。", "target_word": "重量", "complexity_tier": "T3", "furigana": "大[おお]きな机[つくえ]の重量[じゅうりょう]を支[ささ]えるために、脚[あし]を太[ふと]くした。", "sentence_source": "generated"}, {"text": "郵便局で、小包の重量を調べてもらった。", "target_word": "重量", "complexity_tier": "T2", "furigana": "郵便局[ゆうびんきょく]で、小包[こづつみ]の重量[じゅうりょう]を調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "金属は同じ大きさでも、木より重量が大きい。", "target_word": "重量", "complexity_tier": "T3", "furigana": "金属[きんぞく]は同[おな]じ大[おお]きさでも、木[き]より重量[じゅうりょう]が大[おお]きい。", "sentence_source": "generated"}, {"text": "持ち上げられる重量には、人によって限りがある。", "target_word": "重量", "complexity_tier": "T3", "furigana": "持[も]ち上[あ]げられる重量[じゅうりょう]には、人[ひと]によって限[かぎ]りがある。", "sentence_source": "generated"}, {"text": "登山では、リュックの重量が体力を大きく左右する。", "target_word": "重量", "complexity_tier": "T4", "furigana": "登山[とざん]では、リュックの重量[じゅうりょう]が体力[たいりょく]を大[おお]きく左右[さゆう]する。", "sentence_source": "generated"}, {"text": "部品の重量が少しでも違うと、機械は正しく動かない。", "target_word": "重量", "complexity_tier": "T4", "furigana": "部品[ぶひん]の重量[じゅうりょう]が少[すこ]しでも違[ちが]うと、機械[きかい]は正[ただ]しく動[うご]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重量", "label": "基本形"}, {"form": "重量の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "物の重さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d2c8cb-9fa5-4cd8-b72e-a635a8a4b334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体積", "is_correct": false, "explanation": "「荷物の体積は五キロ」は容積の話で、重さの量と合わない。"}, {"text": "重量", "is_correct": true, "explanation": "「荷物の重量は五キロ」は物の重さの量を表し、文に合う。"}, {"text": "温度", "is_correct": false, "explanation": "「荷物の温度は五キロ」は意味が通らず、文が成り立たない。"}, {"text": "長さ", "is_correct": false, "explanation": "「荷物の長さは五キロ」は長さに重さの単位を使っており、合わない。"}], "explanations": {"体積": "「荷物の体積は五キロ」は容積の話で、重さの量と合わない。", "重量": "「荷物の重量は五キロ」は物の重さの量を表し、文に合う。", "温度": "「荷物の温度は五キロ」は意味が通らず、文が成り立たない。", "長さ": "「荷物の長さは五キロ」は長さに重さの単位を使っており、合わない。"}, "sentence_index": 0, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の重量は三十リットルある。", "explanation": "重量は重さの量なので、リットルで表す容積の話には使えない。"}, {"text": "この布は重量が濃い。", "explanation": "重量は重さの量なので、色の濃さの話には使えない。"}, {"text": "この板は重量が硬い。", "explanation": "重量は重さの量なので、硬さの話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色", "is_correct": false, "explanation": "「木より色が大きい」は意味が通らず、比べる対象として成り立たない。"}, {"text": "重量", "is_correct": true, "explanation": "「木より重量が大きい」は、同じ大きさでも重さが大きいという意味で文に合う。"}, {"text": "学力", "is_correct": false, "explanation": "「木より学力が大きい」は物どうしの比較として意味が通らず、文に合わない。"}, {"text": "点数", "is_correct": false, "explanation": "「木より点数が大きい」は意味が通らず、金属と木の比較にならない。"}], "explanations": {"色": "「木より色が大きい」は意味が通らず、比べる対象として成り立たない。", "重量": "「木より重量が大きい」は、同じ大きさでも重さが大きいという意味で文に合う。", "学力": "「木より学力が大きい」は物どうしの比較として意味が通らず、文に合わない。", "点数": "「木より点数が大きい」は意味が通らず、金属と木の比較にならない。"}, "sentence_index": 6, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今回のテストの重量が高かった。", "explanation": "重量は重さの量なので、テストの成績の話には使えない。"}, {"text": "この電池は重量が長い。", "explanation": "重量は重さの量なので、使える期間の話には使えない。"}, {"text": "この船は重量が二十ノットだ。", "explanation": "重量は重さの量なので、船の速さの話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51709, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この箱の重量へ十キロです。", "corrected_sentence": "この箱の重量は十キロです。", "error_description": "「重量」が主題になるので「は」が正しい。「へ」は方向を表し、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51709, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荷物の重量を増えると、機械が壊れる。", "corrected_sentence": "荷物の重量が増えると、機械が壊れる。", "error_description": "「増える」は自動詞で主語に「が」を取るので「が」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d6334c-4a48-4c27-85fa-e2127c5a9b86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「天井の電球」の所属を示す「の」で、天井に付いている電球という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここは電球を修飾する所属を表すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「天井へ電球」では電球の所属が示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「天井より電球」は文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「天井の電球」の所属を示す「の」で、天井に付いている電球という意味になる。", "を": "「を」は目的語を示すが、ここは電球を修飾する所属を表すので合わない。", "へ": "「へ」は方向を示すが、「天井へ電球」では電球の所属が示せないので合わない。", "より": "「より」は比較を示すので、「天井より電球」は文の意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「天井が低い」の主語を示す「が」で、低いという状態の主語になる。"}, {"text": "に", "is_correct": false, "explanation": "「天井に低い」は場所を示しても形容詞の主語にならず、合わない。"}, {"text": "で", "is_correct": false, "explanation": "「天井で低い」は形容詞の主語にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「天井と低い部屋」は並列になり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「天井が低い」の主語を示す「が」で、低いという状態の主語になる。", "に": "「天井に低い」は場所を示しても形容詞の主語にならず、合わない。", "で": "「天井で低い」は形容詞の主語にならず、文が成り立たない。", "と": "「天井と低い部屋」は並列になり、意味が通らない。"}, "error_tags": {"に": "場所", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "部屋の上の部分で、頭の上にある平らなところです。", "primary_collocate": null, "pronunciation": "てんじょう", "ipa": "tendʑoː", "syllable_count": 4, "sentences": [{"text": "この部屋は天井が高いので、広く感じます。", "target_word": "天井", "complexity_tier": "T3", "furigana": "この部屋[へや]は天井[てんじょう]が高[たか]いので、広[ひろ]く感[かん]じます。", "sentence_source": "generated"}, {"text": "天井の電球が切れたので、新しいものに替えました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "天井[てんじょう]の電球[でんきゅう]が切[き]れたので、新[あたら]しいものに替[か]えました。", "sentence_source": "generated"}, {"text": "子どものころ、寝る前にベッドから天井の模様を数えていました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "子[こ]どものころ、寝[ね]る前[まえ]にベッドから天井[てんじょう]の模様[もよう]を数[かぞ]えていました。", "sentence_source": "generated"}, {"text": "古い家なので、雨の日は天井から水が落ちてきます。", "target_word": "天井", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]なので、雨[あめ]の日[ひ]は天井[てんじょう]から水[みず]が落[お]ちてきます。", "sentence_source": "generated"}, {"text": "背の高い兄は、低い天井に頭をぶつけてしまいました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "背[せ]の高[たか]い兄[あに]は、低[ひく]い天井[てんじょう]に頭[あたま]をぶつけてしまいました。", "sentence_source": "generated"}, {"text": "天井にクモの巣があるので、掃除のときに取ってください。", "target_word": "天井", "complexity_tier": "T3", "furigana": "天井[てんじょう]にクモの巣[す]があるので、掃除[そうじ]のときに取[と]ってください。", "sentence_source": "generated"}, {"text": "この教会は、天井に有名な画家の絵が描かれています。", "target_word": "天井", "complexity_tier": "T3", "furigana": "この教会[きょうかい]は、天井[てんじょう]に有名[ゆうめい]な画家[がか]の絵[え]が描[えが]かれています。", "sentence_source": "generated"}, {"text": "天井が低い部屋は、落ち着くという人もいます。", "target_word": "天井", "complexity_tier": "T3", "furigana": "天井[てんじょう]が低[ひく]い部屋[へや]は、落[お]ち着[つ]くという人[ひと]もいます。", "sentence_source": "generated"}, {"text": "地震で天井の一部が落ちて、教室が使えなくなりました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "地震[じしん]で天井[てんじょう]の一部[いちぶ]が落[お]ちて、教室[きょうしつ]が使[つか]えなくなりました。", "sentence_source": "generated"}, {"text": "天井についた扇風機が、ゆっくり回っています。", "target_word": "天井", "complexity_tier": "T3", "furigana": "天井[てんじょう]についた扇風機[せんぷうき]が、ゆっくり回[まわ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天井", "label": "基本形"}], "register": "polite", "sense_fingerprint": "部屋の上側にある平らな面。建物の内部の頭上の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天井", "is_correct": true, "explanation": "部屋の上側の面で、「天井が高い」という状態に合う。"}, {"text": "会議", "is_correct": false, "explanation": "「会議が高い」は意味が通らず、合わない。"}, {"text": "朝ごはん", "is_correct": false, "explanation": "「朝ごはんが高い」は部屋の広さの話に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題が高い」は部屋の高さの文脈では成り立たない。"}], "explanations": {"天井": "部屋の上側の面で、「天井が高い」という状態に合う。", "会議": "「会議が高い」は意味が通らず、合わない。", "朝ごはん": "「朝ごはんが高い」は部屋の広さの話に合わない。", "宿題": "「宿題が高い」は部屋の高さの文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "天井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天井を押して、電気をつけた。", "explanation": "ここは〈スイッチ〉の意味。電気をつけるために押すのはスイッチで、天井は押して操作するものではないので合わない。"}, {"text": "天井に大きな虹がかかった。", "explanation": "ここは〈空〉の意味。虹がかかるのは空で、部屋の天井には虹はかからないので合わない。"}, {"text": "天井を閉めて、部屋を出た。", "explanation": "ここは〈ドア〉の意味。閉めるのは出入り口のドアで、天井は閉める物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天井", "is_correct": true, "explanation": "教会の天井に絵が描かれるという文脈に合う。"}, {"text": "雲", "is_correct": false, "explanation": "「雲に絵が描かれています」は不自然で、教会の天井の文脈に合わない。"}, {"text": "ため息", "is_correct": false, "explanation": "「ため息に絵が描かれています」は成り立たず、合わない。"}, {"text": "朝", "is_correct": false, "explanation": "「朝に絵が描かれています」は場所を表さず、文が成り立たない。"}], "explanations": {"天井": "教会の天井に絵が描かれるという文脈に合う。", "雲": "「雲に絵が描かれています」は不自然で、教会の天井の文脈に合わない。", "ため息": "「ため息に絵が描かれています」は成り立たず、合わない。", "朝": "「朝に絵が描かれています」は場所を表さず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "天井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は天井をさして、学校へ歩いた。", "explanation": "ここは〈傘〉の意味。さすのは傘で、天井はさせないので合わない。"}, {"text": "天井を投げて、友達に渡した。", "explanation": "ここは〈ボール〉の意味。投げて渡すのはボールで、天井は投げられる物ではないので合わない。"}, {"text": "天井で名前を書いた。", "explanation": "ここは〈ペン〉の意味。字を書く道具はペンで、天井は書く道具として使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天井を丸い照明がついています。", "corrected_sentence": "天井に丸い照明がついています。", "error_description": "正しくは「天井に」。「ついている」の場所を示すのは「に」で、「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51711, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝ころんで、天井を聞いていた。", "corrected_sentence": "寝ころんで、天井を見ていた。", "error_description": "正しくは「天井を見る」。「聞く」は音などに使う動詞で、天井には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51712, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「天井が高い」の主語を示す「が」で、形容詞「高い」の主語として天井に付く。"}, {"text": "を", "is_correct": false, "explanation": "「高い」は目的語を取らないので、「天井を高い」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「天井に高い」は場所を示しても形容詞の主語にならず、合わない。"}, {"text": "で", "is_correct": false, "explanation": "「天井で高い」は形容詞の主語にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「天井が高い」の主語を示す「が」で、形容詞「高い」の主語として天井に付く。", "を": "「高い」は目的語を取らないので、「天井を高い」は成り立たない。", "に": "「天井に高い」は場所を示しても形容詞の主語にならず、合わない。", "で": "「天井で高い」は形容詞の主語にならず、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
