INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51712, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物や部屋の内部で、最も高い位置にある水平な面。上のふたのような部分。", "primary_collocate": null, "pronunciation": "てんじょう", "ipa": "tendʑoː", "syllable_count": 4, "sentences": [{"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "天井", "complexity_tier": "T4", "furigana": "特[とく]に注目[ちゅうもく]すべきは、天井[てんじょう]の重量[じゅうりょう]を分散[ぶんさん]させる「リブ・ヴォールト」と、壁[かべ]の外側[そとがわ]から支[ささ]える「フライング・バットレス」と呼[よ]ばれる技術[ぎじゅつ]です。", "sentence_source": "mined"}, {"text": "部屋の天井が高いので、とても広く感じます。", "target_word": "天井", "complexity_tier": "T3", "furigana": "部屋[へや]の天井[てんじょう]が高[たか]いので、とても広[ひろ]く感[かん]じます。", "sentence_source": "generated"}, {"text": "雨の日に、天井から水が落ちてきて困りました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]に、天井[てんじょう]から水[みず]が落[お]ちてきて困[こま]りました。", "sentence_source": "generated"}, {"text": "兄は背が高くて、天井に頭がぶつかりそうです。", "target_word": "天井", "complexity_tier": "T3", "furigana": "兄[あに]は背[せ]が高[たか]くて、天井[てんじょう]に頭[あたま]がぶつかりそうです。", "sentence_source": "generated"}, {"text": "古い教会の天井には、美しい絵がえがかれています。", "target_word": "天井", "complexity_tier": "T3", "furigana": "古[ふる]い教会[きょうかい]の天井[てんじょう]には、美[うつく]しい絵[え]がえがかれています。", "sentence_source": "generated"}, {"text": "天井の電気が切れたので、新しいものに替えました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "天井[てんじょう]の電気[でんき]が切[き]れたので、新[あたら]しいものに替[か]えました。", "sentence_source": "generated"}, {"text": "夜、ベッドに寝て天井を見ていたら、小さなくもを見つけました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "夜[よる]、ベッドに寝[ね]て天井[てんじょう]を見[み]ていたら、小[ちい]さなくもを見[み]つけました。", "sentence_source": "generated"}, {"text": "風船が手から離れて、天井まで飛んでいきました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "風船[ふうせん]が手[て]から離[はな]れて、天井[てんじょう]まで飛[と]んでいきました。", "sentence_source": "generated"}, {"text": "この店は天井が低いので、背の高い人は少し不便です。", "target_word": "天井", "complexity_tier": "T3", "furigana": "この店[みせ]は天井[てんじょう]が低[ひく]いので、背[せ]の高[たか]い人[ひと]は少[すこ]し不便[ふべん]です。", "sentence_source": "generated"}, {"text": "工事の人が天井を張り替えるあいだ、私たちは隣の部屋にいました。", "target_word": "天井", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が天井[てんじょう]を張[は]り替[か]えるあいだ、私[わたし]たちは隣[となり]の部屋[へや]にいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天井", "label": "基本形"}], "register": "polite", "sense_fingerprint": "部屋や建物の内側のいちばん上の面(天井)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: えがか (Zipf 1.55)','sentence 9 above tier T3: contains vocabulary far above tier T3: 張り替える (Zipf 1.84)']::text[], '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51712, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天井", "is_correct": true, "explanation": "建物の内部の上面を指し、重量を分散させる構造の話に合う。"}, {"text": "会話", "is_correct": false, "explanation": "「会話の重量を分散させる」は意味が通らず、建築の話に入らない。"}, {"text": "夕方", "is_correct": false, "explanation": "「夕方の重量を分散させる」は意味が通らず、合わない。"}, {"text": "切符", "is_correct": false, "explanation": "「切符の重量を分散させる」は建築の技術の話として成り立たない。"}], "explanations": {"天井": "建物の内部の上面を指し、重量を分散させる構造の話に合う。", "会話": "「会話の重量を分散させる」は意味が通らず、建築の話に入らない。", "夕方": "「夕方の重量を分散させる」は意味が通らず、合わない。", "切符": "「切符の重量を分散させる」は建築の技術の話として成り立たない。"}, "sentence_index": 0, "correct_answer": "天井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い風で天井の瓦が飛んでしまい、空が見えるようになった。", "explanation": "ここは〈屋根〉の意味。瓦が飛んで空が見えるのは屋根の話で、室内の天井には瓦も空もないので合わない。"}, {"text": "明日の天井は、ずっと晴れでしょう。", "explanation": "ここは〈天気〉の意味。晴れるのは空模様で、室内の天井が晴れることはないので合わない。"}, {"text": "天井が晴れて、青い色が広がった。", "explanation": "ここは〈空〉の意味。晴れて青く広がるのは空で、部屋の内側の天井には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51712, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天井", "is_correct": true, "explanation": "寝ころんで見上げる頭上の面を指し、「天井を見ていたら」に合う。"}, {"text": "ため息", "is_correct": false, "explanation": "「ため息を見ていたら」は見るものとして成り立たず、合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は聞くものなので、「見ていたら」とは合わない。"}, {"text": "雷鳴", "is_correct": false, "explanation": "「雷鳴を見ていたら」は聞くものなので成り立たず、合わない。"}], "explanations": {"天井": "寝ころんで見上げる頭上の面を指し、「天井を見ていたら」に合う。", "ため息": "「ため息を見ていたら」は見るものとして成り立たず、合わない。", "足音": "足音は聞くものなので、「見ていたら」とは合わない。", "雷鳴": "「雷鳴を見ていたら」は聞くものなので成り立たず、合わない。"}, "sentence_index": 6, "correct_answer": "天井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天井に敷いたマットが汚れたので、洗いました。", "explanation": "ここは〈床〉の意味。マットを敷くのは床で、天井には敷けないので合わない。"}, {"text": "朝、天井を引いて、部屋に光を入れた。", "explanation": "ここは〈カーテン〉の意味。光を入れるために引いて開けるのはカーテンで、天井は引いて開け閉めするものではないので合わない。"}, {"text": "天井をはいて、外に出ました。", "explanation": "ここは〈くつ〉の意味。はくのはくつで、天井ははけないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51712, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風のあと、天井を雨もりの跡が残っていました。", "corrected_sentence": "台風のあと、天井に雨もりの跡が残っていました。", "error_description": "正しくは「天井に」（場所を示す「に」）。「残る」の場所に「を」を使った誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51712, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベッドに寝て、天井を見下ろしていました。", "corrected_sentence": "ベッドに寝て、天井を見上げていました。", "error_description": "正しくは「天井を見上げる」。天井は頭の上にあるので、「見下ろす」は方向が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ボールトの曲線」と、ボールトに直接続けて名詞を修飾する。"}, {"text": "に", "is_correct": false, "explanation": "「ボールトに曲線」では文の意味が通らず、対象を表す「に」は合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「ボールトを曲線が」となり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「ボールトへ曲線」となり、名詞どうしを結べない。"}], "correct_answer": "の", "explanations": {"の": "「ボールトの曲線」と、ボールトに直接続けて名詞を修飾する。", "に": "「ボールトに曲線」では文の意味が通らず、対象を表す「に」は合わない。", "を": "目的語の「を」では「ボールトを曲線が」となり、文が成り立たない。", "へ": "方向の「へ」では「ボールトへ曲線」となり、名詞どうしを結べない。"}, "error_tags": {"に": "帰着・対象の助詞", "を": "目的格の助詞", "へ": "方向の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "天井の丸く曲がった形のこと。", "primary_collocate": null, "pronunciation": "ぼーると", "ipa": "boːɾɯto", "syllable_count": 4, "sentences": [{"text": "この教会の天井は、丸いボールトの形をしている。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "この教会[きょうかい]の天井[てんじょう]は、丸[まる]いボールトの形[かたち]をしている。", "sentence_source": "generated"}, {"text": "古い駅の地下道は、天井がボールトのように曲がっている。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "古[ふる]い駅[えき]の地下道[ちかどう]は、天井[てんじょう]がボールトのように曲[ま]がっている。", "sentence_source": "generated"}, {"text": "ボールトの天井は、平らな天井より高く広く見える。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "ボールトの天井[てんじょう]は、平[たい]らな天井[てんじょう]より高[たか]く広[ひろ]く見[み]える。", "sentence_source": "generated"}, {"text": "洞窟の入口は、自然にできたボールトのような形だった。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の入口[いりぐち]は、自然[しぜん]にできたボールトのような形[かたち]だった。", "sentence_source": "generated"}, {"text": "長い廊下の天井が丸いボールトになっていて、声がよく響く。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "長[なが]い廊下[ろうか]の天井[てんじょう]が丸[まる]いボールトになっていて、声[こえ]がよく響[ひび]く。", "sentence_source": "generated"}, {"text": "建築の授業で、ボールトの形がなぜ強いのかを習った。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "建築[けんちく]の授業[じゅぎょう]で、ボールトの形[かたち]がなぜ強[つよ]いのかを習[なら]った。", "sentence_source": "generated"}, {"text": "地下のワイン倉庫は、低いボールトの天井で涼しい。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "地下[ちか]のワイン倉庫[そうこ]は、低[ひく]いボールトの天井[てんじょう]で涼[すず]しい。", "sentence_source": "generated"}, {"text": "写真を撮るときは、ボールトの曲線がきれいに見える角度を探した。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "写真[しゃしん]を撮[と]るときは、ボールトの曲線[きょくせん]がきれいに見[み]える角度[かくど]を探[さが]した。", "sentence_source": "generated"}, {"text": "天井がボールトになっているので、部屋の上のほうが丸く見える。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "天井[てんじょう]がボールトになっているので、部屋[へや]の上[うえ]のほうが丸[まる]く見[み]える。", "sentence_source": "generated"}, {"text": "ボールトの形をした天井に、青い星の絵が描かれている。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "ボールトの形[かたち]をした天井[てんじょう]に、青[あお]い星[ほし]の絵[え]が描[えが]かれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボールト", "label": "基本形"}, {"form": "ボールトの", "label": "連体(の)"}, {"form": "ボールトに", "label": "位置(に)"}], "register": "neutral", "sense_fingerprint": "建物の天井が丸く弧を描く形(かまぼこ形の天井)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボールト", "is_correct": true, "explanation": "天井の丸く曲がった形を表し、「丸いボールトの形」で文意が通る。"}, {"text": "床", "is_correct": false, "explanation": "床は足元の面を指すので、天井の丸い形を説明する語としては合わない。"}, {"text": "基礎", "is_correct": false, "explanation": "基礎は建物を地面で支える構造なので、天井の形には使えない。"}, {"text": "土台", "is_correct": false, "explanation": "土台は建物の下部に置く横材で、丸い天井の形を表せない。"}], "explanations": {"ボールト": "天井の丸く曲がった形を表し、「丸いボールトの形」で文意が通る。", "床": "床は足元の面を指すので、天井の丸い形を説明する語としては合わない。", "基礎": "基礎は建物を地面で支える構造なので、天井の形には使えない。", "土台": "土台は建物の下部に置く横材で、丸い天井の形を表せない。"}, "sentence_index": 0, "correct_answer": "ボールト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールトを締めて、机の脚を固定した。", "explanation": "ここは〈ボルト〉の意味。ボールトは天井の形で、締めて固定する部品ではない。"}, {"text": "ボールトを蹴って、ゴールに入れた。", "explanation": "ここは〈ボール〉の意味。ボールトは天井の形を表す語で、蹴って使う物ではない。"}, {"text": "ボールトに卵と砂糖を入れて、よく混ぜた。", "explanation": "ここは〈ボウル〉の意味。ボールトは形の名前で、中に物を入れて混ぜる器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボールト", "is_correct": true, "explanation": "天井の丸い形を表し、「低いボールトの天井」で文意が通る。"}, {"text": "石垣", "is_correct": false, "explanation": "石を積んだ壁で、天井の形を表す語にはならない。"}, {"text": "窓枠", "is_correct": false, "explanation": "窓をはめる枠なので、天井の形の説明には合わない。"}, {"text": "塀", "is_correct": false, "explanation": "敷地を囲む壁で、天井の形を説明する語ではない。"}], "explanations": {"ボールト": "天井の丸い形を表し、「低いボールトの天井」で文意が通る。", "石垣": "石を積んだ壁で、天井の形を表す語にはならない。", "窓枠": "窓をはめる枠なので、天井の形の説明には合わない。", "塀": "敷地を囲む壁で、天井の形を説明する語ではない。"}, "sentence_index": 6, "correct_answer": "ボールト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールトをしっかり締めて、棚を固定した。", "explanation": "ここは〈ボルト〉の意味。ボールトは天井の形で、締めて固定する部品ではない。"}, {"text": "ボールトで手紙を書いた。", "explanation": "ここは〈ボールペン〉の意味。ボールトは天井の形で、文字を書く道具ではない。"}, {"text": "ボールトに水を入れて、花を生けた。", "explanation": "ここは〈花瓶〉の意味。ボールトは天井の丸い形を表す語で、水を入れて花を生ける器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この聖堂の天井は、丸いボールトを形をしている。", "corrected_sentence": "この聖堂の天井は、丸いボールトの形をしている。", "error_description": "「ボールト」に続く助詞の誤り。「丸いボールトの形」と「の」で名詞を続けるのが正しい。「を」は目的語を示すため、「形をしている」とは続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51713, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地下室は、低いボールトな天井がある。", "corrected_sentence": "この地下室は、低いボールトの天井がある。", "error_description": "「ボールト」に続く助詞の誤り。名詞どうしを「の」で続けるのが正しい。「な」は名詞には続かないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ボールトの後に続けて主題を示す「は」。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「伝える」の目的語として「力を」が既にあり、二重になる。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では主題が二つになり、「伝える」の文と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では「ボールトへ、伝える」が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "ボールトの後に続けて主題を示す「は」。正解。", "を": "目的語を示す「を」。「伝える」の目的語として「力を」が既にあり、二重になる。", "と": "並列の「と」では主題が二つになり、「伝える」の文と合わない。", "へ": "方向を示す「へ」では「ボールトへ、伝える」が成り立たない。"}, "error_tags": {"を": "目的格の助詞", "と": "並列の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ボールトの構造」と、名詞どうしを「の」で続ける。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「ボールトを構造」となり、名詞どうしを結べない。"}, {"text": "に", "is_correct": false, "explanation": "「ボールトに構造」は成り立たず、帰着や対象を表す「に」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「ボールトから構造」となり、文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「ボールトの構造」と、名詞どうしを「の」で続ける。正解。", "を": "目的語の「を」では「ボールトを構造」となり、名詞どうしを結べない。", "に": "「ボールトに構造」は成り立たず、帰着や対象を表す「に」では意味が通らない。", "から": "起点の「から」では「ボールトから構造」となり、文脈に合わない。"}, "error_tags": {"を": "目的格の助詞", "に": "帰着・対象の助詞", "から": "起点の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "アーチ状の天井構造。石やレンガを組み合わせて作られ、建物の屋根を支える役割を持つ。", "primary_collocate": null, "pronunciation": "ぼーると", "ipa": "boːɾɯto", "syllable_count": 4, "sentences": [{"text": "中世の修道院では、石を積んだボールトが屋根を支えている。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の修道院[しゅうどういん]では、石[いし]を積[つ]んだボールトが屋根[やね]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "レンガのボールトは、重い屋根の力を壁に分けて伝える。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "レンガのボールトは、重[おも]い屋根[やね]の力[ちから]を壁[かべ]に分[わ]けて伝[つた]える。", "sentence_source": "generated"}, {"text": "職人は石を一つずつ組み合わせて、大きなボールトを作った。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "職人[しょくにん]は石[いし]を一[ひと]つずつ組[く]み合[あ]わせて、大[おお]きなボールトを作[つく]った。", "sentence_source": "generated"}, {"text": "地震があっても、この聖堂のボールトは崩れなかった。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "地震[じしん]があっても、この聖堂[せいどう]のボールトは崩[くず]れなかった。", "sentence_source": "generated"}, {"text": "大聖堂のボールトを支えるために、外側に太い柱が付けられた。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "大聖堂[だいせいどう]のボールトを支[ささ]えるために、外側[そとがわ]に太[ふと]い柱[はしら]が付[つ]けられた。", "sentence_source": "generated"}, {"text": "古いレンガ造りの橋の下には、ボールトの構造が見える。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "古[ふる]いレンガ造[づく]りの橋[はし]の下[した]には、ボールトの構造[こうぞう]が見[み]える。", "sentence_source": "generated"}, {"text": "建築家は、石のボールトと木の梁を比べて強さを説明した。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "建築家[けんちくか]は、石[いし]のボールトと木[き]の梁[はり]を比[くら]べて強[つよ]さを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この駅舎はボールトの構造なので、中に柱が少ない。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "この駅舎[えきしゃ]はボールトの構造[こうぞう]なので、中[なか]に柱[はしら]が少[すく]ない。", "sentence_source": "generated"}, {"text": "修復工事で、傷んだボールトのレンガを新しく入れ替えた。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "修復工事[しゅうふくこうじ]で、傷[いた]んだボールトのレンガを新[あたら]しく入[い]れ替[か]えた。", "sentence_source": "generated"}, {"text": "ローマ時代の建物は、ボールトの技術を使って広い空間を作っている。", "target_word": "ボールト", "complexity_tier": "T3", "furigana": "ローマ時代[じだい]の建物[たてもの]は、ボールトの技術[ぎじゅつ]を使[つか]って広[ひろ]い空間[くうかん]を作[つく]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボールト", "label": "基本形"}, {"form": "ボールトの", "label": "連体(の)"}, {"form": "ボールトが", "label": "主格(が)"}], "register": "technical", "sense_fingerprint": "石やレンガで組んだアーチ状の天井構造で、屋根を支える建築部材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボールト", "is_correct": true, "explanation": "石を積んで屋根を支える構造を表し、「石を積んだボールトが屋根を支える」で文が通る。"}, {"text": "扉", "is_correct": false, "explanation": "出入り口の戸なので、屋根を支える部材ではない。"}, {"text": "廊下", "is_correct": false, "explanation": "建物内の通路で、屋根を支える役割はない。"}, {"text": "窓", "is_correct": false, "explanation": "光を入れる開口部で、屋根を支える部材ではない。"}], "explanations": {"ボールト": "石を積んで屋根を支える構造を表し、「石を積んだボールトが屋根を支える」で文が通る。", "扉": "出入り口の戸なので、屋根を支える部材ではない。", "廊下": "建物内の通路で、屋根を支える役割はない。", "窓": "光を入れる開口部で、屋根を支える部材ではない。"}, "sentence_index": 0, "correct_answer": "ボールト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールトで机の脚を固定した。", "explanation": "ここは〈ボルト〉の意味。ボールトは建物の天井構造で、机を固定する部品ではない。"}, {"text": "ボールトで答案に丸をつけた。", "explanation": "ここは〈ボールペン〉の意味。ボールトは構造物で、丸を書く筆記具ではない。"}, {"text": "週末は湖でボールトをこいで、景色を眺めた。", "explanation": "ここは〈ボート〉の意味。ボールトは建物の天井構造で、湖でこぐ乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボールト", "is_correct": true, "explanation": "石で組んだ天井の構造を表し、「石のボールトと木の梁を比べる」で文が通る。"}, {"text": "玄関", "is_correct": false, "explanation": "出入口の空間で、構造の強さを比べる対象にはならない。"}, {"text": "窓枠", "is_correct": false, "explanation": "窓の枠で、構造の強さを比べる対象には合わない。"}, {"text": "表札", "is_correct": false, "explanation": "家の名札で、構造の強さの比較には合わない。"}], "explanations": {"ボールト": "石で組んだ天井の構造を表し、「石のボールトと木の梁を比べる」で文が通る。", "玄関": "出入口の空間で、構造の強さを比べる対象にはならない。", "窓枠": "窓の枠で、構造の強さを比べる対象には合わない。", "表札": "家の名札で、構造の強さの比較には合わない。"}, "sentence_index": 6, "correct_answer": "ボールト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールトをパスして、ゴールを決めた。", "explanation": "ここは〈ボール〉の意味。ボールトは構造の名前で、パスできる物ではない。"}, {"text": "ボールトに牛乳を注いで、泡立てた。", "explanation": "ここは〈ボウル〉の意味。ボールトは天井の形を表す語で、牛乳を入れる器ではない。"}, {"text": "ボールトで箱を作って、中に写真を入れた。", "explanation": "ここは〈ボール紙〉の意味。ボールトは建物の天井構造で、箱の材料になる紙ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ローマ時代の橋は、石を積んだボールトを重さを支えている。", "corrected_sentence": "ローマ時代の橋は、石を積んだボールトが重さを支えている。", "error_description": "「ボールト」に続く助詞の誤り。主語を示す「が」が正しい。「を」は目的語を示すため、後ろの「重さを」と二重になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51714, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この礼拝堂の天井は、丸いボールトの支えられている。", "corrected_sentence": "この礼拝堂の天井は、丸いボールトで支えられている。", "error_description": "「ボールト」に続く助詞の誤り。手段を示す「で」が正しい。「の」では「支えられている」と続かず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞で、『白いリブの並んでいて』では述語の主語にならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すが、『リブより並んでいて』では意味が通らない。"}, {"text": "が", "is_correct": true, "explanation": "『白いリブ』が『並んでいて』の主語になるので『が』が正しい。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すが、『リブから並んでいて』では不自然。"}], "correct_answer": "が", "explanations": {"の": "『の』は名詞をつなぐ助詞で、『白いリブの並んでいて』では述語の主語にならないので合わない。", "より": "『より』は比較を示すが、『リブより並んでいて』では意味が通らない。", "が": "『白いリブ』が『並んでいて』の主語になるので『が』が正しい。", "から": "『から』は起点を示すが、『リブから並んでいて』では不自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の天井を支える、骨組みのような部分です。", "primary_collocate": null, "pronunciation": "りぶ", "ipa": "ɾibɯ", "syllable_count": 2, "sentences": [{"text": "古い教会の天井では、石のリブが屋根の重さを支えています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "古[ふる]い教会[きょうかい]の天井[てんじょう]では、石[いし]のリブが屋根[やね]の重[おも]さを支[ささ]えています。", "sentence_source": "generated"}, {"text": "天井のリブが美しい模様を作っているので、観光客は上を見上げます。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "天井[てんじょう]のリブが美[うつく]しい模様[もよう]を作[つく]っているので、観光客[かんこうきゃく]は上[うえ]を見上[みあ]げます。", "sentence_source": "generated"}, {"text": "この建物は、リブが太いので地震にも強いです。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "この建物[たてもの]は、リブが太[ふと]いので地震[じしん]にも強[つよ]いです。", "sentence_source": "generated"}, {"text": "修理の人が、天井のリブにひびが入っていないか調べました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "修理[しゅうり]の人[ひと]が、天井[てんじょう]のリブにひびが入[はい]っていないか調[しら]べました。", "sentence_source": "generated"}, {"text": "ドームの内側には、細いリブが何本も交差しています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "ドームの内側[うちがわ]には、細[ほそ]いリブが何本[なんぼん]も交差[こうさ]しています。", "sentence_source": "generated"}, {"text": "大聖堂の天井を支えるリブは、中世の職人が石で作りました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "大聖堂[だいせいどう]の天井[てんじょう]を支[ささ]えるリブは、中世[ちゅうせい]の職人[しょくにん]が石[いし]で作[つく]りました。", "sentence_source": "generated"}, {"text": "リブがなければ、広い天井はすぐに落ちてしまうでしょう。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "リブがなければ、広[ひろ]い天井[てんじょう]はすぐに落[お]ちてしまうでしょう。", "sentence_source": "generated"}, {"text": "展示室の天井は、白いリブが並んでいて、まるで大きな傘のようです。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "展示室[てんじしつ]の天井[てんじょう]は、白[しろ]いリブが並[なら]んでいて、まるで大[おお]きな傘[かさ]のようです。", "sentence_source": "generated"}, {"text": "建築の授業で、天井のリブがどんな役割をするか教わりました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "建築[けんちく]の授業[じゅぎょう]で、天井[てんじょう]のリブがどんな役割[やくわり]をするか教[おそ]わりました。", "sentence_source": "generated"}, {"text": "古い図書館の天井では、木のリブが屋根を支えています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "古[ふる]い図書館[としょかん]の天井[てんじょう]では、木[き]のリブが屋根[やね]を支[ささ]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リブ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "建築で、天井やドームを支える骨組み状の部材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窓", "is_correct": false, "explanation": "窓は採光や換気のための開口部で、屋根の重さを支える役割はないので合わない。"}, {"text": "リブ", "is_correct": true, "explanation": "天井の骨組みとして屋根の重さを支える部材なので、ここに入る。"}, {"text": "鐘", "is_correct": false, "explanation": "鐘は教会の塔に吊るされる楽器で、屋根を支える部材ではないので合わない。"}, {"text": "祭壇", "is_correct": false, "explanation": "祭壇は礼拝に使う台で、屋根の重さを支える構造材ではないので合わない。"}], "explanations": {"窓": "窓は採光や換気のための開口部で、屋根の重さを支える役割はないので合わない。", "リブ": "天井の骨組みとして屋根の重さを支える部材なので、ここに入る。", "鐘": "鐘は教会の塔に吊るされる楽器で、屋根を支える部材ではないので合わない。", "祭壇": "祭壇は礼拝に使う台で、屋根の重さを支える構造材ではないので合わない。"}, "sentence_index": 0, "correct_answer": "リブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "転んで、胸のリブを強く打ってしまいました。", "explanation": "ここは『体の骨』の意味。建物の天井を支える骨組みの意味ではないので、この定義には合わない。"}, {"text": "厚いリブが外の寒さを防いでいます。", "explanation": "ここは〈壁〉の意味。リブは天井を支える骨組みで、外の寒さを防ぐ壁の役割はしないので合わない。"}, {"text": "レストランで、牛のリブを注文しました。", "explanation": "ここは食肉の部位の意味。建築の骨組みの意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煙突", "is_correct": false, "explanation": "煙突は屋根の上の排気管で、天井を支える役割はないので合わない。"}, {"text": "暖炉", "is_correct": false, "explanation": "暖炉は部屋で火を焚く設備で、天井を支える役割はないので合わない。"}, {"text": "リブ", "is_correct": true, "explanation": "天井を支える骨組みで、なければ天井が落ちるという文脈に入る。"}, {"text": "照明", "is_correct": false, "explanation": "照明は天井などに付ける器具で、天井を支える部材ではないので合わない。"}], "explanations": {"煙突": "煙突は屋根の上の排気管で、天井を支える役割はないので合わない。", "暖炉": "暖炉は部屋で火を焚く設備で、天井を支える役割はないので合わない。", "リブ": "天井を支える骨組みで、なければ天井が落ちるという文脈に入る。", "照明": "照明は天井などに付ける器具で、天井を支える部材ではないので合わない。"}, "sentence_index": 6, "correct_answer": "リブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きなリブから、朝の光が入ってきます。", "explanation": "ここは〈開口部〉の意味。リブは骨組みの部材で、光を通す開口部ではないので合わない。"}, {"text": "この部屋はリブが冷たいので、スリッパを履いて歩きます。", "explanation": "ここは〈床〉の意味。リブは天井の骨組みで、歩いて踏む床の代わりにはならないので合わない。"}, {"text": "セーターの袖口は、リブで編みました。", "explanation": "ここは編み物の『リブ編み』の意味。建築の骨組みの意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大聖堂の天井では、石のリブを屋根の重さを支えています。", "corrected_sentence": "大聖堂の天井では、石のリブが屋根の重さを支えています。", "error_description": "『リブ』は『支えています』の主語なので『が』が正しい。『を』だと『屋根の重さを』と目的語が二つ重なり、不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51715, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドームのリブが屋根の重さに支えていました。", "corrected_sentence": "ドームのリブが屋根の重さを支えていました。", "error_description": "「支える」は目的語を「を」で示す。「屋根の重さに」の「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正解。結集（集める）の対義語で、ばらばらに散らばる意味。"}, {"text": "集合", "is_correct": false, "explanation": "結集と近い意味の語で、対義語ではない。"}, {"text": "整列", "is_correct": false, "explanation": "順番に並ぶ意味で、集まる動作の反対語ではない。"}, {"text": "沈黙", "is_correct": false, "explanation": "声を出さないことで、人の集まりの反対語ではない。"}], "correct_answer": "分散", "explanations": {"分散": "正解。結集（集める）の対義語で、ばらばらに散らばる意味。", "集合": "結集と近い意味の語で、対義語ではない。", "整列": "順番に並ぶ意味で、集まる動作の反対語ではない。", "沈黙": "声を出さないことで、人の集まりの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「結集によって」の形で、結集が原因や手段であることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「結集がよって」となり、後ろの文と続かない。"}, {"text": "を", "is_correct": false, "explanation": "「結集をよって」となり、動作の対象を表す形として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「結集でよって」となり、手段を表す自然な形にならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「結集によって」の形で、結集が原因や手段であることを示す。", "が": "「結集がよって」となり、後ろの文と続かない。", "を": "「結集をよって」となり、動作の対象を表す形として成り立たない。", "で": "「結集でよって」となり、手段を表す自然な形にならない。"}, "error_tags": {"が": "主語を示す", "を": "目的語を示す", "で": "場所や手段を示す"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正解。結集の対義語で、集まっていた人や力が散らばる意味。"}, {"text": "合流", "is_correct": false, "explanation": "流れや人が一つに集まる意味で、結集の反対語ではない。"}, {"text": "集約", "is_correct": false, "explanation": "まとめて一つにする意味で、結集と近い方向の語。対義語ではない。"}, {"text": "静止", "is_correct": false, "explanation": "動かずにとどまる意味で、集まる動作の反対語ではない。"}], "correct_answer": "分散", "explanations": {"分散": "正解。結集の対義語で、集まっていた人や力が散らばる意味。", "合流": "流れや人が一つに集まる意味で、結集の反対語ではない。", "集約": "まとめて一つにする意味で、結集と近い方向の語。対義語ではない。", "静止": "動かずにとどまる意味で、集まる動作の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんの人が集まること。または、知恵や力が一つに集まること。", "primary_collocate": null, "pronunciation": "けっしゅう", "ipa": "keɕːɯː", "syllable_count": 4, "sentences": [{"text": "駅前の広場に、数千人の市民が結集しました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]に、数千人[すうせんにん]の市民[しみん]が結集[けっしゅう]しました。", "sentence_source": "generated"}, {"text": "反対する人々は、公園に結集して声を上げました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "反対[はんたい]する人々[ひとびと]は、公園[こうえん]に結集[けっしゅう]して声[こえ]を上[あ]げました。", "sentence_source": "generated"}, {"text": "全国から農家の代表が結集し、会議が開かれました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "全国[ぜんこく]から農家[のうか]の代表[だいひょう]が結集[けっしゅう]し、会議[かいぎ]が開[ひら]かれました。", "sentence_source": "generated"}, {"text": "選手たちは試合の前に、監督のもとに結集しました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは試合[しあい]の前[まえ]に、監督[かんとく]のもとに結集[けっしゅう]しました。", "sentence_source": "generated"}, {"text": "町の人々の力を結集して、祭りの準備を進めました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]の力[ちから]を結集[けっしゅう]して、祭[まつ]りの準備[じゅんび]を進[すす]めました。", "sentence_source": "generated"}, {"text": "国民の力が結集すれば、大きな変化を起こせます。", "target_word": "結集", "complexity_tier": "T3", "furigana": "国民[こくみん]の力[ちから]が結集[けっしゅう]すれば、大[おお]きな変化[へんか]を起[お]こせます。", "sentence_source": "generated"}, {"text": "学生たちは校門の前に結集して、先生に意見を伝えました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "学生[がくせい]たちは校門[こうもん]の前[まえ]に結集[けっしゅう]して、先生[せんせい]に意見[いけん]を伝[つた]えました。", "sentence_source": "generated"}, {"text": "若者たちの結集によって、小さな運動が全国に広がりました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "若者[わかもの]たちの結集[けっしゅう]によって、小[ちい]さな運動[うんどう]が全国[ぜんこく]に広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "世界各国の代表が結集する会議が、来月開かれます。", "target_word": "結集", "complexity_tier": "T3", "furigana": "世界[せかい]各国[かっこく]の代表[だいひょう]が結集[けっしゅう]する会議[かいぎ]が、来月[らいげつ]開[ひら]かれます。", "sentence_source": "generated"}, {"text": "町じゅうの消防士が結集して、大きな火事を消しました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "町[まち]じゅうの消防士[しょうぼうし]が結集[けっしゅう]して、大[おお]きな火事[かじ]を消[け]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結集", "label": "基本形"}, {"form": "結集する", "label": "動詞形(する)"}, {"form": "結集した", "label": "過去形"}, {"form": "結集して", "label": "て形"}, {"form": "結集しました", "label": "丁寧な過去形"}], "register": "標準(丁寧体)", "sense_fingerprint": "同じ目的のために多くの人が一か所に集まること、また力を一つにまとめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結集", "is_correct": true, "explanation": "正解。多くの市民が一か所に集まるという意味で、文の動作に合う。"}, {"text": "結露", "is_correct": false, "explanation": "結露は水滴ができる現象で、人の集まりには使わない。"}, {"text": "結実", "is_correct": false, "explanation": "努力が実を結ぶ意味で、人が一か所に集まる動作には使わない。"}, {"text": "結論", "is_correct": false, "explanation": "話し合いの結末を判断する意味で、市民が広場に集まる動作とは合わない。"}], "explanations": {"結集": "正解。多くの市民が一か所に集まるという意味で、文の動作に合う。", "結露": "結露は水滴ができる現象で、人の集まりには使わない。", "結実": "努力が実を結ぶ意味で、人が一か所に集まる動作には使わない。", "結論": "話し合いの結末を判断する意味で、市民が広場に集まる動作とは合わない。"}, "sentence_index": 0, "correct_answer": "結集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキの材料を大きなボウルに結集して、よく混ぜます。", "explanation": "ここは〈集める〉の意味。結集は人や力の集まりに使い、材料には使わないので合わない。"}, {"text": "一匹の犬が、飼い主の足元に結集してきました。", "explanation": "ここは〈集まる〉の意味。結集は多くの人や力が集まることを指し、一匹の犬には使わない。"}, {"text": "珍しい虫を結集して、標本箱に並べました。", "explanation": "ここは〈収集〉の意味。結集は人や力が集まることを表し、虫を集めることには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結集", "is_correct": true, "explanation": "正解。学生たちが校門の前に集まるという意味で、文に合う。"}, {"text": "結晶", "is_correct": false, "explanation": "努力などの成果を指す語で、人が集まる動作には使わない。"}, {"text": "結末", "is_correct": false, "explanation": "物語や出来事の終わりを表し、人が集まる動作には合わない。"}, {"text": "結納", "is_correct": false, "explanation": "婚約の際の儀礼を指し、校門の前の文脈には合わない。"}], "explanations": {"結集": "正解。学生たちが校門の前に集まるという意味で、文に合う。", "結晶": "努力などの成果を指す語で、人が集まる動作には使わない。", "結末": "物語や出来事の終わりを表し、人が集まる動作には合わない。", "結納": "婚約の際の儀礼を指し、校門の前の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "結集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の前日、私は勉強に結集して、朝まで机に向かいました。", "explanation": "ここは〈集中〉の意味。結集は人や力が集まることで、一人の勉強には使わないので合わない。"}, {"text": "二つの川を、ここで結集させて一つの大きな流れにしました。", "explanation": "ここは〈合流〉の意味。川は人や力ではないので、結集の対象にはしない。"}, {"text": "風で落ち葉が一か所に結集して、山になりました。", "explanation": "ここは〈寄せ集まる〉の意味。落ち葉は人や力ではないので、結集とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域の住民の力に結集して、防災訓練を行いました。", "corrected_sentence": "地域の住民の力を結集して、防災訓練を行いました。", "error_description": "誤りは「力に」。結集する対象は「力を」で示すのが正しい。「力を結集して」が自然な形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51717, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生たちは校門の前に結集で、大学への要望を伝えました。", "corrected_sentence": "学生たちは校門の前に結集して、大学への要望を伝えました。", "error_description": "誤りは「結集で」。動詞の連用形は「結集して」の形で、後ろの文につなぐ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
