INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51718, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "多くの人や物、知恵などが一か所に集まること。また、集めること。", "primary_collocate": null, "pronunciation": "けっしゅう", "ipa": "keɕːɯː", "syllable_count": 4, "sentences": [{"text": "この建設には、当時の建築工学の知恵が結集されています。", "target_word": "結集", "complexity_tier": "T3", "furigana": "この建設[けんせつ]には、当時[とうじ]の建築工学[けんちくこうがく]の知恵[ちえ]が結集[けっしゅう]されています。", "sentence_source": "mined"}, {"text": "このロボットには、日本の最新技術が結集されています。", "target_word": "結集", "complexity_tier": "T3", "furigana": "このロボットには、日本[にほん]の最新[さいしん]技術[ぎじゅつ]が結集[けっしゅう]されています。", "sentence_source": "generated"}, {"text": "世界中の科学者の知恵を結集して、新しい薬が開発されました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "世界中[せかいじゅう]の科学者[かがくしゃ]の知恵[ちえ]を結集[けっしゅう]して、新[あたら]しい薬[くすり]が開発[かいはつ]されました。", "sentence_source": "generated"}, {"text": "社員の力を結集すれば、この難しい仕事も終えられるはずです。", "target_word": "結集", "complexity_tier": "T3", "furigana": "社員[しゃいん]の力[ちから]を結集[けっしゅう]すれば、この難[むずか]しい仕事[しごと]も終[お]えられるはずです。", "sentence_source": "generated"}, {"text": "この映画は、一流のスタッフの才能が結集した作品です。", "target_word": "結集", "complexity_tier": "T3", "furigana": "この映画[えいが]は、一流[いちりゅう]のスタッフの才能[さいのう]が結集[けっしゅう]した作品[さくひん]です。", "sentence_source": "generated"}, {"text": "市民の意見を結集して、町の計画案をまとめました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "市民[しみん]の意見[いけん]を結集[けっしゅう]して、町[まち]の計画案[けいかくあん]をまとめました。", "sentence_source": "generated"}, {"text": "長年の研究の成果を結集した本が、先月出版されました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "長年[ながねん]の研究[けんきゅう]の成果[せいか]を結集[けっしゅう]した本[ほん]が、先月[せんげつ]出版[しゅっぱん]されました。", "sentence_source": "generated"}, {"text": "チーム全員の力を結集したおかげで、大会で優勝できました。", "target_word": "結集", "complexity_tier": "T3", "furigana": "チーム全員[ぜんいん]の力[ちから]を結集[けっしゅう]したおかげで、大会[たいかい]で優勝[ゆうしょう]できました。", "sentence_source": "generated"}, {"text": "この料理には、店主の経験と工夫が結集されています。", "target_word": "結集", "complexity_tier": "T3", "furigana": "この料理[りょうり]には、店主[てんしゅ]の経験[けいけん]と工夫[くふう]が結集[けっしゅう]されています。", "sentence_source": "generated"}, {"text": "専門家の知識を結集させて、災害の対策を考えます。", "target_word": "結集", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の知識[ちしき]を結集[けっしゅう]させて、災害[さいがい]の対策[たいさく]を考[かんが]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結集", "label": "基本形"}, {"form": "結集する", "label": "動詞形(する)"}, {"form": "結集した", "label": "過去形"}, {"form": "結集して", "label": "て形"}, {"form": "結集される", "label": "受身形"}], "register": "標準(丁寧体)", "sense_fingerprint": "知恵・技術・力などを一つに集めて生かすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51718, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結集", "is_correct": true, "explanation": "知恵や技術を一か所に集めて生かすという意味で、「知恵が結集されています」に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "「知恵が点灯されています」は意味が通らず、合わない。"}, {"text": "就寝", "is_correct": false, "explanation": "「知恵が就寝されています」は成り立たず、合わない。"}, {"text": "沈黙", "is_correct": false, "explanation": "「知恵が沈黙されています」は意味が通らず、合わない。"}], "explanations": {"結集": "知恵や技術を一か所に集めて生かすという意味で、「知恵が結集されています」に合う。", "点灯": "「知恵が点灯されています」は意味が通らず、合わない。", "就寝": "「知恵が就寝されています」は成り立たず、合わない。", "沈黙": "「知恵が沈黙されています」は意味が通らず、合わない。"}, "sentence_index": 0, "correct_answer": "結集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験の結集が、明日の朝に発表されます。", "explanation": "ここは〈結果〉の意味。試験の成績を発表するのは結果で、結集は発表されるものではないので合わない。"}, {"text": "友人が来月結集するので、お祝いをしよう。", "explanation": "ここは〈結婚〉の意味。人が夫婦になるのは結婚で、結集は力や知恵を一つに集める語なので合わない。"}, {"text": "会議で結集を出した。", "explanation": "ここは〈結論〉の意味。会議で出すのは結論で、結集は出すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51718, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結集", "is_correct": true, "explanation": "研究の成果を一つに集めて生かしたという意味で、「結集した本」に合う。"}, {"text": "停電", "is_correct": false, "explanation": "「成果を停電した本」は意味が通らず、合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "「成果を乾燥した本」は意味が通らず、合わない。"}, {"text": "出発", "is_correct": false, "explanation": "「成果を出発した本」は成り立たず、合わない。"}], "explanations": {"結集": "研究の成果を一つに集めて生かしたという意味で、「結集した本」に合う。", "停電": "「成果を停電した本」は意味が通らず、合わない。", "乾燥": "「成果を乾燥した本」は意味が通らず、合わない。", "出発": "「成果を出発した本」は成り立たず、合わない。"}, "sentence_index": 6, "correct_answer": "結集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の結集を、ホームページで発表した。", "explanation": "ここは〈結果〉の意味。発表するのは結果で、結集は発表する対象ではないので合わない。"}, {"text": "この実験から、結集を導いた。", "explanation": "ここは〈結論〉の意味。実験から導くのは結論で、結集は導かれるものではないので合わない。"}, {"text": "妹は今年の秋に結集して、海外へ引っ越します。", "explanation": "ここは〈結婚〉の意味。人が夫婦になるのは結婚で、結集は人の身の上には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51718, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民の力を結集に、公園を守りました。", "corrected_sentence": "市民の力を結集して、公園を守りました。", "error_description": "正しくは「結集して」（動詞「結集する」のて形）。「結集に」は名詞扱いの誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51718, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人の力を結集する、祭りを成功させました。", "corrected_sentence": "町の人の力を結集して、祭りを成功させました。", "error_description": "正しくは「結集して」（て形）。「結集する」で文を切ると後ろの文とつながらないので、動詞の形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「本の外側に」で、場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「外側をついている」は成り立たず、文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「本の外側の、カバーがついています」となり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「本の外側が、カバーがついています」となり、主語と動詞の対応が不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「本の外側に」で、場所を示す。", "を": "「外側をついている」は成り立たず、文に合わない。", "の": "「本の外側の、カバーがついています」となり、文が成り立たない。", "が": "「本の外側が、カバーがついています」となり、主語と動詞の対応が不自然。"}, "error_tags": {"を": "目的語を示す", "の": "連体修飾を示す", "が": "主語を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「缶の外側に」で、場所を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「外側へ書いてある」は方向を表す形になり、文の意味に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比べる意味になり、「缶の外側より書いてあります」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「外側を書いてあります」は書く対象として成り立たず、文に合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「缶の外側に」で、場所を示す。", "へ": "「外側へ書いてある」は方向を表す形になり、文の意味に合わない。", "より": "比べる意味になり、「缶の外側より書いてあります」は成り立たない。", "を": "「外側を書いてあります」は書く対象として成り立たず、文に合わない。"}, "error_tags": {"へ": "方向を示す", "より": "比較を示す", "を": "目的語を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの外の部分のことです。", "primary_collocate": null, "pronunciation": "そとがわ", "ipa": "sotoɡawa", "syllable_count": 4, "sentences": [{"text": "家の外側を、白いペンキでぬりました。", "target_word": "外側", "complexity_tier": "T3", "furigana": "家[いえ]の外側[そとがわ]を、白[しろ]いペンキでぬりました。", "sentence_source": "generated"}, {"text": "本の外側に、きれいな紙のカバーがついています。", "target_word": "外側", "complexity_tier": "T3", "furigana": "本[ほん]の外側[そとがわ]に、きれいな紙[かみ]のカバーがついています。", "sentence_source": "generated"}, {"text": "卵の外側はかたいですが、中はやわらかいです。", "target_word": "外側", "complexity_tier": "T3", "furigana": "卵[たまご]の外側[そとがわ]はかたいですが、中[なか]はやわらかいです。", "sentence_source": "generated"}, {"text": "大きな木の外側は、茶色い皮でおおわれています。", "target_word": "外側", "complexity_tier": "T3", "furigana": "大[おお]きな木[き]の外側[そとがわ]は、茶色[ちゃいろ]い皮[かわ]でおおわれています。", "sentence_source": "generated"}, {"text": "建物の外側に、非常階段があります。", "target_word": "外側", "complexity_tier": "T3", "furigana": "建物[たてもの]の外側[そとがわ]に、非常階段[ひじょうかいだん]があります。", "sentence_source": "generated"}, {"text": "このかばんは、外側にも小さいポケットがあります。", "target_word": "外側", "complexity_tier": "T3", "furigana": "このかばんは、外側[そとがわ]にも小[ちい]さいポケットがあります。", "sentence_source": "generated"}, {"text": "池の外側を歩くと、ぐるっと一周できます。", "target_word": "外側", "complexity_tier": "T3", "furigana": "池[いけ]の外側[そとがわ]を歩[ある]くと、ぐるっと一周[いっしゅう]できます。", "sentence_source": "generated"}, {"text": "缶の外側に、賞味期限が書いてあります。", "target_word": "外側", "complexity_tier": "T3", "furigana": "缶[かん]の外側[そとがわ]に、賞味期限[しょうみきげん]が書[か]いてあります。", "sentence_source": "generated"}, {"text": "パンの外側はかりかりで、中はふわふわです。", "target_word": "外側", "complexity_tier": "T3", "furigana": "パンの外側[そとがわ]はかりかりで、中[なか]はふわふわです。", "sentence_source": "generated"}, {"text": "洗濯するときは、服の外側が傷つかないように袋に入れます。", "target_word": "外側", "complexity_tier": "T3", "furigana": "洗濯[せんたく]するときは、服[ふく]の外側[そとがわ]が傷[きず]つかないように袋[ふくろ]に入[い]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外側", "label": "基本形"}], "register": "標準(丁寧体)", "sense_fingerprint": "ものの外にあたる部分。中身や内側に対する表面側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外側", "is_correct": true, "explanation": "正解。家の外の面にぬるという意味で、文に合う。"}, {"text": "中身", "is_correct": false, "explanation": "家の中にあるものを指し、ペンキをぬる対象としては合わない。"}, {"text": "大きさ", "is_correct": false, "explanation": "家の大きさをぬるという言い方は成り立たず、文の意味に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "家の値段をぬるという言い方は成り立たず、文に合わない。"}], "explanations": {"外側": "正解。家の外の面にぬるという意味で、文に合う。", "中身": "家の中にあるものを指し、ペンキをぬる対象としては合わない。", "大きさ": "家の大きさをぬるという言い方は成り立たず、文の意味に合わない。", "値段": "家の値段をぬるという言い方は成り立たず、文に合わない。"}, "sentence_index": 0, "correct_answer": "外側"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家の外側に入ってから、寝ました。", "explanation": "ここは〈中〉の意味。家に入る場合は中に入るのであり、外側に入るとは言わない。"}, {"text": "鍋の外側に、野菜を入れて煮ました。", "explanation": "ここは〈中〉の意味。煮る材料は鍋の中に入れるもので、外側には入れない。"}, {"text": "試験の外側で、答えを書きました。", "explanation": "ここは〈枠の外〉の意味。試験は枠として外側という語では表せず、文の意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外側", "is_correct": true, "explanation": "正解。池のまわりの外の縁を歩くという意味で、文に合う。"}, {"text": "形", "is_correct": false, "explanation": "池の形を歩くという意味にはならず、文脈に合わない。"}, {"text": "深さ", "is_correct": false, "explanation": "池の深さを歩くという言い方は成り立たず、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "池の季節を歩くという意味にはならず、文脈に合わない。"}], "explanations": {"外側": "正解。池のまわりの外の縁を歩くという意味で、文に合う。", "形": "池の形を歩くという意味にはならず、文脈に合わない。", "深さ": "池の深さを歩くという言い方は成り立たず、文に合わない。", "季節": "池の季節を歩くという意味にはならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "外側"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は外側の国に、三年間留学しました。", "explanation": "ここは〈外国〉の意味。国は外側ではなく外国と言うので、外側の国とは言わない。"}, {"text": "会社の外側の人に、意見を聞きました。", "explanation": "ここは〈外部〉の意味。人は外側ではなく外部と言うので、外側の人とは言わない。"}, {"text": "鉛筆の外側で、字を書きました。", "explanation": "ここは〈芯〉の意味。字を書くのは木の外側ではなく芯なので、外側では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "かばんの外側を、名前のラベルを貼りました。", "corrected_sentence": "かばんの外側に、名前のラベルを貼りました。", "error_description": "誤りは「外側を」。貼る場所を示すのは「外側に」で、場所の「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "袋の外側を、原材料が書いてあります。", "corrected_sentence": "袋の外側に、原材料が書いてあります。", "error_description": "誤りは「外側を」。「書いてある」は書かれている場所を「に」で示すので、「外側に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「箱の外側に」で、場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「外側を書く」の形は場所を表さず、文の意味に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「外側の、送り先の住所を書いて」となり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比べる意味になり、「箱の外側より」では文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「箱の外側に」で、場所を示す。", "を": "「外側を書く」の形は場所を表さず、文の意味に合わない。", "の": "「外側の、送り先の住所を書いて」となり、文が成り立たない。", "より": "比べる意味になり、「箱の外側より」では文が成り立たない。"}, "error_tags": {"を": "目的語を示す", "の": "連体修飾を示す", "より": "比較を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「外側がぬれた」の形で、外側が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「外側へぬれた」は方向を表す形になり、文の意味に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比べる意味になり、「外側よりぬれた」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「外側とぬれた」は並列の形で、動詞のぬれたと続かない。"}], "correct_answer": "が", "explanations": {"が": "正解。「外側がぬれた」の形で、外側が主語になる。", "へ": "「外側へぬれた」は方向を表す形になり、文の意味に合わない。", "より": "比べる意味になり、「外側よりぬれた」は文が成り立たない。", "と": "「外側とぬれた」は並列の形で、動詞のぬれたと続かない。"}, "error_tags": {"へ": "方向を示す", "より": "比較を示す", "と": "並列を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物や場所の、外に面した側や部分。", "primary_collocate": null, "pronunciation": "そとがわ", "ipa": "sotoɡawa", "syllable_count": 4, "sentences": [{"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "外側", "complexity_tier": "T3", "furigana": "特[とく]に注目[ちゅうもく]すべきは、天井[てんじょう]の重量[じゅうりょう]を分散[ぶんさん]させる「リブ・ヴォールト」と、壁[かべ]の外側[そとがわ]から支[ささ]える「フライング・バットレス」と呼[よ]ばれる技術[ぎじゅつ]です。", "sentence_source": "mined"}, {"text": "箱の外側に、送り先の住所を書いてください。", "target_word": "外側", "complexity_tier": "T3", "furigana": "箱[はこ]の外側[そとがわ]に、送[おく]り先[さき]の住所[じゅうしょ]を書[か]いてください。", "sentence_source": "generated"}, {"text": "このカップは外側が熱くなるので、気をつけてください。", "target_word": "外側", "complexity_tier": "T3", "furigana": "このカップは外側[そとがわ]が熱[あつ]くなるので、気[き]をつけてください。", "sentence_source": "generated"}, {"text": "ホームの黄色い線の外側には、出ないでください。", "target_word": "外側", "complexity_tier": "T3", "furigana": "ホームの黄色[きいろ]い線[せん]の外側[そとがわ]には、出[で]ないでください。", "sentence_source": "generated"}, {"text": "城の外側には、深い堀があります。", "target_word": "外側", "complexity_tier": "T3", "furigana": "城[しろ]の外側[そとがわ]には、深[ふか]い堀[ほり]があります。", "sentence_source": "generated"}, {"text": "りんごは外側が赤いですが、中は白いです。", "target_word": "外側", "complexity_tier": "T3", "furigana": "りんごは外側[そとがわ]が赤[あか]いですが、中[なか]は白[しろ]いです。", "sentence_source": "generated"}, {"text": "外側のカバーを外すと、機械の中が見えます。", "target_word": "外側", "complexity_tier": "T3", "furigana": "外側[そとがわ]のカバーを外[はず]すと、機械[きかい]の中[なか]が見[み]えます。", "sentence_source": "generated"}, {"text": "雨でコートの外側がぬれたので、玄関でかわかしました。", "target_word": "外側", "complexity_tier": "T3", "furigana": "雨[あめ]でコートの外側[そとがわ]がぬれたので、玄関[げんかん]でかわかしました。", "sentence_source": "generated"}, {"text": "カーブでは、外側の車線のほうが少し長くなります。", "target_word": "外側", "complexity_tier": "T3", "furigana": "カーブでは、外側[そとがわ]の車線[しゃせん]のほうが少[すこ]し長[なが]くなります。", "sentence_source": "generated"}, {"text": "窓の外側は汚れていて、中からは拭けません。", "target_word": "外側", "complexity_tier": "T3", "furigana": "窓[まど]の外側[そとがわ]は汚[よご]れていて、中[なか]からは拭[ふ]けません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外側", "label": "基本形"}], "register": "標準(丁寧体)", "sense_fingerprint": "物や場所の、外に向いている側。内側の反対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: かわかし (Zipf 1.27)']::text[], '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外側", "is_correct": true, "explanation": "正解。壁の外の面から支えるという意味で、文に合う。"}, {"text": "中身", "is_correct": false, "explanation": "内部にあるものを指し、壁の外から支える文脈には合わない。"}, {"text": "色", "is_correct": false, "explanation": "壁の色から支えるという意味にはならず、文脈に合わない。"}, {"text": "大きさ", "is_correct": false, "explanation": "壁の大きさから支えるという言い方は不自然で、文の意味に合わない。"}], "explanations": {"外側": "正解。壁の外の面から支えるという意味で、文に合う。", "中身": "内部にあるものを指し、壁の外から支える文脈には合わない。", "色": "壁の色から支えるという意味にはならず、文脈に合わない。", "大きさ": "壁の大きさから支えるという言い方は不自然で、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "外側"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は外側がいいので、会社では人気者だが家では無口だ。", "explanation": "ここは〈外面〉の意味。人当たりを言うときは「外面（そとづら）」を使い、外側は使わない。"}, {"text": "彼女は心の外側が傷ついて、ずっと泣いていた。", "explanation": "ここは〈内面〉の意味。心には外側を使わず、「心が傷つく」と言う。"}, {"text": "会議の外側で、一週間の日程を決めた。", "explanation": "ここは〈会議の場外〉の意味。会議は物や場所ではないので、外側ではなく場外と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外側", "is_correct": true, "explanation": "正解。カバーの外に面した部分を指し、「外側のカバー」に合う。"}, {"text": "形", "is_correct": false, "explanation": "「形のカバー」は形状を指し、外す対象の部分としては成り立たないので合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段のカバー」は成り立たず、文の意味に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節のカバー」は成り立たず、文の意味に合わない。"}], "explanations": {"外側": "正解。カバーの外に面した部分を指し、「外側のカバー」に合う。", "形": "「形のカバー」は形状を指し、外す対象の部分としては成り立たないので合わない。", "値段": "「値段のカバー」は成り立たず、文の意味に合わない。", "季節": "「季節のカバー」は成り立たず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "外側"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱の外側に入っているお菓子を、みんなで食べました。", "explanation": "ここは〈中身〉の意味。箱の中に入っている物は外側ではなく中身と言う。"}, {"text": "彼女は外側が明るく、みんなに好かれています。", "explanation": "ここは〈外面〉の意味。性格を言うときは外面（そとづら）を使い、外側は使わない。"}, {"text": "試合の外側で、大きなゴールが決まりました。", "explanation": "ここは〈途中〉の意味。試合の展開は外側と言わず、ゴールは試合の中で決まるので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱の外側を、ラベルを貼ってください。", "corrected_sentence": "箱の外側に、ラベルを貼ってください。", "error_description": "誤りは「外側を」。貼る場所を示すのは「外側に」で、場所の「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51720, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の外側が拭いて、きれいにしました。", "corrected_sentence": "窓の外側を拭いて、きれいにしました。", "error_description": "誤りは「外側が」。「拭く」は対象を「を」で示すので、「外側を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51721, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厚い", "is_correct": true, "explanation": "物の厚さという意味での「薄い」の対義語。"}, {"text": "高い", "is_correct": false, "explanation": "高さを表す形容詞で、厚さの対義語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深さを表す形容詞で、「薄い」の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞で、厚さの対義語ではない。"}], "correct_answer": "厚い", "explanations": {"厚い": "物の厚さという意味での「薄い」の対義語。", "高い": "高さを表す形容詞で、厚さの対義語ではない。", "深い": "深さを表す形容詞で、「薄い」の対義語ではない。", "重い": "重さを表す形容詞で、厚さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
