INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51721, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物の厚さが少ないこと。", "primary_collocate": null, "pronunciation": "うすい", "ipa": "ɯsɯi", "syllable_count": 3, "sentences": [{"text": "薄い雑誌なので、電車の中で読み終えました。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "薄[うす]い雑誌[ざっし]なので、電車[でんしゃ]の中[なか]で読[よ]み終[お]えました。", "sentence_source": "generated"}, {"text": "冬なのに薄いシャツ一枚で出かけて、風邪をひきました。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "冬[ふゆ]なのに薄[うす]いシャツ一枚[いちまい]で出[で]かけて、風邪[かぜ]をひきました。", "sentence_source": "generated"}, {"text": "この板は薄いから、重い物をのせると割れてしまいます。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "この板[いた]は薄[うす]いから、重[おも]い物[もの]をのせると割[わ]れてしまいます。", "sentence_source": "generated"}, {"text": "薄いガラスのコップは、落とすとすぐに割れます。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "薄[うす]いガラスのコップは、落[お]とすとすぐに割[わ]れます。", "sentence_source": "generated"}, {"text": "餅を薄く伸ばしてから、フライパンで焼きます。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "餅[もち]を薄[うす]く伸[の]ばしてから、フライパンで焼[や]きます。", "sentence_source": "generated"}, {"text": "薄いカーテンだったので、朝日がそのまま部屋に入ってきた。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "薄[うす]いカーテンだったので、朝日[あさひ]がそのまま部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "テレビが薄くなって、壁に掛けられるようになりました。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "テレビが薄[うす]くなって、壁[かべ]に掛[か]けられるようになりました。", "sentence_source": "generated"}, {"text": "彼女は薄い手袋をはめて、写真を傷つけないように扱った。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は薄[うす]い手袋[てぶくろ]をはめて、写真[しゃしん]を傷[きず]つけないように扱[あつか]った。", "sentence_source": "generated"}, {"text": "薄い財布は持ちやすいが、カードが少ししか入らない。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "薄[うす]い財布[さいふ]は持[も]ちやすいが、カードが少[すこ]ししか入[はい]らない。", "sentence_source": "generated"}, {"text": "皮を薄くむくと、実がたくさん残ります。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "皮[かわ]を薄[うす]くむくと、実[み]がたくさん残[のこ]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "薄い", "label": "終止形・連体形"}, {"form": "薄く", "label": "連用形"}, {"form": "薄くて", "label": "て形"}, {"form": "薄かった", "label": "過去形"}, {"form": "薄くない", "label": "否定形"}, {"form": "薄ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物の厚みが少ない(雑誌・シャツ・板・ガラスなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51721, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薄い", "is_correct": true, "explanation": "連体形で、後ろの「雑誌」を修飾する。「薄い雑誌なので」と一致する。"}, {"text": "薄く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できないので、「薄く雑誌」は不成立。"}, {"text": "薄さ", "is_correct": false, "explanation": "名詞なので、「薄さの雑誌」のように「の」が要る。"}, {"text": "薄め", "is_correct": false, "explanation": "「薄めの」と「の」が要るため、「薄め雑誌」とは続かない。"}], "explanations": {"薄い": "連体形で、後ろの「雑誌」を修飾する。「薄い雑誌なので」と一致する。", "薄く": "連用形は名詞を直接修飾できないので、「薄く雑誌」は不成立。", "薄さ": "名詞なので、「薄さの雑誌」のように「の」が要る。", "薄め": "「薄めの」と「の」が要るため、「薄め雑誌」とは続かない。"}, "sentence_index": 0, "correct_answer": "薄い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この綱は薄いので、大きな船をつなげない。", "explanation": "ここは〈細い〉の意味。綱の細さは「細い」で言い、厚さの「薄い」は平たい物に使うので合わない。"}, {"text": "この糸は薄くて、すぐ切れる。", "explanation": "ここは〈細い〉の意味。糸の太さを「薄い」とは言わないので合わない。"}, {"text": "この湖は薄くて、ボートが進みにくい。", "explanation": "ここは〈浅い〉の意味。水深を「薄い」とは言わないので、厚さの定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51721, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薄く", "is_correct": true, "explanation": "連用形で、後ろの「なって」に続く。「薄くなって」と一致する。"}, {"text": "薄い", "is_correct": false, "explanation": "終止形は「薄いなって」とは続かない。"}, {"text": "薄かった", "is_correct": false, "explanation": "過去形は「薄かったなって」とは続かない。"}, {"text": "薄くない", "is_correct": false, "explanation": "否定形は「薄くないなって」とは続かない。"}], "explanations": {"薄く": "連用形で、後ろの「なって」に続く。「薄くなって」と一致する。", "薄い": "終止形は「薄いなって」とは続かない。", "薄かった": "過去形は「薄かったなって」とは続かない。", "薄くない": "否定形は「薄くないなって」とは続かない。"}, "sentence_index": 6, "correct_answer": "薄く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この井戸は薄いので、深く掘れない。", "explanation": "ここは〈浅い〉の意味。井戸の深さは「浅い」で言い、厚さの「薄い」は平たい物に使うので合わない。"}, {"text": "この畑は薄くて、広く野菜を育てられない。", "explanation": "ここは〈広い〉の意味。畑の広さは「広い」で言い、厚さの「薄い」は平たい物に使うので合わない。"}, {"text": "この教室は薄くて、三十人は入れない。", "explanation": "ここは〈狭い〉の意味。部屋の広さを「薄い」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51721, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この手帳は薄くので、かばんに入る。", "corrected_sentence": "この手帳は薄いので、かばんに入る。", "error_description": "理由の「ので」には終止形の「薄いので」が必要。連用形の「薄くので」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "薄い", "is_correct": true, "explanation": "連体形で、後ろの「シャツ」を修飾する。文中の「薄いシャツ」と一致する。"}, {"text": "薄く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できないので、「薄くシャツ」は不成立。"}, {"text": "薄くて", "is_correct": false, "explanation": "て形は名詞を修飾できないので、「薄くてシャツ」は不成立。"}, {"text": "薄ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できないので、「薄ければシャツ」は不成立。"}], "correct_form": "薄い", "base_form": "薄い", "form_label": "連体形", "sentence_index": 1, "explanations": {"薄い": "連体形で、後ろの「シャツ」を修飾する。文中の「薄いシャツ」と一致する。", "薄く": "連用形は名詞を直接修飾できないので、「薄くシャツ」は不成立。", "薄くて": "て形は名詞を修飾できないので、「薄くてシャツ」は不成立。", "薄ければ": "仮定形は名詞を修飾できないので、「薄ければシャツ」は不成立。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51721, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このシャツは薄いて、夏に向いています。", "corrected_sentence": "このシャツは薄くて、夏に向いています。", "error_description": "て形の「薄くて」が正しい。終止形の「薄いて」は「て」に接続できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "薄い", "is_correct": true, "explanation": "連体形で、後ろの「手袋」を修飾する。文中の「薄い手袋」と一致する。"}, {"text": "薄かったら", "is_correct": false, "explanation": "仮定形は名詞を修飾できないので、「薄かったら手袋」は不成立。"}, {"text": "薄くなければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できないので、「薄くなければ手袋」は不成立。"}, {"text": "薄くありません", "is_correct": false, "explanation": "敬体の否定形は名詞を直接修飾できないので、「薄くありません手袋」は不成立。"}], "correct_form": "薄い", "base_form": "薄い", "form_label": "連体形", "sentence_index": 7, "explanations": {"薄い": "連体形で、後ろの「手袋」を修飾する。文中の「薄い手袋」と一致する。", "薄かったら": "仮定形は名詞を修飾できないので、「薄かったら手袋」は不成立。", "薄くなければ": "仮定形は名詞を修飾できないので、「薄くなければ手袋」は不成立。", "薄くありません": "敬体の否定形は名詞を直接修飾できないので、「薄くありません手袋」は不成立。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厚く", "is_correct": true, "explanation": "物の厚さという意味での「薄く」の対義語。"}, {"text": "早く", "is_correct": false, "explanation": "速さを表す副詞で、厚さの「薄く」とは対義関係にない。"}, {"text": "深く", "is_correct": false, "explanation": "深さを表す副詞で、「薄く」の対義語ではない。"}, {"text": "軽く", "is_correct": false, "explanation": "重さを表す副詞で、厚さの対義語ではない。"}], "correct_answer": "厚く", "explanations": {"厚く": "物の厚さという意味での「薄く」の対義語。", "早く": "速さを表す副詞で、厚さの「薄く」とは対義関係にない。", "深く": "深さを表す副詞で、「薄く」の対義語ではない。", "軽く": "重さを表す副詞で、厚さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厚く", "is_correct": true, "explanation": "塗る厚さで「薄く」と反対になる対義語。"}, {"text": "遅く", "is_correct": false, "explanation": "時間を表す副詞で、「薄く」の対義語ではない。"}, {"text": "強く", "is_correct": false, "explanation": "力の強さを表す副詞で、厚さの対義語ではない。"}, {"text": "固く", "is_correct": false, "explanation": "硬さを表す副詞で、厚さの対義語ではない。"}], "correct_answer": "厚く", "explanations": {"厚く": "塗る厚さで「薄く」と反対になる対義語。", "遅く": "時間を表す副詞で、「薄く」の対義語ではない。", "強く": "力の強さを表す副詞で、厚さの対義語ではない。", "固く": "硬さを表す副詞で、厚さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物の厚さが普通より小さいさま。", "primary_collocate": null, "pronunciation": "うすい", "ipa": "ɯsɯi", "syllable_count": 3, "sentences": [{"text": "これらにより、壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "これらにより、壁[かべ]を薄[うす]くして大[おお]きな窓[まど]を設[もう]けることが可能[かのう]となり、内部[ないぶ]は光[ひかり]に満[み]ちあふれました。", "sentence_source": "mined"}, {"text": "このノートは紙が薄いので、裏に字が透けて見えます。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "このノートは紙[かみ]が薄[うす]いので、裏[うら]に字[じ]が透[す]けて見[み]えます。", "sentence_source": "generated"}, {"text": "薄い毛布しかなかったので、夜は寒くて眠れませんでした。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "薄[うす]い毛布[もうふ]しかなかったので、夜[よる]は寒[さむ]くて眠[ねむ]れませんでした。", "sentence_source": "generated"}, {"text": "パンを薄く切ると、早く焼けます。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "パンを薄[うす]く切[き]ると、早[はや]く焼[や]けます。", "sentence_source": "generated"}, {"text": "彼は薄いコートを着て出かけたが、雪が降ってきて後悔した。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "彼[かれ]は薄[うす]いコートを着[き]て出[で]かけたが、雪[ゆき]が降[ふ]ってきて後悔[こうかい]した。", "sentence_source": "generated"}, {"text": "この携帯電話は薄くて軽いので、ポケットに入れても邪魔になりません。", "target_word": "薄くて", "complexity_tier": "T3", "furigana": "この携帯電話[けいたいでんわ]は薄[うす]くて軽[かる]いので、ポケットに入[い]れても邪魔[じゃま]になりません。", "sentence_source": "generated"}, {"text": "氷が薄い池には、入らないでください。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "氷[こおり]が薄[うす]い池[いけ]には、入[はい]らないでください。", "sentence_source": "generated"}, {"text": "ハムを薄く切ってもらい、サンドイッチに挟みました。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "ハムを薄[うす]く切[き]ってもらい、サンドイッチに挟[はさ]みました。", "sentence_source": "generated"}, {"text": "薄い辞書は持ち歩きやすいが、載っている言葉は少ない。", "target_word": "薄い", "complexity_tier": "T3", "furigana": "薄[うす]い辞書[じしょ]は持[も]ち歩[ある]きやすいが、載[の]っている言葉[ことば]は少[すく]ない。", "sentence_source": "generated"}, {"text": "ペンキを薄く塗ってから、乾くのを待ちました。", "target_word": "薄く", "complexity_tier": "T3", "furigana": "ペンキを薄[うす]く塗[ぬ]ってから、乾[かわ]くのを待[ま]ちました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "薄い", "label": "終止形・連体形"}, {"form": "薄く", "label": "連用形"}, {"form": "薄くて", "label": "て形"}, {"form": "薄かった", "label": "過去形"}, {"form": "薄くない", "label": "否定形"}, {"form": "薄ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物の厚みが普通より小さい(紙・布・板・切り方など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薄く", "is_correct": true, "explanation": "「壁を薄くして」の連用形で、「薄くする」の形から「して」に続く。"}, {"text": "薄い", "is_correct": false, "explanation": "終止形なので「薄いして」とは続かない。"}, {"text": "薄さ", "is_correct": false, "explanation": "名詞なので「薄さして」とは続かない。"}, {"text": "薄かった", "is_correct": false, "explanation": "過去形なので「薄かったして」は成立しない。"}], "explanations": {"薄く": "「壁を薄くして」の連用形で、「薄くする」の形から「して」に続く。", "薄い": "終止形なので「薄いして」とは続かない。", "薄さ": "名詞なので「薄さして」とは続かない。", "薄かった": "過去形なので「薄かったして」は成立しない。"}, "sentence_index": 0, "correct_answer": "薄く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この机は脚が薄いので、重い本は置けない。", "explanation": "ここは〈細い〉の意味。脚の細さは「細い」で言い、厚さの「薄い」は板状の物に使うので合わない。"}, {"text": "この道は薄くて、車が通れない。", "explanation": "ここは〈細い〉（幅が狭い）の意味。道の幅を「薄い」とは言わないので、厚さの定義には合わない。"}, {"text": "この川は薄くて、子どもでも歩いて渡れる。", "explanation": "ここは〈浅い〉の意味。川の深さを「薄い」とは言わないので、厚さの定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薄い", "is_correct": true, "explanation": "連体形で、後ろの「池」を修飾できる。"}, {"text": "薄く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できない。「氷が薄く池には」は不成立。"}, {"text": "薄め", "is_correct": false, "explanation": "「薄めの」と「の」が要るため、「薄め池」とは続かない。"}, {"text": "薄くて", "is_correct": false, "explanation": "て形は名詞を修飾しないので、「池」に続かない。"}], "explanations": {"薄い": "連体形で、後ろの「池」を修飾できる。", "薄く": "連用形は名詞を直接修飾できない。「氷が薄く池には」は不成立。", "薄め": "「薄めの」と「の」が要るため、「薄め池」とは続かない。", "薄くて": "て形は名詞を修飾しないので、「池」に続かない。"}, "sentence_index": 6, "correct_answer": "薄い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池は薄くて、深く潜れる。", "explanation": "ここは〈浅い〉の意味になり、「深く潜れる」と矛盾する。厚さの「薄い」は平たい物に使うので合わない。"}, {"text": "この部屋は薄くて、二人では住めない。", "explanation": "ここは〈狭い〉（床面積が小さい）の意味。部屋の広さを「薄い」とは言わないので合わない。"}, {"text": "この庭は薄くて、子どもが走り回れる。", "explanation": "ここは〈広い〉の意味。庭の広さは「広い」で言い、厚さの「薄い」は平たい物に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この靴下は薄くので、冬は寒いです。", "corrected_sentence": "この靴下は薄いので、冬は寒いです。", "error_description": "「ので」に続けるには終止形の「薄いので」が必要。連用形の「薄くので」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "薄い", "is_correct": true, "explanation": "終止形で「ので」の前に来る形。「紙が薄いので」と一致する。"}, {"text": "薄く", "is_correct": false, "explanation": "連用形は「ので」に続かない。「紙が薄くので」は不成立。"}, {"text": "薄くて", "is_correct": false, "explanation": "て形は「ので」でつながらない。"}, {"text": "薄ければ", "is_correct": false, "explanation": "仮定形なので、理由を表す「ので」と重ねられない。"}], "correct_form": "薄い", "base_form": "薄い", "form_label": "終止形", "sentence_index": 1, "explanations": {"薄い": "終止形で「ので」の前に来る形。「紙が薄いので」と一致する。", "薄く": "連用形は「ので」に続かない。「紙が薄くので」は不成立。", "薄くて": "て形は「ので」でつながらない。", "薄ければ": "仮定形なので、理由を表す「ので」と重ねられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51722, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この紙は薄いて、すぐ破れる。", "corrected_sentence": "この紙は薄くて、すぐ破れる。", "error_description": "て形の「薄くて」が正しい。終止形の「薄いて」は「て」に接続できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "薄く", "is_correct": true, "explanation": "連用形で、後ろの「切る」を修飾する形。「薄く切ってもらい」と一致する。"}, {"text": "薄い", "is_correct": false, "explanation": "終止形・連体形は「ハムを薄い切って」とならず、動詞につながらない。"}, {"text": "薄くない", "is_correct": false, "explanation": "否定形は「薄くない切って」とならず、文が成り立たない。"}, {"text": "薄かった", "is_correct": false, "explanation": "過去形は「薄かった切って」とならず、文が成り立たない。"}], "correct_form": "薄く", "base_form": "薄い", "form_label": "連用形", "sentence_index": 7, "explanations": {"薄く": "連用形で、後ろの「切る」を修飾する形。「薄く切ってもらい」と一致する。", "薄い": "終止形・連体形は「ハムを薄い切って」とならず、動詞につながらない。", "薄くない": "否定形は「薄くない切って」とならず、文が成り立たない。", "薄かった": "過去形は「薄かった切って」とならず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「フライングを」で目的語を示し、「した」に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、「フライングへした」と動作の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」では、「フライングよりした」と動作の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、「フライングのした」と文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「フライングを」で目的語を示し、「した」に続く。", "へ": "方向を示す「へ」では、「フライングへした」と動作の対象にならない。", "より": "比較を示す「より」では、「フライングよりした」と動作の対象にならない。", "の": "連体修飾の「の」では、「フライングのした」と文が成り立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "合図より早く動いてしまうこと。", "primary_collocate": null, "pronunciation": "ふらいんぐ", "ipa": "ɸɯɾaiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "走る前に動いたら、フライングだよ。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "走[はし]る前[まえ]に動[うご]いたら、フライングだよ。", "sentence_source": "generated"}, {"text": "フライングをした人は、もう一度やり直しです。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "フライングをした人[ひと]は、もう一度[いちど]やり直[なお]しです。", "sentence_source": "generated"}, {"text": "兄はフライングして、先生に怒られた。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "兄[あに]はフライングして、先生[せんせい]に怒[おこ]られた。", "sentence_source": "generated"}, {"text": "かけっこで、フライングをしてしまいました。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "かけっこで、フライングをしてしまいました。", "sentence_source": "generated"}, {"text": "「よーい、どん」の前に走り出すと、フライングになります。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "「よーい、どん」の前[まえ]に走[はし]り出[だ]すと、フライングになります。", "sentence_source": "generated"}, {"text": "フライングが三回もあって、運動会の競走はなかなか始まらなかった。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "フライングが三回[さんかい]もあって、運動会[うんどうかい]の競走[きょうそう]はなかなか始[はじ]まらなかった。", "sentence_source": "generated"}, {"text": "弟は早く行きたくて、フライングしてスタートした。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "弟[おとうと]は早[はや]く行[い]きたくて、フライングしてスタートした。", "sentence_source": "generated"}, {"text": "合図が鳴る前に飛び出すのは、フライングです。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "合図[あいず]が鳴[な]る前[まえ]に飛[と]び出[だ]すのは、フライングです。", "sentence_source": "generated"}, {"text": "先生は、フライングをした子に「もう一度」と言った。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "先生[せんせい]は、フライングをした子[こ]に「もう一度[いちど]」と言[い]った。", "sentence_source": "generated"}, {"text": "速い選手でも、フライングをすると失格になることがある。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "速[はや]い選手[せんしゅ]でも、フライングをすると失格[しっかく]になることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フライング", "label": "基本形"}, {"form": "フライングする", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "合図より早く動いてしまうこと(かけっこなどのフライング)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フライング", "is_correct": true, "explanation": "名詞として「だよ」の前に入る。「フライングだよ」と一致する。"}, {"text": "フライングを", "is_correct": false, "explanation": "「を」を伴うと「フライングをだよ」となり、文が成り立たない。"}, {"text": "フライングで", "is_correct": false, "explanation": "「で」を伴うと「フライングでだよ」となり、文が成り立たない。"}, {"text": "フライングした", "is_correct": false, "explanation": "過去形は「だよ」に続かず、文が成り立たない。"}], "explanations": {"フライング": "名詞として「だよ」の前に入る。「フライングだよ」と一致する。", "フライングを": "「を」を伴うと「フライングをだよ」となり、文が成り立たない。", "フライングで": "「で」を伴うと「フライングでだよ」となり、文が成り立たない。", "フライングした": "過去形は「だよ」に続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "フライング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な書類を、フライングをして捨ててしまった。", "explanation": "ここは〈早とちり〉の意味。合図より早く動くことを指す語ではないので、フライングとは言わない。"}, {"text": "渋滞の中、彼はフライングで前の車を追い越した。", "explanation": "ここは〈追い越し〉の意味。前の車を抜くことは合図より早く動くことではないので、フライングとは言わない。"}, {"text": "夏休みに、フライングで沖縄まで行った。", "explanation": "ここは〈飛行機で移動する〉の意味。競技のスタートの反則という意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フライング", "is_correct": true, "explanation": "「フライングして」の形で動詞として続くため、名詞のまま「して」に続く形が正しい。"}, {"text": "フライングが", "is_correct": false, "explanation": "「が」を伴うと「フライングがしてスタート」となり、不自然で文が成り立たない。"}, {"text": "フライングの", "is_correct": false, "explanation": "「の」を伴うと「フライングのしてスタート」となり、文が成り立たない。"}, {"text": "フライングへ", "is_correct": false, "explanation": "「へ」を伴うと「フライングへしてスタート」となり、文が成り立たない。"}], "explanations": {"フライング": "「フライングして」の形で動詞として続くため、名詞のまま「して」に続く形が正しい。", "フライングが": "「が」を伴うと「フライングがしてスタート」となり、不自然で文が成り立たない。", "フライングの": "「の」を伴うと「フライングのしてスタート」となり、文が成り立たない。", "フライングへ": "「へ」を伴うと「フライングへしてスタート」となり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "フライング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大事な発表で、彼は一人だけフライングで手柄を立てた。", "explanation": "ここは〈抜け駆け〉の意味。人より先に勝手に行うことは「抜け駆け」で言い、合図より早く動く意味のフライングとは合わない。"}, {"text": "ルールを破って、フライングを科された。", "explanation": "ここは〈罰則〉の意味。ルール違反の罰を指すので、合図より早く動く反則の意味には合わない。"}, {"text": "寝坊して、フライングをした。", "explanation": "ここは〈遅刻〉の意味。寝坊による遅れを指すので、スタートの反則の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "フライングに取られた選手は、失格になった。", "corrected_sentence": "フライングを取られた選手は、失格になった。", "error_description": "「フライングを取られる」の目的語は「を」。「に」は誤りで、「フライングを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51723, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はフライングを取られって、落ち込んだ。", "corrected_sentence": "彼はフライングを取られて、落ち込んだ。", "error_description": "て形の「取られて」が正しい。「取られって」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「フライングを」で目的語を示し、「して」に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」では、「フライングがして」と目的語の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「フライングに」は「する」と結びつかず、動作の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示す「で」では、「フライングでして」と動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「フライングを」で目的語を示し、「して」に続く。", "が": "主語を示す「が」では、「フライングがして」と目的語の関係が成り立たない。", "に": "「フライングに」は「する」と結びつかず、動作の対象にならない。", "で": "手段・場所を示す「で」では、「フライングでして」と動作の対象にならない。"}, "error_tags": {"が": "主語を示す", "に": "方向・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「フライングを」で目的語を示し、「した」に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、「フライングへした」と動作の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」では、「フライングよりした」と動作の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、「フライングのした」と文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「フライングを」で目的語を示し、「した」に続く。", "へ": "方向を示す「へ」では、「フライングへした」と動作の対象にならない。", "より": "比較を示す「より」では、「フライングよりした」と動作の対象にならない。", "の": "連体修飾の「の」では、「フライングのした」と文が成り立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "決められた合図より早く動き出すこと。特に、競技のスタートで。", "primary_collocate": null, "pronunciation": "ふらいんぐ", "ipa": "ɸɯɾaiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "スタートで早く走り出したので、フライングになった。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "スタートで早[はや]く走[はし]り出[だ]したので、フライングになった。", "sentence_source": "generated"}, {"text": "百メートル走でフライングをして、失格になりました。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "百[ひゃく]メートル走[そう]でフライングをして、失格[しっかく]になりました。", "sentence_source": "generated"}, {"text": "フライングが続いたので、審判はスタートのやり直しを命じた。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "フライングが続[つづ]いたので、審判[しんぱん]はスタートのやり直[なお]しを命[めい]じた。", "sentence_source": "generated"}, {"text": "合図の前に動いてしまい、フライングを取られた。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "合図[あいず]の前[まえ]に動[うご]いてしまい、フライングを取[と]られた。", "sentence_source": "generated"}, {"text": "彼はフライングを恐れて、スタートが少し遅れた。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "彼[かれ]はフライングを恐[おそ]れて、スタートが少[すこ]し遅[おく]れた。", "sentence_source": "generated"}, {"text": "水泳の大会では、フライングを二回すると失格です。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "水泳[すいえい]の大会[たいかい]では、フライングを二回[にかい]すると失格[しっかく]です。", "sentence_source": "generated"}, {"text": "ピストルの音より先に飛び出して、フライングになってしまった。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "ピストルの音[おと]より先[さき]に飛[と]び出[だ]して、フライングになってしまった。", "sentence_source": "generated"}, {"text": "緊張しすぎて、スタートでフライングをした選手がいた。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "緊張[きんちょう]しすぎて、スタートでフライングをした選手[せんしゅ]がいた。", "sentence_source": "generated"}, {"text": "フライングのため、選手たちはスタートラインに戻された。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "フライングのため、選手[せんしゅ]たちはスタートラインに戻[もど]された。", "sentence_source": "generated"}, {"text": "最初のフライングは注意だけで、二度目から失格になる。", "target_word": "フライング", "complexity_tier": "T3", "furigana": "最初[さいしょ]のフライングは注意[ちゅうい]だけで、二度目[にどめ]から失格[しっかく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フライング", "label": "基本形"}, {"form": "フライングする", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "競技のスタートで合図より早く動き出す反則(フライング)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フライング", "is_correct": true, "explanation": "名詞として「になった」に続く。文中の「フライングになった」と一致する。"}, {"text": "フライングを", "is_correct": false, "explanation": "「を」を伴うと「フライングをになった」となり、文が成り立たない。"}, {"text": "フライングで", "is_correct": false, "explanation": "「で」を伴うと「フライングでになった」となり、文が成り立たない。"}, {"text": "フライングした", "is_correct": false, "explanation": "動詞の過去形は「になった」と続かず、文が成り立たない。"}], "explanations": {"フライング": "名詞として「になった」に続く。文中の「フライングになった」と一致する。", "フライングを": "「を」を伴うと「フライングをになった」となり、文が成り立たない。", "フライングで": "「で」を伴うと「フライングでになった」となり、文が成り立たない。", "フライングした": "動詞の過去形は「になった」と続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "フライング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールを持ちすぎて、フライングを取られた。", "explanation": "ここは〈反則〉の意味。ボールの持ちすぎは合図より早く動くことではないので、フライングとは言わない。"}, {"text": "ゴール前で手を使い、フライングを取られた。", "explanation": "ここは〈ファウル〉の意味。手を使った反則は、スタートの合図より早く動くことを指さないので合わない。"}, {"text": "夏休みに、フライングで沖縄まで行った。", "explanation": "ここは〈飛行機で移動する〉の意味。競技のスタートの反則という意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フライング", "is_correct": true, "explanation": "名詞として「になってしまった」に続く。「フライングになってしまった」と一致する。"}, {"text": "フライングする", "is_correct": false, "explanation": "動詞の終止形は「になってしまった」に続かない。"}, {"text": "フライングして", "is_correct": false, "explanation": "て形は「になってしまった」に続かない。"}, {"text": "フライングが", "is_correct": false, "explanation": "「が」を伴うと「フライングがになって」となり、文が成り立たない。"}], "explanations": {"フライング": "名詞として「になってしまった」に続く。「フライングになってしまった」と一致する。", "フライングする": "動詞の終止形は「になってしまった」に続かない。", "フライングして": "て形は「になってしまった」に続かない。", "フライングが": "「が」を伴うと「フライングがになって」となり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "フライング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で彼は結論をフライングして、誤解を招いた。", "explanation": "ここは〈早とちり〉の意味。結論を急いで出すことは合図より早く動くことではないので、フライングとは言わない。"}, {"text": "体調が悪く、フライングをした。", "explanation": "ここは〈早退〉の意味。体調不良で帰ることを指すので、スタートの反則の意味には合わない。"}, {"text": "テストで彼はフライングで答えを見て、先生に叱られた。", "explanation": "ここは〈カンニング〉の意味。試験中に答えを見ることは合図より早く動くことではないので、フライングとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの選手はフライングで取られて、失格になった。", "corrected_sentence": "あの選手はフライングを取られて、失格になった。", "error_description": "「フライングを取られる」の目的語は「を」。「で」は誤りで、「フライングを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手がフライングをって、失格になった。", "corrected_sentence": "選手がフライングをして、失格になった。", "error_description": "「フライングをする」の活用が誤り。連用形の「して」が正しく、「をって」は不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
