INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51725, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「バットレスの間」のように、バットレスに直接続く「の」。"}, {"text": "に", "is_correct": false, "explanation": "「バットレスに間を」は到達点や場所を示す形になり、名詞に続く用法として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「バットレスで間を」は文脈に合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「バットレスへ間を」は意味をなさない。"}], "correct_answer": "の", "explanations": {"の": "正解。「バットレスの間」のように、バットレスに直接続く「の」。", "に": "「バットレスに間を」は到達点や場所を示す形になり、名詞に続く用法として成り立たない。", "で": "「で」は手段や場所を示すが、「バットレスで間を」は文脈に合わず不自然。", "へ": "「へ」は方向を示すが、「バットレスへ間を」は意味をなさない。"}, "error_tags": {"に": "到達点・場所", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51725, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の壁を外から支えるための、かたちがとくべつな柱です。", "primary_collocate": null, "pronunciation": "ばっとれす", "ipa": "battoɾesɯ", "syllable_count": 5, "sentences": [{"text": "この教会の壁の外には、バットレスという太い柱があります。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "この教会[きょうかい]の壁[かべ]の外[そと]には、バットレスという太[ふと]い柱[はしら]があります。", "sentence_source": "generated"}, {"text": "バットレスは、壁が倒れないように外から支えます。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "バットレスは、壁[かべ]が倒[たお]れないように外[そと]から支[ささ]えます。", "sentence_source": "generated"}, {"text": "古い建物の横に、大きなバットレスが立っています。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]の横[よこ]に、大[おお]きなバットレスが立[た]っています。", "sentence_source": "generated"}, {"text": "先生は、バットレスの形を黒板に描いて説明した。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "先生[せんせい]は、バットレスの形[かたち]を黒板[こくばん]に描[えが]いて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "高い壁には、たいていバットレスが付いている。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "高[たか]い壁[かべ]には、たいていバットレスが付[つ]いている。", "sentence_source": "generated"}, {"text": "バットレスがあるので、この石の壁は強いです。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "バットレスがあるので、この石[いし]の壁[かべ]は強[つよ]いです。", "sentence_source": "generated"}, {"text": "写真に、バットレスのある古い教会が写っている。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "写真[しゃしん]に、バットレスのある古[ふる]い教会[きょうかい]が写[うつ]っている。", "sentence_source": "generated"}, {"text": "バットレスの間を、子どもたちが走って遊んでいた。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "バットレスの間[あいだ]を、子[こ]どもたちが走[はし]って遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "工事の人が、こわれたバットレスを直しています。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、こわれたバットレスを直[なお]しています。", "sentence_source": "generated"}, {"text": "外から見ると、バットレスは壁にくっついた大きな柱のようだ。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "外[そと]から見[み]ると、バットレスは壁[かべ]にくっついた大[おお]きな柱[はしら]のようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バットレス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "建物の壁を外から支える特別な形の柱(バットレス)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51725, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バットレス", "is_correct": true, "explanation": "正解。壁の外に立つ太い柱の名称で、「〜という太い柱」に当てはまる。"}, {"text": "花壇", "is_correct": false, "explanation": "太い柱ではなく、壁の外に立つ支持構造の名前として合わない。"}, {"text": "洗面台", "is_correct": false, "explanation": "壁の外に立つ太い柱ではなく、説明文の内容に合わない。"}, {"text": "信号機", "is_correct": false, "explanation": "道路に立つ柱で、建物の壁を外から支える構造ではない。"}], "explanations": {"バットレス": "正解。壁の外に立つ太い柱の名称で、「〜という太い柱」に当てはまる。", "花壇": "太い柱ではなく、壁の外に立つ支持構造の名前として合わない。", "洗面台": "壁の外に立つ太い柱ではなく、説明文の内容に合わない。", "信号機": "道路に立つ柱で、建物の壁を外から支える構造ではない。"}, "sentence_index": 0, "correct_answer": "バットレス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古い窓は、ガラスを四角く囲むバットレスが木で作られている。", "explanation": "ここは窓枠の意味。ガラスを四角く囲んで留めるのは窓枠で、壁を外から支えるバットレスとは別物。"}, {"text": "工事の現場では、作業員がバットレスを上り下りして外壁を塗っている。", "explanation": "ここは足場の意味。作業員が上り下りして使う仮設の構造は足場で、壁を支えるバットレスとは別物。"}, {"text": "古い建物の軒先には、雨水を流すバットレスが取り付けられている。", "explanation": "ここは雨どいの意味。雨水を流し落とすのは雨どいで、壁を外から支えるバットレスの役割ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51725, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バットレス", "is_correct": true, "explanation": "正解。「バットレスのある古い教会」という、壁を外から支える構造を持つ教会の写真の説明に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫のある古い教会」は写真の説明として不自然で、建築の特徴を表さない。"}, {"text": "体重計", "is_correct": false, "explanation": "教会の建築の特徴を表す語ではなく、写真の説明として合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "教会の写真に写る建築の特徴としては成り立たず、文脈に合わない。"}], "explanations": {"バットレス": "正解。「バットレスのある古い教会」という、壁を外から支える構造を持つ教会の写真の説明に合う。", "冷蔵庫": "「冷蔵庫のある古い教会」は写真の説明として不自然で、建築の特徴を表さない。", "体重計": "教会の建築の特徴を表す語ではなく、写真の説明として合わない。", "洗濯機": "教会の写真に写る建築の特徴としては成り立たず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "バットレス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋根の上に、煙を外へ出すバットレスが突き出ている。", "explanation": "ここは煙突の意味。煙を外へ出すのは煙突で、壁を外から支えるバットレスの役割ではない。"}, {"text": "階段の横に、つかまるためのバットレスを取り付けた。", "explanation": "ここは手すりの意味。人がつかまるための設備で、壁を支えるバットレスとは役割が違う。"}, {"text": "道の横に、夜道を照らすバットレスが立っている。", "explanation": "ここは街灯の意味。夜道を照らすのは街灯で、壁を外から支えるバットレスは照明の役割を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51725, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寺院の壁の外側には、壁を支えるためのバットレスを立っている。", "corrected_sentence": "寺院の壁の外側には、壁を支えるためのバットレスが立っている。", "error_description": "「立つ」は自動詞なので主語に「が」を使う。「バットレスを立っている」は誤りで、正しくは「バットレスが立っている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51725, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "郊外の教会には、今も古いバットレスが残ってている。", "corrected_sentence": "郊外の教会には、今も古いバットレスが残っている。", "error_description": "「残っている」の「ている」が重なった誤り。正しくは「残っている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「並んでいる」の主語であるバットレスに付く「が」。"}, {"text": "を", "is_correct": false, "explanation": "「並ぶ」は自動詞で目的語の「を」は取れないため、ここでは合わない。"}, {"text": "に", "is_correct": false, "explanation": "「バットレスに並んでいる」は到達点や場所を示す文になり、主語のバットレスが並ぶ文として合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞に続くだけで、「並んでいます」の主語にならず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「並んでいる」の主語であるバットレスに付く「が」。", "を": "「並ぶ」は自動詞で目的語の「を」は取れないため、ここでは合わない。", "に": "「バットレスに並んでいる」は到達点や場所を示す文になり、主語のバットレスが並ぶ文として合わない。", "の": "「の」は名詞に続くだけで、「並んでいます」の主語にならず文が成り立たない。"}, "error_tags": {"を": "目的語（並ぶは自動詞）", "に": "到達点・場所", "の": "名詞に続き述語にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「付けられている」の対象であるバットレスに付く「が」。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すため、「バットレスより付けられている」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、付けられる対象のバットレスを起点とする文としては不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「バットレスと付けられている」は受身文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「付けられている」の対象であるバットレスに付く「が」。", "より": "「より」は比較の基準を示すため、「バットレスより付けられている」は文が成り立たない。", "から": "「から」は起点を示すが、付けられる対象のバットレスを起点とする文としては不自然。", "と": "「と」は並列や相手を示すが、「バットレスと付けられている」は受身文として成り立たない。"}, "error_tags": {"より": "比較の基準", "から": "起点", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の壁を外側から支えるために、壁に取り付けられたアーチ状の構造物。", "primary_collocate": null, "pronunciation": "ばっとれす", "ipa": "battoɾesɯ", "syllable_count": 5, "sentences": [{"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "特[とく]に注目[ちゅうもく]すべきは、天井[てんじょう]の重量[じゅうりょう]を分散[ぶんさん]させる「リブ・ヴォールト」と、壁[かべ]の外側[そとがわ]から支[ささ]える「フライング・バットレス」と呼[よ]ばれる技術[ぎじゅつ]です。", "sentence_source": "mined"}, {"text": "ゴシック教会の外壁には、壁を支えるバットレスが並んでいます。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "ゴシック教会[きょうかい]の外壁[がいへき]には、壁[かべ]を支[ささ]えるバットレスが並[なら]んでいます。", "sentence_source": "generated"}, {"text": "バットレスのおかげで、高い壁を作ることができた。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "バットレスのおかげで、高[たか]い壁[かべ]を作[つく]ることができた。", "sentence_source": "generated"}, {"text": "この石造りの塔は、古くなったためバットレスで補強された。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "この石造[いしづく]りの塔[とう]は、古[ふる]くなったためバットレスで補強[ほきょう]された。", "sentence_source": "generated"}, {"text": "大聖堂を訪ねたとき、外壁のバットレスの形に目を奪われた。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "大聖堂[だいせいどう]を訪[たず]ねたとき、外壁[がいへき]のバットレスの形[かたち]に目[め]を奪[うば]われた。", "sentence_source": "generated"}, {"text": "バットレスがなければ、高い壁は外側に倒れてしまうかもしれない。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "バットレスがなければ、高[たか]い壁[かべ]は外側[そとがわ]に倒[たお]れてしまうかもしれない。", "sentence_source": "generated"}, {"text": "建築の授業で、バットレスの役割を図で説明した。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "建築[けんちく]の授業[じゅぎょう]で、バットレスの役割[やくわり]を図[ず]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "古い城の壁にも、崩れないようにバットレスが付けられている。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "古[ふる]い城[しろ]の壁[かべ]にも、崩[くず]れないようにバットレスが付[つ]けられている。", "sentence_source": "generated"}, {"text": "修復工事で、傷んだバットレスの石を新しく積み直した。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "修復工事[しゅうふくこうじ]で、傷[いた]んだバットレスの石[いし]を新[あたら]しく積[つ]み直[なお]した。", "sentence_source": "generated"}, {"text": "壁から突き出たバットレスが、窓と窓の間に影を落としていた。", "target_word": "バットレス", "complexity_tier": "T3", "furigana": "壁[かべ]から突[つ]き出[だ]したバットレスが、窓[まど]と窓[まど]の間[あいだ]に影[かげ]を落[お]としていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バットレス", "label": "基本形"}], "register": "technical", "sense_fingerprint": "建築で壁を外側から支える控え壁・アーチ状の構造物(バットレス)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バットレス", "is_correct": true, "explanation": "正解。「フライング・バットレス」は、壁を外から支える控え壁を指す建築用語。"}, {"text": "ドア", "is_correct": false, "explanation": "「フライング・ドア」という建築用語はなく、天井の重みを壁の外へ分散させる構造を指さない。"}, {"text": "階段", "is_correct": false, "explanation": "「フライング・階段」は建築用語ではなく、壁を外から支える構造に当たらない。"}, {"text": "花瓶", "is_correct": false, "explanation": "「フライング・花瓶」は意味をなさず、壁を支える構造の名称として合わない。"}], "explanations": {"バットレス": "正解。「フライング・バットレス」は、壁を外から支える控え壁を指す建築用語。", "ドア": "「フライング・ドア」という建築用語はなく、天井の重みを壁の外へ分散させる構造を指さない。", "階段": "「フライング・階段」は建築用語ではなく、壁を外から支える構造に当たらない。", "花瓶": "「フライング・花瓶」は意味をなさず、壁を支える構造の名称として合わない。"}, "sentence_index": 0, "correct_answer": "バットレス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い城門の脇には、押して開けるバットレスが付いていて、人が出入りできる。", "explanation": "ここは扉の意味。押して開け閉めし、出入りを仕切るのは扉で、壁を外から支えるバットレスとは別物。"}, {"text": "屋根の重さを支えるため、部屋の真ん中にバットレスを一本立てた。", "explanation": "ここは〈柱〉の意味。バットレスは壁の外側から壁を支える構造で、室内に独立して立てるものではない。"}, {"text": "壁に棚を取り付けるため、バットレスという金具を二つ付けた。", "explanation": "ここは〈金具〉の意味。棚を支える小さな金具で、外壁を支えるアーチ状の構造物とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バットレス", "is_correct": true, "explanation": "正解。壁を外から支える構造で、建築の授業で役割を図で説明する対象になる。"}, {"text": "洗濯機", "is_correct": false, "explanation": "建築の授業で構造の役割を図で説明する対象ではなく、文脈に合わない。"}, {"text": "財布", "is_correct": false, "explanation": "建築の構造物ではないため、役割を図で説明する文脈に合わない。"}, {"text": "信号機", "is_correct": false, "explanation": "建築の授業で壁を支える構造の役割を説明する対象ではない。"}], "explanations": {"バットレス": "正解。壁を外から支える構造で、建築の授業で役割を図で説明する対象になる。", "洗濯機": "建築の授業で構造の役割を図で説明する対象ではなく、文脈に合わない。", "財布": "建築の構造物ではないため、役割を図で説明する文脈に合わない。", "信号機": "建築の授業で壁を支える構造の役割を説明する対象ではない。"}, "sentence_index": 6, "correct_answer": "バットレス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "門の脇に、来客を知らせるバットレスが付いている。", "explanation": "ここは〈呼び鈴〉の意味。来客を知らせる装置で、壁を外から支えるアーチ状の構造物ではない。"}, {"text": "地下室の入り口に、湿気を逃がすバットレスが取り付けられている。", "explanation": "ここは〈換気口〉の意味。湿気を外へ逃がす設備で、壁を外から支える構造物ではない。"}, {"text": "屋根の骨組みを組むため、太いバットレスを横に渡した。", "explanation": "ここは梁の意味。屋根の骨組みに横に渡して支えるのは梁で、外壁を支えるバットレスではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "聖堂の側面には、天井の重みを支えるバットレスを並んでいる。", "corrected_sentence": "聖堂の側面には、天井の重みを支えるバットレスが並んでいる。", "error_description": "「並ぶ」は自動詞なので、主語には「が」を使う。「バットレスを並んでいる」は誤りで、正しくは「バットレスが並んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教会の外壁には、大きなバットレスが等間隔で並べている。", "corrected_sentence": "教会の外壁には、大きなバットレスが等間隔で並んでいる。", "error_description": "「並ぶ」は自動詞。主語はバットレスなので「並んでいる」が正しく、他動詞の「並べている」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「窓から」は光が入ってくる起点を示し、正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、光が差し込む起点には使えないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は、光の起点を示す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は、この文の光の起点を示さないので合わない。"}], "correct_answer": "から", "explanations": {"から": "「窓から」は光が入ってくる起点を示し、正しい。", "を": "目的語の「を」は、光が差し込む起点には使えないので合わない。", "で": "手段や場所の「で」は、光の起点を示す文には合わない。", "と": "並列の「と」は、この文の光の起点を示さないので合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「窓を開ける」の目的語を示す「を」で、正しく入る。"}, {"text": "が", "is_correct": false, "explanation": "「窓が開けたまま」は文法が合わず、開ける対象には「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、開ける対象には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、この文の構造に合わない。"}], "correct_answer": "を", "explanations": {"を": "「窓を開ける」の目的語を示す「を」で、正しく入る。", "が": "「窓が開けたまま」は文法が合わず、開ける対象には「を」が必要。", "へ": "方向を示す「へ」は、開ける対象には合わない。", "より": "比較の「より」は、この文の構造に合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "壁や建物にあいていて、外の光や風が入ってくる場所のことです。", "primary_collocate": null, "pronunciation": "まど", "ipa": "mado", "syllable_count": 2, "sentences": [{"text": "窓を開けると、気持ちのいい風が入ってきました。", "target_word": "窓", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、気持[きも]ちのいい風[かぜ]が入[はい]ってきました。", "sentence_source": "generated"}, {"text": "朝、窓から明るい光が差し込んでいます。", "target_word": "窓", "complexity_tier": "T3", "furigana": "朝[あさ]、窓[まど]から明[あか]るい光[ひかり]が差[さ]し込[こ]んでいます。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、窓を閉めました。", "target_word": "窓", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、窓[まど]を閉[し]めました。", "sentence_source": "generated"}, {"text": "私の部屋の窓は、大きくて庭がよく見えます。", "target_word": "窓", "complexity_tier": "T3", "furigana": "私[わたし]の部屋[へや]の窓[まど]は、大[おお]きくて庭[にわ]がよく見[み]えます。", "sentence_source": "generated"}, {"text": "電車の窓から、きれいな海が見えました。", "target_word": "窓", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の窓[まど]から、きれいな海[うみ]が見[み]えました。", "sentence_source": "generated"}, {"text": "寒い日は、窓に水滴がつきます。", "target_word": "窓", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、窓[まど]に水滴[すいてき]がつきます。", "sentence_source": "generated"}, {"text": "窓のそばに座ると、外の景色を楽しめます。", "target_word": "窓", "complexity_tier": "T3", "furigana": "窓[まど]のそばに座[すわ]ると、外[そと]の景色[けしき]を楽[たの]しめます。", "sentence_source": "generated"}, {"text": "夏は暑いので、窓を開けたまま寝ます。", "target_word": "窓", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、窓[まど]を開[あ]けたまま寝[ね]ます。", "sentence_source": "generated"}, {"text": "風が強くて、窓がガタガタ鳴っています。", "target_word": "窓", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]くて、窓[まど]がガタガタ鳴[な]っています。", "sentence_source": "generated"}, {"text": "掃除のとき、窓をきれいにふきました。", "target_word": "窓", "complexity_tier": "T3", "furigana": "掃除[そうじ]のとき、窓[まど]をきれいにふきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "窓", "label": "基本形"}], "register": "polite", "sense_fingerprint": "壁や建物にあいた、光や風が入る開口部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窓", "is_correct": true, "explanation": "壁にあいていて開けられるもので、「窓を開けると」に合う。"}, {"text": "雨", "is_correct": false, "explanation": "降るもので、開けるものではないので合わない。"}, {"text": "空", "is_correct": false, "explanation": "見上げるもので、開けるものではないので合わない。"}, {"text": "雲", "is_correct": false, "explanation": "空に浮かぶもので、開けるものではないので合わない。"}], "explanations": {"窓": "壁にあいていて開けられるもので、「窓を開けると」に合う。", "雨": "降るもので、開けるものではないので合わない。", "空": "見上げるもので、開けるものではないので合わない。", "雲": "空に浮かぶもので、開けるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "窓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓に出て、夜空を眺めました。", "explanation": "〈ベランダ〉（屋外に張り出した床）と混同。窓は人が出て立つ場所ではないので合わない。"}, {"text": "窓を椅子にして、本を読みました。", "explanation": "〈椅子〉（座る家具）と混同。窓は座る家具ではないので合わない。"}, {"text": "窓に筆を入れて、手紙を書きました。", "explanation": "〈ペン〉（筆記具）と混同。窓は筆記具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窓", "is_correct": true, "explanation": "外の景色が見える壁の開口部で、「窓のそばに座る」に合う。"}, {"text": "霧", "is_correct": false, "explanation": "大気中の水滴で、そばに座る対象ではないので合わない。"}, {"text": "音", "is_correct": false, "explanation": "聞こえるもので、そばに座る対象ではないので合わない。"}, {"text": "香り", "is_correct": false, "explanation": "においのことで、そばに座る対象ではないので合わない。"}], "explanations": {"窓": "外の景色が見える壁の開口部で、「窓のそばに座る」に合う。", "霧": "大気中の水滴で、そばに座る対象ではないので合わない。", "音": "聞こえるもので、そばに座る対象ではないので合わない。", "香り": "においのことで、そばに座る対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "窓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓のコップに水を入れました。", "explanation": "〈ガラス〉（材料や器）と混同。窓はコップにならないので合わない。"}, {"text": "窓に鍵を入れて出かけました。", "explanation": "〈ポケット〉（衣服の袋）と混同。窓は鍵を入れる場所ではないので合わない。"}, {"text": "窓の引き出しに、手紙をしまいました。", "explanation": "〈たんす〉などの収納家具と混同。窓は開口部なので、物をしまう家具ではなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒いので、窓が閉めました。", "corrected_sentence": "寒いので、窓を閉めました。", "error_description": "「閉める」は他動詞なので、窓の後は「を」が正しい。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51727, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓をそばに、小さなテーブルを置きました。", "corrected_sentence": "窓のそばに、小さなテーブルを置きました。", "error_description": "「窓のそば」の「の」が「を」になっている。「そば」の前は「の」が正しく、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
