INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51729, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを作ったり、置いたりして、使えるようにすること。", "primary_collocate": null, "pronunciation": "もうける", "ipa": "moɯkeɾɯ", "syllable_count": 4, "sentences": [{"text": "市は海水浴場に、無料で使えるシャワー室を設けました。", "target_word": "設けました", "complexity_tier": "T3", "furigana": "市[し]は海水浴場[かいすいよくじょう]に、無料[むりょう]で使[つか]えるシャワー室[しつ]を設[もう]けました。", "sentence_source": "generated"}, {"text": "この旅館では、客がくつろげるように庭に足湯を設けています。", "target_word": "設けています", "complexity_tier": "T3", "furigana": "この旅館[りょかん]では、客[きゃく]がくつろげるように庭[にわ]に足湯[あしゆ]を設[もう]けています。", "sentence_source": "generated"}, {"text": "工場の入り口に手を洗う場所を設けた。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "工場[こうじょう]の入[い]り口[ぐち]に手[て]を洗[あら]う場所[ばしょ]を設[もう]けた。", "sentence_source": "generated"}, {"text": "空港は外国からの旅行者のために、案内カウンターを設けた。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "空港[くうこう]は外国[がいこく]からの旅行者[りょこうしゃ]のために、案内[あんない]カウンターを設[もう]けた。", "sentence_source": "generated"}, {"text": "会議室の隅にコーヒーを飲めるコーナーを設けておいた。", "target_word": "設けておいた", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]の隅[すみ]にコーヒーを飲[の]めるコーナーを設[もう]けておいた。", "sentence_source": "generated"}, {"text": "山道の途中に、休めるベンチを設けてある。", "target_word": "設けてある", "complexity_tier": "T3", "furigana": "山道[やまみち]の途中[とちゅう]に、休[やす]めるベンチを設[もう]けてある。", "sentence_source": "generated"}, {"text": "新しい校舎には、屋上に菜園が設けられた。", "target_word": "設けられた", "complexity_tier": "T3", "furigana": "新[あたら]しい校舎[こうしゃ]には、屋上[おくじょう]に菜園[さいえん]が設[もう]けられた。", "sentence_source": "generated"}, {"text": "スーパーは入り口の近くに、お年寄り用の駐車場を設けた。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "スーパーは入[い]り口[ぐち]の近[ちか]くに、お年寄[としよ]り用[よう]の駐車場[ちゅうしゃじょう]を設[もう]けた。", "sentence_source": "generated"}, {"text": "病院は待合室に、子どもが遊べる場所を設けました。", "target_word": "設けました", "complexity_tier": "T3", "furigana": "病院[びょういん]は待合室[まちあいしつ]に、子[こ]どもが遊[あそ]べる場所[ばしょ]を設[もう]けました。", "sentence_source": "generated"}, {"text": "大会の会場には、選手が準備できる控え室が設けられている。", "target_word": "設けられている", "complexity_tier": "T3", "furigana": "大会[たいかい]の会場[かいじょう]には、選手[せんしゅ]が準備[じゅんび]できる控[ひか]え室[しつ]が設[もう]けられている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設ける", "label": "終止形"}, {"form": "設けない", "label": "否定形"}, {"form": "設けます", "label": "丁寧形"}, {"form": "設けて", "label": "て形"}, {"form": "設けた", "label": "過去形"}, {"form": "設ければ", "label": "仮定形"}, {"form": "設けられる", "label": "受身形"}, {"form": "設けよう", "label": "意向形"}], "register": "標準的な書き言葉", "sense_fingerprint": "人が使えるように施設・コーナー・設備を作って備える意味の他動詞（儲ける・利益を得る意味ではない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51729, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設けました", "is_correct": true, "explanation": "正解。「シャワー室を設けました」の丁寧な過去形で、設備を新しく作る文に合う。"}, {"text": "歌いました", "is_correct": false, "explanation": "「シャワー室を歌いました」は意味をなさず、文が成り立たない。"}, {"text": "笑いました", "is_correct": false, "explanation": "「シャワー室を笑いました」は文が成り立たず、文脈に合わない。"}, {"text": "走りました", "is_correct": false, "explanation": "「シャワー室を走りました」は文が成り立たず、設備を作る文脈に合わない。"}], "explanations": {"設けました": "正解。「シャワー室を設けました」の丁寧な過去形で、設備を新しく作る文に合う。", "歌いました": "「シャワー室を歌いました」は意味をなさず、文が成り立たない。", "笑いました": "「シャワー室を笑いました」は文が成り立たず、文脈に合わない。", "走りました": "「シャワー室を走りました」は文が成り立たず、設備を作る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "設けました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は友人の話に、疑いを設けた。", "explanation": "ここは〈抱く〉の意味。設けるは何かを作って使えるようにする意味で、気持ちを心に持つ文には使わない。"}, {"text": "玄関に季節の花を設けた。", "explanation": "ここは〈飾る〉の意味。設けるは施設や設備を新しく備える意味で、花を飾る文には使わない。"}, {"text": "来場者に無料の資料を設けた。", "explanation": "ここは〈配る〉の意味。設けるは場所や設備を備える意味で、資料を配る文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51729, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設けられた", "is_correct": true, "explanation": "正解。屋上に菜園が設けられた、受身の過去形で、設備が作られた文に合う。"}, {"text": "泣いた", "is_correct": false, "explanation": "「菜園が泣いた」は文が成り立たず、設備を作る文脈に合わない。"}, {"text": "踊った", "is_correct": false, "explanation": "「菜園が踊った」は文が成り立たず、文脈に合わない。"}, {"text": "眠った", "is_correct": false, "explanation": "「菜園が眠った」は文が成り立たず、設備を作る文脈に合わない。"}], "explanations": {"設けられた": "正解。屋上に菜園が設けられた、受身の過去形で、設備が作られた文に合う。", "泣いた": "「菜園が泣いた」は文が成り立たず、設備を作る文脈に合わない。", "踊った": "「菜園が踊った」は文が成り立たず、文脈に合わない。", "眠った": "「菜園が眠った」は文が成り立たず、設備を作る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "設けられた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その商人は、仕入れ値に大きな利益を設けた。", "explanation": "ここは〈儲ける〉の意味。利益を得る意味で、施設を備える意味とは別物。"}, {"text": "その映画は、観客に感動を設けた。", "explanation": "ここは〈生む〉の意味。設けるは何かを作って使えるようにする意味で、感動を呼び起こす文には使わない。"}, {"text": "壁に大きな絵を設けた。", "explanation": "ここは〈掛ける〉の意味。設けるは場所や設備を備える意味で、絵を壁に掛ける文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51729, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は駅の西口に、自転車を停める場所が設けた。", "corrected_sentence": "町は駅の西口に、自転車を停める場所を設けた。", "error_description": "「設ける」は他動詞で、作る対象は「を」で示す。「場所が設けた」は「が」が誤りで、正しくは「場所を設けた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "設けています", "is_correct": true, "explanation": "正解。庭に足湯を設けている状態を丁寧に述べる形。"}, {"text": "設けていた", "is_correct": false, "explanation": "過去の継続を表し、現在の状態を述べる文と時制が合わない。"}, {"text": "設けていない", "is_correct": false, "explanation": "否定形で、足湯を設けていないことになり、文の事実と反する。"}, {"text": "設けさせている", "is_correct": false, "explanation": "使役の形で、誰かに作らせている意味になり文が変わる。"}], "correct_form": "設けています", "base_form": "設ける", "form_label": "丁寧な継続形（ています）", "sentence_index": 1, "explanations": {"設けています": "正解。庭に足湯を設けている状態を丁寧に述べる形。", "設けていた": "過去の継続を表し、現在の状態を述べる文と時制が合わない。", "設けていない": "否定形で、足湯を設けていないことになり、文の事実と反する。", "設けさせている": "使役の形で、誰かに作らせている意味になり文が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51729, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民センターには、子どもが遊べる小さな図書コーナーが設けている。", "corrected_sentence": "市民センターには、子どもが遊べる小さな図書コーナーが設けられている。", "error_description": "「設ける」は、物が主語の場合は受身の「設けられている」が自然。「設けている」は主語の図書コーナーと合わない能動形で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "設けた", "is_correct": true, "explanation": "正解。駐車場を作った過去の事実を述べる形。"}, {"text": "設けない", "is_correct": false, "explanation": "否定形で、駐車場を作った事実を述べる文とは合わない。"}, {"text": "設けたら", "is_correct": false, "explanation": "条件を表す形になり、文が途中で終わって事実を述べる文にならない。"}, {"text": "設けられる", "is_correct": false, "explanation": "受身の可能や予定を表す形で、「駐車場を」の目的語と合わない。"}], "correct_form": "設けた", "base_form": "設ける", "form_label": "過去形（た形）", "sentence_index": 7, "explanations": {"設けた": "正解。駐車場を作った過去の事実を述べる形。", "設けない": "否定形で、駐車場を作った事実を述べる文とは合わない。", "設けたら": "条件を表す形になり、文が途中で終わって事実を述べる文にならない。", "設けられる": "受身の可能や予定を表す形で、「駐車場を」の目的語と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
