INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51730, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "必要なものや設備を用意して、そこに置いたり作ったりすること。", "primary_collocate": null, "pronunciation": "もうける", "ipa": "moɯkeɾɯ", "syllable_count": 4, "sentences": [{"text": "壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "設ける", "complexity_tier": "T3", "furigana": "壁[かべ]を薄[うす]くして大[おお]きな窓[まど]を設[もう]けることが可能[かのう]となり、内部[ないぶ]は光[ひかり]に満[み]ちあふれました。", "sentence_source": "generated"}, {"text": "駅前に自転車を止める場所を設けた。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に自転車[じてんしゃ]を止[と]める場所[ばしょ]を設[もう]けた。", "sentence_source": "generated"}, {"text": "学校は校庭の隅に小さな花壇を設けました。", "target_word": "設けました", "complexity_tier": "T3", "furigana": "学校[がっこう]は校庭[こうてい]の隅[すみ]に小[ちい]さな花壇[かだん]を設[もう]けました。", "sentence_source": "generated"}, {"text": "この図書館は、子どもが静かに本を読める部屋を設けている。", "target_word": "設けている", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は、子[こ]どもが静[しず]かに本[ほん]を読[よ]める部屋[へや]を設[もう]けている。", "sentence_source": "generated"}, {"text": "会社は社員のために、休憩できるスペースを設けた。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]のために、休憩[きゅうけい]できるスペースを設[もう]けた。", "sentence_source": "generated"}, {"text": "川の近くに避難所を設けておけば、大雨のときも安心です。", "target_word": "設けておけば", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くに避難所[ひなんじょ]を設[もう]けておけば、大雨[おおあめ]のときも安心[あんしん]です。", "sentence_source": "generated"}, {"text": "店の入り口に傘を置く場所を設けたので、床がぬれなくなった。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "店[みせ]の入[い]り口[ぐち]に傘[かさ]を置[お]く場所[ばしょ]を設[もう]けたので、床[ゆか]がぬれなくなった。", "sentence_source": "generated"}, {"text": "彼は家の北側に、仕事用の小さな書斎を設けた。", "target_word": "設けた", "complexity_tier": "T3", "furigana": "彼[かれ]は家[いえ]の北側[きたがわ]に、仕事用[しごとよう]の小[ちい]さな書斎[しょさい]を設[もう]けた。", "sentence_source": "generated"}, {"text": "駅には車いすの人のために、広い改札口が設けられている。", "target_word": "設けられている", "complexity_tier": "T3", "furigana": "駅[えき]には車[くるま]いすの人[ひと]のために、広[ひろ]い改札口[かいさつぐち]が設[もう]けられている。", "sentence_source": "generated"}, {"text": "工事の間、現場の横に仮の事務所を設けることになった。", "target_word": "設ける", "complexity_tier": "T3", "furigana": "工事[こうじ]の間[あいだ]、現場[げんば]の横[よこ]に仮[かり]の事務所[じむしょ]を設[もう]けることになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設ける", "label": "終止形"}, {"form": "設けない", "label": "否定形"}, {"form": "設けます", "label": "丁寧形"}, {"form": "設けて", "label": "て形"}, {"form": "設けた", "label": "過去形"}, {"form": "設ければ", "label": "仮定形"}, {"form": "設けられる", "label": "受身形"}, {"form": "設けよう", "label": "意向形"}], "register": "標準的な書き言葉", "sense_fingerprint": "場所・設備・窓などを新しく作って備える意味の他動詞（儲ける・利益を得る意味ではない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51730, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設ける", "is_correct": true, "explanation": "正解。場所や設備を新しく作って備える意味で、「大きな窓を設けること」に合う。"}, {"text": "撤去する", "is_correct": false, "explanation": "既存のものを取り去る意味で、新しく作る文脈と逆になる。"}, {"text": "塞ぐ", "is_correct": false, "explanation": "穴や入口をふさぐ意味で、新しく窓を作る文には合わない。"}, {"text": "解体する", "is_correct": false, "explanation": "建物などを壊す意味で、窓を作る文脈と逆になる。"}], "explanations": {"設ける": "正解。場所や設備を新しく作って備える意味で、「大きな窓を設けること」に合う。", "撤去する": "既存のものを取り去る意味で、新しく作る文脈と逆になる。", "塞ぐ": "穴や入口をふさぐ意味で、新しく窓を作る文には合わない。", "解体する": "建物などを壊す意味で、窓を作る文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "設ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は新しい部長に、山田さんを設けた。", "explanation": "ここは〈任命する〉の意味。設けるは役職や場所を新しく置く意味で、人を役職に任じる文には使わない。"}, {"text": "彼の言葉は、皆に大きな喜びを設けた。", "explanation": "ここは〈生む〉の意味。設けるは場所や設備を備える意味で、感情を生み出す文には使わない。"}, {"text": "彼は毎晩、寝る前に日記を設けた。", "explanation": "ここは〈書く〉の意味。設けるは場所や設備を備える意味で、文章を書き記す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51730, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設けた", "is_correct": true, "explanation": "正解。店の入り口に場所を新しく作った過去の文に合う。"}, {"text": "眺めた", "is_correct": false, "explanation": "見つめる意味で、場所を作る文脈には合わない。"}, {"text": "歌った", "is_correct": false, "explanation": "場所を作る文には合わず、歌うという行為は文脈に合わない。"}, {"text": "笑った", "is_correct": false, "explanation": "場所を作る文には合わず、笑うという行為は文脈に合わない。"}], "explanations": {"設けた": "正解。店の入り口に場所を新しく作った過去の文に合う。", "眺めた": "見つめる意味で、場所を作る文脈には合わない。", "歌った": "場所を作る文には合わず、歌うという行為は文脈に合わない。", "笑った": "場所を作る文には合わず、笑うという行為は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "設けた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は夕食のあと、台所で眠気を設けた。", "explanation": "ここは〈感じる〉の意味。設けるは場所や設備を備える意味で、眠気を覚える文には使わない。"}, {"text": "庭の隅で、ため息を設けた。", "explanation": "ここは〈吐く〉の意味。設けるは場所や設備を備える意味で、息を外へ出す動作には使わない。"}, {"text": "司会者は会場の入り口で、大声を設けた。", "explanation": "ここは〈叫ぶ〉の意味。設けるは場所や設備を備える意味で、大声を張り上げる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51730, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市役所は一階の受付の横に、相談用の小部屋を設けだ。", "corrected_sentence": "市役所は一階の受付の横に、相談用の小部屋を設けた。", "error_description": "過去の「た」を濁らせた誤り。「設けだ」は活用の形として誤りで、正しくは「設けた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "設けた", "is_correct": true, "explanation": "正解。文末の過去の形で、場所を作った事実を述べる。"}, {"text": "設けない", "is_correct": false, "explanation": "否定形で、場所を作った事実を述べる文とは合わない。"}, {"text": "設けよう", "is_correct": false, "explanation": "意向形で、既に行った行為を述べる文に合わない。"}, {"text": "設けられた", "is_correct": false, "explanation": "受身形になり、「場所を」の目的語と合わず文の形が変わる。"}], "correct_form": "設けた", "base_form": "設ける", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"設けた": "正解。文末の過去の形で、場所を作った事実を述べる。", "設けない": "否定形で、場所を作った事実を述べる文とは合わない。", "設けよう": "意向形で、既に行った行為を述べる文に合わない。", "設けられた": "受身形になり、「場所を」の目的語と合わず文の形が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は校舎の裏に、生徒が使える自転車置き場に設けた。", "corrected_sentence": "学校は校舎の裏に、生徒が使える自転車置き場を設けた。", "error_description": "「設ける」の目的語は「を」で示す。「自転車置き場に設けた」では「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "設けた", "is_correct": true, "explanation": "正解。書斎を作った過去の事実を述べる形。"}, {"text": "設けます", "is_correct": false, "explanation": "丁寧形で、普通体の過去の文とは文体が合わない。"}, {"text": "設ければ", "is_correct": false, "explanation": "仮定形で、事実を述べる文が条件の文になり合わない。"}, {"text": "設けさせた", "is_correct": false, "explanation": "使役の形で、自分が作った事実ではなく他者にさせた意味になる。"}], "correct_form": "設けた", "base_form": "設ける", "form_label": "過去形（た形）", "sentence_index": 7, "explanations": {"設けた": "正解。書斎を作った過去の事実を述べる形。", "設けます": "丁寧形で、普通体の過去の文とは文体が合わない。", "設ければ": "仮定形で、事実を述べる文が条件の文になり合わない。", "設けさせた": "使役の形で、自分が作った事実ではなく他者にさせた意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「散歩する人々で」の「で」。人々が多く集まって場所を満たす原因・手段を表す。"}, {"text": "を", "is_correct": false, "explanation": "「人々を満ち溢れていた」は自動詞「満ち溢れる」に目的語の「を」が付くので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、場所を満たす意味の文脈に合わず、「人々へ満ち溢れていた」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」は「人々と満ち溢れていた」となり、人々が満ちる原因を表せない。"}], "correct_answer": "で", "explanations": {"で": "「散歩する人々で」の「で」。人々が多く集まって場所を満たす原因・手段を表す。", "を": "「人々を満ち溢れていた」は自動詞「満ち溢れる」に目的語の「を」が付くので不自然。", "へ": "方向の「へ」は、場所を満たす意味の文脈に合わず、「人々へ満ち溢れていた」は成り立たない。", "と": "共同の「と」は「人々と満ち溢れていた」となり、人々が満ちる原因を表せない。"}, "error_tags": {"を": "自動詞に目的語", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「観光客で」の「で」。観光客が多く集まって店を満たす原因を表す。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「観光客から満ち溢れる」となり、満ちる原因を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「観光客より満ち溢れる」となり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は「観光客の満ち溢れる」となり、述語として文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「観光客で」の「で」。観光客が多く集まって店を満たす原因を表す。", "から": "起点の「から」は「観光客から満ち溢れる」となり、満ちる原因を表せない。", "より": "比較の「より」は「観光客より満ち溢れる」となり、文が成り立たない。", "の": "連体の「の」は「観光客の満ち溢れる」となり、述語として文が成り立たない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いっぱいになる。", "primary_collocate": null, "pronunciation": "みちあふれる", "ipa": "mit͡ɕiaɸɯɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "雨で川の水が満ち溢れ、道まで流れてきた。", "target_word": "満ち溢れ", "complexity_tier": "T3", "furigana": "雨(あめ)で川(かわ)の水(みず)が満(み)ち溢(あふ)れ、道(みち)まで流(なが)れてきた。", "sentence_source": "generated"}, {"text": "朝の公園は、散歩する人々で満ち溢れていた。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "朝(あさ)の公園(こうえん)は、散歩(さんぽ)する人々(ひとびと)で満(み)ち溢(あふ)れていた。", "sentence_source": "generated"}, {"text": "春になると、野原は花で満ち溢れる。", "target_word": "満ち溢れる", "complexity_tier": "T3", "furigana": "春(はる)になると、野原(のはら)は花(はな)で満(み)ち溢(あふ)れる。", "sentence_source": "generated"}, {"text": "満ち溢れた水が、ダムの外へ流れ出した。", "target_word": "満ち溢れた", "complexity_tier": "T3", "furigana": "満(み)ち溢(あふ)れた水(みず)が、ダムの外(そと)へ流(なが)れ出(だ)した。", "sentence_source": "generated"}, {"text": "駅前の広場は、祭りに来た人で満ち溢れている。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "駅前(えきまえ)の広場(ひろば)は、祭(まつ)りに来(き)た人(ひと)で満(み)ち溢(あふ)れている。", "sentence_source": "generated"}, {"text": "池に満ち溢れる水を、ポンプでくみ出した。", "target_word": "満ち溢れる", "complexity_tier": "T3", "furigana": "池(いけ)に満(み)ち溢(あふ)れる水(みず)を、ポンプでくみ出(だ)した。", "sentence_source": "generated"}, {"text": "部屋じゅうにごみが満ち溢れていて、足の置き場がない。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "部屋(へや)じゅうにごみが満(み)ち溢(あふ)れていて、足(あし)の置(お)き場(ば)がない。", "sentence_source": "generated"}, {"text": "海辺の店は夏になると観光客で満ち溢れる。", "target_word": "満ち溢れる", "complexity_tier": "T3", "furigana": "海辺(うみべ)の店(みせ)は夏(なつ)になると観光客(かんこうきゃく)で満(み)ち溢(あふ)れる。", "sentence_source": "generated"}, {"text": "お風呂のお湯が満ち溢れる前に、水を止めた。", "target_word": "満ち溢れる", "complexity_tier": "T3", "furigana": "お風呂(ふろ)のお湯(ゆ)が満(み)ち溢(あふ)れる前(まえ)に、水(みず)を止(と)めた。", "sentence_source": "generated"}, {"text": "倉庫は荷物で満ち溢れ、新しい物が入らない。", "target_word": "満ち溢れ", "complexity_tier": "T3", "furigana": "倉庫(そうこ)は荷物(にもつ)で満(み)ち溢(あふ)れ、新(あたら)しい物(もの)が入(はい)らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "満ち溢れる", "label": "辞書形"}, {"form": "満ち溢れない", "label": "否定形"}, {"form": "満ち溢れ", "label": "連用形"}, {"form": "満ち溢れた", "label": "過去形"}, {"form": "満ち溢れて", "label": "て形"}, {"form": "満ち溢れれば", "label": "仮定形"}], "register": "標準語", "sense_fingerprint": "場所や入れ物が水や人や物でいっぱいになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "満ち溢れ", "is_correct": true, "explanation": "「雨で川の水が〜、道まで流れてきた」と続く連用形。川の水が岸からあふれる文脈に合う。"}, {"text": "沈み", "is_correct": false, "explanation": "「沈む」は水面の下へ下がる意味で、川の水が道まで流れてくる場面とは合わない。"}, {"text": "凍り", "is_correct": false, "explanation": "「凍る」は水が固まる意味で、雨で水が流れ出す文脈と逆になる。"}, {"text": "澄み", "is_correct": false, "explanation": "「澄む」は水が透き通る意味で、水が道まであふれる量の多さを表さない。"}], "explanations": {"満ち溢れ": "「雨で川の水が〜、道まで流れてきた」と続く連用形。川の水が岸からあふれる文脈に合う。", "沈み": "「沈む」は水面の下へ下がる意味で、川の水が道まで流れてくる場面とは合わない。", "凍り": "「凍る」は水が固まる意味で、雨で水が流れ出す文脈と逆になる。", "澄み": "「澄む」は水が透き通る意味で、水が道まであふれる量の多さを表さない。"}, "sentence_index": 0, "correct_answer": "満ち溢れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は今の生活に満ち溢れている。", "explanation": "ここは「満ち足りる」の意味。満ち溢れるは物や人が場所いっぱいにあふれる意味で、生活への満足には使わない。"}, {"text": "月が満ち溢れて、もうすぐ出産の時期になった。", "explanation": "ここは「満ちる」の意味（月が満ちる＝臨月になる）。満ち溢れるは中身があふれる状態を言うので、この言い方はしない。"}, {"text": "契約の期限が満ち溢れて、更新することになった。", "explanation": "ここは「満期（期限が来る）」の意味。満ち溢れるは物や人が空間いっぱいになる意味で、期限の到来には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "満ち溢れて", "is_correct": true, "explanation": "「部屋じゅうにごみが〜いて」の形。ごみが部屋いっぱいに広がる状態を表す。"}, {"text": "眠って", "is_correct": false, "explanation": "「眠る」はごみの状態に使えず、「ごみが眠っていて」は意味が通らない。"}, {"text": "踊って", "is_correct": false, "explanation": "「踊る」は人や生き物の動作で、ごみには合わない。"}, {"text": "叫んで", "is_correct": false, "explanation": "「叫ぶ」は声を出す動作で、ごみの様子を表す文には合わない。"}], "explanations": {"満ち溢れて": "「部屋じゅうにごみが〜いて」の形。ごみが部屋いっぱいに広がる状態を表す。", "眠って": "「眠る」はごみの状態に使えず、「ごみが眠っていて」は意味が通らない。", "踊って": "「踊る」は人や生き物の動作で、ごみには合わない。", "叫んで": "「叫ぶ」は声を出す動作で、ごみの様子を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "満ち溢れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空っぽの箱に、お菓子が満ち溢れていた。", "explanation": "ここは「空（からっぽ）」の意味。満ち溢れるは十分すぎるほど中身がある状態なので、空の箱には使えない。"}, {"text": "月日が満ち溢れて、もう一年が過ぎた。", "explanation": "ここは「経過する」の意味。満ち溢れるは空間に物が十分ある状態で、時間の流れには使わない。"}, {"text": "水が満ち溢れて、少しずつ減っていった。", "explanation": "ここは「減る」の意味。満ち溢れるは量が十分にある状態で、少しずつ減っていく様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨で川の水を満ち溢れ、橋が通れなくなった。", "corrected_sentence": "大雨で川の水が満ち溢れ、橋が通れなくなった。", "error_description": "誤：「を」。正：「が」。満ち溢れるは自動詞なので目的語の「を」は取れず、主語の「が」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "満ち溢れて", "is_correct": true, "explanation": "「満ち溢れていた」の「て形」。「朝の公園は〜」の文で状態が続いていることを表す。"}, {"text": "満ち溢れた", "is_correct": false, "explanation": "過去形。「満ち溢れたいた」となり、「ていた」の形に続かない。"}, {"text": "満ち溢れない", "is_correct": false, "explanation": "否定形。公園が人で満ちていた事実と逆の意味になる。"}, {"text": "満ち溢れれば", "is_correct": false, "explanation": "仮定形。「〜ていた」の過去の状態を述べる文に、仮定の条件は合わない。"}], "correct_form": "満ち溢れて", "base_form": "満ち溢れる", "form_label": "て形", "sentence_index": 1, "explanations": {"満ち溢れて": "「満ち溢れていた」の「て形」。「朝の公園は〜」の文で状態が続いていることを表す。", "満ち溢れた": "過去形。「満ち溢れたいた」となり、「ていた」の形に続かない。", "満ち溢れない": "否定形。公園が人で満ちていた事実と逆の意味になる。", "満ち溢れれば": "仮定形。「〜ていた」の過去の状態を述べる文に、仮定の条件は合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51731, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "倉庫の奥まで荷物を満ち溢れて、通路を通れない。", "corrected_sentence": "倉庫の奥まで荷物が満ち溢れて、通路を通れない。", "error_description": "誤：「を」。正：「が」。満ち溢れるは自動詞なので「を」は付かず、荷物が主語として「が」で続く。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "満ち溢れる", "is_correct": true, "explanation": "辞書形。「夏になると〜満ち溢れる」の、繰り返し起こる状態を表す形。"}, {"text": "満ち溢れ", "is_correct": false, "explanation": "連用形で、文を終える形として使えない。"}, {"text": "満ち溢れて", "is_correct": false, "explanation": "て形は後ろに別の動詞や文が続く形で、ここでは文末の辞書形が必要。"}, {"text": "満ち溢れさせる", "is_correct": false, "explanation": "使役の形で目的語を取るため、「店は観光客で満ち溢れさせる」は目的語の「を」がなく文が成り立たない。"}], "correct_form": "満ち溢れる", "base_form": "満ち溢れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"満ち溢れる": "辞書形。「夏になると〜満ち溢れる」の、繰り返し起こる状態を表す形。", "満ち溢れ": "連用形で、文を終える形として使えない。", "満ち溢れて": "て形は後ろに別の動詞や文が続く形で、ここでは文末の辞書形が必要。", "満ち溢れさせる": "使役の形で目的語を取るため、「店は観光客で満ち溢れさせる」は目的語の「を」がなく文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「活気に」の「に」。活気が町に満ちている状態の対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「活気を満ち溢れている」は自動詞に目的語の「を」が付くので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「活気へ満ち溢れている」となり、状態を表せない。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」は「活気と満ち溢れている」となり、満ちている対象を表せない。"}], "correct_answer": "に", "explanations": {"に": "「活気に」の「に」。活気が町に満ちている状態の対象を表す。", "を": "「活気を満ち溢れている」は自動詞に目的語の「を」が付くので不自然。", "へ": "方向の「へ」は「活気へ満ち溢れている」となり、状態を表せない。", "と": "共同の「と」は「活気と満ち溢れている」となり、満ちている対象を表せない。"}, "error_tags": {"を": "自動詞に目的語", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「香りが」の「が」。カレーの香りが満ちる主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "「香りを満ち溢れている」は自動詞に目的語の「を」が付くので不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「香りから満ち溢れている」となり、満ちている主語になれない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「香りより満ち溢れている」となり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「香りが」の「が」。カレーの香りが満ちる主語を表す。", "を": "「香りを満ち溢れている」は自動詞に目的語の「を」が付くので不自然。", "から": "起点の「から」は「香りから満ち溢れている」となり、満ちている主語になれない。", "より": "比較の「より」は「香りより満ち溢れている」となり、文が成り立たない。"}, "error_tags": {"を": "自動詞に目的語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物や感情が、全体にわたって十分に広がっている状態になること。", "primary_collocate": null, "pronunciation": "みちあふれる", "ipa": "mit͡ɕiaɸɯɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "彼女の顔は、喜びに満ち溢れていた。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の顔(かお)は、喜(よろこ)びに満(み)ち溢(あふ)れていた。", "sentence_source": "generated"}, {"text": "この町は、活気に満ち溢れている。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "この町(まち)は、活気(かっき)に満(み)ち溢(あふ)れている。", "sentence_source": "generated"}, {"text": "彼の話には、自信が満ち溢れていた。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)には、自信(じしん)が満(み)ち溢(あふ)れていた。", "sentence_source": "generated"}, {"text": "教室は、子どもたちの笑い声で満ち溢れている。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "教室(きょうしつ)は、子(こ)どもたちの笑(わら)い声(ごえ)で満(み)ち溢(あふ)れている。", "sentence_source": "generated"}, {"text": "愛情に満ち溢れた家庭で育った。", "target_word": "満ち溢れた", "complexity_tier": "T3", "furigana": "愛情(あいじょう)に満(み)ち溢(あふ)れた家庭(かてい)で育(そだ)った。", "sentence_source": "generated"}, {"text": "手紙には、感謝の気持ちが満ち溢れていた。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "手紙(てがみ)には、感謝(かんしゃ)の気持(きも)ちが満(み)ち溢(あふ)れていた。", "sentence_source": "generated"}, {"text": "新しい学校は、希望に満ち溢れた場所だった。", "target_word": "満ち溢れた", "complexity_tier": "T3", "furigana": "新(あたら)しい学校(がっこう)は、希望(きぼう)に満(み)ち溢(あふ)れた場所(ばしょ)だった。", "sentence_source": "generated"}, {"text": "台所には、カレーの香りが満ち溢れている。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "台所(だいどころ)には、カレーの香(かお)りが満(み)ち溢(あふ)れている。", "sentence_source": "generated"}, {"text": "彼の目は、やる気に満ち溢れていた。", "target_word": "満ち溢れて", "complexity_tier": "T3", "furigana": "彼(かれ)の目(め)は、やる気(き)に満(み)ち溢(あふ)れていた。", "sentence_source": "generated"}, {"text": "会場は、祝福の空気に満ち溢れた。", "target_word": "満ち溢れた", "complexity_tier": "T3", "furigana": "会場(かいじょう)は、祝福(しゅくふく)の空気(くうき)に満(み)ち溢(あふ)れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "満ち溢れる", "label": "辞書形"}, {"form": "満ち溢れない", "label": "否定形"}, {"form": "満ち溢れ", "label": "連用形"}, {"form": "満ち溢れた", "label": "過去形"}, {"form": "満ち溢れて", "label": "て形"}, {"form": "満ち溢れれば", "label": "仮定形"}], "register": "標準語", "sense_fingerprint": "感情・気配・においなどが全体に行き渡る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "満ち溢れて", "is_correct": true, "explanation": "「喜びに〜いた」の形。顔いっぱいに喜びが行き渡っている状態を表す。"}, {"text": "眠って", "is_correct": false, "explanation": "「喜びに眠っていた」は、感情に眠るという動作が成り立たず不自然。"}, {"text": "砕けて", "is_correct": false, "explanation": "「砕ける」は物が割れる意味で、感情を表す「喜びに」とは結びつかない。"}, {"text": "凍えて", "is_correct": false, "explanation": "「凍える」は寒さで体が冷える意味で、喜びの表情を表す文には合わない。"}], "explanations": {"満ち溢れて": "「喜びに〜いた」の形。顔いっぱいに喜びが行き渡っている状態を表す。", "眠って": "「喜びに眠っていた」は、感情に眠るという動作が成り立たず不自然。", "砕けて": "「砕ける」は物が割れる意味で、感情を表す「喜びに」とは結びつかない。", "凍えて": "「凍える」は寒さで体が冷える意味で、喜びの表情を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "満ち溢れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借金の期限が満ち溢れて、今月中に返すことになった。", "explanation": "ここは〈期限が来る（満期）〉の意味。満ち溢れるは気持ちや雰囲気が行き渡る意味で、期限の到来には使わない。"}, {"text": "彼の心は空虚で、喜びが満ち溢れていた。", "explanation": "ここは「空虚（中身がない）」の意味。満ち溢れるは気持ちが十分に行き渡る意味なので、空っぽの心とは合わない。"}, {"text": "その町は人影も少なく、活気が満ち溢れている。", "explanation": "ここは「さびれる」の意味。満ち溢れるは活気が十分に行き渡ることで、人影が少なく寂れた様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "満ち溢れた", "is_correct": true, "explanation": "「希望に〜場所だった」の連体形。希望が強く行き渡った場所を修飾する。"}, {"text": "踊った", "is_correct": false, "explanation": "「希望に踊った場所」は、希望と踊りが結びつかず成り立たない。"}, {"text": "叫んだ", "is_correct": false, "explanation": "「叫ぶ」は声を出す動作で、場所を修飾する形として意味が通らない。"}, {"text": "削がれた", "is_correct": false, "explanation": "「削がれる」は気力などが減る意味で、希望に満ちた場所という文脈と逆になる。"}], "explanations": {"満ち溢れた": "「希望に〜場所だった」の連体形。希望が強く行き渡った場所を修飾する。", "踊った": "「希望に踊った場所」は、希望と踊りが結びつかず成り立たない。", "叫んだ": "「叫ぶ」は声を出す動作で、場所を修飾する形として意味が通らない。", "削がれた": "「削がれる」は気力などが減る意味で、希望に満ちた場所という文脈と逆になる。"}, "sentence_index": 6, "correct_answer": "満ち溢れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "潮が満ち溢れて、浜辺が水に沈んだ。", "explanation": "ここは〈潮が満ちる〉の意味。満ち溢れるは気配や感情が行き渡る意味で、潮の満ち引きには使わない。"}, {"text": "不安が満ち溢れ、ほっとした。", "explanation": "ここは「消える」の意味。満ち溢れるは気持ちが強く広がる意味で、不安が消えてほっとする流れとは合わない。"}, {"text": "その笑顔には、かすかな喜びが満ち溢れていた。", "explanation": "ここは「ほのか」な気配の意味。満ち溢れるは強く行き渡る状態を表すので、かすかなものとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の声には、喜びを満ち溢れていた。", "corrected_sentence": "彼女の声には、喜びが満ち溢れていた。", "error_description": "誤：「を」。正：「が」。満ち溢れるは自動詞なので、「喜び」には「が」が付く。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "満ち溢れて", "is_correct": true, "explanation": "「活気に〜いる」の形。町に活気が行き渡っている状態を表す。"}, {"text": "満ち溢れない", "is_correct": false, "explanation": "否定形で、町が活気に満ちているという文の意味と逆になる。"}, {"text": "満ち溢れれば", "is_correct": false, "explanation": "仮定形で、「〜ている」の現在の状態を述べる文に条件の形は合わない。"}, {"text": "満ち溢れ", "is_correct": false, "explanation": "連用形で、「〜ている」の続く形にならず、文が完結しない。"}], "correct_form": "満ち溢れて", "base_form": "満ち溢れる", "form_label": "て形", "sentence_index": 1, "explanations": {"満ち溢れて": "「活気に〜いる」の形。町に活気が行き渡っている状態を表す。", "満ち溢れない": "否定形で、町が活気に満ちているという文の意味と逆になる。", "満ち溢れれば": "仮定形で、「〜ている」の現在の状態を述べる文に条件の形は合わない。", "満ち溢れ": "連用形で、「〜ている」の続く形にならず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51732, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会場には、拍手へ満ち溢れていた。", "corrected_sentence": "会場には、拍手が満ち溢れていた。", "error_description": "誤：「へ」。正：「が」。満ち溢れるの主語になる拍手には、主語を表す「が」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "満ち溢れて", "is_correct": true, "explanation": "「香りが〜いる」の形。カレーの香りが台所に行き渡っている状態を表す。"}, {"text": "満ち溢れた", "is_correct": false, "explanation": "過去形。「〜ている」の現在の状態を述べる文に合わない。"}, {"text": "満ち溢れよう", "is_correct": false, "explanation": "意志の形で、香りが満ちている事実を述べる文には合わない。"}, {"text": "満ち溢れる", "is_correct": false, "explanation": "辞書形。「〜ている」の状態を述べる形に続かず、文が成り立たない。"}], "correct_form": "満ち溢れて", "base_form": "満ち溢れる", "form_label": "て形", "sentence_index": 7, "explanations": {"満ち溢れて": "「香りが〜いる」の形。カレーの香りが台所に行き渡っている状態を表す。", "満ち溢れた": "過去形。「〜ている」の現在の状態を述べる文に合わない。", "満ち溢れよう": "意志の形で、香りが満ちている事実を述べる文には合わない。", "満ち溢れる": "辞書形。「〜ている」の状態を述べる形に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「戦後の食べ物」の「の」で、食べ物が戦後の時期のものであることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「戦後を食べ物が少ない時代に」は成り立たず、文の形が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「戦後へ食べ物が少ない時代」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表すが、「戦後と食べ物が少ない時代」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「戦後の食べ物」の「の」で、食べ物が戦後の時期のものであることを示す。", "を": "「戦後を食べ物が少ない時代に」は成り立たず、文の形が崩れる。", "へ": "方向を表すが、「戦後へ食べ物が少ない時代」は意味が通らない。", "と": "並列を表すが、「戦後と食べ物が少ない時代」は不自然。"}, "error_tags": {"を": "object", "へ": "direction", "と": "and"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "戦前", "is_correct": true, "explanation": "戦争が始まる前の時代を指し、戦後の対義語。"}, {"text": "開戦", "is_correct": false, "explanation": "戦争が始まること。時期の対義語ではなく、戦後とは対にならない。"}, {"text": "交戦", "is_correct": false, "explanation": "敵どうしが戦うこと。戦後の反対語ではない。"}, {"text": "宣戦", "is_correct": false, "explanation": "相手国に戦争を宣言すること。戦後とは対義関係にない。"}], "correct_answer": "戦前", "explanations": {"戦前": "戦争が始まる前の時代を指し、戦後の対義語。", "開戦": "戦争が始まること。時期の対義語ではなく、戦後とは対にならない。", "交戦": "敵どうしが戦うこと。戦後の反対語ではない。", "宣戦": "相手国に戦争を宣言すること。戦後とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "戦前", "is_correct": true, "explanation": "戦争が始まる前の時代を指し、戦後の対義語。"}, {"text": "敗戦", "is_correct": false, "explanation": "戦争に負けること。戦後と関係する語だが、時期の対義語ではない。"}, {"text": "停戦", "is_correct": false, "explanation": "戦闘を一時的にやめること。戦後の反対語ではない。"}, {"text": "戦禍", "is_correct": false, "explanation": "戦争による被害のこと。時期を表す対義語ではない。"}], "correct_answer": "戦前", "explanations": {"戦前": "戦争が始まる前の時代を指し、戦後の対義語。", "敗戦": "戦争に負けること。戦後と関係する語だが、時期の対義語ではない。", "停戦": "戦闘を一時的にやめること。戦後の反対語ではない。", "戦禍": "戦争による被害のこと。時期を表す対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "戦争が終わった後のこと。特に、第二次世界大戦が終わった後の時代のこと。", "primary_collocate": null, "pronunciation": "せんご", "ipa": "seŋɡo", "syllable_count": 3, "sentences": [{"text": "戦後、私の祖父は小さな店を開きました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]、私[わたし]の祖父[そふ]は小[ちい]さな店[みせ]を開[ひら]きました。", "sentence_source": "generated"}, {"text": "戦後の食べ物が少ない時代に、祖母は育ちました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]の食[た]べ物[もの]が少[すく]ない時代[じだい]に、祖母[そぼ]は育[そだ]ちました。", "sentence_source": "generated"}, {"text": "戦後の日本では、新しい憲法が作られました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]の日本[にほん]では、新[あたら]しい憲法[けんぽう]が作[つく]られました。", "sentence_source": "generated"}, {"text": "戦後すぐは、多くの町が復興の途中でした。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]すぐは、多[おお]くの町[まち]が復興[ふっこう]の途中[とちゅう]でした。", "sentence_source": "generated"}, {"text": "この映画は、戦後の貧しい家族を描いています。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "この映画[えいが]は、戦後[せんご]の貧[まず]しい家族[かぞく]を描[えが]いています。", "sentence_source": "generated"}, {"text": "戦後に建てられた学校が、今も残っています。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]に建[た]てられた学校[がっこう]が、今[いま]も残[のこ]っています。", "sentence_source": "generated"}, {"text": "戦後の暮らしについて、博物館で調べました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]の暮[く]らしについて、博物館[はくぶつかん]で調[しら]べました。", "sentence_source": "generated"}, {"text": "戦後生まれの父は、戦争の話を祖父から聞きました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]生[う]まれの父[ちち]は、戦争[せんそう]の話[はなし]を祖父[そふ]から聞[き]きました。", "sentence_source": "generated"}, {"text": "戦後、人々は少しずつ平和な生活を取り戻しました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]、人々[ひとびと]は少[すこ]しずつ平和[へいわ]な生活[せいかつ]を取[と]り戻[もど]しました。", "sentence_source": "generated"}, {"text": "戦後の復興のおかげで、町は明るくなりました。", "target_word": "戦後", "complexity_tier": "T3", "furigana": "戦後[せんご]の復興[ふっこう]のおかげで、町[まち]は明[あか]るくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦後", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "戦争が終わった後の時代、特に第二次世界大戦後", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦後", "is_correct": true, "explanation": "戦争が終わった後を指し、祖父が店を開いた時期を示す文に合う。"}, {"text": "交通", "is_correct": false, "explanation": "人や物の移動を表す語で、時期を示す副詞句にならない。"}, {"text": "農業", "is_correct": false, "explanation": "作物を育てる産業で、時期を示す語ではない。文に合わない。"}, {"text": "電力", "is_correct": false, "explanation": "電気の供給を表す語で、時期を示せない。「電力、祖父は店を開いた」は不自然。"}], "explanations": {"戦後": "戦争が終わった後を指し、祖父が店を開いた時期を示す文に合う。", "交通": "人や物の移動を表す語で、時期を示す副詞句にならない。", "農業": "作物を育てる産業で、時期を示す語ではない。文に合わない。", "電力": "電気の供給を表す語で、時期を示せない。「電力、祖父は店を開いた」は不自然。"}, "sentence_index": 0, "correct_answer": "戦後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "退院の戦後は、無理をせず体を休めましょう。", "explanation": "ここは〈退院後〉の意味。退院した後の過ごし方は〈退院後〉と言い、戦争が終わった後を指す〈戦後〉は合わない。"}, {"text": "授業の戦後に、部活動へ行きます。", "explanation": "ここは〈放課後〉の意味。授業が終わった後の時間は〈放課後〉と言い、〈戦後〉は戦争の終結後を指すので合わない。"}, {"text": "雨の戦後は、山道がとても滑りやすくなります。", "explanation": "ここは〈雨後〉の意味。雨が上がった後の状態は〈雨後〉と言い、〈戦後〉は山道の状態には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦後", "is_correct": true, "explanation": "戦争が終わった後の時代を指し、戦後の暮らしを調べるという文脈に合う。"}, {"text": "食料", "is_correct": false, "explanation": "食べ物を表す語で時代を示さない。「食料の暮らし」は不自然。"}, {"text": "照明", "is_correct": false, "explanation": "明かりを表す語で時代を示さない。「照明の暮らし」は意味が通らない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表す語で時代を示さない。「機械の暮らし」は不自然。"}], "explanations": {"戦後": "戦争が終わった後の時代を指し、戦後の暮らしを調べるという文脈に合う。", "食料": "食べ物を表す語で時代を示さない。「食料の暮らし」は不自然。", "照明": "明かりを表す語で時代を示さない。「照明の暮らし」は意味が通らない。", "機械": "装置を表す語で時代を示さない。「機械の暮らし」は不自然。"}, "sentence_index": 6, "correct_answer": "戦後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "戦後、子どもたちは毎日防空壕に避難していました。", "explanation": "ここは〈戦時中〉の意味。空襲を避けて防空壕に入るのは戦争の最中なので、〈戦後〉は合わない。"}, {"text": "引退の戦後に備えて、資金を少しずつ貯めています。", "explanation": "ここは〈老後〉の意味。引退した後の生活は〈老後〉と言い、〈戦後〉は戦争の終結後を指すので合わない。"}, {"text": "戦後、この町の学校は疎開先に移りました。", "explanation": "ここは〈開戦後〉の意味。疎開は戦争が始まった後に行うので、戦争の終結後を指す〈戦後〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "戦後で、私の祖父は小さな店を開きました。", "corrected_sentence": "戦後に、私の祖父は小さな店を開きました。", "error_description": "時点を示すときは「戦後に」と言う。「戦後で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "戦後で、この町の学校は再開されました。", "corrected_sentence": "戦後に、この町の学校は再開されました。", "error_description": "時点を示す「戦後に」の「に」を「で」にした誤り。「戦後で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。『は』は主題を示し、コンクリートについて説明する文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "『を』は動作の対象を示すが、この文は説明文なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や対象を示し、ここでは主題を作れず意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ働きで、主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "正解。『は』は主題を示し、コンクリートについて説明する文の主題になる。", "を": "『を』は動作の対象を示すが、この文は説明文なので合わない。", "に": "『に』は位置や対象を示し、ここでは主題を作れず意味が通らない。", "の": "『の』は名詞をつなぐ働きで、主題にはならない。"}, "error_tags": {"を": "対格", "に": "位置", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。『固まっていません』の主語を示す『が』。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すが、ここは状態を述べる文なので方向は合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示し、ここでは主語の働きをしない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示し、『固まる』の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。『固まっていません』の主語を示す『が』。", "へ": "『へ』は方向を示すが、ここは状態を述べる文なので方向は合わない。", "と": "『と』は並列や相手を示し、ここでは主語の働きをしない。", "から": "『から』は起点を示し、『固まる』の主語にはならない。"}, "error_tags": {"へ": "方向", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物を作るための、石のように固い材料です。", "primary_collocate": null, "pronunciation": "こんくりーと", "ipa": "koŋkɯɾiːto", "syllable_count": 6, "sentences": [{"text": "新しい家の土台に、コンクリートを使います。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]の土台[どだい]に、コンクリートを使[つか]います。", "sentence_source": "generated"}, {"text": "コンクリートは石のように固い材料です。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "コンクリートは石[いし]のように固[かた]い材料[ざいりょう]です。", "sentence_source": "generated"}, {"text": "工事の人が、コンクリートを型に流しました。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、コンクリートを型[かた]に流[なが]しました。", "sentence_source": "generated"}, {"text": "コンクリートの床は冷たくて、夏は気持ちがいいです。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "コンクリートの床[ゆか]は冷[つめ]たくて、夏[なつ]は気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "公園のコンクリートの上で、子どもが絵を描いています。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "公園[こうえん]のコンクリートの上[うえ]で、子[こ]どもが絵[え]を描[か]いています。", "sentence_source": "generated"}, {"text": "雨の日は、コンクリートの道がすべりやすいです。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、コンクリートの道[みち]がすべりやすいです。", "sentence_source": "generated"}, {"text": "このビルはコンクリートでできているので、とても丈夫です。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "このビルはコンクリートでできているので、とても丈夫[じょうぶ]です。", "sentence_source": "generated"}, {"text": "昨日流したコンクリートが、まだ固まっていません。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "昨日[きのう]流[なが]したコンクリートが、まだ固[かた]まっていません。", "sentence_source": "generated"}, {"text": "コンクリートのかべに、ツタが伸びています。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "コンクリートのかべに、ツタが伸[の]びています。", "sentence_source": "generated"}, {"text": "駐車場の地面は、全部コンクリートです。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]の地面[じめん]は、全部[ぜんぶ]コンクリートです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンクリート", "label": "基本形"}], "register": "polite", "sense_fingerprint": "建物を作る石のように固い材料（コンクリート）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンクリート", "is_correct": true, "explanation": "正解。建物の土台に使う、石のように固い建築材料。"}, {"text": "障子", "is_correct": false, "explanation": "障子は紙と木枠で作る建具で、土台に使う材料ではない。"}, {"text": "襖", "is_correct": false, "explanation": "襖は部屋を仕切る建具で、土台に使う材料ではない。"}, {"text": "瓦", "is_correct": false, "explanation": "瓦は屋根に葺く材料で、土台に使うものではない。"}], "explanations": {"コンクリート": "正解。建物の土台に使う、石のように固い建築材料。", "障子": "障子は紙と木枠で作る建具で、土台に使う材料ではない。", "襖": "襖は部屋を仕切る建具で、土台に使う材料ではない。", "瓦": "瓦は屋根に葺く材料で、土台に使うものではない。"}, "sentence_index": 0, "correct_answer": "コンクリート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このコンクリートは、糸を織って作られた柔らかい素材です。", "explanation": "ここは〈布〉の意味。コンクリートは糸を織らず、固くて柔らかくないので、こうは言わない。"}, {"text": "この菓子はコンクリートを煮詰めて作ります。", "explanation": "ここは〈砂糖〉の意味。コンクリートは煮詰めて作る材料ではなく、水と反応して固まる材料である。"}, {"text": "この窓は、コンクリートを溶かして吹いて作ってあります。", "explanation": "ここは〈ガラス〉の意味。コンクリートは溶かして吹く材料ではないので、溶かして吹いて作るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンクリート", "is_correct": true, "explanation": "正解。固くて丈夫な建築材料で、建物はこれでできていると言える。"}, {"text": "雨戸", "is_correct": false, "explanation": "雨戸は窓を覆う建具で、建物全体の材料にはならない。"}, {"text": "畳", "is_correct": false, "explanation": "畳は床に敷く敷物で、建物全体の材料にはならない。"}, {"text": "欄間", "is_correct": false, "explanation": "欄間は長押の上の透かし彫りの装飾で、建物の素材にはならない。"}], "explanations": {"コンクリート": "正解。固くて丈夫な建築材料で、建物はこれでできていると言える。", "雨戸": "雨戸は窓を覆う建具で、建物全体の材料にはならない。", "畳": "畳は床に敷く敷物で、建物全体の材料にはならない。", "欄間": "欄間は長押の上の透かし彫りの装飾で、建物の素材にはならない。"}, "sentence_index": 6, "correct_answer": "コンクリート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この靴はコンクリートで作られていて、やわらかく足になじみます。", "explanation": "ここは〈革〉の意味。コンクリートは固くて柔らかくならず、足になじむという使い方はしない。"}, {"text": "コンクリートは、ろくろで形を作ってから焼くと器になります。", "explanation": "ここは〈陶土〉の意味。コンクリートは焼いて固める材料ではなく、焼いて器にするとは言わない。"}, {"text": "コンクリートで紙に書くと、きれいな線になります。", "explanation": "ここは〈墨〉の意味。コンクリートは書く材料ではないので、紙に線を書くことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋根の下の壁は、コンクリートに作られています。", "corrected_sentence": "屋根の下の壁は、コンクリートで作られています。", "error_description": "『作る』の手段を示すのは『で』。『コンクリートに』は誤りで、正しくは『コンクリートで』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51735, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ぬかるみを防ぐため、道の土をコンクリートで固ためます。", "corrected_sentence": "ぬかるみを防ぐため、道の土をコンクリートで固めます。", "error_description": "『固める』の連用形は『固め』。『固ためます』は誤りで、正しくは『固めます』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。『使われる』の主語を示す『が』で、コンクリートが使われるという関係を作る。"}, {"text": "を", "is_correct": false, "explanation": "『使われる』は受身なので、動作の対象を『を』で示す形にはならない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ働きで、動詞『使われる』の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『使われる』の主語を作れず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。『使われる』の主語を示す『が』で、コンクリートが使われるという関係を作る。", "を": "『使われる』は受身なので、動作の対象を『を』で示す形にはならない。", "の": "『の』は名詞をつなぐ働きで、動詞『使われる』の主語にはならない。", "で": "『で』は手段や場所を示すので、『使われる』の主語を作れず、文が成り立たない。"}, "error_tags": {"を": "対格", "の": "連体", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。『傷みやすくなる』の主語を示す『が』。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や対象を示すので、『傷む』の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示し、ここでは主語の働きをしない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、状態を述べる文では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。『傷みやすくなる』の主語を示す『が』。", "に": "『に』は位置や対象を示すので、『傷む』の主語にはならない。", "と": "『と』は並列や相手を示し、ここでは主語の働きをしない。", "へ": "『へ』は方向を示すので、状態を述べる文では意味が通らない。"}, "error_tags": {"に": "位置", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "セメント、砂、砂利、水を混ぜて固めた建築材料。鉄筋と組み合わせて鉄筋コンクリートとして使われることが多い。", "primary_collocate": null, "pronunciation": "こんくりーと", "ipa": "koŋkɯɾiːto", "syllable_count": 6, "sentences": [{"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "コンクリートの打[う]ちっぱなしという素材感[そざいかん]を活[い]かした設計[せっけい]は、入居者[にゅうきょしゃ]のコミュニティ形成[けいせい]に多大[ただい]な社会的[しゃかいてき]影響[えいきょう]を与[あた]えました。", "sentence_source": "mined"}, {"text": "橋の柱にはコンクリートが使われており、強い地震にも耐えられます。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "橋[はし]の柱[はしら]にはコンクリートが使[つか]われており、強[つよ]い地震[じしん]にも耐[た]えられます。", "sentence_source": "generated"}, {"text": "雨が降る前に、職人は急いでコンクリートを流し込みました。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]に、職人[しょくにん]は急[いそ]いでコンクリートを流[なが]し込[こ]みました。", "sentence_source": "generated"}, {"text": "コンクリートが固まるまでには、数日かかります。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "コンクリートが固[かた]まるまでには、数日[すうじつ]かかります。", "sentence_source": "generated"}, {"text": "古いコンクリートの壁にひびが入り、補修工事が始まりました。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "古[ふる]いコンクリートの壁[かべ]にひびが入[はい]り、補修工事[ほしゅうこうじ]が始[はじ]まりました。", "sentence_source": "generated"}, {"text": "この建物はコンクリートの冷たい質感が特徴で、夏でも涼しく感じます。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "この建物[たてもの]はコンクリートの冷[つめ]たい質感[しつかん]が特徴[とくちょう]で、夏[なつ]でも涼[すず]しく感[かん]じます。", "sentence_source": "generated"}, {"text": "砂利と水を混ぜたコンクリートを、型枠に流して固めます。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "砂利[じゃり]と水[みず]を混[ま]ぜたコンクリートを、型枠[かたわく]に流[なが]して固[かた]めます。", "sentence_source": "generated"}, {"text": "海辺では塩分の影響で、コンクリートが傷みやすくなります。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "海辺[うみべ]では塩分[えんぶん]の影響[えいきょう]で、コンクリートが傷[いた]みやすくなります。", "sentence_source": "generated"}, {"text": "庭の一部をコンクリートで固めると、雑草が生えにくくなります。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "庭[にわ]の一部[いちぶ]をコンクリートで固[かた]めると、雑草[ざっそう]が生[は]えにくくなります。", "sentence_source": "generated"}, {"text": "道路の下には、厚いコンクリートの層が敷かれています。", "target_word": "コンクリート", "complexity_tier": "T3", "furigana": "道路[どうろ]の下[した]には、厚[あつ]いコンクリートの層[そう]が敷[し]かれています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンクリート", "label": "基本形"}], "register": "polite", "sense_fingerprint": "セメント・砂・砂利・水を混ぜて固めた建築材料（コンクリート）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンクリート", "is_correct": true, "explanation": "正解。『打ちっぱなし』は表面を仕上げずに見せるコンクリートの仕上げ方で、ここでは素材そのものを指す。"}, {"text": "漆喰", "is_correct": false, "explanation": "漆喰は壁に塗る材料で、『打ちっぱなし』（未仕上げ）という言い方とは合わない。"}, {"text": "大理石", "is_correct": false, "explanation": "大理石は磨いて仕上げる石材で、『打ちっぱなし』の対象にはならない。"}, {"text": "瓦", "is_correct": false, "explanation": "瓦は屋根に葺く焼き物で、『打ちっぱなし』という仕上げ方を指す語ではない。"}], "explanations": {"コンクリート": "正解。『打ちっぱなし』は表面を仕上げずに見せるコンクリートの仕上げ方で、ここでは素材そのものを指す。", "漆喰": "漆喰は壁に塗る材料で、『打ちっぱなし』（未仕上げ）という言い方とは合わない。", "大理石": "大理石は磨いて仕上げる石材で、『打ちっぱなし』の対象にはならない。", "瓦": "瓦は屋根に葺く焼き物で、『打ちっぱなし』という仕上げ方を指す語ではない。"}, "sentence_index": 0, "correct_answer": "コンクリート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁のひびは、石膏と水を練ったコンクリートで埋めました。", "explanation": "ここは〈石膏〉の意味。コンクリートはセメントを使って固める材料で、石膏を水で練ったものは石膏と呼ぶので、コンクリートとは言わない。"}, {"text": "この茶碗は土を焼き固めて作ったコンクリートです。", "explanation": "ここは〈陶器〉の意味。コンクリートは焼かずに水と反応させて固める材料なので、焼き固めて器を作るとは言わない。"}, {"text": "割れた皿は、コンクリートで貼り合わせると元どおりになります。", "explanation": "ここは〈接着剤〉の意味。コンクリートは固めて構造を作る材料で、物を貼り合わせる働きはないので、割れた皿の修理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンクリート", "is_correct": true, "explanation": "正解。砂利と水を混ぜて固めた材料で、型枠に流して固める対象に合う。"}, {"text": "木材", "is_correct": false, "explanation": "木材は型枠に流して固めるものではないので、文の意味が通らない。"}, {"text": "障子", "is_correct": false, "explanation": "障子は紙と木枠でできた建具で、流し込んで固める材料ではない。"}, {"text": "畳", "is_correct": false, "explanation": "畳は床に敷く敷物で、型枠に流して固めるものではない。"}], "explanations": {"コンクリート": "正解。砂利と水を混ぜて固めた材料で、型枠に流して固める対象に合う。", "木材": "木材は型枠に流して固めるものではないので、文の意味が通らない。", "障子": "障子は紙と木枠でできた建具で、流し込んで固める材料ではない。", "畳": "畳は床に敷く敷物で、型枠に流して固めるものではない。"}, "sentence_index": 6, "correct_answer": "コンクリート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は、コンクリートを折って作ってあります。", "explanation": "ここは〈厚紙〉の意味。コンクリートは固く、折り曲げることができないので、折って箱を作るとは言わない。"}, {"text": "この器は、コンクリートをこねて形を作ったものです。", "explanation": "ここは〈粘土〉の意味。粘土は手でこねて形を作る材料だが、コンクリートはこねて器にする素材ではない。"}, {"text": "コンクリートは強く引っ張ると、よく伸びます。", "explanation": "ここは〈ゴム〉の意味。コンクリートは引っ張りに弱く、伸びずに割れるので、伸びるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "床の下地には、厚さ十センチのコンクリートに流し込みます。", "corrected_sentence": "床の下地には、厚さ十センチのコンクリートを流し込みます。", "error_description": "『流し込む』は対象を『を』で取る他動詞。『コンクリートに』は誤りで、正しくは『コンクリートを』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51736, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "基礎の穴にコンクリートを流し込てから、板で表面をならします。", "corrected_sentence": "基礎の穴にコンクリートを流し込んでから、板で表面をならします。", "error_description": "『流し込む』のて形は『流し込んで』。『流し込て』は誤りで、正しくは『流し込んで』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。『ブルータリズムの建物』と名詞をつなぐ連体の『の』。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語に付くので、名詞をつなぐこの場面では合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や対象を示し、名詞をつなげない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示し、名詞修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "正解。『ブルータリズムの建物』と名詞をつなぐ連体の『の』。", "を": "『を』は目的語に付くので、名詞をつなぐこの場面では合わない。", "に": "『に』は位置や対象を示し、名詞をつなげない。", "で": "『で』は手段や場所を示し、名詞修飾にはならない。"}, "error_tags": {"を": "対格", "に": "位置", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。『ブルータリズムの特徴』と名詞をつなぐ連体の『の』。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示し、名詞をつなぐ働きはしない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示し、名詞修飾にはならない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、ここでは名詞をつなげず意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。『ブルータリズムの特徴』と名詞をつなぐ連体の『の』。", "へ": "『へ』は方向を示し、名詞をつなぐ働きはしない。", "から": "『から』は起点を示し、名詞修飾にはならない。", "より": "『より』は比較を示し、ここでは名詞をつなげず意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ブルータリズムは、コンクリートをそのまま見せる建物のスタイルです。", "primary_collocate": null, "pronunciation": "ぶるーたりずむ", "ipa": "bɯɾɯːtaɾizɯmɯ", "syllable_count": 7, "sentences": [{"text": "駅の近くに、ブルータリズムの古い市役所があります。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに、ブルータリズムの古[ふる]い市役所[しやくしょ]があります。", "sentence_source": "generated"}, {"text": "ブルータリズムの建物は、壁に色を塗らないので灰色に見えます。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムの建物[たてもの]は、壁[かべ]に色[いろ]を塗[ぬ]らないので灰色[はいいろ]に見[み]えます。", "sentence_source": "generated"}, {"text": "私はブルータリズムの建物の写真を集めています。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "私[わたし]はブルータリズムの建物[たてもの]の写真[しゃしん]を集[あつ]めています。", "sentence_source": "generated"}, {"text": "ブルータリズムは飾りが少ないので、形がとても単純です。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムは飾[かざ]りが少[すく]ないので、形[かたち]がとても単純[たんじゅん]です。", "sentence_source": "generated"}, {"text": "この美術館はブルータリズムで建てられたため、中も外もコンクリートの壁です。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "この美術館[びじゅつかん]はブルータリズムで建[た]てられたため、中[なか]も外[そと]もコンクリートの壁[かべ]です。", "sentence_source": "generated"}, {"text": "友達はブルータリズムが好きで、休みの日に建物を見に行きます。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "友達[ともだち]はブルータリズムが好[す]きで、休[やす]みの日[ひ]に建物[たてもの]を見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "ブルータリズムの建物は、近くで見ると大きくて迫力があります。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムの建物[たてもの]は、近[ちか]くで見[み]ると大[おお]きくて迫力[はくりょく]があります。", "sentence_source": "generated"}, {"text": "先生は授業で、ブルータリズムの特徴を三つ説明しました。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]で、ブルータリズムの特徴[とくちょう]を三[みっ]つ説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "白い壁の家とは違って、ブルータリズムの建物は表面がざらざらしています。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "白[しろ]い壁[かべ]の家[いえ]とは違[ちが]って、ブルータリズムの建物[たてもの]は表面[ひょうめん]がざらざらしています。", "sentence_source": "generated"}, {"text": "ブルータリズムというスタイルは、四角い形が多いのが特徴です。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムというスタイルは、四角[しかく]い形[かたち]が多[おお]いのが特徴[とくちょう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブルータリズム", "label": "基本形"}], "register": "polite", "sense_fingerprint": "コンクリートをそのまま見せる、飾りの少ない建物のスタイル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブルータリズム", "is_correct": true, "explanation": "正解。コンクリートをそのまま見せた様式の古い市役所を指す。"}, {"text": "浮世絵", "is_correct": false, "explanation": "浮世絵は版画の一種で、建物の様式を表す語ではない。"}, {"text": "俳句", "is_correct": false, "explanation": "俳句は詩の形式で、建物の様式には使えない。"}, {"text": "能楽", "is_correct": false, "explanation": "能楽は舞台芸能で、建物の様式を表さない。"}], "explanations": {"ブルータリズム": "正解。コンクリートをそのまま見せた様式の古い市役所を指す。", "浮世絵": "浮世絵は版画の一種で、建物の様式を表す語ではない。", "俳句": "俳句は詩の形式で、建物の様式には使えない。", "能楽": "能楽は舞台芸能で、建物の様式を表さない。"}, "sentence_index": 0, "correct_answer": "ブルータリズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ブルータリズムは、装飾が非常に多く華やかな様式です。", "explanation": "ここは〈ロココ〉の意味。ブルータリズムは装飾を避ける様式なので、華やかな装飾が多いとは言わない。"}, {"text": "ブルータリズムは、土をろくろで回して器を作る技法です。", "explanation": "ここは〈陶芸〉の意味。ブルータリズムは建築様式で、器を作る技法ではない。"}, {"text": "ブルータリズムは、墨だけで描く東洋の絵画です。", "explanation": "ここは〈水墨画〉の意味。ブルータリズムは絵画ではなく建築様式である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブルータリズム", "is_correct": true, "explanation": "正解。大きくて迫力のある、コンクリートをそのまま見せた建物の様式を指す。"}, {"text": "落語", "is_correct": false, "explanation": "落語は話芸で、建物の様式にはあたらない。"}, {"text": "演歌", "is_correct": false, "explanation": "演歌は歌謡で、建物の様式を表す語ではない。"}, {"text": "短歌", "is_correct": false, "explanation": "短歌は和歌の形式で、建物の様式には使わない。"}], "explanations": {"ブルータリズム": "正解。大きくて迫力のある、コンクリートをそのまま見せた建物の様式を指す。", "落語": "落語は話芸で、建物の様式にはあたらない。", "演歌": "演歌は歌謡で、建物の様式を表す語ではない。", "短歌": "短歌は和歌の形式で、建物の様式には使わない。"}, "sentence_index": 6, "correct_answer": "ブルータリズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブルータリズムは、隈取りで役柄を表す伝統芸能です。", "explanation": "ここは〈歌舞伎〉の意味。ブルータリズムは建築様式で、芸能ではない。"}, {"text": "ブルータリズムは、帯で体を締める日本の衣服です。", "explanation": "ここは〈着物〉の意味。ブルータリズムは衣服ではなく、建築の様式を指す。"}, {"text": "ブルータリズムは、小さな鉢で木の姿を楽しむ趣味です。", "explanation": "ここは〈盆栽〉の意味。ブルータリズムは趣味ではなく、建築様式を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の新しい本社は、ブルータリズムが様式で建てられました。", "corrected_sentence": "会社の新しい本社は、ブルータリズムの様式で建てられました。", "error_description": "『ブルータリズムの様式』と『の』でつなぐ。『が』は主語を示すので、名詞『様式』をつなげず、正しくは『の』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51737, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達はブルータリズムを好むで、休みの日に建物を見に行きます。", "corrected_sentence": "友達はブルータリズムを好んで、休みの日に建物を見に行きます。", "error_description": "『好む』のて形は『好んで』。『好むで』は誤りで、正しくは『好んで』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
