INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51738, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。『ブルータリズムの庁舎』と名詞をつなぐ連体の『の』。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や対象を示し、名詞をつなぐ働きはしない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示し、名詞修飾にはならない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すので、ここでは名詞をつなげず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。『ブルータリズムの庁舎』と名詞をつなぐ連体の『の』。", "に": "『に』は位置や対象を示し、名詞をつなぐ働きはしない。", "から": "『から』は起点を示し、名詞修飾にはならない。", "が": "『が』は主語を示すので、ここでは名詞をつなげず文が成り立たない。"}, "error_tags": {"に": "位置", "から": "起点", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51738, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ブルータリズムは、鉄筋コンクリートの打ち放し（表面を仕上げずにそのまま見せること）を特徴とする建築様式で、機能性を重視したデザインです。", "primary_collocate": null, "pronunciation": "ぶるーたりずむ", "ipa": "bɯɾɯːtaɾizɯmɯ", "syllable_count": 7, "sentences": [{"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "戦後[せんご]の都市計画[としけいかく]において、ブルータリズムは機能性[きのうせい]を重視[じゅうし]した新[あら]たな住宅様式[じゅうたくようしき]として普及[ふきゅう]しました。", "sentence_source": "mined"}, {"text": "この図書館は、打ち放しのコンクリートが印象的なブルータリズムの建物です。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は、打[う]ち放[はな]しのコンクリートが印象的[いんしょうてき]なブルータリズムの建物[たてもの]です。", "sentence_source": "generated"}, {"text": "ブルータリズムは装飾を避けるので、外観が重々しく見えます。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムは装飾[そうしょく]を避[さ]けるので、外観[がいかん]が重々[おもおも]しく見[み]えます。", "sentence_source": "generated"}, {"text": "彼は大学で、ブルータリズムの建築について研究しています。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で、ブルータリズムの建築[けんちく]について研究[けんきゅう]しています。", "sentence_source": "generated"}, {"text": "ブルータリズムの建物は表面を仕上げないため、雨のあとに壁の色が濃くなります。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムの建物[たてもの]は表面[ひょうめん]を仕上[しあ]げないため、雨[あめ]のあとに壁[かべ]の色[いろ]が濃[こ]くなります。", "sentence_source": "generated"}, {"text": "ブルータリズムは、戦後の復興期に各国で広まった様式の一つです。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムは、戦後[せんご]の復興期[ふっこうき]に各国[かっこく]で広[ひろ]まった様式[ようしき]の一[ひと]つです。", "sentence_source": "generated"}, {"text": "ブルータリズムを好む人は、飾りのない素材そのものの力強さに魅力を感じます。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "ブルータリズムを好[この]む人[ひと]は、飾[かざ]りのない素材[そざい]そのものの力強[ちからづよ]さに魅力[みりょく]を感[かん]じます。", "sentence_source": "generated"}, {"text": "古いブルータリズムの庁舎は、修理の費用が高く、保存するかどうか議論になっています。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "古[ふる]いブルータリズムの庁舎[ちょうしゃ]は、修理[しゅうり]の費用[ひよう]が高[たか]く、保存[ほぞん]するかどうか議論[ぎろん]になっています。", "sentence_source": "generated"}, {"text": "華やかな装飾が特徴の様式とは違い、ブルータリズムは機能を第一に考えます。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "華[はな]やかな装飾[そうしょく]が特徴[とくちょう]の様式[ようしき]とは違[ちが]い、ブルータリズムは機能[きのう]を第一[だいいち]に考[かんが]えます。", "sentence_source": "generated"}, {"text": "旅行先でブルータリズムの教会を見て、その迫力に驚きました。", "target_word": "ブルータリズム", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]でブルータリズムの教会[きょうかい]を見[み]て、その迫力[はくりょく]に驚[おどろ]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブルータリズム", "label": "基本形"}], "register": "formal", "sense_fingerprint": "建築様式。打ち放しコンクリートと機能性を重視する20世紀中頃のデザイン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 打ち放し (Zipf 1.43)','sentence 2 above tier T3: contains vocabulary far above tier T3: 重々しく (Zipf 1.98)']::text[], '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブルータリズム", "is_correct": true, "explanation": "正解。機能性を重視した住宅様式として普及した建築様式を指す。"}, {"text": "印象派", "is_correct": false, "explanation": "印象派は絵画の流派で、住宅様式として普及した対象にはならない。"}, {"text": "浮世絵", "is_correct": false, "explanation": "浮世絵は版画の一種で、住宅様式を表す語ではない。"}, {"text": "水墨画", "is_correct": false, "explanation": "水墨画は墨で描く絵画で、住宅様式として普及するものではない。"}], "explanations": {"ブルータリズム": "正解。機能性を重視した住宅様式として普及した建築様式を指す。", "印象派": "印象派は絵画の流派で、住宅様式として普及した対象にはならない。", "浮世絵": "浮世絵は版画の一種で、住宅様式を表す語ではない。", "水墨画": "水墨画は墨で描く絵画で、住宅様式として普及するものではない。"}, "sentence_index": 0, "correct_answer": "ブルータリズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この教会は、尖塔が天に伸びるブルータリズム様式で、装飾が多いのが特徴です。", "explanation": "ここは〈ゴシック〉の意味。ブルータリズムは装飾を避ける様式なので、装飾が多いのが特徴とは言わない。"}, {"text": "ブルータリズムは、光の移ろいを色の点で描く画風です。", "explanation": "ここは〈印象派〉の意味。ブルータリズムは建築様式で、絵の画風ではない。"}, {"text": "ブルータリズムは、ドイツで機能性と合理性を重視した造形学校です。", "explanation": "ここは〈バウハウス〉の意味。ブルータリズムは学校ではなく、建築の様式を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブルータリズム", "is_correct": true, "explanation": "正解。飾りのない素材の力強さに魅力を感じさせる建築様式。"}, {"text": "ロココ", "is_correct": false, "explanation": "ロココは装飾の多い様式で、『飾りのない素材』という文脈と矛盾する。"}, {"text": "アールヌーボー", "is_correct": false, "explanation": "アールヌーボーは曲線的な装飾が特徴で、『飾りのない』と矛盾する。"}, {"text": "バロック", "is_correct": false, "explanation": "バロックは華やかな装飾の様式で、飾りのない素材の力強さとは合わない。"}], "explanations": {"ブルータリズム": "正解。飾りのない素材の力強さに魅力を感じさせる建築様式。", "ロココ": "ロココは装飾の多い様式で、『飾りのない素材』という文脈と矛盾する。", "アールヌーボー": "アールヌーボーは曲線的な装飾が特徴で、『飾りのない』と矛盾する。", "バロック": "バロックは華やかな装飾の様式で、飾りのない素材の力強さとは合わない。"}, "sentence_index": 6, "correct_answer": "ブルータリズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブルータリズムは、こぶしを効かせて歌う日本の歌謡です。", "explanation": "ここは〈演歌〉の意味。ブルータリズムは建築様式で、歌ではない。"}, {"text": "ブルータリズムでは、抹茶を点てて客をもてなします。", "explanation": "ここは〈茶道〉の意味。ブルータリズムは建築様式で、お茶の作法ではない。"}, {"text": "ブルータリズムは、五・七・五の十七音で詠む詩です。", "explanation": "ここは〈俳句〉の意味。ブルータリズムは建築様式で、詩の形式ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このホテルはブルータリズムを建築で、飾りの少ない外観が特徴です。", "corrected_sentence": "このホテルはブルータリズムの建築で、飾りの少ない外観が特徴です。", "error_description": "『ブルータリズムの建築』と『の』で名詞をつなぐ。『を』は『建築』を修飾できず不自然なので、正しくは『の』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
