INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51739, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出社", "is_correct": false, "explanation": "会社へ出勤する意味で、住居に関わらない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かける意味で、住居の出入りの対義語ではない。"}, {"text": "購入", "is_correct": false, "explanation": "住まいを買う意味で、住み始めることの反対語ではない。"}, {"text": "退去", "is_correct": true, "explanation": "住んでいた場所から出ていくことで、入居の対義語。"}], "correct_answer": "退去", "explanations": {"出社": "会社へ出勤する意味で、住居に関わらない。", "散歩": "歩いて出かける意味で、住居の出入りの対義語ではない。", "購入": "住まいを買う意味で、住み始めることの反対語ではない。", "退去": "住んでいた場所から出ていくことで、入居の対義語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51739, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "帰省", "is_correct": false, "explanation": "故郷へ帰る意味で、住み始めることの反対語ではない。"}, {"text": "出国", "is_correct": false, "explanation": "国を出る意味で、住居に関わらない。"}, {"text": "退去", "is_correct": true, "explanation": "住んでいた場所から出ていくことで、入居の対義語。"}, {"text": "収穫", "is_correct": false, "explanation": "作物を取り入れる意味で、住居の出入りとは関係しない。"}], "correct_answer": "退去", "explanations": {"帰省": "故郷へ帰る意味で、住み始めることの反対語ではない。", "出国": "国を出る意味で、住居に関わらない。", "退去": "住んでいた場所から出ていくことで、入居の対義語。", "収穫": "作物を取り入れる意味で、住居の出入りとは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51739, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "家に住み始めること。", "primary_collocate": null, "pronunciation": "にゅうきょ", "ipa": "ɲɯːkʲo", "syllable_count": 3, "sentences": [{"text": "新しい家への入居が済んで、やっと生活が落ち着きました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]への入居[にゅうきょ]が済[す]んで、やっと生活[せいかつ]が落[お]ち着[つ]きました。", "sentence_source": "generated"}, {"text": "入居したばかりの家では、まだ段ボールがたくさん残っています。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]したばかりの家[いえ]では、まだ段[だん]ボールがたくさん残[のこ]っています。", "sentence_source": "generated"}, {"text": "この寮は、春から入居できます。", "target_word": "入居", "complexity_tier": "T3", "furigana": "この寮[りょう]は、春[はる]から入居[にゅうきょ]できます。", "sentence_source": "generated"}, {"text": "入居の日に、隣の家へあいさつに行きました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]の日[ひ]に、隣[となり]の家[いえ]へあいさつに行[い]きました。", "sentence_source": "generated"}, {"text": "古い家でも、掃除をすれば入居できる状態になります。", "target_word": "入居", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]でも、掃除[そうじ]をすれば入居[にゅうきょ]できる状態[じょうたい]になります。", "sentence_source": "generated"}, {"text": "兄は新しい家に入居して、毎朝近くの公園を散歩しています。", "target_word": "入居", "complexity_tier": "T3", "furigana": "兄[あに]は新[あたら]しい家[いえ]に入居[にゅうきょ]して、毎朝[まいあさ]近[ちか]くの公園[こうえん]を散歩[さんぽ]しています。", "sentence_source": "generated"}, {"text": "入居の前に、鍵を受け取らなければなりません。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]の前[まえ]に、鍵[かぎ]を受[う]け取[と]らなければなりません。", "sentence_source": "generated"}, {"text": "工事が終わったので、来週から入居が始まります。", "target_word": "入居", "complexity_tier": "T3", "furigana": "工事[こうじ]が終[お]わったので、来週[らいしゅう]から入居[にゅうきょ]が始[はじ]まります。", "sentence_source": "generated"}, {"text": "入居する人が決まるまで、部屋はずっと空いていました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]する人[ひと]が決[き]まるまで、部屋[へや]はずっと空[あ]いていました。", "sentence_source": "generated"}, {"text": "入居してから一週間で、近所の店を全部覚えました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]してから一週間[いっしゅうかん]で、近所[きんじょ]の店[みせ]を全部[ぜんぶ]覚[おぼ]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "入居", "label": "基本形"}, {"form": "入居する", "label": "辞書形"}, {"form": "入居した", "label": "過去形"}, {"form": "入居して", "label": "て形"}, {"form": "入居できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "家や部屋に住み始めること。サ変名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51739, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出勤", "is_correct": false, "explanation": "「新しい家への出勤」は意味が通らず、住み始めることの文脈に合わない。"}, {"text": "授業", "is_correct": false, "explanation": "「新しい家への授業」は成り立たず、生活が落ち着く文脈に合わない。"}, {"text": "入居", "is_correct": true, "explanation": "「新しい家への入居が済んで」は住み始めることが終わった意味で、文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「新しい家への散歩」は意味が通らず、生活の落ち着きの文脈に合わない。"}], "explanations": {"出勤": "「新しい家への出勤」は意味が通らず、住み始めることの文脈に合わない。", "授業": "「新しい家への授業」は成り立たず、生活が落ち着く文脈に合わない。", "入居": "「新しい家への入居が済んで」は住み始めることが終わった意味で、文脈に合う。", "散歩": "「新しい家への散歩」は意味が通らず、生活の落ち着きの文脈に合わない。"}, "sentence_index": 0, "correct_answer": "入居"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来春、市内の高校に入居します。", "explanation": "ここは〈入学〉の意味。高校は住む場所ではないので、入居とは言わない。"}, {"text": "来月、この会員制クラブに入居します。", "explanation": "ここは〈入会〉の意味。クラブは住居ではないので、入居とは言わない。"}, {"text": "来週、病院に入居することになりました。", "explanation": "ここは〈入院〉の意味。病院での治療は入院と言い、入居は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51739, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地震", "is_correct": false, "explanation": "「地震の前に鍵を受け取る」は意味が通らず、入居前の手続きの文脈に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重の前に」は成り立たず、鍵を受け取る文脈に合わない。"}, {"text": "入居", "is_correct": true, "explanation": "「入居の前に、鍵を受け取る」は住み始める前の手続きとして自然。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気の前に」は意味が通らず、鍵の受け取りの文脈に合わない。"}], "explanations": {"地震": "「地震の前に鍵を受け取る」は意味が通らず、入居前の手続きの文脈に合わない。", "体重": "「体重の前に」は成り立たず、鍵を受け取る文脈に合わない。", "入居": "「入居の前に、鍵を受け取る」は住み始める前の手続きとして自然。", "眠気": "「眠気の前に」は意味が通らず、鍵の受け取りの文脈に合わない。"}, "sentence_index": 6, "correct_answer": "入居"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お風呂に入居して、体を温めました。", "explanation": "ここは〈入浴〉の意味。風呂に入ることは入浴と言い、入居は使わない。"}, {"text": "来年から写真部に入居します。", "explanation": "ここは〈入部〉の意味。部活動は住む場所ではないので、入居とは言わない。"}, {"text": "開演の前に、ホールに入居しました。", "explanation": "ここは〈入場〉の意味。会場に入ることは入場と言い、入居は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
