INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51739, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月、新しい家で入居する予定です。", "corrected_sentence": "来月、新しい家に入居する予定です。", "error_description": "入居は「家に入る」の意味なので、場所は「に」で示す。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "が", "is_correct": false, "explanation": "「へが入居」は主語の形になり、この文では成立しない。"}, {"text": "を", "is_correct": false, "explanation": "入居は目的語を取らないので、「を」は不自然。"}, {"text": "の", "is_correct": true, "explanation": "「マンションへの入居」の「の」。入居を名詞として「へ＋の＋入居」でつながる。"}, {"text": "で", "is_correct": false, "explanation": "「へで入居」は手段や場所の「で」になり、名詞句の結びつけに合わない。"}], "correct_answer": "の", "explanations": {"が": "「へが入居」は主語の形になり、この文では成立しない。", "を": "入居は目的語を取らないので、「を」は不自然。", "の": "「マンションへの入居」の「の」。入居を名詞として「へ＋の＋入居」でつながる。", "で": "「へで入居」は手段や場所の「で」になり、名詞句の結びつけに合わない。"}, "error_tags": {"が": "subject", "を": "object", "で": "means_location"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "購入", "is_correct": false, "explanation": "住まいを買う意味で、住み始めることの反対語ではない。"}, {"text": "退去", "is_correct": true, "explanation": "住んでいた場所から出ていくことで、入居の対義語。"}, {"text": "出発", "is_correct": false, "explanation": "旅立つ意味で、住居の出入りとは関係しない。"}, {"text": "出社", "is_correct": false, "explanation": "会社へ出勤する意味で、住居に関わらない。"}], "correct_answer": "退去", "explanations": {"購入": "住まいを買う意味で、住み始めることの反対語ではない。", "退去": "住んでいた場所から出ていくことで、入居の対義語。", "出発": "旅立つ意味で、住居の出入りとは関係しない。", "出社": "会社へ出勤する意味で、住居に関わらない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "に", "is_correct": false, "explanation": "「入居に時期」は成り立たず、名詞同士の結びつけに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「入居へ時期」は方向の「へ」になり、この文では不自然。"}, {"text": "の", "is_correct": true, "explanation": "「入居の時期」の「の」。入居を名詞として時期に結びつける。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」になり、「入居より時期」は文として成立しない。"}], "correct_answer": "の", "explanations": {"に": "「入居に時期」は成り立たず、名詞同士の結びつけに合わない。", "へ": "「入居へ時期」は方向の「へ」になり、この文では不自然。", "の": "「入居の時期」の「の」。入居を名詞として時期に結びつける。", "より": "比較の「より」になり、「入居より時期」は文として成立しない。"}, "error_tags": {"に": "dative_location", "へ": "direction", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "帰省", "is_correct": false, "explanation": "故郷へ帰る意味で、住み始めることの反対語ではない。"}, {"text": "出国", "is_correct": false, "explanation": "国を出る意味で、住居に関わらない。"}, {"text": "退去", "is_correct": true, "explanation": "住んでいた場所から出ていくことで、入居の対義語。"}, {"text": "収穫", "is_correct": false, "explanation": "作物を取り入れる意味で、住居の出入りとは関係しない。"}], "correct_answer": "退去", "explanations": {"帰省": "故郷へ帰る意味で、住み始めることの反対語ではない。", "出国": "国を出る意味で、住居に関わらない。", "退去": "住んでいた場所から出ていくことで、入居の対義語。", "収穫": "作物を取り入れる意味で、住居の出入りとは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい家や部屋に引っ越して住み始めること。", "primary_collocate": null, "pronunciation": "にゅうきょ", "ipa": "ɲɯːkʲo", "syllable_count": 3, "sentences": [{"text": "設計の打ち合わせが終わり、入居の準備は予定どおり進んでいます。", "target_word": "入居", "complexity_tier": "T3", "furigana": "設計[せっけい]の打[う]ち合[あ]わせが終[お]わり、入居[にゅうきょ]の準備[じゅんび]は予定[よてい]どおり進[すす]んでいます。", "sentence_source": "generated"}, {"text": "新しいマンションへの入居は、来月の五日に決まりました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "新[あたら]しいマンションへの入居[にゅうきょ]は、来月[らいげつ]の五日[いつか]に決[き]まりました。", "sentence_source": "generated"}, {"text": "入居の前に、管理会社の人と部屋の中を確認しました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]の前[まえ]に、管理会社[かんりがいしゃ]の人[ひと]と部屋[へや]の中[なか]を確認[かくにん]しました。", "sentence_source": "generated"}, {"text": "大学に近いアパートを見つけて、四月から入居する予定です。", "target_word": "入居", "complexity_tier": "T3", "furigana": "大学[だいがく]に近[ちか]いアパートを見[み]つけて、四月[しがつ]から入居[にゅうきょ]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "入居の手続きに必要な書類を、今週中に送らなければなりません。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]の手続[てつづ]きに必要[ひつよう]な書類[しょるい]を、今週中[こんしゅうちゅう]に送[おく]らなければなりません。", "sentence_source": "generated"}, {"text": "新築の団地は人気が高く、入居を希望する家族が多いです。", "target_word": "入居", "complexity_tier": "T3", "furigana": "新築[しんちく]の団地[だんち]は人気[にんき]が高[たか]く、入居[にゅうきょ]を希望[きぼう]する家族[かぞく]が多[おお]いです。", "sentence_source": "generated"}, {"text": "入居の日が近づくと、荷物をまとめる作業で毎日忙しくなりました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]の日[ひ]が近[ちか]づくと、荷物[にもつ]をまとめる作業[さぎょう]で毎日[まいにち]忙[いそが]しくなりました。", "sentence_source": "generated"}, {"text": "工事が遅れたため、入居の時期が二か月延びてしまいました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "工事[こうじ]が遅[おく]れたため、入居[にゅうきょ]の時期[じき]が二[に]か月[げつ]延[の]びてしまいました。", "sentence_source": "generated"}, {"text": "入居の際に敷金を払ったので、引っ越しの費用が高くなりました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "入居[にゅうきょ]の際[さい]に敷金[しききん]を払[はら]ったので、引[ひ]っ越[こ]しの費用[ひよう]が高[たか]くなりました。", "sentence_source": "generated"}, {"text": "彼らは結婚してすぐに、市内の新しい住宅に入居しました。", "target_word": "入居", "complexity_tier": "T3", "furigana": "彼[かれ]らは結婚[けっこん]してすぐに、市内[しない]の新[あたら]しい住宅[じゅうたく]に入居[にゅうきょ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "入居", "label": "基本形"}, {"form": "入居する", "label": "辞書形"}, {"form": "入居した", "label": "過去形"}, {"form": "入居して", "label": "て形"}, {"form": "入居しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "新居や新しい部屋に引っ越して住み始めること。サ変名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠気", "is_correct": false, "explanation": "「眠気の準備」は意味が通らず、入居の準備の文脈に合わない。"}, {"text": "入居", "is_correct": true, "explanation": "「入居の準備」は住み始める前の準備の意味で、文脈に合う。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音の準備」は成り立たず、入居の準備の文脈に合わない。"}, {"text": "咳", "is_correct": false, "explanation": "「咳の準備」は意味が通らず、入居の準備の文脈に合わない。"}], "explanations": {"眠気": "「眠気の準備」は意味が通らず、入居の準備の文脈に合わない。", "入居": "「入居の準備」は住み始める前の準備の意味で、文脈に合う。", "騒音": "「騒音の準備」は成り立たず、入居の準備の文脈に合わない。", "咳": "「咳の準備」は意味が通らず、入居の準備の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "入居"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月、家族で神戸へ入居します。", "explanation": "ここは〈転居〉の意味。入居は住まいに住み始めることなので、都市名を移動先に取ると不自然。"}, {"text": "来年、大学に入居します。", "explanation": "ここは〈入学〉の意味。大学は住む場所ではないので、入居とは言わない。"}, {"text": "来月からジムに入居します。", "explanation": "ここは〈入会〉の意味。ジムは住居ではないので、入居とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頭痛", "is_correct": false, "explanation": "「頭痛の日が近づく」は意味が通らず、荷物をまとめる文脈に合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "「渋滞の日が近づく」は成り立たず、引っ越しの準備の文脈に合わない。"}, {"text": "入居", "is_correct": true, "explanation": "「入居の日」は住み始める日の意味で、荷物をまとめる文脈に合う。"}, {"text": "発熱", "is_correct": false, "explanation": "「発熱の日が近づく」は意味が通らず、文脈に合わない。"}], "explanations": {"頭痛": "「頭痛の日が近づく」は意味が通らず、荷物をまとめる文脈に合わない。", "渋滞": "「渋滞の日が近づく」は成り立たず、引っ越しの準備の文脈に合わない。", "入居": "「入居の日」は住み始める日の意味で、荷物をまとめる文脈に合う。", "発熱": "「発熱の日が近づく」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "入居"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は昨日から病院に入居しました。", "explanation": "ここは〈入院〉の意味。治療のために病院に泊まる場合は入院と言い、入居は使わない。"}, {"text": "来年から野球部に入居します。", "explanation": "ここは〈入部〉の意味。部活動は住む場所ではないので、入居とは言わない。"}, {"text": "来月、自衛隊に入居します。", "explanation": "ここは〈入隊〉の意味。軍や自衛隊に加わることは入居ではなく入隊と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいマンションを入居することになりました。", "corrected_sentence": "新しいマンションに入居することになりました。", "error_description": "入居は「住む場所に入る」の意味なので、場所は「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月、アパートを入居する予定です。", "corrected_sentence": "来月、アパートに入居する予定です。", "error_description": "入居は「住む場所に入る」の意味なので、場所は「に」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「味を生かす」の「味」が生かす対象であることを表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「味が生かすために」では味が主体になり、料理人が生かす意味にならない。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象の「に」。「味に生かす」は格が合わず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「味と生かす」では、並ぶ相手がなく文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「味を生かす」の「味」が生かす対象であることを表す。", "が": "主語を示す。「味が生かすために」では味が主体になり、料理人が生かす意味にならない。", "に": "方向や対象の「に」。「味に生かす」は格が合わず不自然。", "と": "並列の「と」。「味と生かす」では、並ぶ相手がなく文が成立しない。"}, "error_tags": {"が": "主語", "に": "対象・方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「長所を生かす」の「長所」が生かす対象であることを表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「長所へ生かし」では対象として結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「長所より生かし」では文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「長所から生かし」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「長所を生かす」の「長所」が生かす対象であることを表す。", "へ": "方向の「へ」。「長所へ生かし」では対象として結びつかない。", "より": "比較の「より」。「長所より生かし」では文が成立しない。", "から": "起点の「から」。「長所から生かし」では意味が通らない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いいところをちゃんと使うこと。", "primary_collocate": null, "pronunciation": "いかす", "ipa": "ikasɯ", "syllable_count": 3, "sentences": [{"text": "留学の経験を生かして、通訳の仕事を始めました。", "target_word": "生かして", "complexity_tier": "T3", "furigana": "留学[りゅうがく]の経験[けいけん]を生[い]かして、通訳[つうやく]の仕事[しごと]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "この料理は、野菜の味を生かすために薄味にしてあります。", "target_word": "生かす", "complexity_tier": "T3", "furigana": "この料理[りょうり]は、野菜[やさい]の味[あじ]を生[い]かすために薄味[うすあじ]にしてあります。", "sentence_source": "generated"}, {"text": "古い家の柱を生かした、あたたかい雰囲気の店です。", "target_word": "生かした", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]の柱[はしら]を生[い]かした、あたたかい雰囲気[ふんいき]の店[みせ]です。", "sentence_source": "generated"}, {"text": "彼女は語学力を生かせる会社に入りたいと言っている。", "target_word": "生かせる", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は語学力[ごがくりょく]を生[い]かせる会社[かいしゃ]に入[はい]りたいと言[い]っている。", "sentence_source": "generated"}, {"text": "せっかくのチャンスなのだから、うまく生かさなければもったいない。", "target_word": "生かさなければ", "complexity_tier": "T4", "furigana": "せっかくのチャンスなのだから、うまく生[い]かさなければもったいない。", "sentence_source": "generated"}, {"text": "失敗から学んだことを次の試合に生かそう。", "target_word": "生かそう", "complexity_tier": "T3", "furigana": "失敗[しっぱい]から学[まな]んだことを次[つぎ]の試合[しあい]に生[い]かそう。", "sentence_source": "generated"}, {"text": "木の形をそのまま生かして、おもしろい椅子を作った。", "target_word": "生かして", "complexity_tier": "T3", "furigana": "木[き]の形[かたち]をそのまま生[い]かして、おもしろい椅子[いす]を作[つく]った。", "sentence_source": "generated"}, {"text": "背が高いという長所を生かし、バスケットボールで活躍している。", "target_word": "生かし", "complexity_tier": "T4", "furigana": "背[せ]が高[たか]いという長所[ちょうしょ]を生[い]かし、バスケットボールで活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "先生のアドバイスを生かさなかったので、また同じ間違いをした。", "target_word": "生かさなかった", "complexity_tier": "T4", "furigana": "先生[せんせい]のアドバイスを生[い]かさなかったので、また同[おな]じ間違[まちが]いをした。", "sentence_source": "generated"}, {"text": "狭い部屋でも、工夫しだいで空間を生かすことができる。", "target_word": "生かす", "complexity_tier": "T4", "furigana": "狭[せま]い部屋[へや]でも、工夫[くふう]しだいで空間[くうかん]を生[い]かすことができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生かす", "label": "終止形"}, {"form": "生かして", "label": "て形"}, {"form": "生かした", "label": "た形"}, {"form": "生かさない", "label": "ない形"}, {"form": "生かせる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "長所・経験・素材のよさを無駄にせず活用する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生かして", "is_correct": true, "explanation": "て形。「〜て、〜ました」の形で二つの動作をつなぐので、ここに合う。"}, {"text": "生かせ", "is_correct": false, "explanation": "命令形。「生かせ、」と言い切ると、後ろの「始めました」とつながらない。"}, {"text": "生かそう", "is_correct": false, "explanation": "意志形。「生かそう、」と切れると、文が成立しない。"}, {"text": "生かします", "is_correct": false, "explanation": "丁寧な終止形。読点の前で文が切れ、「通訳の仕事を始めました」と続かない。"}], "explanations": {"生かして": "て形。「〜て、〜ました」の形で二つの動作をつなぐので、ここに合う。", "生かせ": "命令形。「生かせ、」と言い切ると、後ろの「始めました」とつながらない。", "生かそう": "意志形。「生かそう、」と切れると、文が成立しない。", "生かします": "丁寧な終止形。読点の前で文が切れ、「通訳の仕事を始めました」と続かない。"}, "sentence_index": 0, "correct_answer": "生かして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い機械を生かして、すぐ廃棄した。", "explanation": "ここは〈廃棄する〉の意味。生かすは〈持ち味を活用する〉なので、不要になったものを捨てる場面では使わない。"}, {"text": "ひびを生かして、壁の傷を隠した。", "explanation": "ここは〈隠す〉の意味。生かすは〈持ち味を活用する〉なので、欠点を隠す場面では使わない。"}, {"text": "せっかくの材料を生かして、そのまま焦がした。", "explanation": "ここは〈焦がす〉の意味。生かすは〈持ち味を活用する〉なので、材料を焦がす場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生かして", "is_correct": true, "explanation": "て形。「〜て、〜た」で動作をつなぐ形なので、ここに合う。"}, {"text": "生かす", "is_correct": false, "explanation": "辞書形。「生かす、」と切れると、後の「椅子を作った」とつながらない。"}, {"text": "生かせる", "is_correct": false, "explanation": "可能形。読点の前で言い切れず、文が成立しない。"}, {"text": "生かせよう", "is_correct": false, "explanation": "意志形。読点の前で文が成立せず、後続と続かない。"}], "explanations": {"生かして": "て形。「〜て、〜た」で動作をつなぐ形なので、ここに合う。", "生かす": "辞書形。「生かす、」と切れると、後の「椅子を作った」とつながらない。", "生かせる": "可能形。読点の前で言い切れず、文が成立しない。", "生かせよう": "意志形。読点の前で文が成立せず、後続と続かない。"}, "sentence_index": 6, "correct_answer": "生かして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "取材で、彼から本音を生かした。", "explanation": "ここは〈引き出す〉の意味。生かすは〈持ち味や経験を活用する〉で、人から本音を取り出す場面では使わない。"}, {"text": "猟師は獲物を一発で生かした。", "explanation": "ここは〈仕留める〉の意味。生かすは〈持ち味を活用する〉で、獲物を仕留める場面では使わない。"}, {"text": "床のごみを生かして、部屋をきれいにした。", "explanation": "ここは〈取り除く〉の意味。生かすは〈持ち味を活用する〉で、ごみを取り除く場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英語の知識を生かすして、海外の会社で働いている。", "corrected_sentence": "英語の知識を生かして、海外の会社で働いている。", "error_description": "て形の誤り。「生かすして」ではなく「生かして」（て形）が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生かす", "is_correct": true, "explanation": "終止形（辞書形）。「〜ために」の前は終止形で、目的を表す。"}, {"text": "生かして", "is_correct": false, "explanation": "て形は「〜ために」の前に続かず、この位置では文法的に合わない。"}, {"text": "生かせ", "is_correct": false, "explanation": "命令形。〜ために の前には続かず、この位置では文法的に合わない。"}, {"text": "生かそう", "is_correct": false, "explanation": "意志形。〜ために の前には続かず、文法的に合わない。"}], "correct_form": "生かす", "base_form": "生かす", "form_label": "終止形", "sentence_index": 1, "explanations": {"生かす": "終止形（辞書形）。「〜ために」の前は終止形で、目的を表す。", "生かして": "て形は「〜ために」の前に続かず、この位置では文法的に合わない。", "生かせ": "命令形。〜ために の前には続かず、この位置では文法的に合わない。", "生かそう": "意志形。〜ために の前には続かず、文法的に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51741, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "経験が生かして、新しい仕事に挑戦した。", "corrected_sentence": "経験を生かして、新しい仕事に挑戦した。", "error_description": "助詞の誤り。「生かす」の目的語は「経験を」で、「経験が」では主語になり、生かす対象にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生かし", "is_correct": true, "explanation": "連用形（中止形）。「〜し、〜ている」で文を続ける形なので、ここに合う。"}, {"text": "生かす", "is_correct": false, "explanation": "辞書形。「長所を生かす、」と言い切ると、後の文とつながらない。"}, {"text": "生かせ", "is_correct": false, "explanation": "命令形。「生かせ、」と言い切れず、文が続かない。"}, {"text": "生かせない", "is_correct": false, "explanation": "ない形。読点の前で切れ、「活躍している」と続かない。"}], "correct_form": "生かし", "base_form": "生かす", "form_label": "連用形", "sentence_index": 7, "explanations": {"生かし": "連用形（中止形）。「〜し、〜ている」で文を続ける形なので、ここに合う。", "生かす": "辞書形。「長所を生かす、」と言い切ると、後の文とつながらない。", "生かせ": "命令形。「生かせ、」と言い切れず、文が続かない。", "生かせない": "ない形。読点の前で切れ、「活躍している」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「魚を生かす」の「魚」が生かす対象であることを表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「魚が生かしておく」では魚が生かす主体になり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "対象や方向の「に」。「魚に生かしておく」は対象の関係が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「魚と生かしておく」では、並ぶ相手がない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「魚を生かす」の「魚」が生かす対象であることを表す。", "が": "主語を示す。「魚が生かしておく」では魚が生かす主体になり、意味が通らない。", "に": "対象や方向の「に」。「魚に生かしておく」は対象の関係が成立しない。", "と": "並列の「と」。「魚と生かしておく」では、並ぶ相手がない。"}, "error_tags": {"が": "主語", "に": "対象・方向", "と": "並列・共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "殺す", "is_correct": true, "explanation": "生かすの対義語。「才能を殺す」は才能を発揮させないことで、ここの「生かす」と対になる。"}, {"text": "育てる", "is_correct": false, "explanation": "才能を伸ばす意味で、生かすと同じ方向の語。対義語ではない。"}, {"text": "使う", "is_correct": false, "explanation": "用いる意味で、生かすと同じ方向の語。対義語ではない。"}, {"text": "伸ばす", "is_correct": false, "explanation": "成長させる意味で、生かすと近い方向の語。対義語ではない。"}], "correct_answer": "殺す", "explanations": {"殺す": "生かすの対義語。「才能を殺す」は才能を発揮させないことで、ここの「生かす」と対になる。", "育てる": "才能を伸ばす意味で、生かすと同じ方向の語。対義語ではない。", "使う": "用いる意味で、生かすと同じ方向の語。対義語ではない。", "伸ばす": "成長させる意味で、生かすと近い方向の語。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「良さを生かす」の「良さ」が生かす対象であることを表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「良さへ生かして」では対象として結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「良さより生かして」は文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「良さから生かして」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「良さを生かす」の「良さ」が生かす対象であることを表す。", "へ": "方向の「へ」。「良さへ生かして」では対象として結びつかない。", "より": "比較の「より」。「良さより生かして」は文が成立しない。", "から": "起点の「から」。「良さから生かして」では意味が通らない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "殺す", "is_correct": true, "explanation": "生かすの対義語。「才能を殺す」は才能を発揮させないことで、ここの「生かす」と対になる。"}, {"text": "守る", "is_correct": false, "explanation": "保護する意味で、対義語ではない。"}, {"text": "導く", "is_correct": false, "explanation": "方向を示す意味で、対義語ではない。"}, {"text": "作る", "is_correct": false, "explanation": "生み出す意味で、対義語ではない。"}], "correct_answer": "殺す", "explanations": {"殺す": "生かすの対義語。「才能を殺す」は才能を発揮させないことで、ここの「生かす」と対になる。", "守る": "保護する意味で、対義語ではない。", "導く": "方向を示す意味で、対義語ではない。", "作る": "生み出す意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "持っている能力や特徴を十分に発揮させること。また、命を長らえさせること。", "primary_collocate": null, "pronunciation": "いかす", "ipa": "ikasɯ", "syllable_count": 3, "sentences": [{"text": "彼の才能を生かすには、自由に作らせるのが一番だ。", "target_word": "生かす", "complexity_tier": "T3", "furigana": "彼[かれ]の才能[さいのう]を生[い]かすには、自由[じゆう]に作[つく]らせるのが一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "釣った魚を生かしておくために、バケツに水を入れた。", "target_word": "生かして", "complexity_tier": "T3", "furigana": "釣[つ]った魚[さかな]を生[い]かしておくために、バケツに水[みず]を入[い]れた。", "sentence_source": "generated"}, {"text": "患者を生かすために、医者は一晩中手当てを続けた。", "target_word": "生かす", "complexity_tier": "T4", "furigana": "患者[かんじゃ]を生[い]かすために、医者[いしゃ]は一晩中[ひとばんじゅう]手当[てあ]てを続[つづ]けた。", "sentence_source": "generated"}, {"text": "新しい監督は、選手一人一人の個性を生かすチーム作りをした。", "target_word": "生かす", "complexity_tier": "T4", "furigana": "新[あたら]しい監督[かんとく]は、選手[せんしゅ]一人一人[ひとりひとり]の個性[こせい]を生[い]かすチーム作[づく]りをした。", "sentence_source": "generated"}, {"text": "川で見つけた小さな鳥を、なんとか生かしてやりたかった。", "target_word": "生かして", "complexity_tier": "T4", "furigana": "川[かわ]で見[み]つけた小[ちい]さな鳥[とり]を、なんとか生[い]かしてやりたかった。", "sentence_source": "generated"}, {"text": "長い髪の特徴を生かしたヘアスタイルが人気だ。", "target_word": "生かした", "complexity_tier": "T3", "furigana": "長[なが]い髪[かみ]の特徴[とくちょう]を生[い]かしたヘアスタイルが人気[にんき]だ。", "sentence_source": "generated"}, {"text": "この小さな水槽では、熱帯魚を生かしておくのは難しい。", "target_word": "生かして", "complexity_tier": "T4", "furigana": "この小[ちい]さな水槽[すいそう]では、熱帯魚[ねったいぎょ]を生[い]かしておくのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "声の良さを生かして、彼女はラジオのアナウンサーになった。", "target_word": "生かして", "complexity_tier": "T3", "furigana": "声[こえ]の良[よ]さを生[い]かして、彼女[かのじょ]はラジオのアナウンサーになった。", "sentence_source": "generated"}, {"text": "才能を生かせないまま、彼は仕事をやめてしまった。", "target_word": "生かせない", "complexity_tier": "T3", "furigana": "才能[さいのう]を生[い]かせないまま、彼[かれ]は仕事[しごと]をやめてしまった。", "sentence_source": "generated"}, {"text": "自然の力を生かした農業で、農薬を使わずに野菜を育てている。", "target_word": "生かした", "complexity_tier": "T4", "furigana": "自然[しぜん]の力[ちから]を生[い]かした農業[のうぎょう]で、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生かす", "label": "終止形"}, {"form": "生かして", "label": "て形"}, {"form": "生かした", "label": "た形"}, {"form": "生かさない", "label": "ない形"}, {"form": "生かせる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "才能・個性を発揮させる、または生き物を死なせず生かし続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生かす", "is_correct": true, "explanation": "辞書形。「〜には」で「〜するためには」の目的を表す形なので、ここに合う。"}, {"text": "生かして", "is_correct": false, "explanation": "て形は「〜には」と続かず、文が成立しない。"}, {"text": "生かした", "is_correct": false, "explanation": "た形は「〜には」とつながらず、過去の意味になる。"}, {"text": "生かせ", "is_correct": false, "explanation": "命令形は「〜には」と続かず、文が成立しない。"}], "explanations": {"生かす": "辞書形。「〜には」で「〜するためには」の目的を表す形なので、ここに合う。", "生かして": "て形は「〜には」と続かず、文が成立しない。", "生かした": "た形は「〜には」とつながらず、過去の意味になる。", "生かせ": "命令形は「〜には」と続かず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "生かす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まだ使える布を生かして、ぼろきれにした。", "explanation": "ここは〈ぼろぼろにする〉の意味。生かすは〈持ち味を発揮させる〉なので、布を傷めて使えなくする場面では使わない。"}, {"text": "事故で亡くなった人を、もう一度生かした。", "explanation": "ここは〈生き返らせる〉の意味。生かすは〈死なせずに保つ〉ことなので、死者には使わない。"}, {"text": "熱湯を使って、器具を生かした。", "explanation": "ここは〈殺菌する〉の意味。生かすは〈死なせずに保つ・発揮させる〉なので、菌を殺す場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生かして", "is_correct": true, "explanation": "て形。「〜ておく」に続く形で、生かし続けるという意味になる。"}, {"text": "生かす", "is_correct": false, "explanation": "辞書形は「〜ておく」に続かず、文が成立しない。"}, {"text": "生かせる", "is_correct": false, "explanation": "可能形は「〜ておく」と続かず、意味も通らない。"}, {"text": "生かそう", "is_correct": false, "explanation": "意志形は「〜ておく」と接続せず、文が成立しない。"}], "explanations": {"生かして": "て形。「〜ておく」に続く形で、生かし続けるという意味になる。", "生かす": "辞書形は「〜ておく」に続かず、文が成立しない。", "生かせる": "可能形は「〜ておく」と続かず、意味も通らない。", "生かそう": "意志形は「〜ておく」と接続せず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "生かして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機械を生かして、スクラップにした。", "explanation": "ここは〈捨てる・処分する〉の意味。生かすは〈持ち味を発揮させる・命を保つ〉なので、機械を捨てる場面では使わない。"}, {"text": "汚れを生かして、きれいに磨いた。", "explanation": "ここは〈落とす〉の意味。生かすは〈持ち味を活用する・命を保つ〉なので、汚れを除く動作には使わない。"}, {"text": "沈んだ船を、もう一度生かした。", "explanation": "ここは〈修理して使えるようにする〉の意味。生かすは生きているものや持ち味に使い、沈んだ船には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの才能が生かすには、のびのびさせるのがよい。", "corrected_sentence": "子どもの才能を生かすには、のびのびさせるのがよい。", "error_description": "助詞の誤り。「生かす」の対象は「才能を」で、「才能が」では主語になり、生かす対象にならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生かして", "is_correct": true, "explanation": "て形。「〜ておく」に続く形で、生かし続けるという意味になる。"}, {"text": "生かす", "is_correct": false, "explanation": "辞書形は「〜ておく」に続かない。"}, {"text": "生かした", "is_correct": false, "explanation": "た形は「〜ておく」と接続せず、「生かしたておく」は成立しない。"}, {"text": "生かさない", "is_correct": false, "explanation": "ない形は「〜ておく」と接続せず、「生かさないておく」は成立しない。"}], "correct_form": "生かして", "base_form": "生かす", "form_label": "て形", "sentence_index": 1, "explanations": {"生かして": "て形。「〜ておく」に続く形で、生かし続けるという意味になる。", "生かす": "辞書形は「〜ておく」に続かない。", "生かした": "た形は「〜ておく」と接続せず、「生かしたておく」は成立しない。", "生かさない": "ない形は「〜ておく」と接続せず、「生かさないておく」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51742, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鳥を生かすておくために、毎日えさを与えた。", "corrected_sentence": "小鳥を生かしておくために、毎日えさを与えた。", "error_description": "て形の誤り。「〜ておく」に続くのは「生かして」（て形）で、「生かすて」は形が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生かして", "is_correct": true, "explanation": "て形。「〜て、〜なった」で手段や理由をつなぐ形なので、ここに合う。"}, {"text": "生かせ", "is_correct": false, "explanation": "命令形。「生かせ、」と言い切れず、後ろの文と続かない。"}, {"text": "生かせない", "is_correct": false, "explanation": "ない形。「生かせない、」で切れ、後の文とつながらない。"}, {"text": "生かせる", "is_correct": false, "explanation": "可能形。「生かせる、」の形では文が続かず、意味も通らない。"}], "correct_form": "生かして", "base_form": "生かす", "form_label": "て形", "sentence_index": 7, "explanations": {"生かして": "て形。「〜て、〜なった」で手段や理由をつなぐ形なので、ここに合う。", "生かせ": "命令形。「生かせ、」と言い切れず、後ろの文と続かない。", "生かせない": "ない形。「生かせない、」で切れ、後の文とつながらない。", "生かせる": "可能形。「生かせる、」の形では文が続かず、意味も通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
