INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51745, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かっこよくないけれど、しっかりしていること。", "primary_collocate": null, "pronunciation": "ぶこつ", "ipa": "bɯkotsɯ", "syllable_count": 3, "sentences": [{"text": "このかばんは無骨ですが、十年使っても壊れません。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "このかばんは無骨[ぶこつ]ですが、十年[じゅうねん]使[つか]っても壊[こわ]れません。", "sentence_source": "generated"}, {"text": "無骨な靴ですが、雨の日でも足が濡れないので助かります。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "無骨[ぶこつ]な靴[くつ]ですが、雨[あめ]の日[ひ]でも足[あし]が濡[ぬ]れないので助[たす]かります。", "sentence_source": "generated"}, {"text": "祖父の無骨な作業机は、今でもしっかりしています。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "祖父[そふ]の無骨[ぶこつ]な作業机[さぎょうづくえ]は、今[いま]でもしっかりしています。", "sentence_source": "generated"}, {"text": "見た目は無骨でも、この自転車は丈夫なので毎日使えます。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "見[み]た目[め]は無骨[ぶこつ]でも、この自転車[じてんしゃ]は丈夫[じょうぶ]なので毎日[まいにち]使[つか]えます。", "sentence_source": "generated"}, {"text": "無骨な道具のほうが、現場では安心して使えます。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "無骨[ぶこつ]な道具[どうぐ]のほうが、現場[げんば]では安心[あんしん]して使[つか]えます。", "sentence_source": "generated"}, {"text": "父は無骨な人ですが、困ったときはいつも助けてくれます。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "父[ちち]は無骨[ぶこつ]な人[ひと]ですが、困[こま]ったときはいつも助[たす]けてくれます。", "sentence_source": "generated"}, {"text": "この時計は無骨な形ですが、時間が正確です。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "この時計[とけい]は無骨[ぶこつ]な形[かたち]ですが、時間[じかん]が正確[せいかく]です。", "sentence_source": "generated"}, {"text": "無骨な鉄の門は、台風の日にもびくともしませんでした。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "無骨[ぶこつ]な鉄[てつ]の門[もん]は、台風[たいふう]の日[ひ]にもびくともしませんでした。", "sentence_source": "generated"}, {"text": "おしゃれではなくても、無骨で頑丈な家具を選びました。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "おしゃれではなくても、無骨[ぶこつ]で頑丈[がんじょう]な家具[かぐ]を選[えら]びました。", "sentence_source": "generated"}, {"text": "彼は見た目を気にしませんが、無骨で頼りになる人です。", "target_word": "無骨", "complexity_tier": "T3", "furigana": "彼[かれ]は見[み]た目[め]を気[き]にしませんが、無骨[ぶこつ]で頼[たよ]りになる人[ひと]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無骨", "label": "語幹"}, {"form": "無骨だ", "label": "終止形"}, {"form": "無骨な", "label": "連体形"}, {"form": "無骨に", "label": "連用形"}, {"form": "無骨で", "label": "て形"}], "register": "neutral", "sense_fingerprint": "見た目は飾りがなくかっこよくないが、作りが頑丈でしっかりしているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51745, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寡黙", "is_correct": false, "explanation": "「寡黙ですが、十年使っても壊れません」は文として成立せず、かばんの描写に合わない。"}, {"text": "無骨", "is_correct": true, "explanation": "かっこよくないが頑丈だという意味で、「ですが、十年使っても壊れません」と対比が成り立つ。"}, {"text": "陽気", "is_correct": false, "explanation": "明るい性格の形容で、かばんの描写には使えない。"}, {"text": "神妙", "is_correct": false, "explanation": "かしこまった態度の形容で、かばんの描写には合わない。"}], "explanations": {"寡黙": "「寡黙ですが、十年使っても壊れません」は文として成立せず、かばんの描写に合わない。", "無骨": "かっこよくないが頑丈だという意味で、「ですが、十年使っても壊れません」と対比が成り立つ。", "陽気": "明るい性格の形容で、かばんの描写には使えない。", "神妙": "かしこまった態度の形容で、かばんの描写には合わない。"}, "sentence_index": 0, "correct_answer": "無骨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は無骨に謝ったが、相手は少しも許してくれなかった。", "explanation": "ここは〈不器用で無愛想〉の意味。謝り方の不器用さを表し、物の頑丈さを表す本語義とは別。"}, {"text": "店の主人は無骨で、客に愛想を見せない。", "explanation": "ここは〈不器用で無愛想〉の意味。態度の無愛想さを表し、本語義の見た目の描写とは別。"}, {"text": "彼は無骨な言い方しかできず、誤解されやすい。", "explanation": "ここは〈不器用で無愛想〉の意味。話し方の粗さを表し、本語義の作りの頑丈さとは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51745, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饒舌", "is_correct": false, "explanation": "話し好きの意味で、時計の形の描写にはならない。"}, {"text": "無邪気", "is_correct": false, "explanation": "あどけない性格の形容で、時計の形には使えない。"}, {"text": "無骨", "is_correct": true, "explanation": "飾り気がなく頑丈そうな形を表し、「この時計は＿な形ですが」の描写に合う。"}, {"text": "健気", "is_correct": false, "explanation": "けなげな態度の形容で、形の描写には合わない。"}], "explanations": {"饒舌": "話し好きの意味で、時計の形の描写にはならない。", "無邪気": "あどけない性格の形容で、時計の形には使えない。", "無骨": "飾り気がなく頑丈そうな形を表し、「この時計は＿な形ですが」の描写に合う。", "健気": "けなげな態度の形容で、形の描写には合わない。"}, "sentence_index": 6, "correct_answer": "無骨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "受付の人は無骨で、客の問いにそっけなく答えた。", "explanation": "ここは〈不器用で無愛想〉の意味。応対のそっけなさを表し、本語義の頑丈さの描写とは別。"}, {"text": "彼は無骨な物言いで、友人を怒らせてしまった。", "explanation": "ここは〈不器用で無愛想〉の意味。物言いの粗さを表し、本語義の見た目の描写とは別。"}, {"text": "彼は無骨に頭を下げたが、言葉はひと言も出てこなかった。", "explanation": "ここは〈不器用で無愛想〉の意味。ぎこちなさと無愛想さを表し、本語義とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51745, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この靴は無骨ので、雨の日も安心です。", "corrected_sentence": "この靴は無骨なので、雨の日も安心です。", "error_description": "形状詞「無骨」は「ので」の前に「な」が必要。「無骨ので」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無骨", "is_correct": true, "explanation": "文中の「無骨な靴」の語幹。基本形「無骨だ」から「だ」を除いた形。"}, {"text": "無骨で", "is_correct": false, "explanation": "て形。名詞「靴」を修飾する位置には入らない。"}, {"text": "無骨に", "is_correct": false, "explanation": "連用形。名詞「靴」を修飾できず、ここでは不適。"}, {"text": "無骨だった", "is_correct": false, "explanation": "過去形。現在の描写を表す文には合わない。"}], "correct_form": "無骨", "base_form": "無骨だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"無骨": "文中の「無骨な靴」の語幹。基本形「無骨だ」から「だ」を除いた形。", "無骨で": "て形。名詞「靴」を修飾する位置には入らない。", "無骨に": "連用形。名詞「靴」を修飾できず、ここでは不適。", "無骨だった": "過去形。現在の描写を表す文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51745, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この箱は無骨くて、とても頑丈です。", "corrected_sentence": "この箱は無骨で、とても頑丈です。", "error_description": "「無骨」は形状詞なので「く」では活用せず、て形は「で」。「くて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無骨", "is_correct": true, "explanation": "文中の「無骨な門」の語幹。基本形「無骨だ」から「だ」を除いた形。"}, {"text": "無骨ならば", "is_correct": false, "explanation": "仮定形。名詞「門」を修飾する位置には入らない。"}, {"text": "無骨だろう", "is_correct": false, "explanation": "推量形。名詞を修飾できず、ここでは不適。"}, {"text": "無骨ではない", "is_correct": false, "explanation": "否定形。肯定の描写を表す文には合わない。"}], "correct_form": "無骨", "base_form": "無骨だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"無骨": "文中の「無骨な門」の語幹。基本形「無骨だ」から「だ」を除いた形。", "無骨ならば": "仮定形。名詞「門」を修飾する位置には入らない。", "無骨だろう": "推量形。名詞を修飾できず、ここでは不適。", "無骨ではない": "否定形。肯定の描写を表す文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
