INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51747, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても大きいこと。", "primary_collocate": null, "pronunciation": "ただい", "ipa": "tadai", "syllable_count": 3, "sentences": [{"text": "台風は果樹園に多大な被害を与え、収穫量が半分に減った。", "target_word": "多大", "complexity_tier": "T3", "furigana": "台風[たいふう]は果樹園[かじゅえん]に多大[ただい]な被害[ひがい]を与[あた]え、収穫量[しゅうかくりょう]が半分[はんぶん]に減[へ]った。", "sentence_source": "generated"}, {"text": "彼女の寄付は、図書館の建設に多大な力となった。", "target_word": "多大", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の寄付[きふ]は、図書館[としょかん]の建設[けんせつ]に多大[ただい]な力[ちから]となった。", "sentence_source": "generated"}, {"text": "発表の準備には、多大な時間がかかりました。", "target_word": "多大", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の準備[じゅんび]には、多大[ただい]な時間[じかん]がかかりました。", "sentence_source": "generated"}, {"text": "多大なご協力に、心より感謝申し上げます。", "target_word": "多大", "complexity_tier": "T3", "furigana": "多大[ただい]なご協力[きょうりょく]に、心[こころ]より感謝[かんしゃ]申[もう]し上[あ]げます。", "sentence_source": "generated"}, {"text": "円安は輸入業者に多大な負担を強いている。", "target_word": "多大", "complexity_tier": "T3", "furigana": "円安[えんやす]は輸入業者[ゆにゅうぎょうしゃ]に多大[ただい]な負担[ふたん]を強[し]いている。", "sentence_source": "generated"}, {"text": "彼の発見は、医学の進歩に多大な意義がある。", "target_word": "多大", "complexity_tier": "T3", "furigana": "彼[かれ]の発見[はっけん]は、医学[いがく]の進歩[しんぽ]に多大[ただい]な意義[いぎ]がある。", "sentence_source": "generated"}, {"text": "会議の遅れで、取引先に多大な迷惑をかけてしまった。", "target_word": "多大", "complexity_tier": "T3", "furigana": "会議[かいぎ]の遅[おく]れで、取引先[とりひきさき]に多大[ただい]な迷惑[めいわく]をかけてしまった。", "sentence_source": "generated"}, {"text": "この教授は、後輩の育成に多大な情熱を注いできた。", "target_word": "多大", "complexity_tier": "T3", "furigana": "この教授[きょうじゅ]は、後輩[こうはい]の育成[いくせい]に多大[ただい]な情熱[じょうねつ]を注[そそ]いできた。", "sentence_source": "generated"}, {"text": "多大な犠牲を払って、ようやく町は復興した。", "target_word": "多大", "complexity_tier": "T3", "furigana": "多大[ただい]な犠牲[ぎせい]を払[はら]って、ようやく町[まち]は復興[ふっこう]した。", "sentence_source": "generated"}, {"text": "広告の効果は多大で、売り上げが三倍になった。", "target_word": "多大", "complexity_tier": "T3", "furigana": "広告[こうこく]の効果[こうか]は多大[ただい]で、売[う]り上[あ]げが三倍[さんばい]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多大だ", "label": "終止形"}, {"form": "多大な", "label": "連体形"}, {"form": "多大に", "label": "連用形"}, {"form": "多大で", "label": "連用形（で）"}], "register": "formal", "sense_fingerprint": "規模・量・程度がとても大きいこと。被害・協力・負担・犠牲などに付く改まった表現。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多大", "is_correct": true, "explanation": "「非常に大きい」の意味で、台風が与えた「被害」の大きさを修飾するのに合う。"}, {"text": "穏やか", "is_correct": false, "explanation": "「静かで落ち着いた」様子を表し、被害の大きさとは合わない。"}, {"text": "華やか", "is_correct": false, "explanation": "「派手で明るい」様子の意味で、被害には使えない。"}, {"text": "清潔", "is_correct": false, "explanation": "「汚れがなく清らかな」意味で、被害の大きさを表さない。"}], "explanations": {"多大": "「非常に大きい」の意味で、台風が与えた「被害」の大きさを修飾するのに合う。", "穏やか": "「静かで落ち着いた」様子を表し、被害の大きさとは合わない。", "華やか": "「派手で明るい」様子の意味で、被害には使えない。", "清潔": "「汚れがなく清らかな」意味で、被害の大きさを表さない。"}, "sentence_index": 0, "correct_answer": "多大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は多大な品ぞろえで、探し物が見つかりやすい。", "explanation": "ここは〈豊富〉の意味。品数の多さには豊富を使い、多大は被害や協力など影響の大きさに付く。"}, {"text": "この古い手紙は多大な資料として、大学に保管されている。", "explanation": "ここは〈貴重〉の意味。価値の高さには貴重を使い、多大は量や程度の大きさを表す。"}, {"text": "彼は多大な腕力で、重い箱を軽々と運んだ。", "explanation": "ここは〈強力〉の意味。腕力の強さには強力を使い、多大は被害や負担などに付く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多大", "is_correct": true, "explanation": "「非常に大きい」の意味で、会議の遅れが相手に与えた「迷惑」の大きさを修飾するのに合う。"}, {"text": "陽気", "is_correct": false, "explanation": "「明るく楽しい」様子の意味で、迷惑には使えない。"}, {"text": "頑丈", "is_correct": false, "explanation": "「がっしりして壊れにくい」の意味で、迷惑とは関係がない。"}, {"text": "素直", "is_correct": false, "explanation": "「ひねくれていない」性格を表し、迷惑の大きさを表さない。"}], "explanations": {"多大": "「非常に大きい」の意味で、会議の遅れが相手に与えた「迷惑」の大きさを修飾するのに合う。", "陽気": "「明るく楽しい」様子の意味で、迷惑には使えない。", "頑丈": "「がっしりして壊れにくい」の意味で、迷惑とは関係がない。", "素直": "「ひねくれていない」性格を表し、迷惑の大きさを表さない。"}, "sentence_index": 6, "correct_answer": "多大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は多大な心配性で、準備に時間をかけすぎてしまう。", "explanation": "ここは〈過剰〉の意味。心配のしすぎには過剰を使い、多大は被害や協力など影響の大きさに付く。"}, {"text": "開会式は多大に行われ、町中がお祝いムードになった。", "explanation": "ここは〈盛大〉の意味。式典の派手さには盛大を使い、多大は量や程度の大きさを表すので合わない。"}, {"text": "彼は多大な発言で、会議の場を驚かせた。", "explanation": "ここは〈大胆〉の意味。思い切った発言には大胆を使い、多大は被害や負担など影響の大きさに付く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "値上げは家計に多大を負担をかけている。", "corrected_sentence": "値上げは家計に多大な負担をかけている。", "error_description": "誤りは「多大を」。形状詞の「多大」は名詞の「負担」を修飾するので「多大な」とする。「を」では名詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多大な", "is_correct": true, "explanation": "形状詞の連体形。名詞「力」の前で「多大な」の形になる。"}, {"text": "多大だ", "is_correct": false, "explanation": "終止形で、文末に置いて述語になる。「力」の前に置いて修飾することはできない。"}, {"text": "多大に", "is_correct": false, "explanation": "連用形で、動詞や形容詞の前で様子を表す。名詞「力」を直接修飾できない。"}, {"text": "多大で", "is_correct": false, "explanation": "連用形（で）で、文を続けるときに使う。名詞「力」の前では文が成り立たない。"}], "correct_form": "多大な", "base_form": "多大", "form_label": "連体形", "sentence_index": 1, "explanations": {"多大な": "形状詞の連体形。名詞「力」の前で「多大な」の形になる。", "多大だ": "終止形で、文末に置いて述語になる。「力」の前に置いて修飾することはできない。", "多大に": "連用形で、動詞や形容詞の前で様子を表す。名詞「力」を直接修飾できない。", "多大で": "連用形（で）で、文を続けるときに使う。名詞「力」の前では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の人々は、町の復興に多大を努力を注いだ。", "corrected_sentence": "地域の人々は、町の復興に多大な努力を注いだ。", "error_description": "誤りは「多大を」。形状詞の「多大」は名詞の「努力」を修飾するので「多大な」とする。「を」は格助詞で、修飾には使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多大な", "is_correct": true, "explanation": "形状詞の連体形。名詞「情熱」の前で「多大な」の形になる。"}, {"text": "多大でない", "is_correct": false, "explanation": "否定の形で、文末の述語になる。名詞「情熱」の前に置いて修飾することはできない。"}, {"text": "多大であった", "is_correct": false, "explanation": "過去の断定の形で、文末の述語になる。名詞「情熱」の前には置けない。"}, {"text": "多大ならば", "is_correct": false, "explanation": "仮定の条件を表す形で、名詞「情熱」を直接修飾することはできない。"}], "correct_form": "多大な", "base_form": "多大", "form_label": "連体形", "sentence_index": 7, "explanations": {"多大な": "形状詞の連体形。名詞「情熱」の前で「多大な」の形になる。", "多大でない": "否定の形で、文末の述語になる。名詞「情熱」の前に置いて修飾することはできない。", "多大であった": "過去の断定の形で、文末の述語になる。名詞「情熱」の前には置けない。", "多大ならば": "仮定の条件を表す形で、名詞「情熱」を直接修飾することはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
