INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51748, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数量や程度が非常に大きいさま。", "primary_collocate": null, "pronunciation": "ただい", "ipa": "tadai", "syllable_count": 3, "sentences": [{"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "多大", "complexity_tier": "T3", "furigana": "コンクリートの打[う]ちっぱなしという素材感[そざいかん]を活[い]かした設計[せっけい]は、入居者[にゅうきょしゃ]のコミュニティ形成[けいせい]に多大[ただい]な社会的[しゃかいてき]影響[えいきょう]を与[あた]えました。", "sentence_source": "mined"}, {"text": "今回の災害は、地域の農業に多大な被害をもたらした。", "target_word": "多大", "complexity_tier": "T3", "furigana": "今回[こんかい]の災害[さいがい]は、地域[ちいき]の農業[のうぎょう]に多大[ただい]な被害[ひがい]をもたらした。", "sentence_source": "generated"}, {"text": "山田さんは長年、会社の発展に多大な貢献をしてきました。", "target_word": "多大", "complexity_tier": "T3", "furigana": "山田[やまだ]さんは長年[ながねん]、会社[かいしゃ]の発展[はってん]に多大[ただい]な貢献[こうけん]をしてきました。", "sentence_source": "generated"}, {"text": "突然の工事のため、近所の皆さまに多大なご迷惑をおかけしました。", "target_word": "多大", "complexity_tier": "T3", "furigana": "突然[とつぜん]の工事[こうじ]のため、近所[きんじょ]の皆[みな]さまに多大[ただい]なご迷惑[めいわく]をおかけしました。", "sentence_source": "generated"}, {"text": "この計画を実現するには、多大な費用と時間が必要だ。", "target_word": "多大", "complexity_tier": "T3", "furigana": "この計画[けいかく]を実現[じつげん]するには、多大[ただい]な費用[ひよう]と時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は試験に合格するために、多大な努力を重ねた。", "target_word": "多大", "complexity_tier": "T3", "furigana": "彼[かれ]は試験[しけん]に合格[ごうかく]するために、多大[ただい]な努力[どりょく]を重[かさ]ねた。", "sentence_source": "generated"}, {"text": "新しい技術の登場は、社会に多大な変化を与えた。", "target_word": "多大", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]の登場[とうじょう]は、社会[しゃかい]に多大[ただい]な変化[へんか]を与[あた]えた。", "sentence_source": "generated"}, {"text": "先生から多大なご支援をいただき、無事に研究を終えられました。", "target_word": "多大", "complexity_tier": "T3", "furigana": "先生[せんせい]から多大[ただい]なご支援[しえん]をいただき、無事[ぶじ]に研究[けんきゅう]を終[お]えられました。", "sentence_source": "generated"}, {"text": "事故の影響で、工場は多大な損害を受けた。", "target_word": "多大", "complexity_tier": "T3", "furigana": "事故[じこ]の影響[えいきょう]で、工場[こうじょう]は多大[ただい]な損害[そんがい]を受[う]けた。", "sentence_source": "generated"}, {"text": "多大な期待を背負って、その選手は試合に臨んだ。", "target_word": "多大", "complexity_tier": "T3", "furigana": "多大[ただい]な期待[きたい]を背負[せお]って、その選手[せんしゅ]は試合[しあい]に臨[のぞ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多大だ", "label": "終止形"}, {"form": "多大な", "label": "連体形"}, {"form": "多大に", "label": "連用形"}, {"form": "多大で", "label": "連用形（で）"}], "register": "formal", "sense_fingerprint": "数量・程度が非常に大きいさま。影響・被害・迷惑・貢献などに付く硬い書き言葉。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51748, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多大", "is_correct": true, "explanation": "「非常に大きい」の意味で、「社会的影響」の大きさを修飾するのに合う。"}, {"text": "無邪気", "is_correct": false, "explanation": "「無邪気」は子どもらしく純真な様子で、影響の大きさとは関係がない。"}, {"text": "不器用", "is_correct": false, "explanation": "「下手な」の意味で、影響の大きさとは関係がない。"}, {"text": "陽気", "is_correct": false, "explanation": "「明るく楽しい」様子を表し、影響には使えない。"}], "explanations": {"多大": "「非常に大きい」の意味で、「社会的影響」の大きさを修飾するのに合う。", "無邪気": "「無邪気」は子どもらしく純真な様子で、影響の大きさとは関係がない。", "不器用": "「下手な」の意味で、影響の大きさとは関係がない。", "陽気": "「明るく楽しい」様子を表し、影響には使えない。"}, "sentence_index": 0, "correct_answer": "多大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その講演会には多大な人が集まり、会場は入りきれないほどだった。", "explanation": "ここは〈大勢〉の意味。多大は影響や被害など抽象的なことの大きさに付き、人の数には使わない。"}, {"text": "この工場では毎日多大な製品を作り、全国に出荷している。", "explanation": "ここは〈大量〉の意味。製品の数量には大量を使い、多大は影響や貢献などに付く。"}, {"text": "彼は多大な体で、ドアをくぐるのにいつも苦労していた。", "explanation": "ここは〈巨大〉の意味。体の大きさには巨大や大柄を使い、多大は人や物の体の大きさには付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51748, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多大", "is_correct": true, "explanation": "「非常に大きい」の意味で、「変化」の大きさを修飾するのに合う。"}, {"text": "清楚", "is_correct": false, "explanation": "「清らかで整っている」様子を表し、変化の大きさとは関係がない。"}, {"text": "頑丈", "is_correct": false, "explanation": "「がっしりして壊れにくい」の意味で、変化には使えない。"}, {"text": "不潔", "is_correct": false, "explanation": "「汚れている」の意味で、変化の大きさを表さない。"}], "explanations": {"多大": "「非常に大きい」の意味で、「変化」の大きさを修飾するのに合う。", "清楚": "「清らかで整っている」様子を表し、変化の大きさとは関係がない。", "頑丈": "「がっしりして壊れにくい」の意味で、変化には使えない。", "不潔": "「汚れている」の意味で、変化の大きさを表さない。"}, "sentence_index": 6, "correct_answer": "多大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議では立場の違う人から多大な意見が出て、議論が白熱した。", "explanation": "ここは〈多様〉の意味。意見の種類の豊かさには多様を使い、多大は量や程度の大きさを表すので合わない。"}, {"text": "彼は多大な声で、遠くの仲間に呼びかけた。", "explanation": "ここは〈大声〉の意味。声の大きさには大声を使い、多大は被害や影響など抽象的なことの大きさに付くので合わない。"}, {"text": "彼の話は多大な表現が多く、どこまで本当かわからない。", "explanation": "ここは〈大げさ〉の意味。誇張した言い方には大げさを使い、多大は被害や影響など実際の大きさに付くので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51748, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は長年、町の祭りの運営に多大を貢献をしてきた。", "corrected_sentence": "父は長年、町の祭りの運営に多大な貢献をしてきた。", "error_description": "誤りは「多大を」。多大は形状詞なので、名詞の「貢献」を修飾するには「多大な」とする。「を」は目的語を示す格助詞で、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多大な", "is_correct": true, "explanation": "形状詞の連体形。名詞「被害」の前で「多大な」の形になる。"}, {"text": "多大だ", "is_correct": false, "explanation": "終止形で文末の述語になる形。「被害」の前に置いて修飾することはできない。"}, {"text": "多大に", "is_correct": false, "explanation": "連用形で、動詞や形容詞の前に置いて様子を表す。名詞「被害」を直接修飾できない。"}, {"text": "多大で", "is_correct": false, "explanation": "連用形（で）で、文を続けるときに使う。「被害」を直接修飾しないので、この位置には合わない。"}], "correct_form": "多大な", "base_form": "多大", "form_label": "連体形", "sentence_index": 1, "explanations": {"多大な": "形状詞の連体形。名詞「被害」の前で「多大な」の形になる。", "多大だ": "終止形で文末の述語になる形。「被害」の前に置いて修飾することはできない。", "多大に": "連用形で、動詞や形容詞の前に置いて様子を表す。名詞「被害」を直接修飾できない。", "多大で": "連用形（で）で、文を続けるときに使う。「被害」を直接修飾しないので、この位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51748, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新薬の開発には多大を費用がかかった。", "corrected_sentence": "新薬の開発には多大な費用がかかった。", "error_description": "誤りは「多大を」。形状詞の「多大」は名詞の「費用」を修飾するので「多大な」とする。「を」は目的語の格助詞で、ここでは使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多大な", "is_correct": true, "explanation": "形状詞の連体形。名詞「ご支援」の前で「多大な」の形になる。"}, {"text": "多大である", "is_correct": false, "explanation": "硬い言い方の断定の形で、文の述語になる。「ご支援」の前に置いて名詞を修飾することはできない。"}, {"text": "多大であった", "is_correct": false, "explanation": "過去の断定の形で、文末の述語になる。「ご支援」の前には置けず、名詞を修飾できない。"}, {"text": "多大ならば", "is_correct": false, "explanation": "仮定の条件を表す形で、「ご支援」を直接修飾することはできない。"}], "correct_form": "多大な", "base_form": "多大", "form_label": "連体形", "sentence_index": 7, "explanations": {"多大な": "形状詞の連体形。名詞「ご支援」の前で「多大な」の形になる。", "多大である": "硬い言い方の断定の形で、文の述語になる。「ご支援」の前に置いて名詞を修飾することはできない。", "多大であった": "過去の断定の形で、文末の述語になる。「ご支援」の前には置けず、名詞を修飾できない。", "多大ならば": "仮定の条件を表す形で、「ご支援」を直接修飾することはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「外観に惹かれる」と、感情を引き起こす対象を示す。「惹かれる」の対象として外観を取るので「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「惹かれる」は「に」で対象を取るので「を」では成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「外観が惹かれて」では感情の対象が示せず不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「外観へ惹かれて」では対象の関係を表せない。"}], "correct_answer": "に", "explanations": {"に": "「外観に惹かれる」と、感情を引き起こす対象を示す。「惹かれる」の対象として外観を取るので「に」が正しい。", "を": "目的語を示すが、「惹かれる」は「に」で対象を取るので「を」では成り立たない。", "が": "主語を示すが、「外観が惹かれて」では感情の対象が示せず不自然になる。", "へ": "方向を示すが、「外観へ惹かれて」では対象の関係を表せない。"}, "error_tags": {"を": "目的語・対象", "が": "主語・主題", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「外観が変わった」と、変化する主語を示す。「変わる」の主語として外観を取るので「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「変わる」は自動詞なので「を」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「外観で変わった」では変化の主体が示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、「外観より変わった」では変化の主体として不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「外観が変わった」と、変化する主語を示す。「変わる」の主語として外観を取るので「が」が正しい。", "を": "目的語を示すが、「変わる」は自動詞なので「を」では文が成り立たない。", "で": "場所や手段を示すが、「外観で変わった」では変化の主体が示せない。", "より": "比較の基準を示すが、「外観より変わった」では変化の主体として不自然になる。"}, "error_tags": {"を": "目的語・対象", "で": "場所・手段", "より": "比較の基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の外から見える形や様子のことです。", "primary_collocate": null, "pronunciation": "がいかん", "ipa": "ɡaikaɴ", "syllable_count": 4, "sentences": [{"text": "新築マンションの外観は、白い壁と大きな窓が特徴だ。", "target_word": "外観", "complexity_tier": "T3", "furigana": "新築[しんちく]マンションの外観[がいかん]は、白[しろ]い壁[かべ]と大[おお]きな窓[まど]が特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "彼は、店の外観に惹かれて入ってみたそうだ。", "target_word": "外観", "complexity_tier": "T3", "furigana": "彼[かれ]は、店[みせ]の外観[がいかん]に惹[ひ]かれて入[はい]ってみたそうだ。", "sentence_source": "generated"}, {"text": "その城は、外観は昔のままだが、内部は博物館になっている。", "target_word": "外観", "complexity_tier": "T3", "furigana": "その城[しろ]は、外観[がいかん]は昔[むかし]のままだが、内部[ないぶ]は博物館[はくぶつかん]になっている。", "sentence_source": "generated"}, {"text": "外観がおしゃれなカフェは、女性客に人気がある。", "target_word": "外観", "complexity_tier": "T3", "furigana": "外観[がいかん]がおしゃれなカフェは、女性客[じょせいきゃく]に人気[にんき]がある。", "sentence_source": "generated"}, {"text": "不動産の広告では、外観の写真が最初に載っている。", "target_word": "外観", "complexity_tier": "T3", "furigana": "不動産[ふどうさん]の広告[こうこく]では、外観[がいかん]の写真[しゃしん]が最初[さいしょ]に載[の]っている。", "sentence_source": "generated"}, {"text": "この小さな橋は、外観こそ質素だが、百年以上も人々を支えてきた。", "target_word": "外観", "complexity_tier": "T3", "furigana": "この小[ちい]さな橋[はし]は、外観[がいかん]こそ質素[しっそ]だが、百年[ひゃくねん]以上[いじょう]も人々[ひとびと]を支[ささ]えてきた。", "sentence_source": "generated"}, {"text": "家電を中古で売るなら、外観をきれいに拭いておくと高く売れる。", "target_word": "外観", "complexity_tier": "T3", "furigana": "家電[かでん]を中古[ちゅうこ]で売[う]るなら、外観[がいかん]をきれいに拭[ふ]いておくと高[たか]く売[う]れる。", "sentence_source": "generated"}, {"text": "美術館の外観が変わったので、道に迷ってしまった。", "target_word": "外観", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]の外観[がいかん]が変[か]わったので、道[みち]に迷[まよ]ってしまった。", "sentence_source": "generated"}, {"text": "外観の印象だけで、その会社の良し悪しを決めてはいけない。", "target_word": "外観", "complexity_tier": "T3", "furigana": "外観[がいかん]の印象[いんしょう]だけで、その会社[かいしゃ]の良[よ]し悪[あ]しを決[き]めてはいけない。", "sentence_source": "generated"}, {"text": "新しい校舎の外観は、森の木々と調和するように設計された。", "target_word": "外観", "complexity_tier": "T3", "furigana": "新[あたら]しい校舎[こうしゃ]の外観[がいかん]は、森[もり]の木々[きぎ]と調和[ちょうわ]するように設計[せっけい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外観", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物や建物の外から見える形や様子。見た目の印象を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外観", "is_correct": true, "explanation": "物や建物の外から見える形や様子を表し、「白い壁と大きな窓が特徴」という文に合う。"}, {"text": "立地", "is_correct": false, "explanation": "場所の条件を指し、白い壁や窓といった見た目の特徴とは合わない。"}, {"text": "評判", "is_correct": false, "explanation": "世間の評価を表し、壁や窓の特徴を述べる文には合わない。"}, {"text": "値段", "is_correct": false, "explanation": "価格を指し、建物の見た目の特徴を表さない。"}], "explanations": {"外観": "物や建物の外から見える形や様子を表し、「白い壁と大きな窓が特徴」という文に合う。", "立地": "場所の条件を指し、白い壁や窓といった見た目の特徴とは合わない。", "評判": "世間の評価を表し、壁や窓の特徴を述べる文には合わない。", "値段": "価格を指し、建物の見た目の特徴を表さない。"}, "sentence_index": 0, "correct_answer": "外観"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くなった外観を張り替えて、屋根を直した。", "explanation": "ここは〈外装〉の意味。張り替える対象は外装で、外観は見た目を表すので張り替えの対象にはならない。"}, {"text": "この橋は外観が丈夫で、大地震にも耐えられる。", "explanation": "ここは〈強度〉の意味。丈夫さや強さには強度を使い、外観は物の見た目を表すので合わない。"}, {"text": "彼は外観が若く見えるので、年齢を聞いて驚く。", "explanation": "ここは〈風貌〉の意味。人の顔つきや雰囲気には風貌を使い、外観は物の見た目に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外観", "is_correct": true, "explanation": "物の外から見える形や様子を表し、家電の「きれいに拭く」対象として合う。"}, {"text": "保証", "is_correct": false, "explanation": "故障時の無償修理の約束を指し、拭く対象にはならない。"}, {"text": "電源", "is_correct": false, "explanation": "電気を供給する装置や状態を指し、拭いて手入れする対象としては合わない。"}, {"text": "設定", "is_correct": false, "explanation": "機械の動作の決まりを指し、拭く対象ではない。"}], "explanations": {"外観": "物の外から見える形や様子を表し、家電の「きれいに拭く」対象として合う。", "保証": "故障時の無償修理の約束を指し、拭く対象にはならない。", "電源": "電気を供給する装置や状態を指し、拭いて手入れする対象としては合わない。", "設定": "機械の動作の決まりを指し、拭く対象ではない。"}, "sentence_index": 6, "correct_answer": "外観"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は外観の医師で、難しい手術を得意としている。", "explanation": "ここは〈外科〉の意味。医療の分野には外科を使い、外観は物の外から見た様子を表すので医師には使わない。"}, {"text": "窓を開けると外観が冷たく、部屋の温度が下がった。", "explanation": "ここは〈外気〉の意味。窓の外の空気には外気を使い、外観は物の見た目を表すので合わない。"}, {"text": "この店には外観から来た客が多く、英語が飛び交っている。", "explanation": "ここは〈外国〉の意味。国の外には外国を使い、外観は物の外から見える様子に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このビルは外観を新しく見えるが、中は古い。", "corrected_sentence": "このビルは外観が新しく見えるが、中は古い。", "error_description": "誤りは「外観を」。「新しく見える」の主語は「外観が」と格助詞「が」で示す。「を」は目的語になり、「見える」と文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51749, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ビルの外観を焼き直して、色を変えた。", "corrected_sentence": "ビルの外観を塗り直して、色を変えた。", "error_description": "誤りは「焼き直す」。外観の色を変えるには「塗り直す」を使う。「焼き直す」は作り直しや再加熱の意味で、外観の見た目を変える動作としては合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
