INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51750, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「外観を守る」と目的語を示す。「守る」の対象として外観を取るので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「外観が守る」では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点や位置を示すが、「外観に守る」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「外観へ守る」では対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「外観を守る」と目的語を示す。「守る」の対象として外観を取るので「を」が正しい。", "が": "主語を示すが、「外観が守る」では意味が通らない。", "に": "帰着点や位置を示すが、「外観に守る」では文が成り立たない。", "へ": "方向を示すが、「外観へ守る」では対象を示せない。"}, "error_tags": {"が": "主語・主題", "に": "位置・帰着点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51750, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の外側から見たときの、形や色、模様などの見た目。", "primary_collocate": null, "pronunciation": "がいかん", "ipa": "ɡaikaɴ", "syllable_count": 4, "sentences": [{"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "外観", "complexity_tier": "T3", "furigana": "しかし、その無骨[ぶこつ]な外観[がいかん]や維持管理[いじかんり]の難[むずか]しさから、現在[げんざい]ではその価値[かち]が再評価[さいひょうか]される一方[いっぽう]で、取[と]り壊[こわ]されるケースも増[ふ]えています。", "sentence_source": "mined"}, {"text": "この家は外観は古いが、中はとても新しくて住みやすい。", "target_word": "外観", "complexity_tier": "T3", "furigana": "この家[いえ]は外観[がいかん]は古[ふる]いが、中[なか]はとても新[あたら]しくて住[す]みやすい。", "sentence_source": "generated"}, {"text": "新しい駅ビルは、ガラスを使った美しい外観が話題になっている。", "target_word": "外観", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ビルは、ガラスを使[つか]った美[うつく]しい外観[がいかん]が話題[わだい]になっている。", "sentence_source": "generated"}, {"text": "中古車を買うときは、外観だけでなくエンジンの状態も確認してください。", "target_word": "外観", "complexity_tier": "T3", "furigana": "中古車[ちゅうこしゃ]を買[か]うときは、外観[がいかん]だけでなくエンジンの状態[じょうたい]も確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "建物の外観を変えずに、内部だけを改装した。", "target_word": "外観", "complexity_tier": "T3", "furigana": "建物[たてもの]の外観[がいかん]を変[か]えずに、内部[ないぶ]だけを改装[かいそう]した。", "sentence_source": "generated"}, {"text": "外観は地味だが、このレストランの料理は絶品だ。", "target_word": "外観", "complexity_tier": "T3", "furigana": "外観[がいかん]は地味[じみ]だが、このレストランの料理[りょうり]は絶品[ぜっぴん]だ。", "sentence_source": "generated"}, {"text": "市役所の外観は、周りの景色に合わせて落ち着いた色になっている。", "target_word": "外観", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]の外観[がいかん]は、周[まわ]りの景色[けしき]に合[あ]わせて落[お]ち着[つ]いた色[いろ]になっている。", "sentence_source": "generated"}, {"text": "古い寺の外観を守るため、屋根の修理には昔と同じ瓦を使った。", "target_word": "外観", "complexity_tier": "T3", "furigana": "古[ふる]い寺[てら]の外観[がいかん]を守[まも]るため、屋根[やね]の修理[しゅうり]には昔[むかし]と同[おな]じ瓦[かわら]を使[つか]った。", "sentence_source": "generated"}, {"text": "写真で見た外観と実物がまったく違い、驚きました。", "target_word": "外観", "complexity_tier": "T3", "furigana": "写真[しゃしん]で見[み]た外観[がいかん]と実物[じつぶつ]がまったく違[ちが]い、驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "外観の傷はほとんどないが、動作が不安定なので安く売られていた。", "target_word": "外観", "complexity_tier": "T3", "furigana": "外観[がいかん]の傷[きず]はほとんどないが、動作[どうさ]が不安定[ふあんてい]なので安[やす]く売[う]られていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外観", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "建物・物の外側から見た形や色などの見た目。内部や中身との対比で使われる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外観", "is_correct": true, "explanation": "物の外側から見た形や色などの見た目を表し、建物の「無骨な」様子に合う。"}, {"text": "食感", "is_correct": false, "explanation": "食べ物を口に入れたときの感触を指し、建物の見た目には使わない。"}, {"text": "香り", "is_correct": false, "explanation": "匂いのことで、形や色といった見た目を表さない。"}, {"text": "音色", "is_correct": false, "explanation": "音の質を表し、建物の見た目には使えない。"}], "explanations": {"外観": "物の外側から見た形や色などの見た目を表し、建物の「無骨な」様子に合う。", "食感": "食べ物を口に入れたときの感触を指し、建物の見た目には使わない。", "香り": "匂いのことで、形や色といった見た目を表さない。", "音色": "音の質を表し、建物の見た目には使えない。"}, "sentence_index": 0, "correct_answer": "外観"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は外観がいいので、よく女性に声をかけられる。", "explanation": "ここは〈外見〉の意味。人の見た目には外見を使い、外観は建物や物の外側の見た目に使う。"}, {"text": "この映画は外観が素晴らしく、ストーリーも深い。", "explanation": "ここは〈映像〉の意味。映画の画面の美しさには映像を使い、外観は物の外側の見た目に使うので合わない。"}, {"text": "このホールは外観の響きがよく、歌手に人気だ。", "explanation": "ここは〈音響〉の意味。音の響き方には音響を使い、外観は物の見た目を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外観", "is_correct": true, "explanation": "物の外側から見た形や色などの見た目を表し、市役所の「落ち着いた色」の話題に合う。"}, {"text": "予算", "is_correct": false, "explanation": "お金の使い方の計画を指し、建物の見た目には関係がない。"}, {"text": "人員", "is_correct": false, "explanation": "働く人の数を表し、色や景色の話題には合わない。"}, {"text": "窓口", "is_correct": false, "explanation": "手続きを受け付ける場所を指し、見た目の色とは関係がない。"}], "explanations": {"外観": "物の外側から見た形や色などの見た目を表し、市役所の「落ち着いた色」の話題に合う。", "予算": "お金の使い方の計画を指し、建物の見た目には関係がない。", "人員": "働く人の数を表し、色や景色の話題には合わない。", "窓口": "手続きを受け付ける場所を指し、見た目の色とは関係がない。"}, "sentence_index": 6, "correct_answer": "外観"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "両国の関係は外観の悪化で、大使が呼び戻された。", "explanation": "ここは〈外交〉の意味。国どうしの交渉には外交を使い、外観は物の見た目を表すので合わない。"}, {"text": "この事件の原因は外観にあり、社内の問題ではなかった。", "explanation": "ここは〈外部〉の意味。組織の外にあることには外部を使い、外観は見た目を表すので合わない。"}, {"text": "転んだ彼は外観のけががひどく、病院に運ばれた。", "explanation": "ここは〈外傷〉の意味。体の表面の傷には外傷を使い、外観は物の見た目を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は外観に魅力的で、人が集まる。", "corrected_sentence": "この店は外観が魅力的で、人が集まる。", "error_description": "誤りは「外観に」。「魅力的だ」の主語は「外観が」と格助詞「が」で示す。「に」では主語を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51750, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ビルの外観を焼き直して、色を変えた。", "corrected_sentence": "ビルの外観を塗り直して、色を変えた。", "error_description": "誤りは「焼き直す」。外観の色を変えるには「塗り直す」を使う。「焼き直す」は作品を作り直す意味で、外観に対して自然に使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「考える」の対象を示す助詞。「最悪のケースを考える」で、考える内容を表す。"}, {"text": "に", "is_correct": false, "explanation": "「考える」の対象は「を」で示すので不可"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「考える」の対象にはならない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、対象を取る「考える」には合わない"}], "correct_answer": "を", "explanations": {"を": "「考える」の対象を示す助詞。「最悪のケースを考える」で、考える内容を表す。", "に": "「考える」の対象は「を」で示すので不可", "で": "手段や場所を示すが、「考える」の対象にはならない", "へ": "方向を示すが、対象を取る「考える」には合わない"}, "error_tags": {"に": "「考える」の対象は「を」で示すので不可", "で": "手段や場所を示すが、「考える」の対象にはならない", "へ": "方向を示すが、対象を取る「考える」には合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「ケースもある」で、ほかにも同様の場合があることを加える助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、ここでは付加の位置に合わない"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、文の意味が合わない"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す助詞で、ここでは付加の位置に合わない"}], "correct_answer": "も", "explanations": {"も": "「ケースもある」で、ほかにも同様の場合があることを加える助詞。", "を": "目的語を示す助詞で、ここでは付加の位置に合わない", "より": "比較を示す助詞で、文の意味が合わない", "と": "並列や相手を示す助詞で、ここでは付加の位置に合わない"}, "error_tags": {"を": "目的語を示す助詞で、ここでは付加の位置に合わない", "より": "比較を示す助詞で、文の意味が合わない", "と": "並列や相手を示す助詞で、ここでは付加の位置に合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることが起こるときのこと。", "primary_collocate": null, "pronunciation": "けーす", "ipa": "keːsɯ", "syllable_count": 3, "sentences": [{"text": "駅まで歩くか、バスに乗るかは、ケースによって変わる。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "駅[えき]まで歩[ある]くか、バスに乗[の]るかは、ケースによって変[か]わる。", "sentence_source": "generated"}, {"text": "最悪のケースを考えて、避難の準備をしておこう。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "最悪[さいあく]のケースを考[かんが]えて、避難[ひなん]の準備[じゅんび]をしておこう。", "sentence_source": "generated"}, {"text": "約束に遅れるケースでは、必ず事前に連絡してください。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "約束[やくそく]に遅[おく]れるケースでは、必[かなら]ず事前[じぜん]に連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "このケースに限って、返品を受け付けることにします。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "このケースに限[かぎ]って、返品[へんぴん]を受[う]け付[つ]けることにします。", "sentence_source": "generated"}, {"text": "子どもが熱を出したケースを想定して、会社は在宅勤務の制度を整えた。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "子[こ]どもが熱[ねつ]を出[だ]したケースを想定[そうてい]して、会社[かいしゃ]は在宅勤務[ざいたくきんむ]の制度[せいど]を整[ととの]えた。", "sentence_source": "generated"}, {"text": "保険金が支払われるケースと、支払われないケースを確認した。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "保険金[ほけんきん]が支払[しはら]われるケースと、支払[しはら]われないケースを確認[かくにん]した。", "sentence_source": "generated"}, {"text": "停電が長引くケースに備えて、懐中電灯を買った。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "停電[ていでん]が長引[ながび]くケースに備[そな]えて、懐中電灯[かいちゅうでんとう]を買[か]った。", "sentence_source": "generated"}, {"text": "相手が怒り出すケースもあるので、言い方には気をつけたい。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "相手[あいて]が怒[おこ]り出[だ]すケースもあるので、言[い]い方[かた]には気[き]をつけたい。", "sentence_source": "generated"}, {"text": "時間が足りないケースでは、説明を短くして要点だけを話す。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "時間[じかん]が足[た]りないケースでは、説明[せつめい]を短[みじか]くして要点[ようてん]だけを話[はな]す。", "sentence_source": "generated"}, {"text": "取引先の都合で予定が変わるケースもあるので、余裕を持って計画を立てた。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "取引先[とりひきさき]の都合[つごう]で予定[よてい]が変[か]わるケースもあるので、余裕[よゆう]を持[も]って計画[けいかく]を立[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ケース", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "あることが起こる場合・状況。「場合」に近い意味の外来語で、入れ物の意味ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ケース", "is_correct": true, "explanation": "正解。「ケースによって変わる」で、あることが起こる場合を表す。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息によって変わる」は意味が通らない。"}, {"text": "足音", "is_correct": false, "explanation": "「足音によって変わる」は文の意味に合わない。"}, {"text": "鼻歌", "is_correct": false, "explanation": "「鼻歌によって変わる」は不自然で、場合を表す語が入らない。"}], "explanations": {"ケース": "正解。「ケースによって変わる」で、あることが起こる場合を表す。", "寝息": "「寝息によって変わる」は意味が通らない。", "足音": "「足音によって変わる」は文の意味に合わない。", "鼻歌": "「鼻歌によって変わる」は不自然で、場合を表す語が入らない。"}, "sentence_index": 0, "correct_answer": "ケース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宝石を入れるケースを、引き出しにしまった。", "explanation": "ここは〈入れ物〉の意味。物を収める箱のことで、「あることが起こる場合」の意味ではない。"}, {"text": "新しい眼鏡のケースを買ったが、ほとんど使っていない。", "explanation": "ここは〈入れ物〉の意味。眼鏡を入れる箱のことで、「あることが起こる場合」の意味ではない。"}, {"text": "スマホのケースが割れたので、新しいものを買った。", "explanation": "ここは〈入れ物〉の意味。機器を守る覆いのことで、「あることが起こる場合」の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ケース", "is_correct": true, "explanation": "正解。「停電が長引くケース」で、ある事例・場合を表す。"}, {"text": "体温", "is_correct": false, "explanation": "「停電が長引く体温に備えて」は意味が通らない。"}, {"text": "目薬", "is_correct": false, "explanation": "「停電が長引く目薬に備えて」は文に合わない。"}, {"text": "味覚", "is_correct": false, "explanation": "「停電が長引く味覚」は不自然で、場合を表す語が入らない。"}], "explanations": {"ケース": "正解。「停電が長引くケース」で、ある事例・場合を表す。", "体温": "「停電が長引く体温に備えて」は意味が通らない。", "目薬": "「停電が長引く目薬に備えて」は文に合わない。", "味覚": "「停電が長引く味覚」は不自然で、場合を表す語が入らない。"}, "sentence_index": 6, "correct_answer": "ケース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ペンと消しゴムを、ケースに入れて持ち歩く。", "explanation": "ここは〈入れ物〉の意味。物を収める箱のことで、「あることが起こる場合」の意味ではない。"}, {"text": "メガネのケースを忘れてしまい、困った。", "explanation": "ここは〈入れ物〉の意味。物を入れる箱のことで、「あることが起こる場合」の意味ではない。"}, {"text": "ケースの中に、古いレコードが並んでいる。", "explanation": "ここは〈入れ物〉の意味。物を収める箱のことで、「あることが起こる場合」の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雷が鳴るケースを、屋内に避難する。", "corrected_sentence": "雷が鳴るケースでは、屋内に避難する。", "error_description": "「雷が鳴るケース」は場面を示すので「では」が自然。「を」は目的語になり、文の意味が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51751, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車が遅れるケースを備えて、代わりの交通手段を調べておく。", "corrected_sentence": "電車が遅れるケースに備えて、代わりの交通手段を調べておく。", "error_description": "「備える」は「〜に備える」と使う。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ケースは少なくない」と主題を示す。ケースが少なくないという評価を述べるので「は」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「ケースを少なくない」と目的語にすると、「少なくない」の主語が立たず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ケースに少なくない」では述語の「少なくない」が続かず、文として不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「ケースで少なくない」と手段や場所を示すと意味が通らず、評価の主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「ケースは少なくない」と主題を示す。ケースが少なくないという評価を述べるので「は」が合う。", "を": "「ケースを少なくない」と目的語にすると、「少なくない」の主語が立たず文が成り立たない。", "に": "「ケースに少なくない」では述語の「少なくない」が続かず、文として不自然になる。", "で": "「ケースで少なくない」と手段や場所を示すと意味が通らず、評価の主題にならない。"}, "error_tags": {"を": "目的語を示す助詞で、ここでは主題の位置に合わない", "に": "場所や時点を示す助詞で、ここでは主題にならない", "で": "手段や場所を示す助詞で、ここでは主題にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ケースは特別だ」と主題を示す。ケースの性質を述べる文なので「は」が合う。"}, {"text": "と", "is_correct": false, "explanation": "「ケースと特別で」と並列の形になり、主題を示せず文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「ケースへ特別で」と方向を示すと、性質を述べる文として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「ケースから特別で」と起点を示すと、「特別だ」の主題にならず文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「ケースは特別だ」と主題を示す。ケースの性質を述べる文なので「は」が合う。", "と": "「ケースと特別で」と並列の形になり、主題を示せず文が不自然になる。", "へ": "「ケースへ特別で」と方向を示すと、性質を述べる文として意味が通らない。", "から": "「ケースから特別で」と起点を示すと、「特別だ」の主題にならず文が成り立たない。"}, "error_tags": {"と": "並列や相手を示す助詞で、ここでは主題にならない", "へ": "方向を示す助詞で、ここでは主題にならない", "から": "起点を示す助詞で、ここでは主題にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の状況や事例を指す言葉。", "primary_collocate": null, "pronunciation": "けーす", "ipa": "keːsɯ", "syllable_count": 3, "sentences": [{"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "しかし、その無骨[ぶこつ]な外観[がいかん]や維持管理[いじかんり]の難[むずか]しさから、現在[げんざい]ではその価値[かち]が再評価[さいひょうか]される一方[いっぽう]で、取[と]り壊[こわ]されるケースも増[ふ]えています。", "sentence_source": "mined"}, {"text": "機械の故障が原因で、事故が起きたケースは少なくない。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "機械[きかい]の故障[こしょう]が原因[げんいん]で、事故[じこ]が起[お]きたケースは少[すく]なくない。", "sentence_source": "generated"}, {"text": "日本では、高齢者が一人で暮らすケースが増えている。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "日本[にほん]では、高齢者[こうれいしゃ]が一人[ひとり]で暮[く]らすケースが増[ふ]えている。", "sentence_source": "generated"}, {"text": "雨の日にこの道が冠水するケースは、過去にも何度かあった。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]にこの道[みち]が冠水[かんすい]するケースは、過去[かこ]にも何度[なんど]かあった。", "sentence_source": "generated"}, {"text": "このケースでは、先に医者に相談したほうがいい。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "このケースでは、先[さき]に医者[いしゃ]に相談[そうだん]したほうがいい。", "sentence_source": "generated"}, {"text": "成功したケースを参考にして、新しい企画を立てた。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "成功[せいこう]したケースを参考[さんこう]にして、新[あたら]しい企画[きかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "夜遅くに帰宅して、家族に叱られるケースもあるようです。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]くに帰宅[きたく]して、家族[かぞく]に叱[しか]られるケースもあるようです。", "sentence_source": "generated"}, {"text": "彼のケースは特別で、通常の規則は当てはまらない。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "彼[かれ]のケースは特別[とくべつ]で、通常[つうじょう]の規則[きそく]は当[あ]てはまらない。", "sentence_source": "generated"}, {"text": "詐欺の被害に遭うケースが、若者の間でも目立ってきた。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "詐欺[さぎ]の被害[ひがい]に遭[あ]うケースが、若者[わかもの]の間[あいだ]でも目立[めだ]ってきた。", "sentence_source": "generated"}, {"text": "天気が悪くて試合が中止になるケースは、年に数回ある。", "target_word": "ケース", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]くて試合[しあい]が中止[ちゅうし]になるケースは、年[とし]に数回[すうかい]ある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ケース", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "特定の状況・事例・場合を指す外来語。入れ物の意味のケースではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ケース", "is_correct": true, "explanation": "正解。「取り壊されるケース」で、特定の事例を表す。"}, {"text": "材料", "is_correct": false, "explanation": "「取り壊される材料」は意味が通らない。事例を表す語が入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は取り壊される対象ではないので、文が成り立たない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は取り壊されない。「取り壊される」に合う名詞ではない。"}], "explanations": {"ケース": "正解。「取り壊されるケース」で、特定の事例を表す。", "材料": "「取り壊される材料」は意味が通らない。事例を表す語が入る。", "天気": "天気は取り壊される対象ではないので、文が成り立たない。", "感想": "感想は取り壊されない。「取り壊される」に合う名詞ではない。"}, "sentence_index": 0, "correct_answer": "ケース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宝石を入れるケースを、引き出しにしまった。", "explanation": "ここは〈入れ物〉の意味。物を収める箱のことで、「特定の事例」の意味ではない。"}, {"text": "新しい眼鏡のケースを買ったが、ほとんど使っていない。", "explanation": "ここは〈入れ物〉の意味。眼鏡を入れる箱のことで、「特定の事例」の意味ではない。"}, {"text": "スマホのケースが割れたので、新しいものを買った。", "explanation": "ここは〈入れ物〉の意味。機器を守る覆いのことで、「特定の事例」の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ケース", "is_correct": true, "explanation": "正解。「叱られるケース」で、ある事例を表す。"}, {"text": "料理", "is_correct": false, "explanation": "「家族に叱られる料理」は意味が通らない。"}, {"text": "小説", "is_correct": false, "explanation": "小説は家族に叱られる対象ではないので、文が成り立たない。"}, {"text": "切符", "is_correct": false, "explanation": "「家族に叱られる切符」は不自然で、事例を表す語が入らない。"}], "explanations": {"ケース": "正解。「叱られるケース」で、ある事例を表す。", "料理": "「家族に叱られる料理」は意味が通らない。", "小説": "小説は家族に叱られる対象ではないので、文が成り立たない。", "切符": "「家族に叱られる切符」は不自然で、事例を表す語が入らない。"}, "sentence_index": 6, "correct_answer": "ケース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ペンと消しゴムを、ケースに入れて持ち歩く。", "explanation": "ここは〈入れ物〉の意味。物を収める箱のことで、「特定の事例」の意味ではない。"}, {"text": "メガネのケースを忘れてしまい、困った。", "explanation": "ここは〈入れ物〉の意味。物を入れる箱のことで、「特定の事例」の意味ではない。"}, {"text": "ケースの中に、古いレコードが並んでいる。", "explanation": "ここは〈入れ物〉の意味。物を収める箱のことで、「特定の事例」の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近年、古い公園の遊具が撤去されるケースを増えています。", "corrected_sentence": "近年、古い公園の遊具が撤去されるケースが増えています。", "error_description": "「増える」は自動詞なので「を」は取らない。主語を示す「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51752, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川の水位が上がるケースを備えて、避難場所を確認しておく。", "corrected_sentence": "川の水位が上がるケースに備えて、避難場所を確認しておく。", "error_description": "「備える」は「〜に備える」と使う。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
