INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51753, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "建物などをこわすこと。", "primary_collocate": null, "pronunciation": "とりこわす", "ipa": "toɾikowasɯ", "syllable_count": 5, "sentences": [{"text": "古い映画館は、来月取り壊すことになりました。", "target_word": "取り壊す", "complexity_tier": "T3", "furigana": "古[ふる]い映画館[えいがかん]は、来月[らいげつ]取[と]り壊[こわ]すことになりました。", "sentence_source": "generated"}, {"text": "地震に弱い家なので、思い切って取り壊しました。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "地震[じしん]に弱[よわ]い家[いえ]なので、思[おも]い切[き]って取[と]り壊[こわ]しました。", "sentence_source": "generated"}, {"text": "町の古い工場が取り壊されて、広い空き地になりました。", "target_word": "取り壊され", "complexity_tier": "T3", "furigana": "町[まち]の古[ふる]い工場[こうじょう]が取[と]り壊[こわ]されて、広[ひろ]い空[あ]き地[ち]になりました。", "sentence_source": "generated"}, {"text": "この小屋はもう使わないので、週末に取り壊そうと思います。", "target_word": "取り壊そ", "complexity_tier": "T3", "furigana": "この小屋[こや]はもう使[つか]わないので、週末[しゅうまつ]に取[と]り壊[こわ]そうと思[おも]います。", "sentence_source": "generated"}, {"text": "取り壊される前に、思い出の校舎を写真に撮っておきました。", "target_word": "取り壊され", "complexity_tier": "T3", "furigana": "取[と]り壊[こわ]される前[まえ]に、思[おも]い出[で]の校舎[こうしゃ]を写真[しゃしん]に撮[と]っておきました。", "sentence_source": "generated"}, {"text": "父は庭の古い物置を取り壊して、新しい車庫を作りました。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]の古[ふる]い物置[ものおき]を取[と]り壊[こわ]して、新[あたら]しい車庫[しゃこ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "長年住んだ家を取り壊すとき、家族みんなで最後の挨拶をしました。", "target_word": "取り壊す", "complexity_tier": "T3", "furigana": "長年[ながねん]住[す]んだ家[いえ]を取[と]り壊[こわ]すとき、家族[かぞく]みんなで最後[さいご]の挨拶[あいさつ]をしました。", "sentence_source": "generated"}, {"text": "台風で傾いた建物は、危険なので取り壊すしかありません。", "target_word": "取り壊す", "complexity_tier": "T3", "furigana": "台風[たいふう]で傾[かたむ]いた建物[たてもの]は、危険[きけん]なので取[と]り壊[こわ]すしかありません。", "sentence_source": "generated"}, {"text": "市は古い体育館を取り壊さずに、改装して使い続けます。", "target_word": "取り壊さ", "complexity_tier": "T3", "furigana": "市[し]は古[ふる]い体育館[たいいくかん]を取[と]り壊[こわ]さずに、改装[かいそう]して使[つか]い続[つづ]けます。", "sentence_source": "generated"}, {"text": "古い住宅を取り壊した後の土地には、新しい学校が建つ予定です。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "古[ふる]い住宅[じゅうたく]を取[と]り壊[こわ]した後[あと]の土地[とち]には、新[あたら]しい学校[がっこう]が建[た]つ予定[よてい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り壊す", "label": "辞書形"}, {"form": "取り壊さ", "label": "未然形"}, {"form": "取り壊そ", "label": "意志形"}, {"form": "取り壊し", "label": "連用形"}, {"form": "取り壊した", "label": "過去形"}, {"form": "取り壊される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "建物などを壊してなくす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51753, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り壊す", "is_correct": true, "explanation": "正解。辞書形で「ことになりました」に続き、来月の取り壊しの予定を表す。"}, {"text": "取り壊し", "is_correct": false, "explanation": "連用形は「こと」に直接続かず、「来月取り壊しことになりました」は不成立。"}, {"text": "取り壊さ", "is_correct": false, "explanation": "未然形は「こと」に続かず、文として成り立たない。"}, {"text": "取り壊して", "is_correct": false, "explanation": "て形は「ことになりました」に続けられず、文が成り立たない。"}], "explanations": {"取り壊す": "正解。辞書形で「ことになりました」に続き、来月の取り壊しの予定を表す。", "取り壊し": "連用形は「こと」に直接続かず、「来月取り壊しことになりました」は不成立。", "取り壊さ": "未然形は「こと」に続かず、文として成り立たない。", "取り壊して": "て形は「ことになりました」に続けられず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "取り壊す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古いタイヤを新しいものに取り壊した。", "explanation": "ここは〈取り替える〉の意味。取り壊すは建物などを壊してなくす語で、タイヤの交換には使わない。"}, {"text": "友達との約束を取り壊してしまい、気まずくなった。", "explanation": "ここは〈破る〉の意味。取り壊すは建物などの構造物を壊す語で、約束を破る場面には合わない。"}, {"text": "ベッドの枠を取り壊して、マットを外した。", "explanation": "ここは〈分解する〉の意味。取り壊すは建物などを取り除く語で、家具を分解する場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51753, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り壊す", "is_correct": true, "explanation": "正解。辞書形で「とき」に続き、家を壊す時点を表す。"}, {"text": "取り壊そ", "is_correct": false, "explanation": "意志形の語幹「取り壊そ」は「とき」に続かず、文として不成立。"}, {"text": "取り壊せ", "is_correct": false, "explanation": "命令形や可能の語幹は「とき」に続かず、文として成り立たない。"}, {"text": "取り壊させ", "is_correct": false, "explanation": "使役の語幹は「とき」に直接続かず、文として成り立たない。"}], "explanations": {"取り壊す": "正解。辞書形で「とき」に続き、家を壊す時点を表す。", "取り壊そ": "意志形の語幹「取り壊そ」は「とき」に続かず、文として不成立。", "取り壊せ": "命令形や可能の語幹は「とき」に続かず、文として成り立たない。", "取り壊させ": "使役の語幹は「とき」に直接続かず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "取り壊す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大事な誓いを取り壊してしまい、後悔した。", "explanation": "ここは〈破る〉の意味。取り壊すは建物などの構造物を壊す語で、誓いには使わない。"}, {"text": "庭の雑草を取り壊して、きれいにした。", "explanation": "ここは〈抜く〉の意味。取り壊すは建物などの構造物を対象とし、雑草には使わない。"}, {"text": "古いファイルを取り壊して、パソコンの容量を増やした。", "explanation": "ここは〈削除する〉の意味。取り壊すは建物などを壊す語で、データの削除には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51753, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い映画館は、来月取り壊して予定です。", "corrected_sentence": "古い映画館は、来月取り壊す予定です。", "error_description": "「予定」の前には辞書形「取り壊す」が必要。「取り壊して」（て形）は予定の文に続かず、不自然な形。正しくは「取り壊す予定」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り壊し", "is_correct": true, "explanation": "正解。連用形で「取り壊しました」と過去の動作を表す。"}, {"text": "取り壊す", "is_correct": false, "explanation": "辞書形は「ました」に続かず、「取り壊すました」は誤り。"}, {"text": "取り壊さ", "is_correct": false, "explanation": "未然形は「ました」に続かず、「取り壊さました」は誤り。"}, {"text": "取り壊そう", "is_correct": false, "explanation": "意志形は「ました」に続かず、「取り壊そうました」は誤り。"}], "correct_form": "取り壊し", "base_form": "取り壊す", "form_label": "連用形", "sentence_index": 1, "explanations": {"取り壊し": "正解。連用形で「取り壊しました」と過去の動作を表す。", "取り壊す": "辞書形は「ました」に続かず、「取り壊すました」は誤り。", "取り壊さ": "未然形は「ました」に続かず、「取り壊さました」は誤り。", "取り壊そう": "意志形は「ました」に続かず、「取り壊そうました」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51753, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い橋に取り壊すことになりました。", "corrected_sentence": "古い橋を取り壊すことになりました。", "error_description": "「取り壊す」の前には目的語を示す「を」が必要。「に」を付けると「橋に取り壊す」となり不自然。正しくは「橋を取り壊す」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り壊す", "is_correct": true, "explanation": "正解。「しかありません」に辞書形が続き、選択肢がないことを表す。"}, {"text": "取り壊そ", "is_correct": false, "explanation": "意志形の語幹は「しかありません」に続かず、不成立。"}, {"text": "取り壊せ", "is_correct": false, "explanation": "命令形や可能の語幹は「しかありません」に続かず、文として成立しない。"}, {"text": "取り壊させ", "is_correct": false, "explanation": "使役の語幹は「しかありません」に続けられず、文として不成立。"}], "correct_form": "取り壊す", "base_form": "取り壊す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"取り壊す": "正解。「しかありません」に辞書形が続き、選択肢がないことを表す。", "取り壊そ": "意志形の語幹は「しかありません」に続かず、不成立。", "取り壊せ": "命令形や可能の語幹は「しかありません」に続かず、文として成立しない。", "取り壊させ": "使役の語幹は「しかありません」に続けられず、文として不成立。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51754, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。時点を示す「に」で、「来年の春に取り壊す」と取り壊しの時期を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「来年の春を取り壊す」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「来年の春へ取り壊す」は時点の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「来年の春と取り壊す」は文の意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。時点を示す「に」で、「来年の春に取り壊す」と取り壊しの時期を表す。", "を": "「を」は目的語を示すので、「来年の春を取り壊す」は成り立たない。", "へ": "「へ」は方向を示すので、「来年の春へ取り壊す」は時点の意味が通らない。", "と": "「と」は並列や引用を示すので、「来年の春と取り壊す」は文の意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
