INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51754, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "建物や構造物を壊して取り除くこと。", "primary_collocate": null, "pronunciation": "とりこわす", "ipa": "toɾikowasɯ", "syllable_count": 5, "sentences": [{"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "取り壊され", "complexity_tier": "T3", "furigana": "しかし、その無骨[ぶこつ]な外観[がいかん]や維持管理[いじかんり]の難[むずか]しさから、現在[げんざい]ではその価値[かち]が再評価[さいひょうか]される一方[いっぽう]で、取[と]り壊[こわ]されるケースも増[ふ]えています。", "sentence_source": "mined"}, {"text": "老朽化した校舎は、来年の春に取り壊すことが決まりました。", "target_word": "取り壊す", "complexity_tier": "T3", "furigana": "老朽化[ろうきゅうか]した校舎[こうしゃ]は、来年[らいねん]の春[はる]に取[と]り壊[こわ]すことが決[き]まりました。", "sentence_source": "generated"}, {"text": "古い橋を取り壊す前に、近くの住民への説明会が開かれました。", "target_word": "取り壊す", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]を取[と]り壊[こわ]す前[まえ]に、近[ちか]くの住民[じゅうみん]への説明会[せつめいかい]が開[ひら]かれました。", "sentence_source": "generated"}, {"text": "市は危険な空き家を取り壊して、そこに小さな公園を作りました。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "市[し]は危険[きけん]な空[あ]き家[や]を取[と]り壊[こわ]して、そこに小[ちい]さな公園[こうえん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "工事のため、この建物は来月から取り壊されます。", "target_word": "取り壊され", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、この建物[たてもの]は来月[らいげつ]から取[と]り壊[こわ]されます。", "sentence_source": "generated"}, {"text": "歴史的な価値があるので、あの駅舎は取り壊さずに残すことになりました。", "target_word": "取り壊さ", "complexity_tier": "T3", "furigana": "歴史的[れきしてき]な価値[かち]があるので、あの駅舎[えきしゃ]は取[と]り壊[こわ]さずに残[のこ]すことになりました。", "sentence_source": "generated"}, {"text": "祖父は古くなった倉庫を取り壊し、跡地に畑を作りました。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "祖父[そふ]は古[ふる]くなった倉庫[そうこ]を取[と]り壊[こわ]し、跡地[あとち]に畑[はたけ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "取り壊された映画館の跡には、大きなマンションが建っています。", "target_word": "取り壊され", "complexity_tier": "T3", "furigana": "取[と]り壊[こわ]された映画館[えいがかん]の跡[あと]には、大[おお]きなマンションが建[た]っています。", "sentence_source": "generated"}, {"text": "地震で傷んだ塀は、危ないので早めに取り壊したほうがいいです。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "地震[じしん]で傷[いた]んだ塀[へい]は、危[あぶ]ないので早[はや]めに取[と]り壊[こわ]したほうがいいです。", "sentence_source": "generated"}, {"text": "火事で傷んだ家を、持ち主は費用をかけて取り壊しました。", "target_word": "取り壊し", "complexity_tier": "T3", "furigana": "火事[かじ]で傷[いた]んだ家[いえ]を、持[も]ち主[ぬし]は費用[ひよう]をかけて取[と]り壊[こわ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り壊す", "label": "辞書形"}, {"form": "取り壊さ", "label": "未然形"}, {"form": "取り壊し", "label": "連用形"}, {"form": "取り壊して", "label": "て形"}, {"form": "取り壊した", "label": "過去形"}, {"form": "取り壊される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "老朽化した建物や構造物を壊して取り除く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り壊され", "is_correct": true, "explanation": "正解。「取り壊される」の受身形で、校舎など建物が壊されることを表し、後ろの「ケース」に続く。"}, {"text": "取り壊し", "is_correct": false, "explanation": "連用形は「る」に続けられず、「取り壊しるケース」は成り立たない。"}, {"text": "取り壊せ", "is_correct": false, "explanation": "命令形・可能の語幹は「ケース」に直接続かず、「取り壊せケース」は成り立たない。"}, {"text": "取り壊した", "is_correct": false, "explanation": "過去形に「る」は続かず、「取り壊したるケース」は成り立たない。"}], "explanations": {"取り壊され": "正解。「取り壊される」の受身形で、校舎など建物が壊されることを表し、後ろの「ケース」に続く。", "取り壊し": "連用形は「る」に続けられず、「取り壊しるケース」は成り立たない。", "取り壊せ": "命令形・可能の語幹は「ケース」に直接続かず、「取り壊せケース」は成り立たない。", "取り壊した": "過去形に「る」は続かず、「取り壊したるケース」は成り立たない。"}, "sentence_index": 0, "correct_answer": "取り壊され"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お気に入りのカップを取り壊してしまい、がっかりした。", "explanation": "ここは〈壊す〉の意味。取り壊すは建物などの構造物を壊して取り除く語なので、カップのような小物には使わない。"}, {"text": "友達の気持ちを取り壊すような言葉を、彼はうっかり口にした。", "explanation": "ここは〈傷つける〉の意味。取り壊すは建物や構造物を対象とし、人の気持ちには使わない。"}, {"text": "古い時計を取り壊して、歯車を一つずつ並べた。", "explanation": "ここは〈分解する〉の意味。取り壊すは建物などの大きな構造物に使い、時計を分解する場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り壊し", "is_correct": true, "explanation": "正解。連用形で「倉庫を取り壊し、」と文を続ける用法で、壊した後に畑を作った流れに合う。"}, {"text": "取り壊される", "is_correct": false, "explanation": "受身形では「倉庫を」の目的語と合わず、祖父が壊す主体の文に合わない。"}, {"text": "取り壊せ", "is_correct": false, "explanation": "命令形や可能の語幹は「取り壊せ、」と中止の形として成り立たない。"}, {"text": "取り壊そう", "is_correct": false, "explanation": "意志形は「、」で文を続ける形にならず、倉庫を壊した事実を述べる文に合わない。"}], "explanations": {"取り壊し": "正解。連用形で「倉庫を取り壊し、」と文を続ける用法で、壊した後に畑を作った流れに合う。", "取り壊される": "受身形では「倉庫を」の目的語と合わず、祖父が壊す主体の文に合わない。", "取り壊せ": "命令形や可能の語幹は「取り壊せ、」と中止の形として成り立たない。", "取り壊そう": "意志形は「、」で文を続ける形にならず、倉庫を壊した事実を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "取り壊し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い議論の末、彼は相手の主張を取り壊した。", "explanation": "ここは〈論破する〉の意味。取り壊すは建物や構造物を対象とし、主張には使わない。"}, {"text": "友人との約束を取り壊してしまい、気まずくなった。", "explanation": "ここは〈破る〉の意味。取り壊すは建物などの構造物に使うので、約束には使わない。"}, {"text": "庭の雑草を取り壊して、きれいにした。", "explanation": "ここは〈抜く〉の意味。取り壊すは建物などの構造物を対象とし、雑草には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い倉庫は、来月の末に取り壊しことになりました。", "corrected_sentence": "古い倉庫は、来月の末に取り壊すことになりました。", "error_description": "「取り壊す」に「こと」を続けるには辞書形の「取り壊す」が必要。「取り壊し」は連用形（名詞形）なので「取り壊しことになりました」は誤り。正しくは「取り壊すことになりました」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り壊す", "is_correct": true, "explanation": "正解。「ことが決まりました」には辞書形が続くため、「取り壊すことが決まりました」となる。"}, {"text": "取り壊し", "is_correct": false, "explanation": "連用形は「こと」に直接続かず、「取り壊しことが決まりました」は誤り。"}, {"text": "取り壊さ", "is_correct": false, "explanation": "未然形は「こと」に続けられず、「取り壊さことが決まりました」は誤り。"}, {"text": "取り壊そ", "is_correct": false, "explanation": "意志形の語幹は「こと」に続かず、「取り壊そことが決まりました」は誤り。"}], "correct_form": "取り壊す", "base_form": "取り壊す", "form_label": "辞書形", "sentence_index": 1, "explanations": {"取り壊す": "正解。「ことが決まりました」には辞書形が続くため、「取り壊すことが決まりました」となる。", "取り壊し": "連用形は「こと」に直接続かず、「取り壊しことが決まりました」は誤り。", "取り壊さ": "未然形は「こと」に続けられず、「取り壊さことが決まりました」は誤り。", "取り壊そ": "意志形の語幹は「こと」に続かず、「取り壊そことが決まりました」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いホテルは、来月取り壊した予定です。", "corrected_sentence": "古いホテルは、来月取り壊す予定です。", "error_description": "「予定」は未来の計画を表すので、辞書形の「取り壊す」が必要。「取り壊した」は過去形で、計画の文に合わない。正しくは「取り壊す予定」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り壊され", "is_correct": true, "explanation": "正解。「映画館の跡」を修飾する過去の受身形で、映画館が取り壊された状態を表す。"}, {"text": "取り壊して", "is_correct": false, "explanation": "て形は名詞を修飾できず、「取り壊して映画館の跡」は成り立たない。"}, {"text": "取り壊せ", "is_correct": false, "explanation": "命令形や可能の語幹は名詞を修飾できず、「取り壊せ映画館」は不成立。"}, {"text": "取り壊させ", "is_correct": false, "explanation": "使役の語幹では名詞を修飾できず、「取り壊させ映画館」は不成立。"}], "correct_form": "取り壊され", "base_form": "取り壊す", "form_label": "受身形（過去）", "sentence_index": 7, "explanations": {"取り壊され": "正解。「映画館の跡」を修飾する過去の受身形で、映画館が取り壊された状態を表す。", "取り壊して": "て形は名詞を修飾できず、「取り壊して映画館の跡」は成り立たない。", "取り壊せ": "命令形や可能の語幹は名詞を修飾できず、「取り壊せ映画館」は不成立。", "取り壊させ": "使役の語幹では名詞を修飾できず、「取り壊させ映画館」は不成立。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「日照を少ない」では形容詞「少ない」の主語を示せない。"}, {"text": "が", "is_correct": true, "explanation": "「日照が少ない」の主語を示す「が」で、ここで正しい。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「日照で少ない」では主語にならず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すため、「日照と少ない」では形容詞「少ない」の主語を示せない。"}], "correct_answer": "が", "explanations": {"を": "「を」は目的語を示すため、「日照を少ない」では形容詞「少ない」の主語を示せない。", "が": "「日照が少ない」の主語を示す「が」で、ここで正しい。", "で": "「で」は場所や手段を示すため、「日照で少ない」では主語にならず、意味が通らない。", "と": "「と」は並列を示すため、「日照と少ない」では形容詞「少ない」の主語を示せない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "「日照が恵まれた」は「恵まれる」の形に合わず、「〜に恵まれる」の形を取る必要がある。"}, {"text": "に", "is_correct": true, "explanation": "「日照に恵まれた」は「〜に恵まれる」の形で、対象を示す「に」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「日照へ恵まれた」では「恵まれる」の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「日照から恵まれた」では意味が通らず、「恵まれる」の形にも合わない。"}], "correct_answer": "に", "explanations": {"が": "「日照が恵まれた」は「恵まれる」の形に合わず、「〜に恵まれる」の形を取る必要がある。", "に": "「日照に恵まれた」は「〜に恵まれる」の形で、対象を示す「に」が正しい。", "へ": "「へ」は方向を示すため、「日照へ恵まれた」では「恵まれる」の対象を示せない。", "から": "「から」は起点を示すため、「日照から恵まれた」では意味が通らず、「恵まれる」の形にも合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "太陽の光が当たることです。", "primary_collocate": null, "pronunciation": "にっしょう", "ipa": "nʲiɕːoː", "syllable_count": 4, "sentences": [{"text": "日照の多い地域では、果物が甘く育つ。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]の多[おお]い地域[ちいき]では、果物[くだもの]が甘[あま]く育[そだ]つ。", "sentence_source": "generated"}, {"text": "谷の底は、山に囲まれていて日照が少ない。", "target_word": "日照", "complexity_tier": "T3", "furigana": "谷[たに]の底[そこ]は、山[やま]に囲[かこ]まれていて日照[にっしょう]が少[すく]ない。", "sentence_source": "generated"}, {"text": "日照があるかどうかで、植物の育ち方は大きく変わる。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]があるかどうかで、植物[しょくぶつ]の育[そだ]ち方[かた]は大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "この畑は午後は日照がないので、日かげを好む野菜を植えた。", "target_word": "日照", "complexity_tier": "T3", "furigana": "この畑[はたけ]は午後[ごご]は日照[にっしょう]がないので、日[ひ]かげを好[この]む野菜[やさい]を植[う]えた。", "sentence_source": "generated"}, {"text": "日照のない部屋は、昼でも暗くて寒い。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]のない部屋[へや]は、昼[ひる]でも暗[くら]くて寒[さむ]い。", "sentence_source": "generated"}, {"text": "トマトは日照を好むので、窓辺に置いた。", "target_word": "日照", "complexity_tier": "T3", "furigana": "トマトは日照[にっしょう]を好[この]むので、窓辺[まどべ]に置[お]いた。", "sentence_source": "generated"}, {"text": "雨が続いて日照が少なく、洗濯物が乾かない。", "target_word": "日照", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いて日照[にっしょう]が少[すく]なく、洗濯物[せんたくもの]が乾[かわ]かない。", "sentence_source": "generated"}, {"text": "日照に恵まれた土地で、ぶどうを育てている。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]に恵[めぐ]まれた土地[とち]で、ぶどうを育[そだ]てている。", "sentence_source": "generated"}, {"text": "冬は日照が減るので、気分が沈みやすい。", "target_word": "日照", "complexity_tier": "T3", "furigana": "冬[ふゆ]は日照[にっしょう]が減[へ]るので、気分[きぶん]が沈[しず]みやすい。", "sentence_source": "generated"}, {"text": "新しい建物のせいで、公園の日照が奪われた。", "target_word": "日照", "complexity_tier": "T3", "furigana": "新[あたら]しい建物[たてもの]のせいで、公園[こうえん]の日照[にっしょう]が奪[うば]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日照", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "太陽の光が当たること。植物や洗濯物などへの日光の当たり具合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方言", "is_correct": false, "explanation": "「方言の多い地域」は言葉の種類を表し、果物が甘く育つ話とは結びつかない。"}, {"text": "電気", "is_correct": false, "explanation": "「電気の多い地域」は意味が通らず、果物の生育条件としても合わない。"}, {"text": "日照", "is_correct": true, "explanation": "「日照の多い地域」は日光がよく当たる地域を表し、果物が甘く育つ内容と一致する。"}, {"text": "歌謡", "is_correct": false, "explanation": "歌謡は歌の種類を指し、「歌謡の多い地域」は果物の生育と関係がない。"}], "explanations": {"方言": "「方言の多い地域」は言葉の種類を表し、果物が甘く育つ話とは結びつかない。", "電気": "「電気の多い地域」は意味が通らず、果物の生育条件としても合わない。", "日照": "「日照の多い地域」は日光がよく当たる地域を表し、果物が甘く育つ内容と一致する。", "歌謡": "歌謡は歌の種類を指し、「歌謡の多い地域」は果物の生育と関係がない。"}, "sentence_index": 0, "correct_answer": "日照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その店は、日照を一袋百円で売り出した。", "explanation": "ここは〈商品〉の意味。値段をつけて店で売るのは商品で、光が当たることを指す日照は売り物にならないので合わない。"}, {"text": "夏祭りで、日照の店を出して大人気だった。", "explanation": "ここは〈屋台〉の意味。祭りで食べ物などを売る小さな店は屋台で、光が当たることを指す日照は店の名前にならないので合わない。"}, {"text": "真夏に外で働いて、日照のペンキで腕を真っ黒にした。", "explanation": "ここは〈塗料〉の意味。腕に塗って色を変えるのは塗料で、光が当たることを指す日照は色を塗れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声量", "is_correct": false, "explanation": "「声量が少なく」は声の大きさを表し、洗濯物が乾かない文脈とは結びつかない。"}, {"text": "人気", "is_correct": false, "explanation": "「人気が少なく」は人々の支持を表し、雨と洗濯物の文脈では意味が通らない。"}, {"text": "日照", "is_correct": true, "explanation": "「日照が少なく」は日光が当たる量が少ないことを表し、雨が続いて洗濯物が乾かない内容と一致する。"}, {"text": "語彙", "is_correct": false, "explanation": "語彙は言葉の集まりを指し、「語彙が少なく」は洗濯物が乾かない理由として成り立たない。"}], "explanations": {"声量": "「声量が少なく」は声の大きさを表し、洗濯物が乾かない文脈とは結びつかない。", "人気": "「人気が少なく」は人々の支持を表し、雨と洗濯物の文脈では意味が通らない。", "日照": "「日照が少なく」は日光が当たる量が少ないことを表し、雨が続いて洗濯物が乾かない内容と一致する。", "語彙": "語彙は言葉の集まりを指し、「語彙が少なく」は洗濯物が乾かない理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "日照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい建物のせいで、公園の日照が濃くなり、ベンチが冷えた。", "explanation": "ここは〈影〉の意味。光が遮られてできる暗い部分は影で、日照は光が当たることを指すため、濃くなる対象にはならない。"}, {"text": "新しい建物のせいで、公園の日照が流れなくなった。", "explanation": "ここは〈雨水〉の意味。流れるのは雨水で、日照は光が当たることを指すため、流れるという動きとは合わない。"}, {"text": "新しい建物のせいで、公園の日照がこもるようになった。", "explanation": "ここは〈熱気〉の意味。こもるのは熱や空気が外へ出ずにとどまることで、光が当たることを指す日照には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の南側の畑は、日照を多くて野菜がよく育つ。", "corrected_sentence": "山の南側の畑は、日照が多くて野菜がよく育つ。", "error_description": "誤りは「日照」に付く助詞。「多い」の主語は「日照」なので「が」が正しい。「を」だと形容詞の主語にならず、文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51755, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この鉢は日照を足りず、花が咲きにくい。", "corrected_sentence": "この鉢は日照が足りず、花が咲きにくい。", "error_description": "誤りは「日照」に付く助詞。「足りない」の主語は「日照」なので「が」が正しい。「を」だと形容詞の主語にならず、文が壊れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「日照をよい」では形容詞「よい」の主語にならず、文が成立しない。"}, {"text": "が", "is_correct": true, "explanation": "「日照がよい」の主語を示す「が」で、ここで正しい。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「日照でよい」では主語にならず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すため、「日照とよい」では形容詞「よい」の主語を示せない。"}], "correct_answer": "が", "explanations": {"を": "「を」は目的語を示すため、「日照をよい」では形容詞「よい」の主語にならず、文が成立しない。", "が": "「日照がよい」の主語を示す「が」で、ここで正しい。", "で": "「で」は場所や手段を示すため、「日照でよい」では主語にならず、意味が通らない。", "と": "「と」は並列を示すため、「日照とよい」では形容詞「よい」の主語を示せない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "「に」は対象や相手を示すため、「日照にさえぎる」では「さえぎる」の目的語を示せない。"}, {"text": "を", "is_correct": true, "explanation": "「日照をさえぎる」の目的語を示す「を」で、ここで正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「日照へさえぎる」では目的語にならず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「日照でさえぎる」は不自然で、「さえぎる」の対象を示せない。"}], "correct_answer": "を", "explanations": {"に": "「に」は対象や相手を示すため、「日照にさえぎる」では「さえぎる」の目的語を示せない。", "を": "「日照をさえぎる」の目的語を示す「を」で、ここで正しい。", "へ": "「へ」は方向を示すため、「日照へさえぎる」では目的語にならず、意味が通らない。", "で": "「で」は手段を示すが、「日照でさえぎる」は不自然で、「さえぎる」の対象を示せない。"}, "error_tags": {"に": "対象・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "太陽の光が地面や建物などに当たること。日当たり。", "primary_collocate": null, "pronunciation": "にっしょう", "ipa": "nʲiɕːoː", "syllable_count": 4, "sentences": [{"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "日照", "complexity_tier": "T3", "furigana": "これは、日照[にっしょう]や風通[かぜとお]しなどの環境[かんきょう]データを変数[へんすう]としてアルゴリズムに入力[にゅうりょく]し、最適[さいてき]な街区配置[がいくはいち]を自動的[じどうてき]に生成[せいせい]する手法[しゅほう]です。", "sentence_source": "mined"}, {"text": "この部屋は日照がよいので、冬でも暖かい。", "target_word": "日照", "complexity_tier": "T3", "furigana": "この部屋[へや]は日照[にっしょう]がよいので、冬[ふゆ]でも暖[あたた]かい。", "sentence_source": "generated"}, {"text": "マンションを選ぶとき、日照を一番大切に考えた。", "target_word": "日照", "complexity_tier": "T3", "furigana": "マンションを選[えら]ぶとき、日照[にっしょう]を一番[いちばん]大切[たいせつ]に考[かんが]えた。", "sentence_source": "generated"}, {"text": "隣に高いビルが建って、日照が悪くなった。", "target_word": "日照", "complexity_tier": "T3", "furigana": "隣[となり]に高[たか]いビルが建[た]って、日照[にっしょう]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "この家は南向きで、一日中日照に恵まれている。", "target_word": "日照", "complexity_tier": "T3", "furigana": "この家[いえ]は南向[みなみむ]きで、一日中[いちにちじゅう]日照[にっしょう]に恵[めぐ]まれている。", "sentence_source": "generated"}, {"text": "日照を確保するため、リビングの窓を大きく作った。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]を確保[かくほ]するため、リビングの窓[まど]を大[おお]きく作[つく]った。", "sentence_source": "generated"}, {"text": "日照のよい場所に洗濯物を干した。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]のよい場所[ばしょ]に洗濯物[せんたくもの]を干[ほ]した。", "sentence_source": "generated"}, {"text": "日照をさえぎる大きな木を、春に切ってもらった。", "target_word": "日照", "complexity_tier": "T3", "furigana": "日照[にっしょう]をさえぎる大[おお]きな木[き]を、春[はる]に切[き]ってもらった。", "sentence_source": "generated"}, {"text": "一階の部屋は日照が少ないので、昼でも電気をつけている。", "target_word": "日照", "complexity_tier": "T3", "furigana": "一階[いっかい]の部屋[へや]は日照[にっしょう]が少[すく]ないので、昼[ひる]でも電気[でんき]をつけている。", "sentence_source": "generated"}, {"text": "不動産屋は、この土地は日照が十分あると説明した。", "target_word": "日照", "complexity_tier": "T3", "furigana": "不動産屋[ふどうさんや]は、この土地[とち]は日照[にっしょう]が十分[じゅうぶん]あると説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日照", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "太陽の光が地面や建物に当たること。住まいや土地の日当たり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名作", "is_correct": false, "explanation": "「名作や風通しなどの環境データ」は意味が通らず、環境データの項目としても合わない。"}, {"text": "教養", "is_correct": false, "explanation": "教養は人の知識や品位を指し、環境データの項目としては合わない。"}, {"text": "日照", "is_correct": true, "explanation": "「日照や風通し」は住環境の項目を並べる言い方で、文の内容とも一致する。"}, {"text": "歴史", "is_correct": false, "explanation": "歴史は過去の出来事を指し、「歴史や風通しなどの環境データ」は意味が通らない。"}], "explanations": {"名作": "「名作や風通しなどの環境データ」は意味が通らず、環境データの項目としても合わない。", "教養": "教養は人の知識や品位を指し、環境データの項目としては合わない。", "日照": "「日照や風通し」は住環境の項目を並べる言い方で、文の内容とも一致する。", "歴史": "歴史は過去の出来事を指し、「歴史や風通しなどの環境データ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "日照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に、部屋の空調を日照に切り替えた。", "explanation": "ここは〈暖房〉の意味。部屋を暖める設備は暖房で、光が当たることを指す日照は暖める働きがないので合わない。"}, {"text": "蛇口の日照を止めて、庭の水やりをやめた。", "explanation": "ここは〈水道〉の意味。水を止めるのは水道の設備の話で、光が当たることを指す日照は止められないので合わない。"}, {"text": "節約するために、日照の料金を一か月ごとに払った。", "explanation": "ここは〈電気〉の意味。使った量に応じて払う料金は電気の料金で、光が当たることを指す日照には料金がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿気", "is_correct": false, "explanation": "「湿気のよい場所」は湿度の高さを表し、洗濯物を干す条件としては意味が逆になる。"}, {"text": "日照", "is_correct": true, "explanation": "「日照のよい場所」は日光がよく当たる場所を表し、洗濯物を干す文脈と一致する。"}, {"text": "温度", "is_correct": false, "explanation": "「温度のよい場所」は温度を表す語で、洗濯物を干す場所の条件として不自然になる。"}, {"text": "気圧", "is_correct": false, "explanation": "気圧は大気の圧力を指し、「気圧のよい場所」は洗濯物を干す条件として意味が通らない。"}], "explanations": {"湿気": "「湿気のよい場所」は湿度の高さを表し、洗濯物を干す条件としては意味が逆になる。", "日照": "「日照のよい場所」は日光がよく当たる場所を表し、洗濯物を干す文脈と一致する。", "温度": "「温度のよい場所」は温度を表す語で、洗濯物を干す場所の条件として不自然になる。", "気圧": "気圧は大気の圧力を指し、「気圧のよい場所」は洗濯物を干す条件として意味が通らない。"}, "sentence_index": 6, "correct_answer": "日照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜は部屋の日照を暗くして、ゆったり過ごした。", "explanation": "ここは〈照明〉の意味。明るさを暗くできるのは照明で、太陽の光が当たることを指す日照は人が調節できないので合わない。"}, {"text": "明日の日照は、街が白く埋まる予報だ。", "explanation": "ここは〈雪〉の意味。街を白く埋めるのは雪で、光が当たることを指す日照はそうした現象を表さないので合わない。"}, {"text": "暑い日は、日照のかさをさして外を歩いた。", "explanation": "ここは〈日傘〉の意味。日差しを防ぐためにさす傘は日傘で、光が当たることを指す日照を道具の名前として使うのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この畑は日照をよいので、野菜がよく育つ。", "corrected_sentence": "この畑は日照がよいので、野菜がよく育つ。", "error_description": "誤りは「日照」に付く助詞。「よい」の主語は「日照」なので「が」が正しい。「を」だと形容詞「よい」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この農園は日照で恵まれていて、野菜がよく育つ。", "corrected_sentence": "この農園は日照に恵まれていて、野菜がよく育つ。", "error_description": "誤りは「日照」に付く助詞。「恵まれる」は「〜に恵まれる」の形で使うため、「に」が正しい。「で」だと文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
