INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51757, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51757, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "何かの形や動きを、数字を使って細かく決めるやり方のことです。", "primary_collocate": null, "pronunciation": "ぱらめとりっく", "ipa": "paɾametoɾikku", "syllable_count": 7, "sentences": [{"text": "パラメトリックなやり方なら、数字を変えるだけで椅子の形を変えられます。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "パラメトリックなやり方[かた]なら、数字[すうじ]を変[か]えるだけで椅子[いす]の形[かたち]を変[か]えられます。", "sentence_source": "generated"}, {"text": "このソフトはパラメトリックに形を決めるので、細かい調整が簡単です。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "このソフトはパラメトリックに形[かたち]を決[き]めるので、細[こま]かい調整[ちょうせい]が簡単[かんたん]です。", "sentence_source": "generated"}, {"text": "兄は模型の窓の大きさを、パラメトリックな方法で細かく決めました。", "target_word": "パラメトリックな", "complexity_tier": "T3", "furigana": "兄[あに]は模型[もけい]の窓[まど]の大きさ[おおきさ]を、パラメトリックな方法[ほうほう]で細[こま]かく決[き]めました。", "sentence_source": "generated"}, {"text": "パラメトリックな設計では、曲がり方も数字で細かく決めることができます。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "パラメトリックな設計[せっけい]では、曲[ま]がり方[かた]も数字[すうじ]で細[こま]かく決[き]めることができます。", "sentence_source": "generated"}, {"text": "手で描くより、パラメトリックに作るほうが、あとで直すのが楽です。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "手[て]で描[えが]くより、パラメトリックに作[つく]るほうが、あとで直[なお]すのが楽[らく]です。", "sentence_source": "generated"}, {"text": "このデザイナーは、パラメトリックな方法で、花びらの動きまで数字で決めています。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "このデザイナーは、パラメトリックな方法[ほうほう]で、花[はな]びらの動[うご]きまで数字[すうじ]で決[き]めています。", "sentence_source": "generated"}, {"text": "数字で形を決める、つまりパラメトリックなやり方は、建築でよく使われます。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "数字[すうじ]で形[かたち]を決[き]める、つまりパラメトリックなやり方[かた]は、建築[けんちく]でよく使[つか]われます。", "sentence_source": "generated"}, {"text": "展示された作品は、すべてパラメトリックに作られた立体でした。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "展示[てんじ]された作品[さくひん]は、すべてパラメトリックに作[つく]られた立体[りったい]でした。", "sentence_source": "generated"}, {"text": "パラメトリックな方法を学ぶために、学生は数字の入れ方から練習します。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "パラメトリックな方法[ほうほう]を学[まな]ぶために、学生[がくせい]は数字[すうじ]の入[い]れ方[かた]から練習[れんしゅう]します。", "sentence_source": "generated"}, {"text": "屋根の傾きをパラメトリックに変えると、影の形もすぐに確かめられます。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "屋根[やね]の傾[かたむ]きをパラメトリックに変[か]えると、影[かげ]の形[かたち]もすぐに確[たし]かめられます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パラメトリック", "label": "語幹"}, {"form": "パラメトリックな", "label": "連体形"}, {"form": "パラメトリックに", "label": "連用形"}], "register": "専門的・やや丁寧", "sense_fingerprint": "形や動きを数字で細かく決めるやり方を表す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51757, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "設計の仕方を指す形状詞。「〜なやり方なら、数字を変えるだけで形を変えられる」の主語として成り立つ唯一の語。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やかなやり方なら」は雰囲気の形容で、数字を変えるだけで形が変わる話の前置きにならない。"}, {"text": "派手", "is_correct": false, "explanation": "「派手なやり方」は見た目の印象を言い、数字で形を変える仕組みを指さない。"}, {"text": "大雑把", "is_correct": false, "explanation": "「大雑把なやり方なら」は作りの粗さを言い、数字の変更で形が変わる理由にならない。"}], "explanations": {"パラメトリック": "設計の仕方を指す形状詞。「〜なやり方なら、数字を変えるだけで形を変えられる」の主語として成り立つ唯一の語。", "穏やか": "「穏やかなやり方なら」は雰囲気の形容で、数字を変えるだけで形が変わる話の前置きにならない。", "派手": "「派手なやり方」は見た目の印象を言い、数字で形を変える仕組みを指さない。", "大雑把": "「大雑把なやり方なら」は作りの粗さを言い、数字の変更で形が変わる理由にならない。"}, "sentence_index": 0, "correct_answer": "パラメトリック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この器は、ろくろで一つずつ手作りしたパラメトリックなものです。", "explanation": "ここは〈手作り〉の意味（職人が手で一つずつ仕上げる）。数字で細かく決めるやり方を指す語なので、手で作った品の説明には合わない。"}, {"text": "この公園は、遊具の位置をパラメトリックにでたらめに決めました。", "explanation": "ここは〈無作為〉の意味（でたらめに決める）。数字で細かく決めるやり方とは逆の考え方なので合わない。"}, {"text": "この模型は、窓の位置をパラメトリックにざっと決めただけで、細部は後回しにしました。", "explanation": "ここは〈大まか〉の意味（おおよそで決める）。パラメトリックは数字で細かく決めるやり方なので、ざっと決める話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51757, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "直前の「数字で形を決める」を言い換える語。「つまり〜なやり方」の形で定義を置くのに合う唯一の語。"}, {"text": "静か", "is_correct": false, "explanation": "「つまり静かなやり方」は「数字で形を決める」の言い換えにならない。音や様子を表す語。"}, {"text": "無造作", "is_correct": false, "explanation": "「無造作なやり方」は計画のなさを表し、数字で決めることの定義にならない。"}, {"text": "素朴", "is_correct": false, "explanation": "「素朴なやり方」は飾らない印象で、数値で形を決める方法の説明にならない。"}], "explanations": {"パラメトリック": "直前の「数字で形を決める」を言い換える語。「つまり〜なやり方」の形で定義を置くのに合う唯一の語。", "静か": "「つまり静かなやり方」は「数字で形を決める」の言い換えにならない。音や様子を表す語。", "無造作": "「無造作なやり方」は計画のなさを表し、数字で決めることの定義にならない。", "素朴": "「素朴なやり方」は飾らない印象で、数値で形を決める方法の説明にならない。"}, "sentence_index": 6, "correct_answer": "パラメトリック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この皿は、同じ型を使って量産するパラメトリックな製品です。", "explanation": "ここは〈量産〉の意味（同じ型で大量に作る）。数字で細かく決めるやり方を指すので、同じ型を繰り返す話には合わない。"}, {"text": "この壁は、パラメトリックな色で塗り分けてあり、一面ごとに色が違います。", "explanation": "ここは〈色彩〉の意味（塗る色の種類）。数字で細かく決めるやり方を指す語なので、色の種類の話には合わない。"}, {"text": "この扉は、パラメトリックに音を外へ漏らさない作りです。", "explanation": "ここは〈防音〉の意味（音を外に漏らさない性能）。数字で細かく決めるやり方を指すので、遮音の性能とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51757, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このソフトは、パラメトリックと形を変えられるので、細かい調整が簡単です。", "corrected_sentence": "このソフトは、パラメトリックに形を変えられるので、細かい調整が簡単です。", "error_description": "「パラメトリック」は後ろの動詞「変える」を修飾するので、副詞形「に」が必要。「と」は並列・共同の助詞で、ここでは合わない。正しくは「パラメトリックに形を変えられる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "語幹の形。「に」が続いて「決める」を修飾しているが、語幹はその前の基本部分。"}, {"text": "パラメトリックな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、ここは後ろの動詞「決める」を修飾しているので合わない。"}, {"text": "パラメトリックに", "is_correct": false, "explanation": "連用形。「に」まで含んだ形なので、語幹だけを問う空所には入らない。"}, {"text": "パラメトリックで", "is_correct": false, "explanation": "「で」が付く形で、手段や理由を言う文脈に使う。ここは動詞「決める」を修飾する位置なので合わない。"}], "correct_form": "パラメトリック", "base_form": "パラメトリック", "form_label": "語幹", "sentence_index": 1, "explanations": {"パラメトリック": "語幹の形。「に」が続いて「決める」を修飾しているが、語幹はその前の基本部分。", "パラメトリックな": "連体形。名詞を修飾する形で、ここは後ろの動詞「決める」を修飾しているので合わない。", "パラメトリックに": "連用形。「に」まで含んだ形なので、語幹だけを問う空所には入らない。", "パラメトリックで": "「で」が付く形で、手段や理由を言う文脈に使う。ここは動詞「決める」を修飾する位置なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51757, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店に並んだ椅子は、すべてパラメトリックく作られた製品でした。", "corrected_sentence": "店に並んだ椅子は、すべてパラメトリックに作られた製品でした。", "error_description": "「パラメトリック」は形状詞なので、後ろの動詞「作る」を修飾するには副詞形「に」が必要。「く」は形容詞の活用で、形状詞には使えない。正しくは「パラメトリックに作られた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "語幹の形。「に」が続いて「作られた」を修飾する前の基本部分。"}, {"text": "パラメトリックだ", "is_correct": false, "explanation": "断定の形。文末で言い切るときに使い、「作られた」を修飾するここでは合わない。"}, {"text": "パラメトリックだった", "is_correct": false, "explanation": "過去の断定の形。過去を表す形は後ろの「立体でした」に付いていて、ここでは合わない。"}, {"text": "パラメトリックだろう", "is_correct": false, "explanation": "推量の形。推量ではなく確かな事実を述べる文なので合わない。"}], "correct_form": "パラメトリック", "base_form": "パラメトリック", "form_label": "語幹", "sentence_index": 7, "explanations": {"パラメトリック": "語幹の形。「に」が続いて「作られた」を修飾する前の基本部分。", "パラメトリックだ": "断定の形。文末で言い切るときに使い、「作られた」を修飾するここでは合わない。", "パラメトリックだった": "過去の断定の形。過去を表す形は後ろの「立体でした」に付いていて、ここでは合わない。", "パラメトリックだろう": "推量の形。推量ではなく確かな事実を述べる文なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の動作や形状を、複数の数値（パラメーター）で自由に変えられるように設計すること。", "primary_collocate": null, "pronunciation": "ぱらめとりっく", "ipa": "paɾametoɾikku", "syllable_count": 7, "sentences": [{"text": "近年、パラメトリックな理論は、都市計画の分野において重要な基盤となりつつあります。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "近年[きんねん]、パラメトリックな理論[りろん]は、都市計画[としけいかく]の分野[ぶんや]において重要[じゅうよう]な基盤[きばん]となりつつあります。", "sentence_source": "generated"}, {"text": "この椅子はパラメトリックな手法で、座面の曲線を数値だけで変えられるように作られています。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "この椅子[いす]はパラメトリックな手法[しゅほう]で、座面[ざめん]の曲線[きょくせん]を数値[すうち]だけで変[か]えられるように作[つく]られています。", "sentence_source": "generated"}, {"text": "設計者が形をパラメトリックに決めておけば、寸法の変更も一度で済みます。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]が形[かたち]をパラメトリックに決[き]めておけば、寸法[すんぽう]の変更[へんこう]も一度[いちど]で済[す]みます。", "sentence_source": "generated"}, {"text": "パラメトリックな設計では、高さや幅を数値で変えるたびに、モデル全体が自動的に変わります。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "パラメトリックな設計[せっけい]では、高[たか]さや幅[はば]を数値[すうち]で変[か]えるたびに、モデル全体[ぜんたい]が自動的[じどうてき]に変[か]わります。", "sentence_source": "generated"}, {"text": "彼女は建築の授業で、パラメトリックな方法を使って屋根の形を調べました。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は建築[けんちく]の授業[じゅぎょう]で、パラメトリックな方法[ほうほう]を使[つか]って屋根[やね]の形[かたち]を調[しら]べました。", "sentence_source": "generated"}, {"text": "数値を一つ変えるだけで形が変わるのは、パラメトリックな設計だからです。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "数値[すうち]を一[ひと]つ変[か]えるだけで形[かたち]が変[か]わるのは、パラメトリックな設計[せっけい]だからです。", "sentence_source": "generated"}, {"text": "この橋の模型はパラメトリックに作ってあるので、長さの違う案をすぐに比べられます。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "この橋[はし]の模型[もけい]はパラメトリックに作[つく]ってあるので、長[なが]さの違[ちが]う案[あん]をすぐに比[くら]べられます。", "sentence_source": "generated"}, {"text": "手で一つずつ描く方法に比べて、パラメトリックな方法は修正の手間がずっと少ないです。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "手[て]で一[ひと]つずつ描[えが]く方法[ほうほう]に比[くら]べて、パラメトリックな方法[ほうほう]は修正[しゅうせい]の手間[てま]がずっと少[すく]ないです。", "sentence_source": "generated"}, {"text": "先生は、パラメトリックな考え方を使えば、複雑な形も少ない数値で表せると説明しました。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "先生[せんせい]は、パラメトリックな考[かんが]え方[かた]を使[つか]えば、複雑[ふくざつ]な形[かたち]も少[すく]ない数値[すうち]で表[あらわ]せると説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "私たちの研究室では、建物の外壁をパラメトリックに設計するソフトを使っています。", "target_word": "パラメトリック", "complexity_tier": "T3", "furigana": "私[わたし]たちの研究室[けんきゅうしつ]では、建物[たてもの]の外壁[がいへき]をパラメトリックに設計[せっけい]するソフトを使[つか]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パラメトリック", "label": "語幹"}, {"form": "パラメトリックな", "label": "連体形"}, {"form": "パラメトリックに", "label": "連用形"}], "register": "専門的・書き言葉", "sense_fingerprint": "数値（パラメーター）で形や動きを自由に変えられる設計方法を表す専門語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "数値で形や動きを変える設計法を指す語で、「〜な理論」の主題として成り立つ唯一の語。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やかな理論」は設計法を指す語にならない。穏やかは雰囲気を表す形容。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は見た目の華やかさを言う語で、ここで求められる設計の方法を指さない。"}, {"text": "大雑把", "is_correct": false, "explanation": "「大雑把」は作りの粗さを言う語で、建築の理論の名として文が通らない。"}], "explanations": {"パラメトリック": "数値で形や動きを変える設計法を指す語で、「〜な理論」の主題として成り立つ唯一の語。", "穏やか": "「穏やかな理論」は設計法を指す語にならない。穏やかは雰囲気を表す形容。", "派手": "「派手」は見た目の華やかさを言う語で、ここで求められる設計の方法を指さない。", "大雑把": "「大雑把」は作りの粗さを言う語で、建築の理論の名として文が通らない。"}, "sentence_index": 0, "correct_answer": "パラメトリック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この椅子は、職人が一つずつ手で削ったパラメトリックな作品です。", "explanation": "ここは〈手作り〉の意味（職人が手で一つずつ仕上げる）。パラメトリックは数値で形を決める設計を指すので、手で削る作業の話には合わない。"}, {"text": "この棚は、板の長さをパラメトリックに固定して、一つの大きさでしか作れません。", "explanation": "ここは〈固定〉の意味（寸法を変えずに一つに決めておく）。パラメトリックは数値で形を自由に変える設計を指すので、固定する話には合わない。"}, {"text": "このドアは、人が近づくとパラメトリックに開くように作られています。", "explanation": "ここは〈自動〉の意味（感知して勝手に動く）。パラメトリックは数値で形や動きを決めて変える設計を指すので、自動で開く仕組みの説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "数値で形を決める設計法。「〜に作ってあるので案を比べられる」という理由になる唯一の語。"}, {"text": "静か", "is_correct": false, "explanation": "「静かに作ってある」は作業の様子を表すだけで、案をすぐ比べられる理由にならない。"}, {"text": "無造作", "is_correct": false, "explanation": "「無造作に作ってあるので比べられる」は因果が成り立たない。"}, {"text": "素朴", "is_correct": false, "explanation": "「素朴に作ってある」は見た目の印象で、比較のしやすさの理由にならない。"}], "explanations": {"パラメトリック": "数値で形を決める設計法。「〜に作ってあるので案を比べられる」という理由になる唯一の語。", "静か": "「静かに作ってある」は作業の様子を表すだけで、案をすぐ比べられる理由にならない。", "無造作": "「無造作に作ってあるので比べられる」は因果が成り立たない。", "素朴": "「素朴に作ってある」は見た目の印象で、比較のしやすさの理由にならない。"}, "sentence_index": 6, "correct_answer": "パラメトリック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この椅子は、同じ型で量産するパラメトリックな製品です。", "explanation": "ここは〈量産〉の意味（同じ型で大量に作る）。パラメトリックは数値で形を変える設計を指すので、同じ型を繰り返す話には合わない。"}, {"text": "この箱はパラメトリックという素材で、軽くて丈夫なアルミでできています。", "explanation": "ここは〈素材〉の意味（材料の種類）。パラメトリックは設計の方法を指すので、材料の名にはならない。"}, {"text": "この壁はパラメトリックに音を通さない造りなので、隣の声が聞こえません。", "explanation": "ここは〈防音〉の意味（音を外に漏らさない性能）。パラメトリックは数値で形を変える設計なので、遮音の性能を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この棚はパラメトリックに手法で、板の長さを数値だけで変えられるように作られています。", "corrected_sentence": "この棚はパラメトリックな手法で、板の長さを数値だけで変えられるように作られています。", "error_description": "「パラメトリック」は形状詞なので、名詞「手法」を修飾するには連体形「な」が必要。連用形「に」は誤り。正しくは「パラメトリックな手法」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "語幹の形。活用語尾を付ける前の基本部分で、ここでは「な」を続けて「手法」を修飾している。"}, {"text": "パラメトリックな", "is_correct": false, "explanation": "連体形。「な」まで含んだ形なので、語幹だけを問う空所には入らない。"}, {"text": "パラメトリックに", "is_correct": false, "explanation": "連用形。「に」が付く形で、ここは「手法」を修飾する位置なので合わない。"}, {"text": "パラメトリックで", "is_correct": false, "explanation": "「で」が付く形で、理由や手段を言う文脈で使う。ここは名詞を直接修飾する位置なので合わない。"}], "correct_form": "パラメトリック", "base_form": "パラメトリック", "form_label": "語幹", "sentence_index": 1, "explanations": {"パラメトリック": "語幹の形。活用語尾を付ける前の基本部分で、ここでは「な」を続けて「手法」を修飾している。", "パラメトリックな": "連体形。「な」まで含んだ形なので、語幹だけを問う空所には入らない。", "パラメトリックに": "連用形。「に」が付く形で、ここは「手法」を修飾する位置なので合わない。", "パラメトリックで": "「で」が付く形で、理由や手段を言う文脈で使う。ここは名詞を直接修飾する位置なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51758, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この机の天板はパラメトリックを決めてあるので、大きさをすぐ変えられます。", "corrected_sentence": "この机の天板はパラメトリックに決めてあるので、大きさをすぐ変えられます。", "error_description": "「パラメトリック」は動詞「決める」を修飾するので、副詞形「に」が必要。「を」は目的語の格助詞で、形状詞には使えない。正しくは「パラメトリックに決めてある」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "パラメトリック", "is_correct": true, "explanation": "語幹の形。「〜な方法」の「な」の前にある基本部分で、活用語尾はその後ろに付く。"}, {"text": "パラメトリックだ", "is_correct": false, "explanation": "断定の形。文末で言い切るときに使い、名詞を修飾するここには入らない。"}, {"text": "パラメトリックだった", "is_correct": false, "explanation": "過去の断定の形。過去の話ではないこの文では合わない。"}, {"text": "パラメトリックだろう", "is_correct": false, "explanation": "推量の形。推量ではなく事実を述べる文なので合わない。"}], "correct_form": "パラメトリック", "base_form": "パラメトリック", "form_label": "語幹", "sentence_index": 7, "explanations": {"パラメトリック": "語幹の形。「〜な方法」の「な」の前にある基本部分で、活用語尾はその後ろに付く。", "パラメトリックだ": "断定の形。文末で言い切るときに使い、名詞を修飾するここには入らない。", "パラメトリックだった": "過去の断定の形。過去の話ではないこの文では合わない。", "パラメトリックだろう": "推量の形。推量ではなく事実を述べる文なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「風通しが」は「よく」の主語を示し、「風通しがよく」の形になる。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では「風通しのよく」となり、文の述語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「風通しとよく」となり、主語の役割を果たさない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「風通しでよく」となり、風通しの良さを表す形にならない。"}], "correct_answer": "が", "explanations": {"が": "「風通しが」は「よく」の主語を示し、「風通しがよく」の形になる。", "の": "連体修飾の「の」では「風通しのよく」となり、文の述語として成り立たない。", "と": "並列の「と」では「風通しとよく」となり、主語の役割を果たさない。", "で": "手段の「で」では「風通しでよく」となり、風通しの良さを表す形にならない。"}, "error_tags": {"の": "連体修飾", "と": "並列・共同", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "風が通り抜けることです。", "primary_collocate": null, "pronunciation": "かぜとおし", "ipa": "kazetooɕi", "syllable_count": 5, "sentences": [{"text": "窓を両方開けると、部屋の風通しがよくなります。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "窓[まど]を両方[りょうほう]開[あ]けると、部屋[へや]の風通[かぜとお]しがよくなります。", "sentence_source": "generated"}, {"text": "この倉庫は壁に穴があって風通しがいいので、荷物がかびません。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "この倉庫[そうこ]は壁[かべ]に穴[あな]があって風通[かぜとお]しがいいので、荷物[にもつ]がかびません。", "sentence_source": "generated"}, {"text": "夏は風通しのいい服を着ると、汗をかいても気持ちがいいです。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "夏[なつ]は風通[かぜとお]しのいい服[ふく]を着[き]ると、汗[あせ]をかいても気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "押し入れの戸を少し開けて、風通しをよくしておきました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "押[お]し入[い]れの戸[と]を少[すこ]し開[あ]けて、風通[かぜとお]しをよくしておきました。", "sentence_source": "generated"}, {"text": "木々が茂りすぎて、庭の風通しが悪くなってしまいました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "木々[きぎ]が茂[しげ]りすぎて、庭[にわ]の風通[かぜとお]しが悪[わる]くなってしまいました。", "sentence_source": "generated"}, {"text": "風通しのよい縁側で、祖母はいつもお茶を飲んでいます。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "風通[かぜとお]しのよい縁側[えんがわ]で、祖母[そぼ]はいつもお茶[ちゃ]を飲[の]んでいます。", "sentence_source": "generated"}, {"text": "梅雨の間は、部屋の風通しに気をつけないとカビが生えます。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "梅雨[つゆ]の間[あいだ]は、部屋[へや]の風通[かぜとお]しに気[き]をつけないとカビが生[は]えます。", "sentence_source": "generated"}, {"text": "竹で編んだ籠は風通しがよく、野菜を入れておくのに向いています。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "竹[たけ]で編[あ]んだ籠[かご]は風通[かぜとお]しがよく、野菜[やさい]を入[い]れておくのに向[む]いています。", "sentence_source": "generated"}, {"text": "古い日本の家は、風通しを大切にして作られています。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "古[ふる]い日本[にほん]の家[いえ]は、風通[かぜとお]しを大切[たいせつ]にして作[つく]られています。", "sentence_source": "generated"}, {"text": "窓が一つしかない部屋は、風通しが悪くて息苦しいです。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "窓[まど]が一[ひと]つしかない部屋[へや]は、風通[かぜとお]しが悪[わる]くて息苦[いきぐる]しいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風通し", "label": "基本形"}], "register": "中立（日常語）", "sense_fingerprint": "部屋・物・服などを風が通り抜けること、またその度合いを表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風通し", "is_correct": true, "explanation": "窓を開けると空気が通る状態がよくなる、という文脈に合う唯一の語。"}, {"text": "家賃", "is_correct": false, "explanation": "窓を開けても家賃はよくならず、「よくなります」と結びつかない。"}, {"text": "音量", "is_correct": false, "explanation": "窓を開けて音量がよくなる、とは言わない。"}, {"text": "段差", "is_correct": false, "explanation": "窓を開けても段差は改善されず、「よくなります」が合わない。"}], "explanations": {"風通し": "窓を開けると空気が通る状態がよくなる、という文脈に合う唯一の語。", "家賃": "窓を開けても家賃はよくならず、「よくなります」と結びつかない。", "音量": "窓を開けて音量がよくなる、とは言わない。", "段差": "窓を開けても段差は改善されず、「よくなります」が合わない。"}, "sentence_index": 0, "correct_answer": "風通し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は風通しで中のほこりを吸い取り、掃除がとても楽です。", "explanation": "ここは〈掃除機〉の意味（ほこりを吸い取る機械）。風通しは空気の流れで、ほこりを吸い取る道具の名にはならないので合わない。"}, {"text": "この庭は風通しの陰にあり、夏でも涼しく過ごせます。", "explanation": "ここは〈木陰〉の意味（木の下の日陰）。風通しは空気の流れで、日陰のある場所を指さないので合わない。"}, {"text": "この風通しは木でできていて、閉めると音がしません。", "explanation": "ここは〈ドア〉の意味（出入り口を開け閉めする戸）。風通しは空気の流れで、木でできた戸の名にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風通し", "is_correct": true, "explanation": "梅雨の間に部屋の空気の流れに気をつける、というカビ対策の文脈で成り立つ唯一の語。"}, {"text": "香り", "is_correct": false, "explanation": "香りはカビの発生と結びつかず、気をつける対象として文が成り立たない。"}, {"text": "機嫌", "is_correct": false, "explanation": "部屋の機嫌は擬人化の表現で、カビとは結びつかない。"}, {"text": "行列", "is_correct": false, "explanation": "部屋の行列に気をつける、は意味を成さず、カビの話に合わない。"}], "explanations": {"風通し": "梅雨の間に部屋の空気の流れに気をつける、というカビ対策の文脈で成り立つ唯一の語。", "香り": "香りはカビの発生と結びつかず、気をつける対象として文が成り立たない。", "機嫌": "部屋の機嫌は擬人化の表現で、カビとは結びつかない。", "行列": "部屋の行列に気をつける、は意味を成さず、カビの話に合わない。"}, "sentence_index": 6, "correct_answer": "風通し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この通路は風通しを傘にして、雨の日でも濡れません。", "explanation": "ここは〈傘〉の意味（雨をよける道具）。風通しは空気の流れで、雨をよける道具の名としては合わない。"}, {"text": "この地下室は風通しの水分が多く、物がかびやすいです。", "explanation": "ここは〈湿気〉の意味（空気中の水分）。風通しは空気の流れで、水分の量を指す語ではないので合わない。"}, {"text": "この靴は風通しなので、雨の日も足がぬれません。", "explanation": "ここは〈防水〉の意味（水を通さない性質）。風通しは空気が通ることで、雨をはじく性能には当たらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を閉め切ると、部屋の風通しをわるくなります。", "corrected_sentence": "窓を閉め切ると、部屋の風通しがわるくなります。", "error_description": "「わるくなる」は自動詞で主語を示す「が」を取る。「を」は目的語の格助詞で誤り。正しくは「風通しがわるくなります」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51759, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を増やすと、部屋の風通しがよいなります。", "corrected_sentence": "窓を増やすと、部屋の風通しがよくなります。", "error_description": "形容詞「よい」は、「なる」に続くとき連用形「よく」になる。「よいなります」は活用の誤り。正しくは「よくなります」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「風通しの」は「よい家」を修飾する連体修飾の「の」で、「風通しのよい家」の形になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、修飾関係を作れず「風通しからよい」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「風通しをよい家」となり、「よい」が家を修飾する形にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「風通しでよい家」となり、風通しの良さを表す形にならない。"}], "correct_answer": "の", "explanations": {"の": "「風通しの」は「よい家」を修飾する連体修飾の「の」で、「風通しのよい家」の形になる。", "から": "起点を示す「から」は、修飾関係を作れず「風通しからよい」は成り立たない。", "を": "目的語の「を」では「風通しをよい家」となり、「よい」が家を修飾する形にならない。", "で": "手段の「で」では「風通しでよい家」となり、風通しの良さを表す形にならない。"}, "error_tags": {"から": "起点", "を": "目的語", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "風が建物や物の間をスムーズに通ること。特に、家の周りなどで空気の流れが良い状態を指す。", "primary_collocate": null, "pronunciation": "かぜとおし", "ipa": "kazetooɕi", "syllable_count": 5, "sentences": [{"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "これは、日照[にっしょう]や風通[かぜとお]しなどの環境[かんきょう]データを変数[へんすう]としてアルゴリズムに入力[にゅうりょく]し、最適[さいてき]な街区[がいく]配置[はいち]を自動的[じどうてき]に生成[せいせい]する手法[しゅほう]です。", "sentence_source": "mined"}, {"text": "この家は隣との間が広く、風通しがよいので、夏でも涼しく過ごせます。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "この家[いえ]は隣[となり]との間[あいだ]が広[ひろ]く、風通[かぜとお]しがよいので、夏[なつ]でも涼[すず]しく過[す]ごせます。", "sentence_source": "generated"}, {"text": "建物の間が狭すぎて風通しが悪く、湿気が壁にたまっています。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "建物[たてもの]の間[あいだ]が狭[せま]すぎて風通[かぜとお]しが悪[わる]く、湿気[しっけ]が壁[かべ]にたまっています。", "sentence_source": "generated"}, {"text": "設計者は、南側の窓を大きくして家の風通しを確かめました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、南側[みなみがわ]の窓[まど]を大[おお]きくして家[いえ]の風通[かぜとお]しを確[たし]かめました。", "sentence_source": "generated"}, {"text": "高い塀を低くしたところ、庭の風通しが見違えるほど良くなりました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "高[たか]い塀[へい]を低[ひく]くしたところ、庭[にわ]の風通[かぜとお]しが見違[みちが]えるほど良[よ]くなりました。", "sentence_source": "generated"}, {"text": "風通しを考えて、二つの棟の間に細い通路を作りました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "風通[かぜとお]しを考[かんが]えて、二[ふた]つの棟[むね]の間[あいだ]に細[ほそ]い通路[つうろ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "ビルが並びすぎると、街の風通しが悪くなり、夏の暑さが厳しくなります。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "ビルが並[なら]びすぎると、街[まち]の風通[かぜとお]しが悪[わる]くなり、夏[なつ]の暑[あつ]さが厳[きび]しくなります。", "sentence_source": "generated"}, {"text": "風通しのよい家では、洗濯物が早く乾くので助かります。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "風通[かぜとお]しのよい家[いえ]では、洗濯物[せんたくもの]が早[はや]く乾[かわ]くので助[たす]かります。", "sentence_source": "generated"}, {"text": "風通しを調べるために、模型に煙を流して空気の動きを見ました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "風通[かぜとお]しを調[しら]べるために、模型[もけい]に煙[けむり]を流[なが]して空気[くうき]の動[うご]きを見[み]ました。", "sentence_source": "generated"}, {"text": "家の北側は風通しが悪いので、窓をもう一つ増やすことにしました。", "target_word": "風通し", "complexity_tier": "T3", "furigana": "家[いえ]の北側[きたがわ]は風通[かぜとお]しが悪[わる]いので、窓[まど]をもう一[ひと]つ増[ふ]やすことにしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風通し", "label": "基本形"}], "register": "中立（日常語・書き言葉）", "sense_fingerprint": "建物や家の周りで風・空気がよく流れる状態（具体的な空気の流れ）を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風通し", "is_correct": true, "explanation": "空気が建物の間を通る状態を表し、日照と並ぶ環境データの項目になる語。"}, {"text": "予算", "is_correct": false, "explanation": "予算は費用の計画で、日照と並べて環境データの項目にはならない。"}, {"text": "材料費", "is_correct": false, "explanation": "費用の語で、日照と並べて環境データの項目にはならない。"}, {"text": "人気", "is_correct": false, "explanation": "人気は評判の語で、環境データの項目として並ばない。"}], "explanations": {"風通し": "空気が建物の間を通る状態を表し、日照と並ぶ環境データの項目になる語。", "予算": "予算は費用の計画で、日照と並べて環境データの項目にはならない。", "材料費": "費用の語で、日照と並べて環境データの項目にはならない。", "人気": "人気は評判の語で、環境データの項目として並ばない。"}, "sentence_index": 0, "correct_answer": "風通し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は風通しを部屋に置いて、空気を入れ替えます。", "explanation": "ここは〈扇風機〉の意味（風を送る機械）。風通しは空気の流れで、部屋に置いて使う機械の名としては合わない。"}, {"text": "この庭は風通しの下にあり、夏の昼でも涼しく過ごせます。", "explanation": "ここは〈木陰〉の意味（木の下の日陰）。風通しは空気の流れで、日陰のある場所を指さないので合わない。"}, {"text": "この部屋は風通しで床のほこりを吸い取るので、掃除がとても楽です。", "explanation": "ここは〈掃除機〉の意味（ほこりを吸い取る機械）。風通しは空気の流れで、ほこりを吸い取る道具にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風通し", "is_correct": true, "explanation": "空気の流れが悪くなり暑さが増す、という因果の主語になる語。"}, {"text": "会話", "is_correct": false, "explanation": "「街の会話が悪くなり、夏の暑さが厳しくなります」は因果が成り立たない。"}, {"text": "年齢", "is_correct": false, "explanation": "街の年齢は暑さの原因にならず、文脈に合わない。"}, {"text": "料金", "is_correct": false, "explanation": "「街の料金が悪くなる」は意味を成さず、暑さの説明にならない。"}], "explanations": {"風通し": "空気の流れが悪くなり暑さが増す、という因果の主語になる語。", "会話": "「街の会話が悪くなり、夏の暑さが厳しくなります」は因果が成り立たない。", "年齢": "街の年齢は暑さの原因にならず、文脈に合わない。", "料金": "「街の料金が悪くなる」は意味を成さず、暑さの説明にならない。"}, "sentence_index": 6, "correct_answer": "風通し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この壁は風通しが入っていて、冬の寒さを防ぎます。", "explanation": "ここは〈断熱材〉の意味（熱を伝えにくい材料）。風通しは空気の流れで、壁に入れる材料ではないので合わない。"}, {"text": "この部屋は風通しで暖まるので、冬でも暖かいです。", "explanation": "ここは〈ストーブ〉の意味（熱を出す暖房器具）。風通しは暖める手段にならないので合わない。"}, {"text": "この建物は風通しを閉めて、外からの光を遮っています。", "explanation": "ここは〈カーテン〉の意味（光をさえぎる布）。風通しは空気の流れで、光を遮る布の名にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は風通しを良いので、夏も涼しく過ごせます。", "corrected_sentence": "この部屋は風通しがよいので、夏も涼しく過ごせます。", "error_description": "「よい」は形容詞で、主語を示す「が」を取る。「を」は目的語の格助詞で誤り。正しくは「風通しがよい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51760, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を一つ増やして、部屋の風通しを開けました。", "corrected_sentence": "窓を一つ増やして、部屋の風通しをよくしました。", "error_description": "「風通し」と結びつくのは「よくする」で、「開ける」は対象が違う（窓や戸に使う動詞）。動詞の部分が誤り。正しくは「風通しをよくしました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51761, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「アルゴリズムの」で前の語句を修飾し、「おかげで」と続く自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「アルゴリズムを」では「おかげで」とつながらず不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「アルゴリズムで」では理由を示す「おかげで」と意味がつながらない。"}, {"text": "と", "is_correct": false, "explanation": "「アルゴリズムと」は並列になり、「おかげで」には合わない。"}], "correct_answer": "の", "explanations": {"の": "「アルゴリズムの」で前の語句を修飾し、「おかげで」と続く自然な形になる。", "を": "「アルゴリズムを」では「おかげで」とつながらず不自然になる。", "で": "「アルゴリズムで」では理由を示す「おかげで」と意味がつながらない。", "と": "「アルゴリズムと」は並列になり、「おかげで」には合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51761, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51761, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題を解くための、決まった手順のことです。", "primary_collocate": null, "pronunciation": "あるごりずむ", "ipa": "aɾɯɡoɾizɯmɯ", "syllable_count": 6, "sentences": [{"text": "検索サイトは、アルゴリズムを使って結果を順番に並べている。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "検索[けんさく]サイトは、アルゴリズムを使[つか]って結果[けっか]を順番[じゅんばん]に並[なら]べている。", "sentence_source": "generated"}, {"text": "新しいアルゴリズムのおかげで、計算の時間が十分の一になった。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "新[あたら]しいアルゴリズムのおかげで、計算[けいさん]の時間[じかん]が十分[じゅうぶん]の一[いち]になった。", "sentence_source": "generated"}, {"text": "彼は道を探すアルゴリズムを考えて、地図アプリに使った。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "彼[かれ]は道[みち]を探[さが]すアルゴリズムを考[かんが]えて、地図[ちず]アプリに使[つか]った。", "sentence_source": "generated"}, {"text": "アルゴリズムとは、問題を解く手順を決めたものだ。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "アルゴリズムとは、問題[もんだい]を解[と]く手順[てじゅん]を決[き]めたものだ。", "sentence_source": "generated"}, {"text": "授業では、数をならべかえるアルゴリズムを学んだ。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]では、数[かず]をならべかえるアルゴリズムを学[まな]んだ。", "sentence_source": "generated"}, {"text": "このアルゴリズムは単純だが、大きなデータでは遅くなる。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "このアルゴリズムは単純[たんじゅん]だが、大[おお]きなデータでは遅[おそ]くなる。", "sentence_source": "generated"}, {"text": "動画サイトのアルゴリズムが、好みに合う動画を選んで見せてくれる。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "動画[どうが]サイトのアルゴリズムが、好[この]みに合[あ]う動画[どうが]を選[えら]んで見[み]せてくれる。", "sentence_source": "generated"}, {"text": "料理のレシピも、アルゴリズムの一種と考えることができる。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "料理[りょうり]のレシピも、アルゴリズムの一種[いっしゅ]と考[かんが]えることができる。", "sentence_source": "generated"}, {"text": "彼女は、より速いアルゴリズムを見つけて、論文を書いた。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、より速[はや]いアルゴリズムを見[み]つけて、論文[ろんぶん]を書[か]いた。", "sentence_source": "generated"}, {"text": "アルゴリズムを変えたところ、エラーがなくなった。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "アルゴリズムを変[か]えたところ、エラーがなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アルゴリズム", "label": "基本形"}, {"form": "アルゴリズムの", "label": "連体形"}, {"form": "アルゴリズムを", "label": "を格形"}], "register": "neutral", "sense_fingerprint": "問題を解くために決められた計算や処理の手順", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51761, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アルゴリズム", "is_correct": true, "explanation": "手順や仕組みを表し、検索サイトが結果を並べる主体として自然に入る。"}, {"text": "通信速度", "is_correct": false, "explanation": "回線の速さを表す語で、結果を並べる手段としては成り立たない。"}, {"text": "解像度", "is_correct": false, "explanation": "画像の細かさを表す語で、結果を順番に並べる文脈と合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の強さを表す語で、結果を並べる手段にはならない。"}], "explanations": {"アルゴリズム": "手順や仕組みを表し、検索サイトが結果を並べる主体として自然に入る。", "通信速度": "回線の速さを表す語で、結果を並べる手段としては成り立たない。", "解像度": "画像の細かさを表す語で、結果を順番に並べる文脈と合わない。", "電圧": "電気の強さを表す語で、結果を並べる手段にはならない。"}, "sentence_index": 0, "correct_answer": "アルゴリズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私のアルゴリズムは、昨夜ぐっすり眠れなかった。", "explanation": "〈頭脳・考える人〉の意味でアルゴリズムを主語にしているが、手順は眠る主体ではないので合わない。"}, {"text": "彼はアルゴリズムに色を塗って、部屋の壁を明るくした。", "explanation": "〈絵の具〉のように色を塗れる物として使っているが、手順は塗る対象にならないので、この意味では使えない。"}, {"text": "友達とアルゴリズムを約束して、映画館で待ち合わせた。", "explanation": "「予定」の意味でアルゴリズムを使っているが、手順は約束を交わす対象ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51761, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アルゴリズム", "is_correct": true, "explanation": "好みを判断して動画を並べる仕組みを指し、動画サイトの主語として合う。"}, {"text": "字幕", "is_correct": false, "explanation": "映像に表示する文字で、動画を選んで見せる主語にはならない。"}, {"text": "画質", "is_correct": false, "explanation": "映像の鮮明さを表す語で、動画を選ぶ働きとは別。"}, {"text": "再生速度", "is_correct": false, "explanation": "再生の速さを表す語で、動画を選ぶ働きを表さない。"}], "explanations": {"アルゴリズム": "好みを判断して動画を並べる仕組みを指し、動画サイトの主語として合う。", "字幕": "映像に表示する文字で、動画を選んで見せる主語にはならない。", "画質": "映像の鮮明さを表す語で、動画を選ぶ働きとは別。", "再生速度": "再生の速さを表す語で、動画を選ぶ働きを表さない。"}, "sentence_index": 6, "correct_answer": "アルゴリズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このアルゴリズムは、冷たくてのどごしがいい。", "explanation": "〈飲み物〉の意味でアルゴリズムを使っているが、手順には冷たさやのどごしがないので、この文では使えない。"}, {"text": "彼は友人にアルゴリズムを贈って、誕生日を祝った。", "explanation": "〈ソフトウェア〉の意味でアルゴリズムを使っているが、アルゴリズムは問題の解き方そのものを指すので、贈り物にはできない。"}, {"text": "この部屋の天井はアルゴリズムが低い。", "explanation": "〈高さ〉の意味でアルゴリズムを使っているが、アルゴリズムは高さを持つ物ではないので、天井の高さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
