INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51763, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "かわることのできる数。", "primary_collocate": null, "pronunciation": "へんすう", "ipa": "hensɯː", "syllable_count": 4, "sentences": [{"text": "この式では、xが変数で、aは定数です。", "target_word": "変数", "complexity_tier": "T3", "furigana": "この式[しき]では、xが変数[へんすう]で、aは定数[ていすう]です。", "sentence_source": "generated"}, {"text": "プログラムの中で、変数に数字を入れて計算する。", "target_word": "変数", "complexity_tier": "T3", "furigana": "プログラムの中[なか]で、変数[へんすう]に数字[すうじ]を入[い]れて計算[けいさん]する。", "sentence_source": "generated"}, {"text": "変数の値が変わると、答えも変わる。", "target_word": "変数", "complexity_tier": "T3", "furigana": "変数[へんすう]の値[あたい]が変[か]わると、答[こた]えも変[か]わる。", "sentence_source": "generated"}, {"text": "変数の名前は、わかりやすいものにしたほうがいい。", "target_word": "変数", "complexity_tier": "T3", "furigana": "変数[へんすう]の名前[なまえ]は、わかりやすいものにしたほうがいい。", "sentence_source": "generated"}, {"text": "実験では、温度を変数にして結果を比べた。", "target_word": "変数", "complexity_tier": "T4", "furigana": "実験[じっけん]では、温度[おんど]を変数[へんすう]にして結果[けっか]を比[くら]べた。", "sentence_source": "generated"}, {"text": "数学の授業で、変数と定数の違いを習った。", "target_word": "変数", "complexity_tier": "T3", "furigana": "数学[すうがく]の授業[じゅぎょう]で、変数[へんすう]と定数[ていすう]の違[ちが]いを習[なら]った。", "sentence_source": "generated"}, {"text": "変数を使うと、同じ計算を何度も書かなくてすむ。", "target_word": "変数", "complexity_tier": "T3", "furigana": "変数[へんすう]を使[つか]うと、同[おな]じ計算[けいさん]を何度[なんど]も書[か]かなくてすむ。", "sentence_source": "generated"}, {"text": "このゲームでは、変数にスコアを記録している。", "target_word": "変数", "complexity_tier": "T3", "furigana": "このゲームでは、変数[へんすう]にスコアを記録[きろく]している。", "sentence_source": "generated"}, {"text": "x+7の変数xに3を入れると、答えは十になる。", "target_word": "変数", "complexity_tier": "T4", "furigana": "x+7の変数[へんすう]xに3を入[い]れると、答[こた]えは十[じゅう]になる。", "sentence_source": "generated"}, {"text": "変数が多すぎて、プログラムを読むのが大変だった。", "target_word": "変数", "complexity_tier": "T3", "furigana": "変数[へんすう]が多[おお]すぎて、プログラムを読[よ]むのが大変[たいへん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変数", "label": "基本形"}, {"form": "変数の", "label": "連体形"}, {"form": "変数に", "label": "に格"}], "register": "technical", "sense_fingerprint": "数学・プログラムで値が変わる数や文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51763, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変数", "is_correct": true, "explanation": "値が変わる文字を表し、「xが変数で、aは定数」と対比する文に合う。"}, {"text": "方程式", "is_correct": false, "explanation": "xが方程式となると、文字の役割が合わず、定数と対比する文の意味が通らない。"}, {"text": "図形", "is_correct": false, "explanation": "xが図形では、定数と対比される文字の意味にならない。"}, {"text": "単位", "is_correct": false, "explanation": "xが単位では、定数と対比する文の意味が通らない。"}], "explanations": {"変数": "値が変わる文字を表し、「xが変数で、aは定数」と対比する文に合う。", "方程式": "xが方程式となると、文字の役割が合わず、定数と対比する文の意味が通らない。", "図形": "xが図形では、定数と対比される文字の意味にならない。", "単位": "xが単位では、定数と対比する文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "変数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この変数の料金は、毎月少しずつ上がっている。", "explanation": "ここは〈料金〉の意味。変数は数学やプログラムで値を入れる文字で、料金の話には使わない。"}, {"text": "英語の変数を覚えるのに苦労した。", "explanation": "ここは〈単語〉の意味。変数は数学やプログラムで値を入れる文字で、英語の語彙には使わない。"}, {"text": "教室の変数が多すぎて、全員が座れない。", "explanation": "ここは〈人数〉の意味。変数は数学やプログラムの語で、教室の人の数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51763, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変数", "is_correct": true, "explanation": "計算を文字で置き換えて書く手段を表し、「変数を使うと」に合う。"}, {"text": "漢字", "is_correct": false, "explanation": "漢字は計算の道具ではなく、「漢字を使うと計算が減る」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は計算に使う語ではなく、文の意味が成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は計算の道具ではなく、文の意味が成り立たない。"}], "explanations": {"変数": "計算を文字で置き換えて書く手段を表し、「変数を使うと」に合う。", "漢字": "漢字は計算の道具ではなく、「漢字を使うと計算が減る」は意味が通らない。", "天気": "天気は計算に使う語ではなく、文の意味が成り立たない。", "財布": "財布は計算の道具ではなく、文の意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "変数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "漢字の変数が多すぎて、覚えるのが大変だ。", "explanation": "ここは〈文字〉の意味。変数は数学やプログラムで値を入れる文字で、漢字には使わない。"}, {"text": "申請書の変数が多すぎて、書くのが大変だ。", "explanation": "ここは〈項目〉の意味。変数は数学やプログラムの語で、申請書の欄や項目には使わない。"}, {"text": "このバッグは変数が高すぎて、買えなかった。", "explanation": "ここは〈値段〉の意味。変数は数学やプログラムの語で、商品の値段には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51763, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この式では、変数を具体的な数を入れて答えを求める。", "corrected_sentence": "この式では、変数に具体的な数を入れて答えを求める。", "error_description": "助詞の誤り。「変数に数を入れる」の「に」が正しく、「変数を」では目的語が二つになり文が成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51763, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この変数を、初めに値を入れる。", "corrected_sentence": "この変数に、初めに値を入れる。", "error_description": "助詞の誤り。「値を入れる」の先は「この変数に」で、「この変数を」では目的語が二つになり文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
