INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51765, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "町や建物の集まりの、ひとまとまりの区画のことです。", "primary_collocate": null, "pronunciation": "がいく", "ipa": "ɡaiku", "syllable_count": 3, "sentences": [{"text": "大通りと川に囲まれた街区に、古い商店が集まっています。", "target_word": "街区", "complexity_tier": "T3", "furigana": "大通[おおどお]りと川[かわ]に囲[かこ]まれた街区[がいく]に、古[ふる]い商店[しょうてん]が集[あつ]まっています。", "sentence_source": "generated"}, {"text": "この街区は火事が多かったので、道を広げて作り直されました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "この街区[がいく]は火事[かじ]が多[おお]かったので、道[みち]を広[ひろ]げて作[つく]り直[なお]されました。", "sentence_source": "generated"}, {"text": "新しい街区には、同じ形の家が三十軒ほど並んでいます。", "target_word": "街区", "complexity_tier": "T3", "furigana": "新[あたら]しい街区[がいく]には、同[おな]じ形[かたち]の家[いえ]が三十軒[さんじゅっけん]ほど並[なら]んでいます。", "sentence_source": "generated"}, {"text": "私たちの学校は、駅から二つ目の街区にあります。", "target_word": "街区", "complexity_tier": "T3", "furigana": "私[わたし]たちの学校[がっこう]は、駅[えき]から二[ふた]つ目[め]の街区[がいく]にあります。", "sentence_source": "generated"}, {"text": "市役所の人が、街区ごとにごみ置き場の場所を決めました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]の人[ひと]が、街区[がいく]ごとにごみ置[お]き場[ば]の場所[ばしょ]を決[き]めました。", "sentence_source": "generated"}, {"text": "夜になると、この街区だけは明かりが少なくて暗いです。", "target_word": "街区", "complexity_tier": "T3", "furigana": "夜[よる]になると、この街区[がいく]だけは明[あ]かりが少[すく]なくて暗[くら]いです。", "sentence_source": "generated"}, {"text": "歩いてみると、街区によって建物の高さがかなり違います。", "target_word": "街区", "complexity_tier": "T3", "furigana": "歩[ある]いてみると、街区[がいく]によって建物[たてもの]の高[たか]さがかなり違[ちが]います。", "sentence_source": "generated"}, {"text": "港に近い街区は、昔は倉庫ばかりでした。", "target_word": "街区", "complexity_tier": "T3", "furigana": "港[みなと]に近[ちか]い街区[がいく]は、昔[むかし]は倉庫[そうこ]ばかりでした。", "sentence_source": "generated"}, {"text": "一つの街区をぐるっと歩いて回るのに、十分もかかりません。", "target_word": "街区", "complexity_tier": "T3", "furigana": "一[ひと]つの街区[がいく]をぐるっと歩[ある]いて回[まわ]るのに、十分[じゅっぷん]もかかりません。", "sentence_source": "generated"}, {"text": "地震のあと、被害の大きかった街区から工事が始まりました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、被害[ひがい]の大[おお]きかった街区[がいく]から工事[こうじ]が始[はじ]まりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "街区", "label": "基本形"}], "register": "やや硬い・中立", "sense_fingerprint": "町や建物が集まったひとまとまりの区画（ブロック）を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 作り直さ (Zipf 2.36)']::text[], 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51765, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街区", "is_correct": true, "explanation": "大通りと川に囲まれた区画を指すので、街区が入る。"}, {"text": "倉庫", "is_correct": false, "explanation": "倉庫に商店が集まるという文は不自然で、区画を表す語ではない。"}, {"text": "駐車場", "is_correct": false, "explanation": "駐車場は車を止める場所で、商店が集まる区域には当てはまらない。"}, {"text": "橋", "is_correct": false, "explanation": "橋は川を渡る構造物で、川と大通りに囲まれた区域とは合わない。"}], "explanations": {"街区": "大通りと川に囲まれた区画を指すので、街区が入る。", "倉庫": "倉庫に商店が集まるという文は不自然で、区画を表す語ではない。", "駐車場": "駐車場は車を止める場所で、商店が集まる区域には当てはまらない。", "橋": "橋は川を渡る構造物で、川と大通りに囲まれた区域とは合わない。"}, "sentence_index": 0, "correct_answer": "街区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私たちは、二つ目の街区で電車を降りて、学校まで歩いた。", "explanation": "ここは〈駅〉の意味。電車を降りる場所は駅で、街区は区画を表すので合わない。"}, {"text": "私たちの学校は、駅から二つ目の街区で電車を待つ場所の近くにある。", "explanation": "ここは〈ホーム〉の意味。電車を待つ場所を指す語で、区画の街区とは合わない。"}, {"text": "私たちは、駅から二つ目の街区を線路として使い、電車で学校へ向かった。", "explanation": "ここは〈線路〉の意味。電車が走る道筋を指すのは線路で、街区は区画なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51765, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街区", "is_correct": true, "explanation": "地域によって建物の高さが違うという文脈で、区画を表す街区が入る。"}, {"text": "言語", "is_correct": false, "explanation": "言語によって建物の高さが違うという関係は成り立たない。"}, {"text": "天候", "is_correct": false, "explanation": "天候によって建物の高さが変わるという言い方は不自然。"}, {"text": "楽器", "is_correct": false, "explanation": "楽器の種類では建物の高さは決まらず、文脈に合わない。"}], "explanations": {"街区": "地域によって建物の高さが違うという文脈で、区画を表す街区が入る。", "言語": "言語によって建物の高さが違うという関係は成り立たない。", "天候": "天候によって建物の高さが変わるという言い方は不自然。", "楽器": "楽器の種類では建物の高さは決まらず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "街区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震のあと、被害の大きかった街区が、一人ずつ転入届を出し直した。", "explanation": "ここは〈住民〉の意味。転入届を出すのは住民で、区画の街区を主語にすると合わない。"}, {"text": "地震のあと、被害の大きかった街区が、一斉に卒業式を行った。", "explanation": "ここは〈学校〉の意味。卒業式を行うのは学校で、区画の街区が行うのは合わない。"}, {"text": "地震のあと、被害の大きかった街区が震度の大きさを記録した。", "explanation": "ここは〈観測所〉の意味。震度を記録するのは観測所で、区画の街区が記録するのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51765, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川沿いの街区を、倉庫が並んでいました。", "corrected_sentence": "川沿いの街区に、倉庫が並んでいました。", "error_description": "並んでいる場所は「に」で示す。「を」は他動詞の目的語を示す助詞で、自動詞の「並ぶ」には使わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51765, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨年、その街区を大きな公園が作られた。", "corrected_sentence": "昨年、その街区に大きな公園が作られた。", "error_description": "作られる場所は「に」で示す。「を」を付けると街区が目的語になり、受身の文と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
