INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51766, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市などで、道路に区切られた建物や土地の一区画。", "primary_collocate": null, "pronunciation": "がいく", "ipa": "ɡaiku", "syllable_count": 3, "sentences": [{"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "街区", "complexity_tier": "T3", "furigana": "これは、日照[にっしょう]や風通[かぜとお]しなどの環境[かんきょう]データを変数[へんすう]としてアルゴリズムに入力[にゅうりょく]し、最適[さいてき]な街区[がいく]配置[はいち]を自動的[じどうてき]に生成[せいせい]する手法[しゅほう]です。", "sentence_source": "mined"}, {"text": "この街区は道が碁盤の目のように並んでいて、初めての人でも歩きやすいです。", "target_word": "街区", "complexity_tier": "T3", "furigana": "この街区[がいく]は道[みち]が碁盤[ごばん]の目[め]のように並[なら]んでいて、初[はじ]めての人[ひと]でも歩[ある]きやすいです。", "sentence_source": "generated"}, {"text": "市は古い街区を取り壊して、新しい公園を作る計画を発表しました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "市[し]は古[ふる]い街区[がいく]を取[と]り壊[こわ]して、新[あたら]しい公園[こうえん]を作[つく]る計画[けいかく]を発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "一つの街区には、住宅のほかに小さな店や学校も入っています。", "target_word": "街区", "complexity_tier": "T3", "furigana": "一[ひと]つの街区[がいく]には、住宅[じゅうたく]のほかに小[ちい]さな店[みせ]や学校[がっこう]も入[はい]っています。", "sentence_source": "generated"}, {"text": "地図を見ると、駅の北側は四角い街区が整然と並んでいます。", "target_word": "街区", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、駅[えき]の北側[きたがわ]は四角[しかく]い街区[がいく]が整然[せいぜん]と並[なら]んでいます。", "sentence_source": "generated"}, {"text": "道路が広がったため、この街区は二つに分けられました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "道路[どうろ]が広[ひろ]がったため、この街区[がいく]は二[ふた]つに分[わ]けられました。", "sentence_source": "generated"}, {"text": "彼は街区ごとに家を訪ねて、アンケートを集めました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "彼[かれ]は街区[がいく]ごとに家[いえ]を訪[たず]ねて、アンケートを集[あつ]めました。", "sentence_source": "generated"}, {"text": "川沿いの街区は洪水の危険があるので、高い堤防が築かれました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "川沿[かわぞ]いの街区[がいく]は洪水[こうずい]の危険[きけん]があるので、高[たか]い堤防[ていぼう]が築[きず]かれました。", "sentence_source": "generated"}, {"text": "古い街区には細い路地が多く、車が入れません。", "target_word": "街区", "complexity_tier": "T3", "furigana": "古[ふる]い街区[がいく]には細[ほそ]い路地[ろじ]が多[おお]く、車[くるま]が入[はい]れません。", "sentence_source": "generated"}, {"text": "都市計画の授業で、学生は一つの街区の大きさを測りました。", "target_word": "街区", "complexity_tier": "T3", "furigana": "都市[とし]計画[けいかく]の授業[じゅぎょう]で、学生[がくせい]は一[ひと]つの街区[がいく]の大[おお]きさを測[はか]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "街区", "label": "基本形"}], "register": "やや硬い・書き言葉（都市計画）", "sense_fingerprint": "都市で道路に囲まれ区切られた建物・土地の一区画（ブロック）を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 碁盤 (Zipf 2.41)']::text[], 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51766, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街区", "is_correct": true, "explanation": "道路に囲まれた都市の区画を配置する対象として、街区が入る。"}, {"text": "語彙", "is_correct": false, "explanation": "語彙は言葉の集まりを指し、都市の区画配置の対象にはならない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は天候の数値で、区画を配置する対象ではない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は人の心の動きで、都市の区画配置には当てはまらない。"}], "explanations": {"街区": "道路に囲まれた都市の区画を配置する対象として、街区が入る。", "語彙": "語彙は言葉の集まりを指し、都市の区画配置の対象にはならない。", "気温": "気温は天候の数値で、区画を配置する対象ではない。", "感情": "感情は人の心の動きで、都市の区画配置には当てはまらない。"}, "sentence_index": 0, "correct_answer": "街区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この街区は車がたくさん行き交う一本の長い道で、両側に街路樹が並んでいる。", "explanation": "ここは〈街路〉の意味。街区は道路に囲まれた区画を指し、道そのものを表さないので合わない。"}, {"text": "この街区は、駅から次の停留所までバスがそのまま走る部分だ。", "explanation": "ここは〈区間〉の意味。路線上の一定の範囲を指す語で、区画の街区とは合わない。"}, {"text": "この街区は地震で傾いた柱を一本ずつ組み直した。", "explanation": "ここは〈建物〉の意味。柱を組み直すのは建物の工事で、道路に囲まれた区画の街区を主語にすると合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51766, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街区", "is_correct": true, "explanation": "ごとに家を訪ねるまとまりとして、区画を表す街区が入る。"}, {"text": "教科", "is_correct": false, "explanation": "教科は学校の科目で、家を訪ねる単位としては成り立たない。"}, {"text": "自動車", "is_correct": false, "explanation": "自動車ごとに家を訪ねるという言い方は不自然で、単位にならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気ごとに家を訪ねるという単位は成り立たず、文脈に合わない。"}], "explanations": {"街区": "ごとに家を訪ねるまとまりとして、区画を表す街区が入る。", "教科": "教科は学校の科目で、家を訪ねる単位としては成り立たない。", "自動車": "自動車ごとに家を訪ねるという言い方は不自然で、単位にならない。", "天気": "天気ごとに家を訪ねるという単位は成り立たず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "街区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生は、一つの街区を一時間で読み終えた。", "explanation": "ここは〈章〉の意味。読み終えるのは文章の区切りである章で、区画の街区は文章の区切りにはならないので合わない。"}, {"text": "学生は、一つの街区の試験で満点を取った。", "explanation": "ここは〈科目〉の意味。試験で評価される単位は科目で、区画の街区は試験の対象にならないので合わない。"}, {"text": "学生は、一つの街区を毎週放送して、視聴者の投票で勝敗を決めた。", "explanation": "ここは〈番組〉の意味。放送されるのは番組で、区画の街区は放送の対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51766, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の街区を、大きな図書館が建てられました。", "corrected_sentence": "駅前の街区に、大きな図書館が建てられました。", "error_description": "建物が建てられる場所は「に」で示す。「を」は目的語の位置に街区を置いてしまう誤りで、建てられる場所としては成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51766, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前の街区を工事が始まった。", "corrected_sentence": "駅前の街区で工事が始まった。", "error_description": "工事が始まる場所は「で」で示す。「を」を付けると街区が目的語になり、自動詞の「始まる」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「手法が結果に影響する」で、影響する主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「影響する」は目的語を取らず、「手法を影響する」は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「手法に結果に」と格が重なり、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「手法へ影響する」では影響の向きが合わない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「手法が結果に影響する」で、影響する主体を表す。", "を": "目的語を示す。「影響する」は目的語を取らず、「手法を影響する」は成立しない。", "に": "「手法に結果に」と格が重なり、文が成立しない。", "へ": "方向の「へ」。「手法へ影響する」では影響の向きが合わない。"}, "error_tags": {"を": "目的語", "に": "対象・方向", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「手法を変えた」で、変える対象を表す。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「手法より変えたら」では文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「手法と変えたら」では対象が合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「手法の変えたら」では文が続かない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「手法を変えた」で、変える対象を表す。", "より": "比較の「より」。「手法より変えたら」では文が成立しない。", "と": "並列の「と」。「手法と変えたら」では対象が合わない。", "の": "連体の「の」。「手法の変えたら」では文が続かない。"}, "error_tags": {"より": "比較", "と": "並列・共同", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、決まったやり方や方法のことです。", "primary_collocate": null, "pronunciation": "しゅほう", "ipa": "ɕɯhoː", "syllable_count": 3, "sentences": [{"text": "この会社は、新しい手法で商品を宣伝している。", "target_word": "手法", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、新[あたら]しい手法[しゅほう]で商品[しょうひん]を宣伝[せんでん]している。", "sentence_source": "generated"}, {"text": "研究では、調査の手法が結果に大きく影響する。", "target_word": "手法", "complexity_tier": "T4", "furigana": "研究[けんきゅう]では、調査[ちょうさ]の手法[しゅほう]が結果[けっか]に大[おお]きく影響[えいきょう]する。", "sentence_source": "generated"}, {"text": "昔ながらの手法を守って、職人はしょうゆを作っている。", "target_word": "手法", "complexity_tier": "T4", "furigana": "昔[むかし]ながらの手法[しゅほう]を守[まも]って、職人[しょくにん]はしょうゆを作[つく]っている。", "sentence_source": "generated"}, {"text": "彼の絵は、光を強く見せる独特の手法で知られている。", "target_word": "手法", "complexity_tier": "T4", "furigana": "彼[かれ]の絵[え]は、光[ひかり]を強[つよ]く見[み]せる独特[どくとく]の手法[しゅほう]で知[し]られている。", "sentence_source": "generated"}, {"text": "問題を解く手法はいくつもあるが、これが一番速い。", "target_word": "手法", "complexity_tier": "T3", "furigana": "問題[もんだい]を解[と]く手法[しゅほう]はいくつもあるが、これが一番[いちばん]速[はや]い。", "sentence_source": "generated"}, {"text": "医者は、体に負担の少ない手法で手術をした。", "target_word": "手法", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、体[からだ]に負担[ふたん]の少[すく]ない手法[しゅほう]で手術[しゅじゅつ]をした。", "sentence_source": "generated"}, {"text": "強引な手法に、周りの人たちは反発した。", "target_word": "手法", "complexity_tier": "T3", "furigana": "強引[ごういん]な手法[しゅほう]に、周[まわ]りの人[ひと]たちは反発[はんぱつ]した。", "sentence_source": "generated"}, {"text": "教え方の手法を変えたら、生徒の成績が上がった。", "target_word": "手法", "complexity_tier": "T3", "furigana": "教[おし]え方[かた]の手法[しゅほう]を変[か]えたら、生徒[せいと]の成績[せいせき]が上[あ]がった。", "sentence_source": "generated"}, {"text": "同じ手法ばかり使っていると、新しい考えが生まれない。", "target_word": "手法", "complexity_tier": "T3", "furigana": "同[おな]じ手法[しゅほう]ばかり使[つか]っていると、新[あたら]しい考[かんが]えが生[う]まれない。", "sentence_source": "generated"}, {"text": "先生は、作文の書き方について、三つの手法を紹介した。", "target_word": "手法", "complexity_tier": "T3", "furigana": "先生[せんせい]は、作文[さくぶん]の書[か]き方[かた]について、三[みっ]つの手法[しゅほう]を紹介[しょうかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手法", "label": "基本形"}, {"form": "手法の", "label": "連体形"}, {"form": "手法で", "label": "で格"}], "register": "formal", "sense_fingerprint": "仕事・研究・表現で用いる決まったやり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手法", "is_correct": true, "explanation": "決まったやり方を表し、「新しい手法で商品を宣伝している」に合う。"}, {"text": "参加者", "is_correct": false, "explanation": "参加者は宣伝の手段にならず、文の意味が成り立たない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は宣伝の仕方を表せず、文の意味が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は宣伝の仕方として意味が通らない。"}], "explanations": {"手法": "決まったやり方を表し、「新しい手法で商品を宣伝している」に合う。", "参加者": "参加者は宣伝の手段にならず、文の意味が成り立たない。", "年齢": "年齢は宣伝の仕方を表せず、文の意味が成り立たない。", "天気": "天気は宣伝の仕方として意味が通らない。"}, "sentence_index": 0, "correct_answer": "手法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その職人は手法が高く、どんな仕事も丁寧だ。", "explanation": "ここは〈技術〉の意味。手法は決まったやり方を指し、腕前の高さは〈技術〉で表すので、「手法が高い」とは言わない。"}, {"text": "この料理は手法がかかって、時間が足りない。", "explanation": "ここは〈手間〉の意味。手法は決まったやり方で、かかる労力には使わない。"}, {"text": "寒さで手法が冷たくなった。", "explanation": "ここは〈手足〉の意味。手法は体の部位ではなく、やり方を表す語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手法", "is_correct": true, "explanation": "決まったやり方を表し、「強引な手法に反発した」の反発の対象として合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は強引な様子を表せず、文が成立しない。"}, {"text": "地域", "is_correct": false, "explanation": "地域は「強引な」とは続かず、反発の対象にならない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は強引さを表す語ではなく、意味が通らない。"}], "explanations": {"手法": "決まったやり方を表し、「強引な手法に反発した」の反発の対象として合う。", "季節": "季節は強引な様子を表せず、文が成立しない。", "地域": "地域は「強引な」とは続かず、反発の対象にならない。", "年齢": "年齢は強引さを表す語ではなく、意味が通らない。"}, "sentence_index": 6, "correct_answer": "手法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は手法を立てて、試合に勝った。", "explanation": "ここは〈作戦〉の意味。手法はやり方の一般的な言い方で、「立てる」対象には使わない。"}, {"text": "引っ越しの届けを出すため、役所で手法をした。", "explanation": "ここは〈手続き〉の意味。手法は決まったやり方で、役所の届けの場面では使わない。"}, {"text": "スーパーで、手法を買ってきた。", "explanation": "ここは〈食材〉の意味。手法はやり方を表す語で、買うものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい手法に取り入れて、仕事の効率を上げた。", "corrected_sentence": "新しい手法を取り入れて、仕事の効率を上げた。", "error_description": "助詞の誤り。「取り入れる」の対象は「を」で、「手法に」では取り入れる対象にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51767, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい手法が試したが、結果は変わらなかった。", "corrected_sentence": "新しい手法を試したが、結果は変わらなかった。", "error_description": "助詞の誤り。「試す」の対象は「を」で、「手法が」では主語になり、試す対象にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「独創を生む」の「を」。生み出す対象を示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「独創が生む」は主語と動詞が合わず、生み出す対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「独創に生む」は生み出す対象の示し方として誤りになる。"}, {"text": "で", "is_correct": false, "explanation": "「独創で生む」は手段の表現になり、生み出す対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「独創を生む」の「を」。生み出す対象を示すので正しい。", "が": "「独創が生む」は主語と動詞が合わず、生み出す対象を示せない。", "に": "「独創に生む」は生み出す対象の示し方として誤りになる。", "で": "「独創で生む」は手段の表現になり、生み出す対象を示せない。"}, "error_tags": {"が": "subject", "に": "goal", "で": "means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模倣", "is_correct": true, "explanation": "独創の対義語。自分だけの発想とは反対に、他人のまねをする意味。"}, {"text": "技術", "is_correct": false, "explanation": "技術は物事を行う腕前や方法で、独創と対になる語ではない。"}, {"text": "教育", "is_correct": false, "explanation": "教育は人を育てることで、独創の反対語にはならない。"}, {"text": "研修", "is_correct": false, "explanation": "研修は訓練や学習の意味で、独創の対義語にはならない。"}], "correct_answer": "模倣", "explanations": {"模倣": "独創の対義語。自分だけの発想とは反対に、他人のまねをする意味。", "技術": "技術は物事を行う腕前や方法で、独創と対になる語ではない。", "教育": "教育は人を育てることで、独創の反対語にはならない。", "研修": "研修は訓練や学習の意味で、独創の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「独創に満ちた」の「に」。満ちる内容を示す形で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「独創を満ちた」は満ちるの対象にならず、成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「独創で満ちた」は手段の意味になり、満ちる内容とは合わない。"}, {"text": "の", "is_correct": false, "explanation": "「独創の満ちた」は満ちる主体として不自然で、文の構造が崩れる。"}], "correct_answer": "に", "explanations": {"に": "「独創に満ちた」の「に」。満ちる内容を示す形で正しい。", "を": "「独創を満ちた」は満ちるの対象にならず、成り立たない。", "で": "「独創で満ちた」は手段の意味になり、満ちる内容とは合わない。", "の": "「独創の満ちた」は満ちる主体として不自然で、文の構造が崩れる。"}, "error_tags": {"を": "object", "で": "means", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模倣", "is_correct": true, "explanation": "独創の対義語。独自の発想とは反対に、他人のまねをする意味。"}, {"text": "手本", "is_correct": false, "explanation": "手本は見習うべき例で、独創と対になる語ではない。"}, {"text": "技能", "is_correct": false, "explanation": "技能は身につけた技量のことで、独創の反対語ではない。"}, {"text": "指導", "is_correct": false, "explanation": "指導は教え導くことで、独創の反対語にはならない。"}], "correct_answer": "模倣", "explanations": {"模倣": "独創の対義語。独自の発想とは反対に、他人のまねをする意味。", "手本": "手本は見習うべき例で、独創と対になる語ではない。", "技能": "技能は身につけた技量のことで、独創の反対語ではない。", "指導": "指導は教え導くことで、独創の反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分だけの新しい考えや作り方を思いつくこと。", "primary_collocate": null, "pronunciation": "どくそう", "ipa": "dokɯsoː", "syllable_count": 4, "sentences": [{"text": "子どもの自由な絵には、大人にはない独創がある。", "target_word": "独創", "complexity_tier": "T2", "furigana": "子[こ]どもの自由[じゆう]な絵[え]には、大人[おとな]にはない独創[どくそう]がある。", "sentence_source": "generated"}, {"text": "独創を生むには、まず常識を疑うことから始めるとよい。", "target_word": "独創", "complexity_tier": "T3", "furigana": "独創[どくそう]を生[う]むには、まず常識[じょうしき]を疑[うたが]うことから始[はじ]めるとよい。", "sentence_source": "generated"}, {"text": "彼の独創のおかげで、この機械は従来の半分の部品で動く。", "target_word": "独創", "complexity_tier": "T3", "furigana": "彼[かれ]の独創[どくそう]のおかげで、この機械[きかい]は従来[じゅうらい]の半分[はんぶん]の部品[ぶひん]で動[うご]く。", "sentence_source": "generated"}, {"text": "発明の世界では、先行例を調べたうえで独創を加える必要がある。", "target_word": "独創", "complexity_tier": "T4", "furigana": "発明[はつめい]の世界[せかい]では、先行例[せんこうれい]を調[しら]べたうえで独創[どくそう]を加[くわ]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "独創にこだわるあまり、使う人のことを考えない製品になってしまった。", "target_word": "独創", "complexity_tier": "T3", "furigana": "独創[どくそう]にこだわるあまり、使[つか]う人[ひと]のことを考[かんが]えない製品[せいひん]になってしまった。", "sentence_source": "generated"}, {"text": "今回の審査では、完成度よりも独創が重視されるそうだ。", "target_word": "独創", "complexity_tier": "T3", "furigana": "今回[こんかい]の審査[しんさ]では、完成度[かんせいど]よりも独創[どくそう]が重視[じゅうし]されるそうだ。", "sentence_source": "generated"}, {"text": "彼女の独創に、先輩たちも「その手があったか」と感心した。", "target_word": "独創", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の独創[どくそう]に、先輩[せんぱい]たちも「その手[て]があったか」と感心[かんしん]した。", "sentence_source": "generated"}, {"text": "独創に満ちた設計で、その建築家は一躍有名になった。", "target_word": "独創", "complexity_tier": "T3", "furigana": "独創[どくそう]に満[み]ちた設計[せっけい]で、その建築家[けんちくか]は一躍[いちやく]有名[ゆうめい]になった。", "sentence_source": "generated"}, {"text": "模倣ばかりの業界で、彼の独創は異彩を放っていた。", "target_word": "独創", "complexity_tier": "T3", "furigana": "模倣[もほう]ばかりの業界[ぎょうかい]で、彼[かれ]の独創[どくそう]は異彩[いさい]を放[はな]っていた。", "sentence_source": "generated"}, {"text": "独創とは、ゼロから作ることだけでなく、既存の方法を新しく組み合わせることでもある。", "target_word": "独創", "complexity_tier": "T4", "furigana": "独創[どくそう]とは、ゼロから作[つく]ることだけでなく、既存[きそん]の方法[ほうほう]を新[あたら]しく組[く]み合[あ]わせることでもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独創", "label": "基本形"}, {"form": "独創的", "label": "派生形(形状詞)"}, {"form": "独創性", "label": "派生形(名詞)"}], "register": "標準", "sense_fingerprint": "独創:自分だけの新しい考えや作り方を思いつくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独創", "is_correct": true, "explanation": "「大人にはない独創がある」の形で、子どもの絵の特徴を表す語として入る。"}, {"text": "食卓", "is_correct": false, "explanation": "「大人にはない食卓がある」は文として成り立たず、絵の特徴を表さない。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は乗り物の料金で、絵の特徴を表す語ではない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさで、絵の特徴には当てはまらない。"}], "explanations": {"独創": "「大人にはない独創がある」の形で、子どもの絵の特徴を表す語として入る。", "食卓": "「大人にはない食卓がある」は文として成り立たず、絵の特徴を表さない。", "運賃": "運賃は乗り物の料金で、絵の特徴を表す語ではない。", "音量": "音量は音の大きさで、絵の特徴には当てはまらない。"}, "sentence_index": 0, "correct_answer": "独創"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "発明の世界では、先行例を調べたうえで、独創をつぶやく必要がある。", "explanation": "ここは〈独り言〉の意味。ひとりで言う言葉を指すので、新しい考えを思いつく独創とは合わない。"}, {"text": "発明の世界では、先行例を調べたうえで、独創のまま先行例を追い越す必要がある。", "explanation": "ここは〈独走〉の意味。他を引き離して一人で先を行くことを指すので、新しい考えを思いつく独創とは合わない。"}, {"text": "発明の世界では、先行例を調べたうえで、独創で学ぶ必要がある。", "explanation": "ここは〈独学〉の意味。一人で学ぶことを指す語で、新しい考えを思いつく独創とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独創", "is_correct": true, "explanation": "「彼女の独創に、先輩たちも感心した」の形で、感心の対象として入る。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗うための品で、感心の対象としては不自然。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙を届ける仕組みで、感心の対象として成り立たない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は寝るための道具で、感心の対象としては文脈に合わない。"}], "explanations": {"独創": "「彼女の独創に、先輩たちも感心した」の形で、感心の対象として入る。", "石鹸": "石鹸は洗うための品で、感心の対象としては不自然。", "郵便": "郵便は手紙を届ける仕組みで、感心の対象として成り立たない。", "寝具": "寝具は寝るための道具で、感心の対象としては文脈に合わない。"}, "sentence_index": 6, "correct_answer": "独創"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は独創と結婚し、家庭を持たないまま三十歳を迎えた。", "explanation": "ここは〈独身〉の意味。結婚の相手は人で、新しい考えを表す独創とは合わないので誤り。"}, {"text": "彼は罰として独創の房に入れられ、三日間出てこなかった。", "explanation": "ここは〈独房〉の意味。一人だけで閉じ込める部屋を指すので、新しい考えを思いつく独創とは合わない。"}, {"text": "彼は、会議で独創を振りかざして皆の意見を退けた。", "explanation": "ここは〈独断〉の意味。自分だけで決めて押し通す態度を指すので、新しい考えを思いつく独創とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの独創を、大人は驚いた。", "corrected_sentence": "子どもの独創に、大人は驚いた。", "error_description": "驚く対象は「に」で示す。「を」を付けると驚く対象が目的語になり、「驚く」の用法と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51769, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は独創に重んじて、社員の提案を採用した。", "corrected_sentence": "その会社は独創を重んじて、社員の提案を採用した。", "error_description": "重んじる対象は「を」で示す。「に」を付けると重んじる対象が成り立たず、誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「独創によって」の「に」。独創を手段として示す形で、ここでは正しい。"}, {"text": "が", "is_correct": false, "explanation": "「独創が」では「によって」と続かず、文の構造が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「独創を」では「によって」と続かず、手段を示す形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「独創で」は「によって」と重なり、不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「独創によって」の「に」。独創を手段として示す形で、ここでは正しい。", "が": "「独創が」では「によって」と続かず、文の構造が崩れる。", "を": "「独創を」では「によって」と続かず、手段を示す形にならない。", "で": "「独創で」は「によって」と重なり、不自然になる。"}, "error_tags": {"が": "subject", "を": "object", "で": "means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模倣", "is_correct": true, "explanation": "独創の対義語。独自の発想とは反対に、他人のまねをする意味。"}, {"text": "研究", "is_correct": false, "explanation": "研究は物事を調べて明らかにすることで、独創の反対語ではない。"}, {"text": "技術", "is_correct": false, "explanation": "技術は物事を行う腕前や方法で、独創と対になる語ではない。"}, {"text": "教育", "is_correct": false, "explanation": "教育は人を育てることで、独創の反対語にはならない。"}], "correct_answer": "模倣", "explanations": {"模倣": "独創の対義語。独自の発想とは反対に、他人のまねをする意味。", "研究": "研究は物事を調べて明らかにすることで、独創の反対語ではない。", "技術": "技術は物事を行う腕前や方法で、独創と対になる語ではない。", "教育": "教育は人を育てることで、独創の反対語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模倣", "is_correct": true, "explanation": "独創の対義語。独自の発想とは反対に、他人のまねをする意味。"}, {"text": "手本", "is_correct": false, "explanation": "手本は見習うべき例で、独創と対になる語ではない。"}, {"text": "技能", "is_correct": false, "explanation": "技能は身につけた技量のことで、独創の反対語ではない。"}, {"text": "研修", "is_correct": false, "explanation": "研修は訓練や学習の意味で、独創の対義語にはならない。"}], "correct_answer": "模倣", "explanations": {"模倣": "独創の対義語。独自の発想とは反対に、他人のまねをする意味。", "手本": "手本は見習うべき例で、独創と対になる語ではない。", "技能": "技能は身につけた技量のことで、独創の反対語ではない。", "研修": "研修は訓練や学習の意味で、独創の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他の人とは違う、自分だけの新しい考えや方法を生み出すこと。", "primary_collocate": null, "pronunciation": "どくそう", "ipa": "dokɯsoː", "syllable_count": 4, "sentences": [{"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "独創", "complexity_tier": "T4", "furigana": "デザイナーの直感[ちょっかん]に頼[たよ]るのではなく、計算[けいさん]された論理[ろんり]によって、機能的[きのうてき]かつ独創的[どくそうてき]な都市空間[としくうかん]を創出[そうしゅつ]することが目指[めざ]されています。", "sentence_source": "mined"}, {"text": "彼女の作品は、模倣ではなく独創によって高く評価された。", "target_word": "独創", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の作品[さくひん]は、模倣[もほう]ではなく独創[どくそう]によって高[たか]く評価[ひょうか]された。", "sentence_source": "generated"}, {"text": "この会社は社員の独創を大切にし、新しい企画を歓迎している。", "target_word": "独創", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は社員[しゃいん]の独創[どくそう]を大切[たいせつ]にし、新[あたら]しい企画[きかく]を歓迎[かんげい]している。", "sentence_source": "generated"}, {"text": "独創に富んだ発想で、その発明家は新しい道具を作り上げた。", "target_word": "独創", "complexity_tier": "T3", "furigana": "独創[どくそう]に富[と]んだ発想[はっそう]で、その発明家[はつめいか]は新[あたら]しい道具[どうぐ]を作[つく]り上[あ]げた。", "sentence_source": "generated"}, {"text": "先生は「他人の真似をせず、独創を目指しなさい」と生徒に言った。", "target_word": "独創", "complexity_tier": "T3", "furigana": "先生[せんせい]は「他人[たにん]の真似[まね]をせず、独創[どくそう]を目指[めざ]しなさい」と生徒[せいと]に言[い]った。", "sentence_source": "generated"}, {"text": "独創がなければ、ほかの店と同じ商品しか作れない。", "target_word": "独創", "complexity_tier": "T2", "furigana": "独創[どくそう]がなければ、ほかの店[みせ]と同[おな]じ商品[しょうひん]しか作[つく]れない。", "sentence_source": "generated"}, {"text": "彼の絵は技術よりも独創が光っていて、審査員の目を引いた。", "target_word": "独創", "complexity_tier": "T3", "furigana": "彼[かれ]の絵[え]は技術[ぎじゅつ]よりも独創[どくそう]が光[ひか]っていて、審査員[しんさいん]の目[め]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "研究では、先人の成果を学ぶことと独創を発揮することの両方が大切だ。", "target_word": "独創", "complexity_tier": "T4", "furigana": "研究[けんきゅう]では、先人[せんじん]の成果[せいか]を学[まな]ぶことと独創[どくそう]を発揮[はっき]することの両方[りょうほう]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "独創を重んじる校風のおかげで、生徒たちは自由に作品を作っている。", "target_word": "独創", "complexity_tier": "T3", "furigana": "独創[どくそう]を重[おも]んじる校風[こうふう]のおかげで、生徒[せいと]たちは自由[じゆう]に作品[さくひん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "その料理人は、伝統の味に自分の独創を加えて新しい一皿を完成させた。", "target_word": "独創", "complexity_tier": "T4", "furigana": "その料理人[りょうりにん]は、伝統[でんとう]の味[あじ]に自分[じぶん]の独創[どくそう]を加[くわ]えて新[あたら]しい一皿[ひとさら]を完成[かんせい]させた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独創", "label": "基本形"}, {"form": "独創的", "label": "派生形(形状詞)"}, {"form": "独創性", "label": "派生形(名詞)"}], "register": "標準", "sense_fingerprint": "独創:他人にない自分だけの新しい考えや方法を生み出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独創的", "is_correct": true, "explanation": "「機能的かつ独創的な」の形で、独創の形容動詞として文に入る。"}, {"text": "写実的", "is_correct": false, "explanation": "写実的は実物をありのまま描く意味で、都市空間の説明には合わない。"}, {"text": "抒情的", "is_correct": false, "explanation": "抒情的は感情を歌うような性質で、機能的な都市空間とは結びつかない。"}, {"text": "音楽的", "is_correct": false, "explanation": "音楽的は音楽に関する性質で、機能的な都市空間の説明としては不自然。"}], "explanations": {"独創的": "「機能的かつ独創的な」の形で、独創の形容動詞として文に入る。", "写実的": "写実的は実物をありのまま描く意味で、都市空間の説明には合わない。", "抒情的": "抒情的は感情を歌うような性質で、機能的な都市空間とは結びつかない。", "音楽的": "音楽的は音楽に関する性質で、機能的な都市空間の説明としては不自然。"}, "sentence_index": 0, "correct_answer": "独創的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その発明家は、他社の製品を独創で真似て、同じ道具を作り上げた。", "explanation": "ここは〈模倣〉の意味。真似る方法を独創と言うのは矛盾し、独創は自分だけの新しい考えを生むことなので合わない。"}, {"text": "その会社は市場の独創を進めて、ほかの店を寄せつけなかった。", "explanation": "ここは〈独占〉の意味。市場を一社で握る話なので、新しい考えを生む独創とは意味が合わない。"}, {"text": "その発明家は独創を売り払って、新しい道具を作り上げた。", "explanation": "ここは〈特許〉の意味。売り払えるのは特許などの権利で、考えそのものを表す独創とは合わないので、混同した誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独創", "is_correct": true, "explanation": "「彼の絵は技術よりも独創が光っていて」の形で、作品の特徴として入る。"}, {"text": "食卓", "is_correct": false, "explanation": "食卓が光るという表現は成り立たず、絵の特徴を表さない。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は乗り物の料金で、絵が光るという文脈には合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさで、絵の光る特徴には当てはまらない。"}], "explanations": {"独創": "「彼の絵は技術よりも独創が光っていて」の形で、作品の特徴として入る。", "食卓": "食卓が光るという表現は成り立たず、絵の特徴を表さない。", "運賃": "運賃は乗り物の料金で、絵が光るという文脈には合わない。", "音量": "音量は音の大きさで、絵の光る特徴には当てはまらない。"}, "sentence_index": 6, "correct_answer": "独創"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その料理人は、伝統の味を守るため、先代の味の独創を一つずつ数えて、帳簿に記した。", "explanation": "ここは〈項目〉の意味。帳簿に一つずつ記すのは項目で、考えそのものを指す独創は数えたり記録したりする対象にならないので合わない。"}, {"text": "その料理人は、伝統の味を守るため、独創のまま三品目に入った。", "explanation": "ここは〈独走〉の意味。他を引き離して一人で先を行くことを指すので、新しい考えを生む独創とは合わない。"}, {"text": "その料理人は、客の前で独創をつぶやき、伝統の味を語った。", "explanation": "ここは〈独り言〉の意味。ひとりで言う言葉を指すので、新しい考えを思いつく独創とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の研究は独創を高く評価された。", "corrected_sentence": "彼の研究は独創が高く評価された。", "error_description": "評価された主語は「が」で示す。「を」を付けると受身の主語が立たず、誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51770, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は、新しい製品で独創に発揮して評判を得た。", "corrected_sentence": "その会社は、新しい製品で独創を発揮して評判を得た。", "error_description": "発揮する対象は「を」で示す。「に」を付けると発揮の目的語が成り立たず、誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出力", "is_correct": true, "explanation": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。"}, {"text": "検索", "is_correct": false, "explanation": "情報を探し出す意味で、入力の反対語ではない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を置き換える意味で、入力とは対にならない。"}, {"text": "送信", "is_correct": false, "explanation": "データを相手に送る意味で、入力の対義語ではない。"}], "correct_answer": "出力", "explanations": {"出力": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。", "検索": "情報を探し出す意味で、入力の反対語ではない。", "翻訳": "言語を置き換える意味で、入力とは対にならない。", "送信": "データを相手に送る意味で、入力の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出力", "is_correct": true, "explanation": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。"}, {"text": "録音", "is_correct": false, "explanation": "音声を記録する意味で、入力の反対語ではない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る意味で、入力とは対にならない。"}, {"text": "表示", "is_correct": false, "explanation": "画面に映し出す意味で、入力の対義語ではない。"}], "correct_answer": "出力", "explanations": {"出力": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。", "録音": "音声を記録する意味で、入力の反対語ではない。", "撮影": "写真や映像を撮る意味で、入力とは対にならない。", "表示": "画面に映し出す意味で、入力の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コンピューターにデータを入れることです。", "primary_collocate": null, "pronunciation": "にゅうりょく", "ipa": "ɲɯːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "売上のデータを表に入力するのが、私の毎朝の仕事です。", "target_word": "入力", "complexity_tier": "T3", "furigana": "売上[うりあげ]のデータを表[ひょう]に入力[にゅうりょく]するのが、私[わたし]の毎朝[まいあさ]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "アンケートの回答を入力し終えるまでに、二時間かかった。", "target_word": "入力", "complexity_tier": "T3", "furigana": "アンケートの回答[かいとう]を入力[にゅうりょく]し終[お]えるまでに、二時間[にじかん]かかった。", "sentence_source": "generated"}, {"text": "入力を間違えると、計算の結果も変わってしまう。", "target_word": "入力", "complexity_tier": "T2", "furigana": "入力[にゅうりょく]を間違[まちが]えると、計算[けいさん]の結果[けっか]も変[か]わってしまう。", "sentence_source": "generated"}, {"text": "彼は両手で入力するのが速く、資料がすぐに完成した。", "target_word": "入力", "complexity_tier": "T3", "furigana": "彼[かれ]は両手[りょうて]で入力[にゅうりょく]するのが速[はや]く、資料[しりょう]がすぐに完成[かんせい]した。", "sentence_source": "generated"}, {"text": "学生番号を入力すると、成績が画面に表示される。", "target_word": "入力", "complexity_tier": "T3", "furigana": "学生番号[がくせいばんごう]を入力[にゅうりょく]すると、成績[せいせき]が画面[がめん]に表示[ひょうじ]される。", "sentence_source": "generated"}, {"text": "声で入力できる機能のおかげで、手が使えない時も便利だ。", "target_word": "入力", "complexity_tier": "T3", "furigana": "声[こえ]で入力[にゅうりょく]できる機能[きのう]のおかげで、手[て]が使[つか]えない時[とき]も便利[べんり]だ。", "sentence_source": "generated"}, {"text": "手書きの書類をすべてパソコンに入力して、紙の保管をやめた。", "target_word": "入力", "complexity_tier": "T3", "furigana": "手書[てが]きの書類[しょるい]をすべてパソコンに入力[にゅうりょく]して、紙[かみ]の保管[ほかん]をやめた。", "sentence_source": "generated"}, {"text": "入力した内容は、送信する前に画面で確認できる。", "target_word": "入力", "complexity_tier": "T3", "furigana": "入力[にゅうりょく]した内容[ないよう]は、送信[そうしん]する前[まえ]に画面[がめん]で確認[かくにん]できる。", "sentence_source": "generated"}, {"text": "入力の作業は単純だが、集中力が必要だ。", "target_word": "入力", "complexity_tier": "T3", "furigana": "入力[にゅうりょく]の作業[さぎょう]は単純[たんじゅん]だが、集中力[しゅうちゅうりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "古い機械では、数字を入力してから結果が出るまで時間がかかった。", "target_word": "入力", "complexity_tier": "T4", "furigana": "古[ふる]い機械[きかい]では、数字[すうじ]を入力[にゅうりょく]してから結果[けっか]が出[で]るまで時間[じかん]がかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "入力", "label": "基本形"}, {"form": "入力する", "label": "サ変動詞"}, {"form": "入力した", "label": "過去形"}, {"form": "入力して", "label": "て形"}], "register": "標準", "sense_fingerprint": "入力:コンピューターにデータを入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入力", "is_correct": true, "explanation": "データを表に入れる意味で、「表に〜するのが仕事」に合う。"}, {"text": "点検", "is_correct": false, "explanation": "機器や設備の状態を調べる意味で、表にデータを入れる文脈には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点数をつける意味で、表に入れる作業とは違う。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、表に何かを入れる文脈では使わない。"}], "explanations": {"入力": "データを表に入れる意味で、「表に〜するのが仕事」に合う。", "点検": "機器や設備の状態を調べる意味で、表にデータを入れる文脈には合わない。", "採点": "答案に点数をつける意味で、表に入れる作業とは違う。", "配達": "品物を届ける意味で、表に何かを入れる文脈では使わない。"}, "sentence_index": 0, "correct_answer": "入力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自動販売機に百円玉を入力して、ジュースを買った。", "explanation": "〈投入〉の意味。硬貨を機械に入れる場合は投入を使い、入力はデータを入れる場合に使う。"}, {"text": "来年、私は地域の合唱団に入力する。", "explanation": "〈入会〉の意味。団体に加わる意味で、入力は機械へのデータ入力を指す。"}, {"text": "祖父は先週から病院に入力している。", "explanation": "〈入院〉の意味。治療のために施設に入る意味で、入力は機械への情報入力を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入力", "is_correct": true, "explanation": "書類の内容をパソコンに入れる意味で、「パソコンに〜して」に合う。"}, {"text": "郵送", "is_correct": false, "explanation": "書類を郵便で送る意味で、パソコンに入れる文脈には合わない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売る意味で、パソコンに何かを入れる文脈では使わない。"}, {"text": "解約", "is_correct": false, "explanation": "契約をやめる意味で、データを入れる作業には当てはまらない。"}], "explanations": {"入力": "書類の内容をパソコンに入れる意味で、「パソコンに〜して」に合う。", "郵送": "書類を郵便で送る意味で、パソコンに入れる文脈には合わない。", "販売": "商品を売る意味で、パソコンに何かを入れる文脈では使わない。", "解約": "契約をやめる意味で、データを入れる作業には当てはまらない。"}, "sentence_index": 6, "correct_answer": "入力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春から、息子は小学校に入力する。", "explanation": "〈入学〉の意味。学校に入る意味で、入力は機械へのデータ入力を指す。"}, {"text": "面接の時間になり、受験者が部屋に入力した。", "explanation": "〈入室〉の意味。部屋に入る意味で、入力は情報を機械に入れる意味で使う。"}, {"text": "新しい商品が店に入力した。", "explanation": "〈入荷〉の意味。店に商品が届く意味で、入力はデータを機械に入れる意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生番号を入力したと、名前が表示されます。", "corrected_sentence": "学生番号を入力すると、名前が表示されます。", "error_description": "「したと」は過去形に「と」を付けた形で、条件を表す「すると」にならない。正しくは「入力すると」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51771, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "データを入力ると、結果が出る。", "corrected_sentence": "データを入力すると、結果が出る。", "error_description": "「入力ると」は「する」が抜けた誤り。条件の「すると」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出力", "is_correct": true, "explanation": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。"}, {"text": "保存", "is_correct": false, "explanation": "データを残しておく意味で、入力の反対語ではない。"}, {"text": "印刷", "is_correct": false, "explanation": "紙に印字する意味で、入力と対になる語ではない。"}, {"text": "表示", "is_correct": false, "explanation": "画面に映し出す意味で、入力の対義語ではない。"}], "correct_answer": "出力", "explanations": {"出力": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。", "保存": "データを残しておく意味で、入力の反対語ではない。", "印刷": "紙に印字する意味で、入力と対になる語ではない。", "表示": "画面に映し出す意味で、入力の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出力", "is_correct": true, "explanation": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。"}, {"text": "検索", "is_correct": false, "explanation": "情報を探し出す意味で、入力の反対語ではない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を別の言語に置き換える意味で、入力とは対にならない。"}, {"text": "送信", "is_correct": false, "explanation": "データを相手に送る意味で、入力の対義語ではない。"}], "correct_answer": "出力", "explanations": {"出力": "「入力」（機械にデータを入れる）の対義語で、機械からデータを外に出す意味。", "検索": "情報を探し出す意味で、入力の反対語ではない。", "翻訳": "言語を別の言語に置き換える意味で、入力とは対にならない。", "送信": "データを相手に送る意味で、入力の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コンピューターなどに数値や文字を入れること。", "primary_collocate": null, "pronunciation": "にゅうりょく", "ipa": "ɲɯːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "入力", "complexity_tier": "T4", "furigana": "これは、日照[にっしょう]や風通[かぜとお]しなどの環境[かんきょう]データを変数[へんすう]としてアルゴリズムに入力[にゅうりょく]し、最適[さいてき]な街区配置[がいくはいち]を自動的[じどうてき]に生成[せいせい]する手法[しゅほう]です。", "sentence_source": "mined"}, {"text": "画面にパスワードを入力してから、ログインボタンを押してください。", "target_word": "入力", "complexity_tier": "T2", "furigana": "画面[がめん]にパスワードを入力[にゅうりょく]してから、ログインボタンを押[お]してください。", "sentence_source": "generated"}, {"text": "名前の入力を間違えたので、もう一度やり直した。", "target_word": "入力", "complexity_tier": "T2", "furigana": "名前[なまえ]の入力[にゅうりょく]を間違[まちが]えたので、もう一度[いちど]やり直[なお]した。", "sentence_source": "generated"}, {"text": "数字を入力するときは、半角で書いてください。", "target_word": "入力", "complexity_tier": "T2", "furigana": "数字[すうじ]を入力[にゅうりょく]するときは、半角[はんかく]で書[か]いてください。", "sentence_source": "generated"}, {"text": "入力が終わったら、内容を確認してから保存してください。", "target_word": "入力", "complexity_tier": "T3", "furigana": "入力[にゅうりょく]が終[お]わったら、内容[ないよう]を確認[かくにん]してから保存[ほぞん]してください。", "sentence_source": "generated"}, {"text": "必要な項目を入力しないと、申し込みの手続きは完了しません。", "target_word": "入力", "complexity_tier": "T3", "furigana": "必要[ひつよう]な項目[こうもく]を入力[にゅうりょく]しないと、申[もう]し込[こ]みの手続[てつづ]きは完了[かんりょう]しません。", "sentence_source": "generated"}, {"text": "事務の仕事で、毎日たくさんの伝票をパソコンに入力している。", "target_word": "入力", "complexity_tier": "T3", "furigana": "事務[じむ]の仕事[しごと]で、毎日[まいにち]たくさんの伝票[でんぴょう]をパソコンに入力[にゅうりょく]している。", "sentence_source": "generated"}, {"text": "入力のミスが多かったので、送信する前にもう一度確かめた。", "target_word": "入力", "complexity_tier": "T3", "furigana": "入力[にゅうりょく]のミスが多[おお]かったので、送信[そうしん]する前[まえ]にもう一度[いちど]確[たし]かめた。", "sentence_source": "generated"}, {"text": "彼は入力が速く、会議の内容をその場で文字にしていった。", "target_word": "入力", "complexity_tier": "T3", "furigana": "彼[かれ]は入力[にゅうりょく]が速[はや]く、会議[かいぎ]の内容[ないよう]をその場[ば]で文字[もじ]にしていった。", "sentence_source": "generated"}, {"text": "スマートフォンでは、画面に指で触れて文字を入力する。", "target_word": "入力", "complexity_tier": "T2", "furigana": "スマートフォンでは、画面[がめん]に指[ゆび]で触[ふ]れて文字[もじ]を入力[にゅうりょく]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "入力", "label": "基本形"}, {"form": "入力する", "label": "サ変動詞"}, {"form": "入力した", "label": "過去形"}, {"form": "入力して", "label": "て形"}], "register": "標準", "sense_fingerprint": "入力:コンピューターなどに数値や文字を入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入力", "is_correct": true, "explanation": "機械に数値やデータを入れる意味で、「アルゴリズムに〜を入れる」に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る意味で、データを機械に入れる文脈では使わない。"}, {"text": "点検", "is_correct": false, "explanation": "機器の状態を調べる意味で、データを入れる文脈には合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "ごみを取り除いてきれいにする意味で、アルゴリズムには当てはまらない。"}], "explanations": {"入力": "機械に数値やデータを入れる意味で、「アルゴリズムに〜を入れる」に合う。", "撮影": "写真や映像を撮る意味で、データを機械に入れる文脈では使わない。", "点検": "機器の状態を調べる意味で、データを入れる文脈には合わない。", "清掃": "ごみを取り除いてきれいにする意味で、アルゴリズムには当てはまらない。"}, "sentence_index": 0, "correct_answer": "入力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議が始まり、全員が会議室に入力した。", "explanation": "〈入室〉の意味。人が部屋に入る意味で、入力は情報を機械に入れる意味で使う。"}, {"text": "開演前、大勢の客が会場に入力した。", "explanation": "〈入場〉の意味。会場に入る意味で、入力は情報を機械に入れる意味で使う。"}, {"text": "自動販売機に硬貨を入力してください。", "explanation": "〈投入〉の意味。機械に硬貨を入れる場合は投入を使い、入力はデータを入れる場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入力", "is_correct": true, "explanation": "伝票の数字をパソコンに入れる意味で、「パソコンに〜している」に合う。"}, {"text": "郵送", "is_correct": false, "explanation": "書類を郵便で送る意味で、パソコンに入れる文脈には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点数をつける意味で、ここでは使わない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売る意味で、データを入れる文脈には合わない。"}], "explanations": {"入力": "伝票の数字をパソコンに入れる意味で、「パソコンに〜している」に合う。", "郵送": "書類を郵便で送る意味で、パソコンに入れる文脈には合わない。", "採点": "答案に点数をつける意味で、ここでは使わない。", "販売": "商品を売る意味で、データを入れる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "入力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来年の春、私は大学に入力する予定だ。", "explanation": "〈入学〉の意味。学校に入る意味で、入力は情報を機械に入れる意味で使う。"}, {"text": "この国は食料の多くを入力に頼っている。", "explanation": "〈輸入〉の意味。海外から物を入れる意味で、入力は機械へのデータ入力を指す。"}, {"text": "夜、お風呂に入力して体を温めた。", "explanation": "〈入浴〉の意味。お風呂に入る意味で、入力は機械へのデータ入力を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "フォームに名前を入力するます。", "corrected_sentence": "フォームに名前を入力します。", "error_description": "「入力するます」は辞書形と丁寧形が重なった誤り。正しくは連用形の「入力し」に「ます」を付けた「入力します」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51772, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "請求書の数字を入力ると、計算が始まる。", "corrected_sentence": "請求書の数字を入力すると、計算が始まる。", "error_description": "「入力ると」は「する」が抜けた誤り。条件を表す「すると」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51773, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「配置を変える」の目的語を示す「を」で、ここでは正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、他動詞「変えた」の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」で、動詞「変えた」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」で、配置と動詞「変えた」をつなぐ意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「配置を変える」の目的語を示す「を」で、ここでは正しい。", "が": "主語を示す「が」で、他動詞「変えた」の目的語にはならない。", "の": "連体の「の」で、動詞「変えた」の目的語にはならない。", "と": "並列の「と」で、配置と動詞「変えた」をつなぐ意味にならない。"}, "error_tags": {"が": "主格", "の": "連体", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
