INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51773, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを、ある場所に置くときに、その場所をどう決めるか、ということ。", "primary_collocate": null, "pronunciation": "はいち", "ipa": "haitɕi", "syllable_count": 3, "sentences": [{"text": "本棚の配置を考えてから、新しい家具を買った。", "target_word": "配置", "complexity_tier": "T2", "furigana": "本棚[ほんだな]の配置[はいち]を考[かんが]えてから、新[あたら]しい家具[かぐ]を買[か]った。", "sentence_source": "generated"}, {"text": "教室の机の配置を、グループ活動向きに変えた。", "target_word": "配置", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の机[つくえ]の配置[はいち]を、グループ活動[かつどう]向[む]きに変[か]えた。", "sentence_source": "generated"}, {"text": "台所は道具の配置がよいと、料理がしやすい。", "target_word": "配置", "complexity_tier": "T2", "furigana": "台所[だいどころ]は道具[どうぐ]の配置[はいち]がよいと、料理[りょうり]がしやすい。", "sentence_source": "generated"}, {"text": "地図には、公園の遊具の配置が細かく書かれている。", "target_word": "配置", "complexity_tier": "T3", "furigana": "地図[ちず]には、公園[こうえん]の遊具[ゆうぐ]の配置[はいち]が細[こま]かく書[か]かれている。", "sentence_source": "generated"}, {"text": "展示室の作品の配置は、見る人の流れを考えて決められた。", "target_word": "配置", "complexity_tier": "T4", "furigana": "展示室[てんじしつ]の作品[さくひん]の配置[はいち]は、見[み]る人[ひと]の流[なが]れを考[かんが]えて決[き]められた。", "sentence_source": "generated"}, {"text": "コンセントの位置に合わせて、パソコンの配置を決めた。", "target_word": "配置", "complexity_tier": "T3", "furigana": "コンセントの位置[いち]に合[あ]わせて、パソコンの配置[はいち]を決[き]めた。", "sentence_source": "generated"}, {"text": "舞台の上の大道具の配置が変わると、場面の印象も変わる。", "target_word": "配置", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の上[うえ]の大道具[おおどうぐ]の配置[はいち]が変わると、場面[ばめん]の印象[いんしょう]も変わる。", "sentence_source": "generated"}, {"text": "照明の配置を工夫すれば、部屋をもっと明るく見せられる。", "target_word": "配置", "complexity_tier": "T3", "furigana": "照明[しょうめい]の配置[はいち]を工夫[くふう]すれば、部屋[へや]をもっと明[あか]るく見[み]せられる。", "sentence_source": "generated"}, {"text": "工場では、機械の配置が悪いと、作業に無駄な動きが増える。", "target_word": "配置", "complexity_tier": "T4", "furigana": "工場[こうじょう]では、機械[きかい]の配置[はいち]が悪[わる]いと、作業[さぎょう]に無駄[むだ]な動[うご]きが増[ふ]える。", "sentence_source": "generated"}, {"text": "彼女は花瓶の配置を少し動かして、テーブルの飾りを整えた。", "target_word": "配置", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は花瓶[かびん]の配置[はいち]を少[すこ]し動[うご]かして、テーブルの飾[かざ]りを整[ととの]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配置", "label": "基本形"}, {"form": "配置する", "label": "サ変動詞"}, {"form": "配置した", "label": "過去形"}, {"form": "配置される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "配置:ものを置くときにその場所をどう決めるか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 大道具 (Zipf 2.32)']::text[], 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51773, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "本棚をどこに置き、どう並べるかという計画を指すので、「本棚の〜を考えて」に合う。"}, {"text": "配送", "is_correct": false, "explanation": "荷物を届ける意味で、本棚をどこに置くかを考える文脈には合わない。"}, {"text": "配膳", "is_correct": false, "explanation": "料理を各席に配る意味で、家具の配置には当てはまらない。"}, {"text": "配線", "is_correct": false, "explanation": "電気の線を通す意味で、本棚の並べ方を考える場面では使わない。"}], "explanations": {"配置": "本棚をどこに置き、どう並べるかという計画を指すので、「本棚の〜を考えて」に合う。", "配送": "荷物を届ける意味で、本棚をどこに置くかを考える文脈には合わない。", "配膳": "料理を各席に配る意味で、家具の配置には当てはまらない。", "配線": "電気の線を通す意味で、本棚の並べ方を考える場面では使わない。"}, "sentence_index": 0, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卵と牛乳を配置して、よくかき混ぜる。", "explanation": "〈配合〉の意味。材料を混ぜ合わせる意味で、配置は物を場所に置く計画を指すので合わない。"}, {"text": "毎朝、郵便物を各家庭に配置している。", "explanation": "〈配達〉の意味。郵便物を届ける意味で、配置は場所に物を置く計画を指すので合わない。"}, {"text": "相手への配置が大切だ。", "explanation": "〈配慮〉の意味。相手を気づかう意味で、配置は物や人の場所を決める意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51773, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "大道具をどこに置くかという計画を指すので、「大道具の〜が変わる」に合う。"}, {"text": "配属", "is_correct": false, "explanation": "人を部署に割り当てる意味で、大道具の並べ方には当てはまらない。"}, {"text": "配布", "is_correct": false, "explanation": "資料などを配って渡す意味で、大道具の場所には関係しない。"}, {"text": "配車", "is_correct": false, "explanation": "車両を手配する意味で、舞台の大道具の並べ方とは関係しない。"}], "explanations": {"配置": "大道具をどこに置くかという計画を指すので、「大道具の〜が変わる」に合う。", "配属": "人を部署に割り当てる意味で、大道具の並べ方には当てはまらない。", "配布": "資料などを配って渡す意味で、大道具の場所には関係しない。", "配車": "車両を手配する意味で、舞台の大道具の並べ方とは関係しない。"}, "sentence_index": 6, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この舞台の配置は、新人が多い。", "explanation": "〈配役〉の意味。出演者の役割を決める意味で、配置は場所に置く計画を指す。"}, {"text": "テストでは、各問を五点ずつに配置した。", "explanation": "〈配点〉の意味。問題ごとに点数を割り振る意味で、配置は場所に物を置く計画を指すので合わない。"}, {"text": "今年は会社の利益を、株主へ配置した。", "explanation": "〈配当〉の意味。利益を分けて渡す意味で、配置は場所に置く計画を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51773, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家具の配置が変えて、部屋を広くした。", "corrected_sentence": "家具の配置を変えて、部屋を広くした。", "error_description": "「配置が」は主語を示すが、他動詞「変えて」には目的語の「を」が必要。正しくは「配置を変えて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51773, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照明の配置を工夫するば、部屋が明るく見える。", "corrected_sentence": "照明の配置を工夫すれば、部屋が明るく見える。", "error_description": "「するば」は辞書形に「ば」を付けた誤り。仮定の「すれば」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51774, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「配置を変える」の目的語を示す「を」で、ここでは正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、他動詞「変えた」の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」で、動詞「変えた」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」で、配置と動詞「変えた」をつなぐ意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「配置を変える」の目的語を示す「を」で、ここでは正しい。", "が": "主語を示す「が」で、他動詞「変えた」の目的語にはならない。", "の": "連体の「の」で、動詞「変えた」の目的語にはならない。", "と": "並列の「と」で、配置と動詞「変えた」をつなぐ意味にならない。"}, "error_tags": {"が": "主格", "の": "連体", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
